window.DESC = window.DESC || {};
window.DESC.ru = {
"730": "Более двух десятилетий Counter-Strike служит примером первоклассной соревновательной игры, путь развития которой определяют миллионы игроков со всего мира. Теперь пришло время нового этапа — Counter-Strike 2.",
"570": "Ежедневно миллионы игроков по всему миру сражаются от лица одного из более сотни героев Dota 2, и даже после тысячи часов в ней есть чему научиться. Благодаря регулярным обновлениям игра живёт своей жизнью: геймплей, возможности и герои постоянно преображаются.",
"578080": "PUBG: BATTLEGROUNDS — культовый шутер, пробудивший интерес к жанру «королевская битва», теперь бесплатный! Высаживайтесь на разные карты, добывайте уникальное оружие и припасы и постарайтесь выжить в постоянно сужающейся зоне, где опасность подстерегает вас за каждым углом.",
"271590": "Grand Theft Auto V для PC позволяет игрокам исследовать знаменитый мир Лос-Сантоса и округа Блэйн в разрешении до 4k и выше с частотой 60 кадров в секунду.",
"359550": "Tom Clancy's Rainbow Six Осада – элитный тактический командный шутер, где побеждает сторона, которая лучше продумает и исполнит свой план.",
"440": "Девять классов с уникальными характерами откроют вам доступ ко множеству разнообразных тактик и навыков. Игра беспрестанно пополняется новыми режимами, картами, предметами и, самое главное, шляпами!",
"105600": "Копайте, сражайтесь, исследуйте, стройте! Нет ничего невозможного в этой насыщенной событиями приключенческой игре. Также доступен комплект для четверых!",
"252490": "Единственная цель в Rust — выживание. Дикая природа острова, его обитатели, окружение, другие выжившие — всё вокруг хочет твоей смерти. Делай всё, что в твоих силах, чтобы пережить ещё одну ночь.",
"4000": "Garry’s Mod — это физическая песочница. Никаких заранее определенных целей и задач нет. Мы даем вам инструменты и оставляем вас играть.",
"1172470": "Apex Legends — удостоенный наградами бесплатный геройский шутер от Respawn Entertainment. Освойте все тонкости игры за легендарных персонажей, число которых продолжает расти, и используйте их мощные умения в стратегии своего отряда. Это новое слово в геройских шутерах и «королевских битвах».",
"413150": "Вам досталась старая дедушкина ферма в долине Стардью. С горстью монет в кармане и старыми инструментами в руках вы начинаете новую жизнь. Сможете ли вы превратить пустырь в цветущий сад?",
"1091500": "Cyberpunk 2077 — приключенческая ролевая игра с открытым миром, действие которой происходит в футуристическом мегаполисе Найт-Сити, где выше всего ценятся власть, роскошь и модификации тела.",
"2358720": "Black Myth: Wukong — ролевой боевик по мотивам китайской мифологии. Став Избранным, вы отправитесь в приключение, полное испытаний и чудес, в котором вам предстоит приподнять завесу тайны над великой легендой.",
"1174180": "Артур Морган и другие подручные Датча ван дер Линде вынуждены пуститься в бега. Их преследуют федеральные агенты и охотники за головами. Чтобы выжить, банде придется участвовать в кражах, грабежах и перестрелках в самом сердце Америки.",
"553850": "Последняя линяя нападения галактики. Станьте Адским Десантником и сражайтесь за свободу по всему враждебному космосу в динамичном, безумном и беспощадном шутере с видом от третьего лица.",
"292030": "Обновлённое издание игры «Ведьмак 3: Дикая Охота» — всё та же любимая многими ролевая игра с открытым миром, но теперь со множеством улучшений. Вместе с охотником на чудовищ Геральтом из Ривии отправьтесь по разорённым войной королевствам Севера на поиски Цири, приёмной дочери ведьмака.",
"1245620": "НОВЫЙ ФЭНТЕЗИЙНЫЙ РОЛЕВОЙ БОЕВИК. Восстань, погасшая душа! Междуземье ждёт своего повелителя. Пусть благодать приведёт тебя к Кольцу Элден.",
"550": "Left 4 Dead 2 — это кооперативный хоррор-шутер от первого лица, действие которого разворачивается в условиях зомби-апокалипсиса. Он проведет вас и ваших друзей через города, болота и кладбища Глубокого Юга, от Саванны до Нового Орлеана, в пяти масштабных кампаниях.",
"236390": "War Thunder – самая масштабная бесплатная кроссплатформенная многопользовательская онлайн-игра, посвященная боевой технике самых разных войн и конфликтов – с начала XX века и до наших дней. Авиация, наземные силы и флот сражаются вместе в одном бою.",
"227300": "Станьте королем европейских дорог — водителем грузовика, который доставляет важные грузы на немалые расстояния! Вас ждут десятки городов Великобритании, Бельгии, Германии, Италии, Нидерландов, Польши и не только. Испытайте свои умения, выносливость и скорость.",
"1086940": "Соберите отряд и вернитесь в Забытые Королевства. Вас ждет история о дружбе и предательстве, выживании и самопожертвовании, о сладком зове абсолютной власти.",
"381210": "10 лет ужаса. 10 лет дрожи от внезапного испуга и рискованных моментов. 10 лет жестоких жертвоприношений и захватывающих дух побегов. Застряв во владениях неумолимого зла, где даже смерть не дарует избавление, четверо решительных выживших сталкиваются с кровожадным убийцей.",
"739630": "Phasmophobia — это психологический хоррор для совместной сетевой игры для 4 игроков. Паранормальная активность растет, и вам и вашей команде предстоит использовать все имеющееся в вашем распоряжении оборудование для охоты за привидениями, чтобы собрать как можно больше улик.",
"230410": "Пробудитесь в роли неудержимого воина и сражайтесь вместе с друзьями в этой сюжетной бесплатной онлайн-игре. Столкнитесь с враждующими фракциями в обширной межпланетной системе, следуя указаниям загадочной Лотос, повышайте уровень своего Варфрейма, создайте арсенал разрушительной огневой мощи, и откройте свой истинный потенциал в огромных открытых мирах этого захватывающего сражения от третьего лица.",
"1085660": "Исследуйте тайны Солнечной системы и наслаждайтесь динамичным шутером от первого лица в Destiny 2. Разблокируйте мощные способности и собирайте уникальное снаряжение, выполняя сюжетные задания в совместных и состязательных режимах.",
"945360": "Локальная и сетевая игра для компании от 4 до 15 игроков о командной работе и предательстве... в космосе!",
"322170": "Прыгайте и летите сквозь опасности в этом ритмичном платформере!",
"346110": "Будучи выброшенным голым на берег таинственного острова, голодая и замерзая, вам придется заниматься ремеслом, охотой и строительством, чтобы выжить. Используйте опыт и ловкость, чтобы приручать, разводить и ездить на первобытных существах, живущих в ARK.",
"242760": "Будучи единственным выжившим после крушения пассажирского самолета, вы оказываетесь в таинственном лесу, сражаясь за выживание против общества мутантов-каннибалов. Стройте, исследуйте и выживайте в этом ужасающем симуляторе ужасов выживания от первого лица.",
"304930": "Unturned — это игра-песочница на выживание зомби в открытом мире. Будучи одним из немногих, кто еще не обратился, вы должны бороться, чтобы остаться в живых.",
"367520": "Hollow Knight – это эпическое приключение в огромном разрушенном королевстве, полном насекомых и героев. Исследуйте извилистые пещеры, сражайтесь с порчеными тварями и заводите дружбу со странными жуками – все это в классической двухмерной ручной рисовке.",
"892970": "Симулятор выживания и исследования для компании от 1 до 10 человек. Вас ждет процедурно генерируемый мир, пропитанный духом скандинавских мифов. Сражайтесь, стройте крепости и докажите, что достойны покровительства Одина!",
"1097150": "Fall Guys — это бесплатная многопользовательская кроссплатформенная игра для весёлой вечеринки. Участвуйте в неуклюжих забегах с преградами, стройте собственные безумные полосы препятствий, делитесь ими с друзьями и игроками по всему миру.",
"218620": "PAYDAY 2 - это кооперативный экшн-шутер для четверых игроков, который снова позволяет игрокам надеть маски оригинальной банды PAYDAY - Даллас, Хокстон, Чейнс и Вулф, которые прибыли в Вашингтон для новой крутой серии преступлений.",
"252950": "Встречайте долгожданное продолжение Supersonic Acrobatic Rocket-Powered Battle-Cars — всеми любимого основанного на физике сочетания футбола и гонок!",
"2357570": "Overwatch®: БУДУЩЕЕ, ЗА КОТОРОЕ СТОИТ БОРОТЬСЯ! Overwatch® — непрерывно развивающаяся бесплатная динамичная командная игра с постоянной поддержкой в ярком мире будущего, где каждый матч представляет собой поистине потрясающий бой 5 на 5 или 6 на 6.",
"1938090": "Хаб серии Call of Duty: Warzone, мультиплеер и кампании в одном лаунчере.",
"2767030": "Marvel Rivals — это командный PVP-шутер, где супергерои сражаются плечом к плечу! Соберите команду мечты из героев Marvel, разработайте уникальные стратегии, объединив силы в невероятные командные навыки, и сразитесь на разрушаемых полях боя в постоянно развивающейся вселенной Marvel!",
"250900": "The Binding of Isaac: Rebirth — это случайно генерируемый ролевой шутер с тяжелыми элементами Rogue-like. Следуя за Исааком в его путешествии, игроки найдут причудливые сокровища, которые меняют форму Исаака, наделяя его сверхчеловеческими способностями и позволяя ему отбиваться от толп загадочных существ, раскрывать секреты и пробиться в безопасное место.",
"1623730": "Собирайте удивительных существ — Палов — на просторах огромного мира, отправляйте их сражаться и трудиться на фабриках, стройте с их помощью здания и выращивайте плантации в этом абсолютно новом симуляторе выживания в открытом мире, поддерживающем совместный режим.",
"291550": "Эпический платформерный файтинг для 8 игроков онлайн или локально. Попробуйте непринужденные схватки, рейтинговые матчи или пригласите друзей в отдельную комнату. И это бесплатно! Играйте в кроссплатформенную игру с миллионами игроков на PlayStation, Xbox, Nintendo Switch, iOS, Android и Steam! Частые обновления. Более шестидесяти легенд.",
"1966720": "Кооперативный хоррор об уборке заброшенных лун с целью продажи металлолома Компании.",
"284160": "Основанный на физике мягких объектов автомобильный симулятор, способный практически на всё.",
"620": "Программа вечного тестирования расширена: создавайте совместные головоломки для себя и друзей!",
"1030300": "Исследуйте огромное проклятое царство в Hollow Knight: Silksong! Открывайте его тайны, сражайтесь и боритесь за свою жизнь, поднимаясь к вершинам земель, где правят шёлк и песня.",
"221100": "Как долго вы сможете выжить в пост-апокалипсисе? Мир пал под натиском зараженных. Боритесь против других выживших за ограниченные ресурсы. Сможете ли вы работать сообща с незнакомцами? Или же станете волком-одиночкой? Это ваша история, это DayZ.",
"322330": "Сражайтесь, занимайтесь фермерством, стройте и исследуйте вместе в автономном многопользовательском дополнении к бескомпромиссной игре на выживание в дикой природе Don't Starve.",
"239140": "Боевик от первого лица с элементами выживания, действие которого разворачиваются в постапокалиптическом мире, кишащем кровожадными зомби. Изучите город, уничтоженный загадочным вирусом: собирайте ресурсы, создавайте оружие и сражайтесь с полчищами мутантов.",
"108600": "Project Zomboid — это вершина выживания среди зомби. В одиночку или в сетевой игре: вы грабите, строите, создаете, сражаетесь, занимаетесь фермерством и ловите рыбу, пытаясь выжить. Неосторожных ждут хардкорный набор навыков ролевой игры, обширная карта, настраиваемая песочница и милый обучающий енот. Так как же ты умрешь? Все, что нужно, это укусить..",
"960090": "Игра-боевик в стиле «оборона крепости»",
"3241660": "Кооперативная онлайн-игра ужасов для 6 игроков. Найдите ценные объекты, полностью основанные на физике, и обращайтесь с ними осторожно, извлекая и извлекая их, чтобы удовлетворить желания своего создателя.",
"444090": "Присоединяйтесь к 25 миллионам игроков в Paladins – бесплатном командном шутере в стиле фэнтези. Используя мощное оружие и магию, станьте легендарным чемпионом королевства! Меняйте ваши способности, чтобы играть именно так, как вам хочется.",
"264710": "Спуститесь в глубины инопланетного подводного мира, полного чудес и опасностей. Создавайте оборудование, пилотируйте подводные лодки и перехитрите дикую природу, чтобы исследовать пышные коралловые рифы, вулканы, пещерные системы и многое другое — и все это в попытке выжить.",
"648800": "Raft™ отправит вас и ваших друзей в эпическое океанское приключение! В одиночку или вместе игроки сражаются, чтобы выжить в опасном путешествии по огромному морю! Собирайте мусор, очищайте рифы и постройте свой собственный плавучий дом, но опасайтесь акул-людоедов!",
"1172620": "Sea of Thieves — культовая игра о пиратских приключениях. Все для настоящего пирата: охота за сокровищами, напряженные сражения, битвы с морскими чудовищами. Переработанное издание включает дополнительные цифровые материалы: поднимайте паруса!",
"275850": "No Man's Sky является научно-фантастической игрой об исследованиях и выживании в бесконечной, процедурно генерируемой вселенной.",
"582010": "Добро пожаловать в новый мир! Отправляйтесь на незабываемую охоту в продолжении серии Monster Hunter: World, используйте любые подручные средства, выслеживайте чудовищ в новом мире, полном сюрпризов и ярких впечатлений.",
"391540": "Андертейл! РПГ игра, в которой вам не придется никого уничтожать.",
"548430": "Deep Rock Galactic — кооперативный шутер от первого лица для 1-4 игроков, в котором вас ждут крутые космические дворфы, полностью разрушаемое окружение, процедурно генерируемые системы пещер, а также бесконечные волны инопланетных чудовищ.",
"1293830": "Времена года полностью меняют облик главного автомобильного фестиваля планеты. Исследуйте чудесные пейзажи и исторические достопримечательности Великобритании, путешествуя по открытому миру в одиночку или вместе с другими игроками.",
"1203220": "NARAKA: BLADEPOINT — это «королевская битва» для 60 человек, вдохновленная мифами и легендами Дальнего Востока. Игра сочетает в себе различные виды боевых искусств, обширный арсенал оружия ближнего и дальнего боя, а также множество персонажей с невероятными способностями.",
"1118200": "Стреляйте, колите, сжигайте, отравляйте, рвите, испаряйте или раздавливайте тряпичных кукол на большом открытом пространстве.",
"3164500": "От мелкого торговца наркотиками до вора в законе — производите и распространяйте разнообразные наркотики по всему мрачному городу Хайленд-Пойнт. Расширьте свою империю за счет недвижимости, предприятий, сотрудников и многого другого.",
"377160": "Fallout 4 — это игра от прославленной студии Bethesda Game Studios (авторов Starfield и The Elder Scrolls V: Skyrim), ставшая важной вехой в жанре ролевых приключений с открытым миром и удостоившаяся свыше 200 наград, в том числе титула «Игра года» по версии DICE и BAFTA.",
"1326470": "Отправленный на поиски пропавшего миллиардера на отдаленный остров, вы попадаете в ад, кишащий каннибалами. Создавайте, стройте и боритесь за выживание в одиночку или с друзьями в этом новом ужасающем симуляторе выживания в открытом мире.",
"1145360": "Бросьте вызов богу мёртвых и прорубите себе путь из Подземного мира в игре в жанрах «рогалик» и «данжен-кроулер» от создателей Bastion, Transistor и Pyre.",
"2073850": "Играйте в THE FINALS, знаменитую бесплатную шоу-игру! Сражайтесь вместе с товарищами по команде на виртуальных аренах, меняйте их и уничтожайте! Разработайте собственный стиль игры в этом боевике от первого лица, победите во всех турнирах и увенчайте себя славой!",
"374320": "Dark Souls продолжит испытывать игроков на прочность в новой главе знаменитой серии, собравшей множество наград и определившей лицо жанра. Соберитесь с духом и погрузитесь во тьму!",
"990080": "«Хогвартс. Наследие» – это ролевая игра с открытым миром. Теперь вы можете контролировать свои действия и стать центральным героем собственных приключений в волшебном мире.",
"289070": "Сыграйте за одного из 20 лидеров – например за Петра Великого, российского императора.",
"251570": "7 Days to Die — это единственная в своем роде игра с открытым миром, сочетающая в себе элементы шутера от первого лица, хоррора на выживание, защиты замка и ролевой игры. Приобретите изменившую жанр RPG-песочницу с выживанием среди зомби, которая задала тон другим похожим играм. Вас ждет Невезган!",
"438100": "Присоединяйтесь к нашему растущему сообществу, исследуйте, играйте и помогайте создавать будущее социальной виртуальной реальности. Создавайте миры и собственные аватары. Добро пожаловать в VRChat.",
"1144200": "Лос-Суэнос. Полиция Лос-Суэноса сообщает о всплеске преступности в городе. Отряды спецназа направлены для урегулирования таких опасных ситуаций, как захват заложников, угрозы взрыва и перестрелки с подозреваемыми.",
"394360": "Победа у вас под рукой! Ваша способность руководить своей нацией — ваше высшее оружие. В стратегической игре Hearts of Iron IV вы сможете взять на себя командование любой нацией во Второй мировой войне; самый захватывающий конфликт в мировой истории.",
"1551360": "Исследуйте яркие пейзажи Мексики в открытом мире с безграничным, захватывающим движением на лучших в мире автомобилях.",
"814380": "Игра года - The Game Awards 2019 Лучший боевик 2019 г. - IGN Составляйте и воплощайте собственные планы мести в удостоенном множества наград боевике от студии FromSoftware, создавшей Bloodborne и серию Dark Souls. Отомстите врагам. Верните свою честь. Освойте искусство убивать.",
"1517290": "Battlefield™ 2042 — это шутер от первого лица, в котором серия возвращается к легендарным масштабным сражениям.",
"1237970": "Включает весь контент Эксклюзивного цифрового издания, набор «Ключ на старт» для ускоренного развития и разблокировки предметов, а также особую боевую раскраску Underground для карабина R-201.",
"1794680": "Пачками косить порождений ночи и дожить до рассвета! Vampire Survivors — казуальная игра в стиле готического хоррора с элементами упрощенного рогалика. Здесь каждое ваше решение может вызвать лавину последствий для орд монстров, с которыми вам предстоит столкнуться.",
"238960": "Вы - изгнанник, который пытается выжить в мрачном мире Рэкласта. Сражаясь за свою жизнь, вы накопите силу, которая поможет вам отомстить тем, кто обрёк вас на эту участь. Path of Exile - это онлайн Action RPG в тёмном фэнтэзийном мире. Игра полностью бесплатна и не имеет Pay-to-Win элементов.",
"632360": "Выберитесь с хаотичной неизвестной планеты, отбиваясь от полчищ безумных монстров в одиночку или с друзьями. Неожиданным образом сочетайте найденные предметы и постигайте все особенности персонажей, пока сами не станете разрушительной силой, вселяющей ужас в противников.",
"976730": "Масштабное путешествие Мастера Чифа охватывает шесть игр серии, собранных в единую коллекцию. «Коллекция Мастер Чифа» произведёт неизгладимое впечатление как на давних поклонников Halo, так и на новичков, которым только предстоит знакомство со Спартанцем-117.",
"1238810": "Вас ждёт максимальное погружение в атмосферу Battlefield™ V. Примите участие в величайшем конфликте за всю историю человечества с полным арсеналом оружия, техники и устройств, а также лучшими элементами персонализации за первые два года существования игры.",
"526870": "Satisfactory — это игра от первого лица в открытом мире, вы которой вам нужно строить заводы, с упором на исследования и бои. Играйте в одиночестве или с друзьями, исследуйте незнакомую планету, возводите многоэтажные заводы и вступите в конвейерный рай!",
"700330": "В Лаборатории SCP во время массовых беспорядков, часть аномалий преодолевают системы защиты и сбегают из своих камер содержания, явно не с добрыми намерениями. Станьте ученым, агентом мобильной опергруппы или аномальным объектом и решите финальный исход игры!",
"261550": "Это стратегическая ролевая игра. Ваш персонаж будет плести интриги, заниматься ремеслами, торговать и воевать в огромной средневековой «песочнице». Командуйте воинами в режиме реального времени. Сражайтесь с видом от первого или третьего лица, осваивая интуитивно понятную систему боевых навыков.",
"1222140": "В Detroit: Become Human в ваших руках окажутся судьбы как человечества, так и андроидов. Каждый сделанный вами выбор повлияет на исход игры, в которой реализован одним из самых замысловатых и разветвленных сюжетов из когда-либо созданных в игровой индустрии.",
"107410": "Испытайте реалистичный бой в масштабной военной песочнице. Сценарии для одиночной и многопользовательской игры, обширный арсенал современного вооружения и техники и широкие возможности для создания контента. Аутентичная, разнообразная и открытая — Arma 3 отправляет вас в зону боевых действий.",
"489830": "В игре The Elder Scrolls V: Skyrim Special Edition, получившей более 200 наград «Игра года», вас ждет удивительный мир, воссозданный с потрясающей детализацией. В издание Special Edition вошли базовая игра и дополнения, добавляющие в нее ряд новых возможностей.",
"1426210": "Отправьтесь в самое безумное путешествие в жизни в игре It Takes Two. Пригласите друга присоединиться бесплатно благодаря версии для друга*, радостно преодолевая многочисленные испытания.",
"255710": "Cities: Skylines предлагает по-новому взглянуть на классический жанр градостроительного симулятора. Эта игра как нельзя лучше передает возникающие перед градоначальником трудности и позволяет создать настоящий мегаполис, одновременно привнося в игру приятные новшества.",
"1229490": "ULTRAKILL — это динамичный и чрезвычайно жестокий ретро-шутер от первого лица, в котором сочетаются система подсчета очков, основанная на мастерстве игрока, характерная для экшенов, и настоящая кровавая бойня, вдохновленная лучшими шутерами 90-х годов.",
"594650": "Hunt: Showdown 1896 — жестокий, но вознаграждающий экстракшен-шутер, полный жутких чудовищ и беспощадного PvP. Выносите Награды из оскверненных земель на окраине мира. Соберите команду и выживите сообща. Получите многое или потеряйте все, включая жизнь.",
"22380": "Добро пожаловать в Вегас. Новый Вегас. Приятного вам отдыха!",
"294100": "Научно-фантастический симулятор колонии с интеллектуальным AI-рассказчиком. Создаёт истории, моделируя психологию, экологию, стрельбу, ближний бой, климат, биомы, дипломатию, межличностные отношения, искусство, медицину, торговлю и многое другое.",
"49520": "Красавчик Джек, Пандора и культовый кооп-лутер-шутер, который до сих пор не постарел.",
"220": "Гордон Фримен вновь пробуждается в оккупированном центре Сити-17 и возглавляет отчаянное сопротивление против Альянса. К нему присоединяется Аликс Вэнс. Сыграйте в этот эпохальный шутер от первого лица с беспрецедентной физикой, обеспечивающей невероятный уровень погружения, и головокружительными сражениями.",
"2246340": "Неистовая стихия дикой природы — не для слабых духом. Окружающий мир может измениться в мгновение ока! Это история о монстрах и людях, а также о том, как они пытаются гармонично сосуществовать в двойственном мире. В Monster Hunter Wilds вас ждет поистине незабываемая охота!",
"1238840": "Вступайте в игровое сообщество Battlefield и откройте для себя зарю мировых войн в командных сетевых боях или в увлекательной одиночной кампании.",
"433850": "King of the Kill – это многопользовательский онлайн-шутер на выбывание, в котором 150 игроков, закаленных в боях, сражаются друг с другом в суровом и детализированном мире. Ищите оружие, боеприпасы, броню, транспорт и продовольствие, чтобы получить преимущество в соревновании и стать последним выжившим.",
"268910": "Cuphead – это в прямом смысле слова \"классический\" платформер. Классический, потому что все в нем выдержано в духе 1930-х: от графики, кажется, вышедшей из-под пера самого Уолта Диснея, до акварельных фонов и джазового музыкального сопровождения.",
"2050650": "Выжить — это лишь первый шаг. Resident Evil 4, настоящий гигант индустрии, возрождается. Вас ждут обновленный игровой процесс, переработанный сюжет и крайне детализированная графика. Вновь переживите кошмар, полностью изменивший жанр ужасов.",
"427520": "Factorio - это игра о создании автоматизированных фабрик по производству вещей все более возрастающей сложности, в пределах бесконечного 2D мира - Используйте свое воображение для проектирования фабрик, комбинируйте простые элементы в комплексные структуры и, наконец, защищайтесь от враждебных существ.",
"646570": "Мы смешали жанры ККИ и «рогалик» в попытке предоставить вам нашу лучшую одиночную карточную стратегию. Вам предстоит собрать уникальную колоду, встретить множество причудливых монстров, найти разнообразные могущественные реликвии и повергнуть Шпиль!",
"1468810": "Tale of Immortal — это песочница с открытым миром, основанная на китайской мифологии и культуре. Вы станете бессмертными, победите зверей из «Классики гор и времен года», тщательно сделаете свой выбор и поймете свою судьбу.",
"782330": "Армии ада вторглись на Землю. Станьте Палачом Рока и убейте демонов во всех измерениях, чтобы спасти человечество. Они боятся только… тебя.",
"12210": "Нико Беллик, Джонни Клебиц и Луис Лопес живут в худшем городе Америки. Либерти-Сити – это рай лишь для тех, кто богат и уважаем.",
"1903340": "Возглавьте Экспедицию 33 и уничтожьте Художницу, чтобы она никогда больше не смогла нарисовать смерть. Исследуйте мир чудес, созданный на основе Прекрасной эпохи Франции, и побеждайте уникальных врагов в пошаговой ролевой игре с механикой реального времени.",
"393380": "Squad — это тактический FPS, предлагающий аутентичный боевый опыт: реалистичные сражения, командная работа и коммуникация. Squad объединяет элементы аркадных шутеров и военого реализма в битвах на 100 игроков с участием техники и строительством укреплений.",
"435150": "Знаменитая ролевая игра от разработчиков Baldur's Gate 3. Соберите отряд. Освойте мощную боевую систему. Пригласите с собой до трех друзей, но помните, что только один из вас сможет стать богом.",
"1240440": "Halo — одна из самых культовых саг за всю историю игр — продолжает расти и развиваться! Вас ждут грандиозная кампания с открытым миром и бесплатный многопользовательский режим.",
"319630": "Эпизод 1 теперь БЕСПЛАТНО! Life is Strange — это отмеченная наградами и получившая признание критиков эпизодическая приключенческая игра, которая позволяет игроку перемотать время назад и повлиять на прошлое, настоящее и будущее.",
"477160": "Human Fall Flat — это уморительно смешной платформер в изменчивом мире снов. Играть можно одному или позвать до семи друзей, а бесплатные новые уровни станут настоящим подарком для фанатов!",
"400": "Портальная пушка, лаборатория Aperture и обещанный торт. Классика головоломок.",
"203160": "«Расхитительница гробниц» исследует напряженную историю происхождения Лары Крофт и ее пути от молодой женщины к закаленной выжившей.",
"552520": "Сразитесь с сектой фанатиков в шутере от первого лица с открытым миром. Зачищайте вражескую территорию в напряженных боях, заручившись помощью верных союзников и животных, и освободите округ Хоуп в одиночном режиме или в кооперативном режиме для 2 игроков.",
"2183900": "Обретите сверхчеловеческую мощь космодесантника. Пустите в ход смертоносные навыки и разрушительное оружие, чтобы истребить безжалостных тиранидов. Защитите Империум в ярких одиночных боях или многопользовательских режимах с видом от третьего лица.",
"812140": "В этом экшен-приключении вам предстоит изменить судьбу Древней Греции. Участвуйте в напряженных боях в море и на суше, пройдите путь от изгоя до легенды и раскройте тайны собственного прошлого.",
"518790": "Наслаждайтесь неповторимой игрой про охоту в динамичном открытом мире, реагирующем на каждое ваше действие. Выслеживайте добычу и будьте готовы к непредсказуемым встречам. Играйте в одиночку или с друзьями.",
"2694490": "Path of Exile 2 – Action RPG следующего поколения от Grinding Gear Games, с совместным режимом до шести игроков. Спустя годы после событий оригинальной Path of Exile, вы возвратитесь в мрачный мир Рэкласта и будете искать способ положить конец разрастающейся порче.",
"270880": "Ощутите мощь легендарных американских грузовиков и доставляйте разнообразные грузы по солнечной Калифорнии, песчаной Неваде и величественному Большому Каньону штата Аризона. American Truck Simulator увлечет вас в захватывающее путешествие по удивительным пейзажам и знаменитым достопримечательностям, разбросанным по всем штатам.",
"534380": "Человечество погрязло в войне с вирусом. Погрузитесь в мир, переживший зомби-апокалипсис, где паркур и боевые навыки — ключ к выживанию. Исследуйте Город при свете дня, но даже не думайте спускаться с крыш по ночам, если вам жизнь дорога.",
"2379780": "Покерная игра-«рогалик». Balatro — гипнотически увлекательная игра с построением колод, где можно использовать нестандартные покерные комбинации, находить джокеров в решающие моменты и запускать забойные, возмутительно мощные комбо.",
"883710": "Выход Resident Evil 2 состоялся в 1998 году, и теперь одна из самых знаменитых игр всех времен возвращается на современные консоли в совершенно новом облике.",
"813780": "Age of Empires II: Definitive Edition также включает в себя расширение «Последние ханы» с 3 кампаниями и 4 новыми цивилизациями. Обновления добавляют события, дополнительный контент, новые режимы игры и улучшенные возможности нового режима совместной игры!",
"1332010": "Потерявшемуся, одинокому, оторванному от семьи бродячему коту предстоит разгадать древнюю тайну, вырваться из давно заброшенного кибергорода и найти дорогу домой.",
"588650": "Dead Cells — это экшен-платформер и метроидвания с элементами рогалика. Вас ждет огромный, постоянно меняющийся замок... Если, конечно, вы сможете победить его стражей. Никаких сохранений. Убивайте, умирайте, учитесь и пробуйте снова.",
"552990": "Погрузитесь в захватывающие морские сражения и соберите армаду из более чем 800 кораблей первой половины XX века: от гигантcких линкоров до скрытных эсминцев. Меняйте облик корабля, выбирайте модернизации под ваш стиль игры и отправляйтесь в бой вместе с другими игроками!",
"379720": "Включает все 3 дополнения (Unto the Evil, Hell Followed и Bloodfall), карты, режимы и оружие, а также все нововведения, включая аркадный режим, и последнее обновление 6.66, затрагивающее сетевую игру.",
"1172380": "В ЗВЁЗДНЫЕ ВОЙНЫ Джедаи: Павший Орден, боевике с видом от третьего лица от Respawn Entertainment, вас ждут приключения галактического масштаба. Оставшемуся в одиночестве падавану необходимо завершить обучение, обрести новые способности Силы и овладеть мастерством боя на световых мечах, а главное — оставаться при этом на шаг впереди Империи.",
"444200": "Выпусти пар и снеси пару башен в бесплатном онлайн-шутере 7 на 7! Врывайся в быстрые 5–7-минутные зарубы на сотнях разных танков: от музейных Тигров и Т-34 до «ЧТО ТЫ ТАКОЕ?» на гусеницах. Катай в одиночку или с друзьями и наслаждайся плавной игрой даже на скромном железе!",
"1771300": "Захватывающий сюжетный ролевой экшен с богатым открытым миром, действие которого разворачивается в Европе XV века. Взгляните на средневековую жизнь глазами молодого Индржиха, отправившись в путешествие эпического масштаба.",
"508440": "Возглавьте войско красных и синих болванчиков из древних времен, жутких миров и сказочных земель. Создавайте симуляции битв с самой неустойчивой физикой в мире.",
"379430": "Kingdom Come: Deliverance – это захватывающая РПГ с открытым миром, которая перенесёт вас в эпическое приключение в Священную Римскую империю. Отомстите за смерть ваших родителей, сражаясь с силами вторжения, выполняйте квесты, изменяйте мир своими решениями. Исследуйте величественные замки, глубокие леса, процветающие деревни и бесчисленное множество других реалистичных локаций в средневековой Богемии!",
"1868140": "DAVE THE DIVER — это казуальная одиночная приключенческая ролевая игра, в которой вам предстоит днем исследовать глубоководные зоны и ловить рыбу, а вечером управлять суши-баром. Помогите Дэйву и его эксцентричным друзьям раскрыть тайны загадочной Синей бездны.",
"1721470": "В этом хоррор-приключении целей две — решить все головоломки и выжить. За вами будут охотиться кровожадные игрушки, обитающие на заброшенной фабрике. Используйте хвататель, чтобы манипулировать проводами и доставать до дальних предметов. Исследуйте территорию и избегайте лап монстров.",
"1057090": "Отправляйтесь в путь по бескрайним просторам сказочного мира, где вас ждут встречи с врагами-исполинами и сложные, но интересные головоломки. Пришло время узнать, что уготовано Ори судьбой.",
"262060": "Darkest Dungeon — сложная пошаговая ролевая roguelike-игра с готической атмосферой, в которой приключения персонажей сказываются на их душевном здоровье. Вам предстоит собрать, обучить и возглавить команду героев, у каждого из которых есть свои недостатки. Команду нужно будет провести по жутким лесам, опустевшим заповедникам, обрушенным склепам и другим опасным местам. Сражаться придётся не только с немыслимыми врагами, но и со стрессом, голодом, болезнями и непроглядной тьмой. Раскрывайте странные тайны и отправляйте героев в бой со страшными монстрами при помощи новой стратегической пошаговой системы боя.",
"227940": "Стреляйте, взрывайте, летайте или отдавайте приказы в бескомпромиссном бесплатном масштабном многопользовательском шутере. Тысячи игроков, множество сетевых баталий, одна необъятная мировая война. Всю славу заберет тот, кто первым захватит 15 городов.",
"1943950": "В этом исследовательском хорроре на 1-4 игроков вам предстоит пройти более 30 жутких уровней Закулисья, остерегаясь ужасающих сущностей и прочих опасностей. Попытайтесь сбежать, но вас предупредили: выжить смогут не все.",
"433340": "Slime Rancher это рассказ o Беатрикс ЛёБо, об отважном молодом фермере, которая решает провести всю оставшуюся жизнь на планете «Беспредельное Запределье», что находится тысячи световых лет от Земли. Там Беатрикс пытается заработать себе на жизнь разводом слаймов. С позитивным настроем «Надо – значит, сделаю!», твёрдостью характера и со своим надёжным рюкзаком-пылесосом наперевес Беатрикс пытается заявить о себе, сколотить состояние, избежав при том смертельной опасности, ежеминутно исходящей от полчищ непоседливых вездесущих слаймов.",
"281990": "Исследуйте полную чудес галактику в научно-фантастической глобальной стратегии от Paradox Development Studios. Знакомьтесь с инопланетянами разных рас, открывайте новые планеты, справляйтесь с неожиданными испытаниями и расширяйте границы своей империи. Ваши возможности практически безграничны.",
"1677740": "Готов к хаосу? Stumble Guys - это веселая многопользовательская игра в жанре party royale на 32 игрока! Беги, прыгай и падай на сумасшедших полосах с препятствиями, чтобы остаться последним выжившим!",
"244210": "Assetto Corsa v1.16 представляет новую трассу с лазерным сканированием Laguna Seca и 7 новых автомобилей, среди которых долгожданная Alfa Romeo Giulia Quadrifoglio! Проверьте журнал изменений для получения дополнительной информации!",
"457140": "Oxygen Not Included — симулятор космической колонии. В недрах инопланетного астероида вашему трудолюбивому экипажу предстоит постичь тонкости разных наук, дать отпор диковинным формам жизни и освоить чудеса космических технологий — таков путь к выживанию... и возможному процветанию.",
"1092790": "Inscryption – мрачное карточное приключение, в котором roguelike с составлением колод, головоломки в духе квест-комнат и психологический хоррор смешались в пропитанный кровью коктейль. А тайны написанного на картах еще мрачнее...",
"240": "Counter-Strike: Source сочетает в себе отмеченную наградами командную игру Counter-Strike с передовой технологией Source™.",
"362890": "Переживите заново Half-Life.",
"306130": "Любая легенда где-то берет начало, и в The Elder Scrolls Online она начинается с вас. Присоединяйтесь к миллионам игроков в этой многопользовательской ролевой игре и исследуйте огромный живой мир TES.",
"504230": "В платформере от создателей TowerFall Мэдлин сражается со своими демонами на пути к вершине горы Селеста. Преодолевай сотни хорошо продуманных сложностей, отыскивай тайники и постигай загадку горы.",
"1593500": "Отомстив богам Олимпа, Кратос живет в царстве скандинавских божеств и чудовищ. В этом суровом беспощадном мире он должен не только самостоятельно бороться за выживание... но и научить этому сына.",
"2622380": "ELDEN RING NIGHTREIGN — это отдельное приключение во вселенной ELDEN RING, которое подарит новые впечатления, изменив основные принципы игры.",
"1222680": "Устраивайте гонки днём и ставьте на кон всё ночью в издании Deluxe Need for Speed™ Heat — захватывающей дух игре об уличных гонках, где закон меняется с заходом солнца.",
"1671210": "Погрузитесь в историю, параллельную UNDERTALE! Сражайтесь или прокладывайте себе путь через насыщенные событиями сражения, исследуя загадочный мир вместе с очаровательными новыми и знакомыми персонажами. Главы 1–5 уже доступны, а новые планируется выпускать в виде бесплатных обновлений!",
"391220": "Издание Rise of the Tomb Raider: 20 Year Celebration включает в себя базовую версию игры и сезонный пропуск со всеми доступными дополнениями. Исследуйте поместье Крофт в новом дополнении Blood Ties и защищайте его от зомби в режиме Lara's Nightmare.",
"1167630": "Совершите идеальное ограбление в воксельном мире, не отказывая себе в разрушениях. Сносите стены, используя машины, или прокладывайте себе путь взрывчаткой. Меняйте окружающий мир под себя и дайте волю фантазии. Играйте в одиночку или в многопользовательском режиме, поддерживающем до 12 игроков.",
"8930": "Создавайте, открывайте и загружайте новые карты, сценарии, интерфейсы и многое другое, созданные игроками!",
"397540": "Всеми любимый «шутер с базиллионами лута» возвращается! Действуя в одиночку или в компании друзей, вы должны будете спасти свой дом от безжалостных психопатов, возглавляющих самую опасную секту в галактике.",
"671860": "BattleBit Remastered - это низкополигональный массовый многопользовательский FPS, поддерживающий 254 игрока на сервере. Сражайтесь на почти полностью разрушаемой карте с различными транспортными средствами!",
"220240": "Примерьте на себя роль Джейсона Броди, застрявшего на островах Рук. Исследуйте тропический открытый мир, где царит беззаконие. Используйте мощный арсенал оружия для спасения друзей и побега из этой обители безумия в знаменитом напряженном шутере от первого лица.",
"1811260": "В FIFA 23 всемирная игра становится еще лучше с технологией HyperMotion2, мужским и женским FIFA World Cup™, женскими командами, кроссплатформенной игрой** и множеством прочих возможностей.",
"220200": "В Kerbal Space Program вам предстоит руководить космической программой инопланетной расы кербалов. Создавайте собственные космические суда, основываясь на своих знаниях (или их отсутствии) законов аэродинамики и физики движения тел на орбите. Выводите корабли с кербонавтами на орбиту (желательно не погубив при этом экипаж) и отправляйте их к другим планетам, попутно конструируя наземные базы и орбитальные станции, которые помогут вам в покорении космических просторов!",
"582160": "Исследуйте Древний Египет в этом экшен-приключении. Сражайтесь с грозными врагами и раскрывайте заговоры, чтобы узнать, как возникло Братство ассасинов.",
"1665460": "Встречайте увлекательную футбольную игру, преодолевшую отметку в 1 миллиард загрузок! Играйте в eFootball™ с другими пользователями по всему миру!",
"386360": "В битве богов SMITE участвуют уже 40 миллионов игроков – присоединяйтесь! Вооружитесь молотом Тора, обращайте врагов в камень, играя за Медузу, или примерьте на себя божественные способности любого другого из более чем 100 легендарных персонажей. Станьте богом и играйте БЕСПЛАТНО уже сегодня!",
"1506830": "Заряжено футболом. EA SPORTS™ FIFA 22 приближает игру к реальности с фундаментальными улучшениями игрового процесса и инновациями во всех режимах.",
"361420": "Меняйте новые странные миры и лепите их, как глину. Постройте базу, освойте управление ресурсами, автоматизируйте производственные линии и разгадайте тайны вселенной в одиночку или с друзьями.",
"412020": "Оставьте позади руины московского метро и снова отправляйтесь в путешествие по постапокалиптическим землям России. Вас ждут большие нелинейные уровни, открытый мир и захватывающая сюжетная линия.",
"223470": "Проживите неделю из жизни «ПОСТАЛЬНОГО чувака»; несчастный обыватель, просто пытающийся выполнить некоторые дела по дому. Покупка молока, возврат просроченной библиотечной книги, получение автографа Гэри Коулмана — что может пойти не так?",
"301520": "Создавайте сумасшедших, полностью адаптируемых боевых роботов, умеющих ездить, парить, ходить и летать, в бесплатной боевой игре Robocraft. Оснастите их оружием будущего, сядьте за руль и ведите свои создания на поле боя, чтобы сразиться с другими в сетевых боях!",
"524220": "Андроиды 2B и 9S на войне с машинами. Философия, слэшер и несколько концовок.",
"1818750": "MultiVersus – это платформер-файтинг со способом распространения free-to-play, который позволяет ощутить всю глубину культовых звёзд WB благодаря почти бесконечным возможностям игры.",
"1145350": "Обуздайте тёмную магию и выйдите за пределы подземного мира, чтобы бросить вызов титану времени, в этом захватывающем продолжении титулованной игры в жанре rogue-like.",
"1716740": "Starfield — это первая за 25 лет новая игровая вселенная, созданная Bethesda Game Studios, прославленными авторами The Elder Scrolls V: Skyrim и Fallout 4.",
"323190": "Frostpunk – первая игра в жанре \"выживание общества\". Как правитель последнего города на земле вы будете управлять его жителями и инфраструктурой. Какие решения вы примете во имя выживания? Как себя поведете в переломный момент? Кем при этом станете?",
"376210": "Испытайте жестокий игровой процесс выживания в открытом мире, пытаясь остаться в живых на беспощадном острове, населенном динозаврами! Хант. Расти. Выживать.",
"1313140": "Взращивайте собственный культ в землях лжепророков, совершайте походы по таинственным уголкам леса, объединяйте вокруг себя верных последователей и несите своё слово в массы, чтобы сделать свой культ единственным.",
"1942280": "Brotato — аренный шутер с элементами «рогалика», в котором вы играете за вооруженную картофелину, дающую отпор ордам пришельцев. Берите до 6 видов оружия, выбирайте черты и предметы, придумывайте тактику и выживайте до прибытия подмоги.",
"2835570": "Сыграйте в русскую рулетку с дробовиком 12-го калибра. Играют четверо. Остается один. Поставьте на кон свою жизнь. Удачи.",
"305620": "The Long Dark - это исследовательская игра-симулятор выживания, в которой игроки-одиночки должны позаботиться о себе в ходе изучения обширных морозных необитаемых территорий, переживших геомагнитную катастрофу. Здесь нет зомби - только вы, холод и все опасности, которые вам может обеспечить мать-природа. Добро пожаловать в тихий апокалипсис!",
"1832640": "Игра представляет собой 3-в-ряд геймплей в стиле мультишного ре́ндеринга на движке UE4, в которой вам предстоит некоторые параллельные вселенные. Каждый выбор ваш будет оказывать влияние на окончание игры.",
"2195250": "EA SPORTS FC™ 24 приветствует вас во всемирной игре: вас ждет самый реалистичный футбол с технологией HyperMotionV, игровыми стилями от компании Opta и улучшенным графическим движком Frostbite™.",
"1604030": "Восстань из теней, вампир! Охота начинается.",
"219150": "Hotline Miami — это адреналиновый боевик, полный первобытной жестокости, смертельно опасных перестрелок и крышесносящих драк.",
"677620": "Splitgate - это бесплатный динамичный многопользовательский шутер, использующий управляемые игроками порталы. Этот научно-фантастический шутер переносит жанр FPS в другое измерение с его механиками порталов, открывая многомерные боевые действия. IGN описывает Splitgate как \"Halo встречает Portal”.",
"204360": "Рубите, режьте и разрушайте все, чтобы добиться победы в приключенческой двумерной аркаде-призере от компании The Behemoth!",
"387990": "Войдите в творческий рай Scrap Mechanic! Стройте фантастические машины, отправляйтесь в приключения вместе с друзьями и защищайтесь от волн злых фермерских роботов в этой творческой многопользовательской песочнице на выживание. С помощью мощных инструментов Scrap Mechanic вы сможете создавать свои собственные приключения!",
"2399830": "Арк переосмысливается с основания в этой технологии видеоигр с помощью Unreal Engine 5! Сформируйте племя, приручите и породу сотни уникальных динозавров и первобытных существ, исследуйте, создайте, строите, строите и пробитесь на вершину пищевой цепи. Ваш новый мир ждет!",
"1361210": "Отбейте город Терциум от полчищ кровожадных врагов в напряженном и брутальном шутере. Warhammer 40,000: Darktide — новая кооперативная игра от удостоенной наград команды создателей серии Vermintide. Терциум падет, отверженные восстанут.",
"516750": "My Summer Car — это идеальный симулятор владения, строительства, ремонта, настройки, обслуживания и выживания автомобилей. Вы начинаете игру с сотнями отдельных деталей и собираете машину и двигатель.",
"304390": "For Honor – инновационная командная PvP-игра с упором на ближний бой, в которой бесконечно сражаются рыцари, самураи, викинги, У Линь и многие другие. Выбирайте уникальных героев и оттачивайте навыки в боях 4x4, 2x2 и 1x1.",
"1643320": "Исследуйте Чернобыльскую Зону Отчуждения полную опасных врагов, смертельных аномалий и мощных артефактов. Напишите собственную эпическую историю, прокладывая тропы к Сердцу Чернобыля. Выбирайте свой путь обдуманно, ведь он определит вашу судьбу в конце.",
"1196590": "Испытайте survival horror, каким его еще не видели, в 8-й части легендарной серии — Resident Evil Village. Проработанная до мелочей графика, напряженная игра от первого лица и превосходное повествование сделают ужас как никогда реальным и неотвратимым.",
"1142710": "Драматический финал трилогии Total War: WARHAMMER уже здесь. Соберите войска и войдите в Царство Хаоса — обитель невообразимых ужасов, где будет решаться судьба всего мира. Обуздаете ли вы своих демонов… или же возглавите их?",
"899770": "В игре Last Epoch вас ждут путешествия во времени, захватывающие подземелья, увлекательная настройка персонажей и бесконечные возможности повторного прохождения. Эта игра в жанре «ролевой экшен» понравится как опытным игрокам, так и новичкам.",
"238320": "Журналист с камерой в психбольнице. Никакого оружия — только бег и ночное видение.",
"225540": "Вас ждет более 1000 квадратных километров свободы. Рико вернулся, чтобы устраивать беспорядки самыми изобретательными способами.",
"581320": "Insurgency: Sandstorm — суровый тактический FPS, в основе которого — смертельные бои в замкнутом пространстве и безжалостный темп. Важны каждая пуля, каждый шаг, и только командная работа позволит выжить в мясорубке современной войны.",
"1817070": "В оригинальной и захватывающей истории «MARVEL Человек-Паук. Обновленная версия» сойдутся миры Питера Паркера и Человека-паука. Сыграйте за опытного Питера Паркера, который борется с крупной преступностью и легендарными злодеями в Нью-Йорке мира Marvel.",
"1449850": "Классическое цифровое издание карточной игры, которая совершенствуется больше 20 лет! Соревнуйтесь на самых высших уровнях с игроками по всему миру.",
"570940": "…Затем появился огонь. Заново переживите события легендарной игры, с которой всё началось. В новом воплощении вас ждёт возвращение в Лордран, представленный в HD-графике с поддержкой 60 кадров/с.",
"1407200": "World of Tanks — это тактический экшен, где тип и роль техники влияют на игровой опыт. Помимо классических PvP-сражений, здесь есть соревновательные и клановые режимы, особые PvE- и PvPvE-события и многое другое. Неважно, заряжены вы на победу или играете для души — WoT вам зайдёт.",
"1304930": "Red Barrels приглашает вас испытать головокружительный ужас, на этот раз вместе с друзьями. Проходите ли вы испытания в одиночку или в команде, если вы продержитесь достаточно долго и завершите терапию, Меркофф с радостью позволит вам уйти… но останетесь ли вы прежним?",
"2709570": "Многопользовательский супермаркет бесплатно прибыл в ваш район! Заполните свое торговое пространство, откройте льготы и франшизы, наймите сотрудников или преследуйте надоедливых воров. Чем больше игроков, тем больше действий!",
"460930": "Возглавьте элитный отряд «Призраков» в тактическом шутере от третьего лица. Исследуйте огромный открытый мир. Сражайтесь с беспощадным картелем Санта-Бланка, чтобы спасти Боливию и ее народ.",
"244850": "Space Engineers — это космический sandbox, где ты строишь корабли, станции и базы, всё разрушается и перестраивается. Исследуй миры, добывай ресурсы, выживай и сражайся — сам или с друзьями, в Creative или Survival.",
"686810": "Присоединяйтесь к постоянно развивающейся игре Hell Let Loose — хардкорному шутеру от первого лица о Второй мировой войне с эпическими битвами на 100 игроков с участием пехоты, танков, артиллерии, с динамично меняющейся линией фронта и уникальной ресурсной метаигрой.",
"674940": "Stick Fight — это основанный на физике диванный онлайн-файтинг, в котором вы сражаетесь в роли культовых фигурок из золотого века Интернета.",
"848450": "Отправляйтесь в ледяное подводное приключение на чужой планете. Действие Below Zero разворачивается через два года после событий оригинальной игры Subnautica. Выживайте с суровых условиях — стройте жилища, создавайте инструменты и погружайтесь еще глубже в пучину вселенной Subnautica.",
"1203620": "Enshrouded — ролевая игра для одиночного или совместного прохождения, поощряющая креативность. Ваша главная задача — одолеть коварную Пелену, которая поглощает королевство Эмбервэйл. Изучите таинственный мир, создайте уникального героя и постройте или преобразуйте все, что хотите.",
"233860": "Отрядная ролевая игра со свободой передвижения, и акцентом на игровом процессе-песочнице с открытой концовкой, а не линейном сюжете. Торгуйте, воруйте, бунтуйте, воюйте, пуститесь в авантюру, займитесь фермерством, угодите в рабство, или на стол к людоедам.",
"447040": "Сан-Франциско ждет! Вы - Маркус, блестящий хакер, объединяетесь с DedSec, чтобы противостоять ctOS 2.0. Ваша цель - взлом века!",
"755790": "Спаситесь от ужасной катастрофы в Ring of Elysium, шутере в жанре королевской битвы, разработанном Aurora Studio.",
"2669320": "EA SPORTS FC™ 25 открывает больше возможностей побеждать за клуб. Играйте с друзьями в ваших любимых режимах в новом Rush 5 на 5. Ведите клуб к победе с FC IQ, предоставляющим больше тактического контроля.",
"219740": "Don’t Starve — это бескомпромиссная игра на выживание в дикой природе, полная науки и магии. Войдите в странный и неизведанный мир, полный странных существ, опасностей и сюрпризов. Собирайте ресурсы для создания предметов и построек, соответствующих вашему стилю выживания.",
"286690": "В 2013 году мир погрузился в пучину апокалипсиса, который уничтожил почти все человечество и превратил поверхность Земли в отравленную пустошь. Небольшая группа выживших укрылась в глубинах московского метро, и для человеческой цивилизации начался новый Темный век. Сейчас 2033 год.",
"1151640": "Разгадайте тайны Земли будущего, которой правят машины, в легендарном путешествии Элой. Используйте сокрушительные атаки против своих жертв и исследуйте прекрасный открытый мир этой знаменитой ролевой игры!",
"761890": "Albion Online - это MMORPG-песочница в фэнтезийном сеттинге, где присутствует управляемая игроками экономика, боевая система без привязки к классам и постоянные PvP-сражения.",
"383870": "Firewatch — одиночная игра-загадка от первого лица, действие которой происходит в лесах Вайоминга.",
"1158310": "Любовь, война, интриги и величие. Определите наследие своего знатного рода в безграничной глобальной стратегии Crusader Kings III. Смерть — это только начало вашего пути по истории выбранной династии в этой полной неожиданностей и славы симуляции Средних веков.",
"1687950": "Возглавьте отряд Призрачных Похитителей в красивой, отмеченной наградами пошаговой ролевой игре. Исследуйте подземелья, обдумывайте стратегию боя и проводите слияние персон. Живите в Токио, сражайтесь с тенями, проникайте в головы бесчестных негодяев и меняйте мир к лучшему!",
"219990": "Окунитесь в апокалиптический фэнтезийный мир, где человечество находится на грани вымирания, железо ценится выше золота, а доверие зарабатывается с трудом. Эта ARPG включает в себя сложное развитие персонажей, сотни уникальных предметов, крафтинг и квесты с выбором и последствиями.",
"546560": "Half-Life: Alyx — это возвращение Valve во вселенную Half-Life в виртуальной реальности. Это история невозможной борьбы с жестокой расой пришельцев, известной как Альянс. События происходят между Half-Life и Half-Life 2. Вы играете за Аликс Вэнс, и вы — единственный шанс человечества на спасение.",
"613100": "House Flipper это уникальная возможность стать командой по ремонту в лице одного человека. Покупай, ремонтируй и переделывай брошенные дома. Вдохни в них вторую жизнь и продавай для получения прибыли!",
"304050": "Хватайте друзей, оттачивайте свои клинки и отправляйтесь в эпическое процедурно-генерируемое приключение в Trove! Сражайтесь с Тенью в мирах, наполненных подземельями и предметами, созданными вашими товарищами по игре. Будь то охота за сокровищами или строительство собственных королевств, быть квадратным еще никогда не было так приятно!",
"766570": "Russian Fishing 4 - это рыболовный симулятор с элементами RPG, игровой процесс которого основан на концепции открытого мира и полной свободе действий игрока.",
"236850": "Управляйте своими землями и миром с полной свободой действий, проработанным игровым процессом и исторической точностью.",
"466240": "Deceit это проверка на доверие, а также ваших инстинктов в многопользовательском шутере от первого лица. Вы очнетесь в неизвестном месте от странного голоса вместе с пятью выжившими. Треть из вас была заражена вирусом, но кто сможет выбраться?",
"629760": "MORDHAU — многопользовательский средневековый слэшер. Создайте наемника и участвуйте в жестоких сражениях, где вас ждут напряженные бои, осады замков, кавалерийские атаки и многое другое.",
"753640": "Outer Wilds — высоко оценённая критиками, завоевавшая множество наград приключенческая игра с открытым миром, посвящённая загадкам солнечной системы во временной петле и получившая в 2019 году звание «Игры года» от Giant Bomb, Polygon, Eurogamer и The Guardian.",
"552500": "Продолжение одобренной критиками игры Vermintide — это революционная экшн-игра, что поражает своей картинкой и выводит на новый уровень кооперативные игры от первого лица. Скорее вступайте в сражение!",
"1046930": "Наймите бойцов и уничтожьте соперников в новом стратегическом автобаттлере в мире Dota 2. Представляем первый сезон: изучайте Белый Шпиль и получайте награды боевого пропуска. Играйте в различных режимах в одиночку или с друзьями. Поддерживается кроссплатформенная игра между компьютерами и мобильными устройствами.",
"418370": "Гнилые стены заброшенной фермы на американском Юге порождают чувство страха и одиночества. Седьмая часть игры с пугающей «изолированной камерой» — это новый подход к survival horror. С современным движком RE Engine ужас достигает невиданной реалистичности. Переживите новый чудовищный кошмар.",
"1454400": "Неспешная игра о выпечке печенья! Вышла в 2013 году в сети, с тех пор активно развивалась, и это ее официальная версия в Steam.",
"1217060": "Gunfire Reborn — это приключенческая многоуровневая игра с элементами ролевой игры (RPG), Roguelite и шутера от первого лица (FPS). Игроки могут управлять героями, которые обладают различными способностями, чтобы исследовать разнообразный геймплей.",
"356190": "Познакомьтесь с легендарным открытым миром, оживленным благодаря знаменитой системе \"Заклятые враги\". Создайте новое Кольцо Власти, захватывайте крепости в масштабных сражениях и правьте Мордором при помощи своей армии орков в игре Средиземье™: Тени войны™.",
"250820": "Загрузите SteamVR, чтобы играть в виртуальной реальности, используя шлемы HTC Vive, Oculus Rift, Windows Mixed Reality или любой другой шлем и контроллеры виртуальной реальности.",
"823130": "Хватай свой воздушный арбалет и верный надувной молот, потому что все скоро зашатается! Станьте последним чудаком, выжившим в ведущей в мире игре Battle Royale, основанной на физике.",
"976310": "Mortal Kombat возвращается! И это лучшая версия культовой франшизы!",
"211820": "Вы покинули свой дом и оказались затерянными в космосе с поврежденным кораблем. Ваш единственный выход — спуститься на планету внизу, отремонтировать свой корабль и отправиться исследовать вселенную...",
"232090": "Совместная мясорубка на шестерых против мутантов. А теперь и режим «Выживание VS» на 12 игроков — почувствуйте себя в шкуре мутанта!",
"646910": "Приобщитесь к американскому гоночному спорту. Покоряйте дороги, властвуйте на море и господствуйте в небе на просторах одного из самых потрясающих открытых миров в истории. Новинка: играйте в The Crew 2 как онлайн, так и офлайн в новом гибридном режиме, который доступен прямо сейчас!",
"222880": "В этой многопользовательской и кооперавтивной игре Вы сражаетесь в кровавых боях на улицах, лицом к лицу с врагом, где выживание Вашей команды зависит от контроля важных точек и уничтожения вражеских боеприпасов, все оперирующее на движке Source. Insurgency — наследник высоко оцененного одноименного мода на движке Source, высококонкурентный и беспощадный, подчеркивающий равность всех игроков.",
"335300": "DARK SOULS™ II: Scholar of the First Sin выводит свойственные серии мрачность и увлекательный процесс игры на новый уровень. Путешествуйте, сражайтесь с врагами, преодолевайте опасности и испытания.",
"594570": "Войска Люстрии ждут ваших приказаний. Выбрав одного из легендарных лордов, собирайте воинства и заключайте союзы в стратегической пошаговой кампании, чтобы затем обрушить всю мощь своей армии на врага в ураганных сражениях в реальном времени.",
"221380": "Age of Empires II теперь доступна в высоком разрешении. Данная версия перестала получать обновления после выхода Age of Empires II: Definitive Edition.",
"683320": "Грис — наивная девочка, запершаяся в собственном мире из-за боли, окутавшей ее в реальности.",
"1366540": "Постройте самую эффективную межгалактическую фабрику в стратегической игре-симуляторе космического пространства Dyson Sphere Program! Используйте силу звезд, собирайте ресурсы, планируйте и проектируйте производственные линии и развивайте свою межзвездную фабрику от небольшой космической мастерской до промышленной империи всей галактики.",
"471710": "Rec Room — идеальная среда для общения, творчества и совместных игр. Встречайтесь с друзьями со всего мира, чтобы поболтать, весело провести время вместе, исследовать МИЛЛИОНЫ комнат, созданных другими игроками, или построить что-то новое, что поразит всех нас.",
"1259420": "Сражайтесь и гоняйте по смертельно опасным дорогам постапокалиптической Америки. Играйте за Дикона Сент-Джона, номада и охотника за наградами, кочующего по разбитым дорогам в поисках смысла жизни в этом приключенческом боевике с открытым миром.",
"12120": "Пять лет назад Карл Джонсон сбежал от тягот жизни в Лос-Сантосе, Сан-Андреас... городе, разрывающемся на части из-за проблем с бандами, наркотиков и коррупции. Где кинозвезды и миллионеры изо всех сил стараются избегать дилеров и бандитов. Сейчас начало 90-х. Карлу пора домой.",
"588430": "Fallout Shelter дарит вам возможность управлять высокотехнологичным подземным убежищем от «Волт-Тек». Постройте лучшее убежище, сделайте его обитателей счастливыми, защитите их от опасностей Пустоши.",
"635260": "CarX Drift Racing Online дает вам шанс окунуться в истинный мир дрифта. Объединяйтесь с друзьями, настраивайте свой автомобиль и жгите резину!",
"359320": "Станьте капитаном звездолета и оставьте свой след в изменчивой галактике. Погрузитесь в гущу боев, освойте добычу ресурсов на астероидах, создайте свою торговую империю или отправьтесь бороздить просторы галактики, воссозданные в масштабе 1:1.",
"20900": "Ведьмак Геральт из Ривии, легендарный охотник на чудовищ, оказался в центре борьбы за мировое господство. Примерьте на себя его роль и погрузитесь в увлекательную историю, в которой вам предстоит не раз принимать сложные решения и сталкиваться с их последствиями.",
"282070": "В «This War of Mine» вы играете не за солдата элитных войск, а за группу мирных жителей, пытающихся выжить в осажденном городе, испытывая нехватку еды, лекарств и постоянную опасность со стороны снайперов и мародеров.",
"881100": "Noita — боевик с элементами «roguelike» с физическим моделированием пикселей. Вы сражаетесь, исследуете различные места, расплавляете, сжигаете, замораживаете и испаряете препятствия, используя заклинания. Можно просто исследовать всё вокруг и смотреть, сколько проблем удастся нажить!",
"703080": "Создайте идеальный мир диких животных в новом симуляторе зоопарка Planet Zoo от авторов Planet Coaster и Zoo Tycoon. Управляйте зоопарком и тщательно воссоздавайте среду обитания животных, в которой им будет комфортно и интересно жить.",
"1446780": "Готовьтесь: настало время охоты! В Monster Hunter Rise — новой игре всемирно известного бестселлера Monster Hunter — вас ждет история, в которой вы станете охотником и отправитесь исследовать невиданные прежде карты и расправляться с кровожадными монстрами с помощью целого арсенала оружия.",
"20920": "Пришло время невиданного хаоса. Могущественные силы сталкиваются в борьбе за власть и величие. Северные королевства готовятся к войне. Но даже армии не могут помешать этому заговору, и прольётся кровь…",
"291480": "Warface: Clutch — современный ММО-шутер от первого лица. Динамичное PvP с различными режимами, захватывающие PvE-миссии и рейды, в которых вы можете испытать себя, ждут вас. Играйте за пять разных классов, каждый из которых обладает огромным настраиваемым арсеналом.",
"550650": "Black Squad — бесплатный военный шутер от первого лица. Игроки могут совершенствовать свои навыки и демонстрировать свои стратегии, используя широкий выбор игровых карт, режимов и оружия на выбор. Присоединяйтесь к тысячам игроков в шутеры от первого лица по всему миру в одной из самых популярных игр в Steam!",
"815370": "Боритесь за жизнь в открытом мире суровых джунглей Амазонии. Задействуйте реальные методы выживания: собирайте ресурсы, добывайте пищу, сражайтесь с представителями местной фауны, обустройте временное жилище или возведите настоящую крепость.",
"1774580": "История Кэла Кестиса продолжается в игре STAR WARS Jedi: Survivor™ — приключенческом экшне галактического масштаба с видом от третьего лица.",
"397900": "\"Бизнес Тур\" - бесплатная настольная онлайн игра. Собирай монополию. Выполняй ежедневные задания, участвуй в соревнованиях среди других игроков, а после выгодно обменивай полученные награды. Покупайте участки и собирайте с них ренту, приведите своих конкурентов к банкротству!",
"268500": "XCOM2 - это продолжение признанной игроками и критиками стратегии XCOM: Enemy Unknown. Двадцать лет минуло с тех пор, как человечество проиграло войну с захватчиками из другого мира, и на Земле теперь царит новый порядок. После лет работы в подполье, остаткам XCOM предстоит восстать из пепла и сокрушить врага.",
"1150690": "Исследуйте странный мир, полный ярких друзей и врагов. Когда придет время, выбранный вами путь определит вашу судьбу... и, возможно, судьбу других тоже.",
"2670630": "Управляйте собственным супермаркетом! Заполняйте полки, устанавливайте цены, принимайте платежи, нанимайте персонал, расширяйте магазин, боритесь с кражами и проектируйте планировку. Покупайте товары онлайн или на местных рынках и лично доставляйте онлайн-заказы вашим клиентам.",
"289650": "Париж, 1789 год. В этом экшен-приключении вам предстоит увидеть Французскую революцию глазами Арно Дориана. Станьте ассасином и выясните, кто на самом деле стоит за революцией, которой суждено определить судьбу целого народа.",
"977950": "«Танец огня и льда» (АДОФАИ) – игра со строгим ритмом. Сосредоточьтесь, ведя две вращающиеся планеты по извилистой траектории, не нарушая их идеального равновесия.",
"311690": "Enter the Gungeon - игра жанра “пулевая завеса в подземелье”, в которой ищущие спасения неудачники стреляют, грабят, перекатываются и опрокидывают столы, чтобы добраться до легендарного сокровища Оружелья: оружия, которое может убить прошлое.",
"2001120": "Испытайте ошеломительные моменты, погружаясь в разнообразные миры Split Fiction, новаторского совместного приключения.",
"254700": "(Выпуск: 2014 г.) Специальный агент Леон С. Кеннеди отправляется с миссией по спасению похищенной дочери президента США.",
"39210": "Присоединяйтесь к более чем 30 миллионам искателей приключений по всему миру и примите участие в эпической и постоянно меняющейся FINAL FANTASY. Насладитесь незабываемой историей, захватывающими битвами и множеством захватывающих локаций для исследования.",
"2054970": "Dragon's Dogma 2 — это однопользовательская ролевая игра, где игрок может выбрать практически все: внешность своего Восставшего, профессию, партию, решения в различных ситуациях и многое другое. Погрузитесь в захватывающий фэнтезийный мир.",
"1151340": "Спустя четверть века после ядерной бомбардировки вы и другие обитатели Убежища наконец выбираетесь на поверхность. Исследуйте постапокалиптическую Америку, стройте поселения, выполняйте задания и побеждайте врагов вместе с миллионами игроков в многопользовательской игре с открытым миром.",
"211420": "По мере прохождения игры уровень сложности будет повышаться, так что Dark Souls станет для вас самым серьезным игровым испытанием в этом году. Сможете ли вы пережить тысячи смертей и увековечить свое наследие?",
"1363080": "Manor Lords — средневековая градостроительная стратегия с масштабными битвами и развитыми системами экономики и общественной жизни. Управляйте землями в мире, где меняется не только погода, но и сезоны, а города растут и приходят в упадок.",
"380600": "Fishing Planet® — это высокореалистичный многопользовательский онлайн-симулятор рыбалки от первого лица. Разработан заядлыми любителями рыбалки, чтобы подарить вам острые ощущения от настоящей рыбалки на вашем ПК. Играйте бесплатно — достаточно просто скачать!",
"365590": "Тактический шутер от третьего лица в открытом мире, показывающем Нью-Йорк после страшной пандемии. С друзьями или в одиночку восстановите порядок, сражаясь с опасными фракциями, собирайте трофеи и проходите рискованные испытания для персонажей высокого уровня.",
"224260": "Шансы на то, что вы выживете в этой войне между обществом и нежитью, равны нулю. Уже сейчас миллионы ходячих мертвецов бродят вокруг в поисках еды. Не существует известного лечения. Один укус может положить конец всему для вас. Однако вы не одиноки в этом кошмаре. В этой богом забытой адской дыре все еще осталось несколько незараженных выживших, и благодаря сотрудничеству и командной работе вы сможете прожить достаточно долго, чтобы пробиться к спасению.",
"636480": "Сражайтесь на Равенфилде вместе со своими союзниками-орлами! Уничтожьте этих надоедливых Воронов, используя вертолеты, танки, пушки и активную физику тряпичной куклы!",
"295110": "Just Survive — это постапокалиптическая игра на выживание, которая погружает вас в мир, где человечество борется за то, чтобы вернуть контроль над ордами зомби.",
"962130": "Мир — огромное, красивое и опасное место, особенно когда вы уменьшились до размеров муравья. Сможете ли вы выжить вместе с полчищами гигантских насекомых, борясь за выживание в опасностях заднего двора?",
"1286830": "Star Wars™: The Old Republic™ — это бесплатная MMORPG, в которой вы будете в центре своей собственной истории. Примерьте на себя роль джедая, ситха, охотника за головами или другую легендарную роль во вселенной «Звёздных Войн» в далекой-далекой галактике за 3000 лет до событий классических фильмов.",
"240720": "Я создал эту игру для определенного круга лиц. Чтобы заставить их страдать.",
"218230": "PlanetSide 2 — это крупномасштабная планетарная война, где тысячи игроков сражаются единым фронтом на огромных континентах. Используйте пехоту, наземный и воздушный транспорт, а также командную работу, чтобы разгромить врагов в этом революционном, масштабном шутере от первого лица.",
"203770": "Исследуйте один из определяющих периодов мировой истории в игре, созданной мастерами Великой стратегии.",
"239030": "Инспектор на границе тоталитарного государства. Слава Арстотцке!",
"287700": "Перейдите в новую эру франшизы с передовыми технологиями, работу которых обеспечивает графический процессор Fox Engine. Игроков ожидает масса положительных эмоций, поскольку теперь им будет предоставлена свобода выбора тактики в миссиях в открытом мире.",
"2881650": "Снимайте жуткие штуки с друзьями и загружайте видео с ними на SpöökTube, чтобы прославиться! Осторожно, вылазки в одиночку не рекомендуются!",
"1466860": "Уже целый год отмеченная наградами и ставшая бестселлером стратегия Age of Empires IV радует миллионы фанатов серии по всему миру. Новое юбилейное издание перенесет вас в эпицентр великих исторических сражений, навсегда изменивших судьбу мира.",
"287390": "2034 год. Под руинами постапокалиптической Москвы, в туннелях метро, остатки человечества противостоят смертельной угрозе как извне, так и внутри. Мутанты бродят по катакомбам под пустынной землей и выискивают жертв под ядовитым небом.",
"750920": "Спасая мир от апокалипсиса, предсказанного майя, она пройдет немало испытаний и выполнит свое предназначение, став настоящей расхитительницей гробниц.",
"349040": "Вас ждут захватывающие и красочные приключения в последней части прославленной серии STORM! Воспользуйтесь полностью обновленной боевой системой и приготовьтесь к самым зрелищным боям, которые вам только доводилось видеть!",
"242050": "Откройте для себя Assassin's Creed IV: Черный флаг – знаменитое пиратское экшен-приключение из 2013 года. Командуйте кораблем, выслеживайте тамплиеров и пишите собственную историю в роли Эдварда Кенуэя в Золотой век пиратства в Карибском море.",
"1113000": "История взросления, в которой главный герой и его друзья отправляются в путешествие, начало которому положила цепочка серийных убийств.",
"307690": "Sleeping Dogs™ Definitive Edition для нового поколения представляет собой переработанное и обновленное издание известного приключенческого боевика с открытым миром, получившего множество наград наряду с признанием критиков. Гонконг ощущается как никогда живым благодаря ранее выпущенным дополнениям, а также множеству новых технических и визуальных улучшений. Вам предстоит играть за Вэй Шеня — отлично натренированного полицейского под прикрытием, получившего задание устранить триады изнутри. Экзотический Гонконг станет для вас непревзойденной игровой площадкой: подчиняйте себе его оживленные улицы, участвуя в будоражащих кровь незаконных уличных гонках, и устраняйте противников в жестоких подземных бойцовских клубах. Когда вы под прикрытием, правила меняются.",
"2479810": "Тактический шутер в открытом мире с акцентом на PvE. Место действия: закрытый остров в Юго-Восточной Азии, раздираемый фракционной войной. Стань элитным бойцом и сражайся в одиночку или в отряде. Тебя ждут задания, репутация и поиски правды о Происшествии, породившем этот конфликт.",
"1250410": "Спасибо поклонникам! Microsoft Flight Simulator Game of the Year Edition добавляет в игру 5 самолётов, 8 созданных вручную аэропортов, 6 экскурсионных полётов, новые курсы и обновления системы погоды. Издание бесплатно для владельцев основной игры. Небо зовёт!",
"386180": "CROSSOUT Remastered - постапокалиптический MMO-экшн, где вы можете собрать из множества деталей бронемашину уникального дизайна, а затем сразиться на ней в жарких многопользовательских боях в воздухе и на земле.",
"304430": "Гонимый и одинокий, мальчик оказывается в самом центре мрачного проекта.",
"274170": "Hotline Miami 2: Wrong Number — это жестокое завершение саги Hotline Miami, действие которого происходит на фоне эскалации насилия и возмездия за пролитую кровь в оригинальной игре.",
"206440": "Игровой опыт про двух врачей, путешествующих по воспоминаниям умирающего мужчины, в попытке искусственно исполнить его последнее желание.",
"1238860": "Доминируйте на поле боя с материалами Premium",
"1248130": "Создайте свою ферму и начинайте растить! Собирайте урожай, ухаживайте за животными, распределяйте продукцию и проходите сезонные испытания.",
"1284190": "Симулятор выживания на безжизненной планете с терраформированием, созданием предметов и открытым миром для 1-10 игроков. Сделайте бесплодную планету пригодной для заселения. Постройте базу и создайте биосферу, начав с кислорода, тепла и давления.",
"620980": "Забивайте ритмы, двигайтесь и испытайте самую популярную в мире ритм-игру в виртуальной реальности!* Приседайте, уклоняйтесь и слушайте более 300 песен, созданных вручную от таких исполнителей, как Coldplay, Imagine Dragons и Metallica. Играйте в одиночку, соревнуйтесь онлайн или передайте гарнитуру на следующей вечеринке. Включите более 60 песен!",
"298110": "Сразитесь за свободу истерзанных войной Гималаев в шутере от первого лица с открытым миром. Пользуйтесь смертоносным арсеналом, контролируйте землю и небо с помощью гирокоптеров и боевых слонов и захватывайте вражескую территорию в одиночной игре или кооперативном режиме.",
"231430": "Оцените единую платформу для стратегических игр по мотивам Второй мировой! Этот комплект включает в себя игру COH 2 и может быть расширен путем покупки независимых дополнений \"Армии Западного фронта\", \"Наступление в Арденнах\" и/или \"Британские войска\". Подробнее см. ниже.",
"2406770": "Bodycam — это первый тактический многопользовательский шутер от первого лица с настоящим обзором с нательной камеры на движке Unreal Engine 5. Ближние бои кажутся резкими и громкими. Каждый ракурс, выноска и пуля имеют значение. Играйте в Deathmatch, Team Deathmatch и Wingman на фотореалистичных.",
"389730": "Любовь, месть, гордость. В созданной на основе движка Unreal Engine 4 игре TEKKEN 7 вас ждут красивейшие сюжетные битвы и поединки, в которых можно сражаться как с друзьями, так и соперниками.",
"205100": "Dishonored — это насыщенный экшен от первого лица, в котором вам предстоит вжиться в роль убийцы, чьими поступками движет жажда мести.",
"1888930": "Откройте для себя знаменитую игру, которая легла в основу отмеченного критиками телешоу. Помогите Джоэлу и Элли пробраться через все опасности постапокалиптической Америки, встречаясь с незабываемыми союзниками и врагами в «Одни из нас»™.",
"1888160": "Новый боевик, в котором концепция серии ARMORED CORE получила современное развитие за счёт знаний, накопленных компанией FromSoftware за время разработки игр этого жанра.",
"17390": "Станьте архитектором своей собственной вселенной в Spore, захватывающем приключении для одного игрока. От Одноклеточного до Галактического Бога — развивайте свое существо во вселенной, созданной вами самими.",
"1371980": "Компания Moon Studios, удостоенная многочисленных наград за Ori and the Blind Forest и Ori and the Will of the Wisps, представляет No Rest for the Wicked — динамичную и бескомпромиссную ролевую игру, которой предстоит сказать новое слово в жанре.",
"414340": "Новая игра от создателей Heavenly Sword, Enslaved: Odyssey to the West и DmC: Devil May Cry о путешествии в глубины легенд и безумия. В эпоху викингов измученная кельтская воительница отправляется в ужасную страну мертвых, чтобы сразиться за душу погибшего возлюбленного.",
"2231450": "Pizza Tower — это энергичный 2D-платформер, завязанный на движении, исследовании и комбо-атаках. Он отличается стилизованным пиксель-артом, который вдохновлен мультфильмами 90-х, и задорной музыкой.",
"460950": "Katana ZERO представляет из себя ураганный неонуарный экшн-платформер с мгновенной смертью. Рубите, уворачивайтесь и управляйте временем, разгадывая секреты собственного прошлого.",
"2215430": "Грядёт великий шторм. Пройдите весь путь Призрака в полной режиссёрской версии игры «Призрак Цусимы» на ПК. Приключенческий боевик в открытом мире предлагает вам увидеть все чудеса острова. Над игрой работали Sucker Punch Productions, Nixxes Software и PlayStation Studios.",
"747660": "В игре Five Nights at Freddy’s: Security Breach вам предстоит проследить за судьбой мальчика Грегори, оказавшегося запертым на ночь в Мега-пицца-плексе Фредди Фазбера. Грегори придется заручиться поддержкой самого Фредди, чтобы раскрыть тайны пицца-плекса, узнать правду и дожить до рассвета.",
"489520": "Динамичный гибрид Коллекционной карточной игры и Башенной защиты. Играй 1 на 1 - или 2 на 2 - и участвуй в динамичных боях наполненных инновационными стратегиями и хитрыми приемами! Собери 200+ карт с уникальными механиками.",
"949230": "Выстройте с нуля процветающий мегаполис в реалистичном симуляторе с живой экономикой и невероятно глубокой проработкой мира.",
"787860": "Разошедшаяся мультимиллионным тиражом франшиза совершает в 2018-м году огромный прыжок вперед после полной ревизии графического движка наряду со всестороннейшим опытом ведения сельхоздеятельности.",
"752590": "Отправляйтесь в путешествие вместе с Амицией и ее младшим братом Гуго.",
"1693980": "Классический научно-популярный хоррор с элементами выживания возвращается: игра была воссоздана с нуля и предлагает ещё глубже погрузиться в обволакивающую атмосферу мёртвого космоса. Ремейк обладает усовершенствованной графикой, звуком и игровым процессом, и при этом сохраняет канву оригинала.",
"241930": "Выясните всю правду о том, кто стремится подчинить вас своей воле. Разузнайте о кольцах власти и бросьте вызов Саурону в новой главе летописи Средиземья.",
"1328670": "Mass Effect™ издание Legendary содержит весь контент и около 40 загружаемых материалов из ставших классикой игр Mass Effect, Mass Effect 2 и Mass Effect 3, а также оружие, броню и наборы из рекламных предложений. Издание оптимизировано под разрешение 4K Ultra HD.",
"387290": "«Ори и слепой лес» рассказывает историю юного сироты, которому суждено стать героем, в потрясающем визуальном платформере, созданном Moon Studios.",
"779340": "Объедините под своей властью Древний Китай в захватывающей пошаговой стратегии с битвами в реальном времени. Используйте систему Гуаньси и дипломатию для формирования союзов, а затем собирайте могучие армии из сотен уникальных отрядов, среди которых есть как пехота и конница, так и боевые машины.",
"582660": "В Black Desert Online играют более 20 миллионов искателей приключений. Это MMORPG с открытым миром. Примите участие в напряженных, насыщенных событиями боях, сражайтесь с огромными мировыми боссами, сражайтесь вместе с друзьями, осаждав и захватывая замки, а также обучайтесь таким профессиям, как рыбалка, торговля, ремесло, кулинария и многое другое!",
"35140": "Почувствуйте, каково это – быть Бэтменом, и сразитесь лицом к лицу с величайшими злодеями Готэма. Исследуйте каждый дюйм лечебницы Аркхем и свободно передвигайтесь по печально известному острову.",
"212680": "Этот «двумерный симулятор космического корабля» отправит ваш корабль и экипаж в полное славы и горьких поражений путешествие через случайным образом генерируемую галактику.",
"871720": "Добро пожаловать в потрясающую коллажную игру FNAF, включающую 50 выбираемых персонажей и настраиваемые уровни сложности!",
"728880": "Overcooked возвращается с новой порцией безумной кулинарии! Вы снова отправитесь в Луковое королевство и соберете команду поваров, чтобы участвовать в классической локальной или сетевой совместной игре, в которую могут играть до 4 человек. Хватайтесь за фартуки — пришло время (снова) спасать мир!",
"602960": "Barotrauma — многопользовательский космический 2D-симулятор подлодки с элементами survival horror и RPG. Управляйте подлодкой, выполняйте миссии, сражайтесь с монстрами, устраняйте протечки и будьте очень внимательны: опасность в игре подкрадывается незаметно!",
"363970": "Знаете, что такое квадриллион урона в секунду? Отправляйтесь в путешествие, и узнаете!",
"2344520": "Вступите в бой за Санктуарий в знаменитой экшн-RPG Diablo® IV. Погрузитесь в получившую признание игроков сюжетную кампанию и исследуйте новый сезонный контент.",
"424370": "Прокладывайте свой путь в этой игре Hack’n’Slash, свободной от классовых границ. Очистите мир, разрушенный коррупцией, и раскройте мрачные тайны и забытые ужасы, скрывающиеся в тенях этой заброшенной земли, по мере того, как вы обретете Силу. Ваш Внутренний аспект манит — ответите ли вы?",
"346900": "Добро пожаловать, энергичный молодой инвестор, в AdVenture Capitalist! Пожалуй, лучший в мире симулятор капитализма!",
"1089350": "ПРИМЕЧАНИЕ: все серверы сетевого режима игры NBA 2K20 будут отключены 31.12.2021. Начиная с этого времени все функции игры, требующие соединения с онлайн-серверами, станут недоступны.",
"1659040": "Войдите в мир наемных убийц. «HITMAN: Мир наемных убийц» включает все лучшее из HITMAN, HITMAN 2 и HITMAN 3, в том числе основную кампанию, режим контрактов, обострения, аркадные контракты на неуловимую цель и режим в стиле roguelike «HITMAN: Фрилансер».",
"2623190": "Взгляните на Сиродил по-новому, приобретя The Elder Scrolls IV: Oblivion™ Remastered, где вас ждут обновленная графика и доработанный игровой процесс.",
"420530": "OneShot – это сюрреалистическая приключенческая игра-головоломка с видом сверху и уникальными игровыми возможностями. Вам предстоит провести ребенка по загадочному миру с целью возродить давно погибшее солнце. Мир знает о вашем существовании.",
"233450": "С самыми безжалостными преступниками планеты справится только по-настоящему безжалостный начальник. В Prison Architect вы сможете создать исправительное заведение по собственному вкусу.",
"246620": "Plague Inc: Evolved - уникальная смесь стратегии и пугающе реалистичной симуляции. Ваш возбудитель инфекции только что заразил \"Нулевого Пациента\" - теперь вы должны положить конец человеческой истории, развивая смертельно опасную и вездесущую Болезнь и адаптируясь под любые попытки человечества защитить себя.",
"1404210": "Вы сможете ловить преступников, сражаться с бандитами и другими игроками, охотиться, рыбачить, торговать, искать сокровища, производить самогон – и это далеко не полный перечень доступных занятий.",
"1627720": "Lies of P — захватывающая игра в жанре soulslike, в которой знакомый сюжет сказки «Пиноккио» развернется в мрачных, но элегантных декорациях Прекрасной эпохи.",
"495420": "Мертвые ожили, а цивилизация пала. В этой игре, сочетающей в себе элементы боевика, стратегии и симулятора, вашей небольшой группе выживших необходимо собирать ресурсы для постройки такой базы, которая устоит перед полчищами ходячих мертвецов.",
"493340": "Planet Coaster® — будущее игр-симуляторов горок уже наступило! Удивляйте, восхищайте и волнуйте невероятные толпы, строя свою империю горок. Дайте волю своему воображению и поделитесь своим успехом со всем миром.",
"760160": "Bloodhunt — это будоражащая кровь бесплатная «королевская битва» в раздираемой войной вампирских кланов Праге. Используйте оружие, сверхъестественные силы и хитрость, чтобы охотиться на соперников и властвовать в ночи!",
"504370": "BATTLERITE — это игра жанра TAB (Team Arena Brawler), смесь шутера с видом сверху и файтинга. Вместе с друзьями брось вызов врагам, и пусть победит тот, чья реакция быстрее. Арена ждёт!",
"629730": "Blade & Sorcery — это средневековое фэнтези, созданное для виртуальной реальности, с полностью физически управляемым рукопашным, дальним и магическим боем. Станьте могущественным воином, рейнджером или колдуном и опустошите своих врагов.",
"33230": "Эпическая история семьи, мести и заговора, действие которой разворачивается в первозданной, но жестокой обстановке Италии эпохи Возрождения. Новая низкая цена!",
"234140": "Играйте за Безумного Макса, непрогибаемого героя и настоящего бойца, единственное чего он хочет - оставить безумие позади и найти покой.",
"206420": "Насладитесь безумием Saints Row IV. Святые прошли долгий тяжелый путь от пентхауса до Белого дома, но теперь Земля оказалась под гнетом инопланетян, и только вам под силу спасти ее с помощью арсенала суперспособностей и необычного оружия в самой безумной игре с открытым миром.",
"3146520": "WEBFISHING — многопользовательская игра о рыбалке, ориентированная на чат! Расслабьтесь и ловите рыбу (в сети!)",
"333930": "Действуйте сообща или умрите в одиночестве! Восстановите мир в Лондоне или уничтожьте его в самом жестоком командном шутере всех времен.",
"1260320": "Сражайтесь с друзьями в роли щенков, котят и других пушистых существ в PARTY ANIMALS! Разберитесь с друзьями в сети и офлайн. Взаимодействуйте с миром при помощи нашего реалистичного движка. Я уже упоминал ЩЕНКОВ?",
"838350": "«The Scroll of Taiwu» — это инди-игра, основанная на китайской мифологии и уся. Игроки берут на себя роль таинственного «наследника клана Тайу» в альтернативном древнем Китае, работая через поколения наследников, чтобы победить могущественного наследственного врага и определить судьбу человеческого мира.",
"1149460": "ICARUS - это сеансовая PvE-игра на выживание, в которую могут играть до восьми игроков. Исследуйте суровые просторы чужой планеты, где когда-то была предпринята неудачная попытка терраформирования. Ваша задача - добыть экзотику и вернуться на орбиту для разработки более совершенного оборудования.",
"200260": "Получите игру «Batman: Аркхем Сити» и весь загружаемый контент по низкой цене с выходом GOTY-издания!",
"50300": "Военный шутер от третьего лица, созданный, чтобы поставить игрока перед тяжелым моральным выбором в обстановке неописуемого кошмара.",
"1089980": "Путь выбора, где терпеть неудачу веселее, чем добиваться успеха.",
"813820": "Станьте лучшим чемпионом в Realm Royale! Наделите вашего персонажа смертоносными способностями и оружием. Исследуйте волшебный мир верхом и спаситесь от губительного тумана. Вас ждет впечатляющая королевская битва с участием 100 игроков!",
"238460": "Играйте в одиночку или с друзьями, чтобы освободить пленников! Прыгайте, решайте головоломки и сражайтесь в загадочном театре, населенном высокотехнологичными кошками, которые постараются доставить вам как можно больше хлопот!",
"204100": "Служба в полиции осталась для Макса позади. В надежде порвать с прошлым он переезжает из Нью-Йорка в Сан-Паулу и устраивается телохранителем в богатую семью. В полное издание Max Payne 3 входит сама игра и все загружаемые дополнения для нее.",
"1313860": "Футбол возвращается вместе с EA SPORTS™ FIFA 21. Теперь у вас будет еще больше возможностей играть вместе на улицах и на стадионах и одерживать главные победы вместе с друзьями.",
"2567870": "Из глубин ада, взбирайтесь, прикованными к цепи, с друзьями через разнообразные миры. В одиночку или в кооперативе, попытайтесь достичь вершины и узнать, что вас там ждет...",
"285900": "Gang Beasts — это глупая многопользовательская игра для вечеринок с угрюмыми студенистыми персонажами, жестокими сценами фарса и абсурдными опасными условиями, действие которых происходит на грязных улицах Биф-Сити.",
"924970": "Back 4 Blood – это захватывающий кооперативный шутер от первого лица от создателей признанной критиками франшизы Left 4 Dead.",
"678950": "В DRAGON BALL FIGHTERZ есть зрелищные бои и могучие воины. Созданная совместно с Arc System Works, DRAGON BALL FIGHTERZ — это безупречная графика в стиле аниме и сложный, но понятный игровой процесс.",
"573090": "Присоединитесь к миру, где вы управляете собственной поисково-спасательной службой, моделируя и создавая транспортные средства. Сражайтесь с яростными бурями и спасайте нуждающихся в вашей помощи. Stormworks: Build and Rescue - это богатая и эффектная песочница.",
"265930": "Goat Simulator — это новейшая высокотехнологичная технология моделирования козла.",
"312660": "Откройте для себя свободу снайперской стрельбы в самом передовом шутере всех времен, действие которого проходит во время Второй мировой войны. Вас ждут тактические бои с видом от третьего лица, выбор геймплея и невероятные дальние выстрелы в ходе кампании по освобождению Италии от ига фашизма.",
"466560": "Northgard: Definitive Edition — тепло принятая критиками стратегия в реальном времени, вдохновлённая скандинавской мифологией. Возглавьте свой клан, откройте тайны загадочного нового континента и победите врагов, чтобы завоевать трон!",
"674020": "World War 3 – это бесплатный тактический онлайн-шутер от первого лица, в котором вашим полем битвы будет весь мир. Побеждайте в ураганных перестрелках, используя огромный арсенал оружия, техники, гаджетов и беспилотников.",
"552100": "Делайте всё, что хотите, в физической песочнице, полной хаотичных разрушений, бесконечных творений игроков и непредсказуемых приключений. Стройте, разрушайте, отыгрывайте роли и просто дурачьтесь — в одиночку или с друзьями!",
"2551020": "Однорукий грабитель — это хаотичная игра об ограблениях от первого лица, в центре которой лежит уникально сложная предпосылка. Игроки берут на себя роль решительного грабителя, вооруженного только одной рукой, которому поручено совершать дерзкие ограбления банков, магазинов и различных учреждений.",
"207610": "Приключенческий хоррор в пяти частях, действие которого происходит во вселенной, созданной Робертом Киркманом - автором серии комиксов, удостоившихся различных наград.",
"319510": "Добро пожаловать на новую летнюю работу в пиццерию Freddy Fazbear's Pizza, куда дети и родители приходят за развлечениями и едой! Главной достопримечательностью, конечно же, является Фредди Фазбир; и двое его друзей. Это роботы-аниматроны, запрограммированные радовать толпу! Однако поведение роботов ночью стало несколько непредсказуемым, и ваша задача — следить за ними!",
"568220": "Симулятор управления монстрами в жанре roguelite, вдохновленный такими играми, как The SCP Foundation, Cabin in the Woods и Warehouse 13. Прикажите своим сотрудникам выполнять работу с существами и наблюдайте, как она разворачивается; использовать больше энергии и расширять объект",
"1533390": "Бегайте, прыгайте и карабкайтесь, используя только руки. Играйте в теги или заражайте людей онлайн. Убегайте от зараженных игроков или перехитрите выживших, чтобы поймать их. Обнимите свою внутреннюю обезьяну.",
"1874880": "Участвуйте в масштабных общевойсковых сражениях, создавайте миссии и управляйте ими в реальном времени, а также опробуйте неисчислимые модификации сообщества. Погрузитесь в эпоху холодной войны и испытайте самую реалистичную военную песочницу.",
"870780": "Полное издание игры CONTROL содержит основную игру и ранее выпущенные расширения «Основание» и «АМС» - в одном пакете по выгодной цене.",
"409710": "Боевик BioShock уникален в своем жанре – такого оружия и боевых приемов вы еще не видели. К вашим услугам богатейший арсенал – от простых револьверов до ракетниц и химических распылителей, но вам придется еще и генетически модифицировать свою ДНК, чтобы создать самое совершенное оружие – себя.",
"221040": "«Resident Evil 6» — это потрясающая смесь экшена и хоррора, которая обещает стать самым сильным произведением в жанре ужасов 2013 года.",
"544810": "KARDS, карточная игра в сеттинге Второй мировой войны, сочетает в себе традиционный игровой процесс ККИ с инновационными механиками, вдохновлёнными классическими стратегиями и реальной тактикой боя.",
"424840": "Little Nightmares – это мрачная сказка, которая заставит вас вспомнить свои детские кошмары. Помогите Шестой выбраться из Чрева – подводного судна, полного жутких существ, ищущих, чем бы поживиться.",
"1206560": "WorldBox - это АБСОЛЮТНЫЙ симулятор бога и песочница. Создавайте свои миры или разрушайте их, используя различные силы. Наблюдайте, как растут цивилизации, создаются королевства и колонизируются новые земли. Города восстанут, империи падут. Вам выбирать - помогать им или смотреть, как они сражаются.",
"1850570": "Легендарный творец Хидэо Кодзима представляет окончательную версию DIRECTOR’S CUT знаковой для жанра игры. Действуя от лица Сэма Бриджеса и объединяя последних выживших на территории Америки, вам предстоит возродить надежду человечества. Удастся ли вам шаг за шагом воссоединить разрушенный мир?",
"1364780": "Новый «Боец» от Capcom! Релиз Street Fighter™ 6 состоится 2 июня 2023 года по всему миру. Это настоящая эволюция игровой серии Street Fighter™! Три режима: «Чемпионат мира», «Поле боя» и «Центр сражений».",
"1919590": "Будьте на высоте в NBA 2K23. Проявите себя в режиме MyCAREER. Объедините сегодняшних звезд и неподвластных времени легенд в MyTEAM. Создайте свою собственную династию в MyGM или поведите NBA в новом направлении в MyLEAGUE. Сразитесь с командами NBA или WNBA в режиме PLAY NOW и насладитесь реалистичным игровым процессом.",
"261570": "Ori and the Blind Forest рассказывает о судьбе юного сироты, которому предначертана судьба героя, в невероятно красочном экшн-платформере, разработанном Moon Studios для ПК.",
"1621690": "Исследуйте бескрайнее подземелье, полное существ, реликвий и ресурсов в приключенческой песочнице. Добывайте ресурсы, сражайтесь, изготавливайте предметы, выращивайте еду в одиночку или в компании до 8 игроков и раскройте тайну древнего Ядра.",
"1290000": "Сбросьте давление вместе с игрой PowerWash Simulator! Смойте свои проблемы под успокаивающий звук водяной струи. Включите автоматическую мойку и с облегчением избавьтесь от грязи и старых пятен - насладитесь простым удовольствием, которое возникает, когда отчищаешь вещь до блеска.",
"431240": "Для чего нужны друзья, как не для того, чтобы играть с ними в гольф... в Golf With Your Friends! Забудьте о границах и почувствуйте драйв, играя в захватывающий динамичный синхронный мини-гольф компанией до 12 игроков!",
"1147560": "Помогите скелету Скалу в одиночку расправиться с императорской армией и спасти своего короля из плена в игре на все времена — остросюжетном 2D-платформере в жанре rogue-lite.",
"243470": "В сегодняшнем гиперсвязанном мире Чикаго работает под управлением ctOS, самой современной компьютерной сети в Америке.",
"1790600": "DRAGON BALL: Sparking! ZERO — продолжение легендарной серии Budokai Tenkaichi с уникальными механиками и динамичным игровым процессом. Овладейте невероятной мощью сильнейших бойцов Dragon Ball!",
"860510": "Little Nightmares II — приключенческая игра с нагнетанием саспенса. Вы играете за мальчика Моно, попавшего в мир, деформированный злой Передачей. С новой подругой Шестой он пытается найти ее источник.",
"1419170": "Погрузитесь в музыкальный мир My Singing Monsters🎵Разводите монстров, кормите их и слушайте, как они поют! Исследуйте огромный фантастический мир, в уголках которого проживают бесчисленные сочетания странных и забавных монстров и отовсюду льется музыка. В мире монстров вам ни на скучно.",
"1846380": "Покорите вершину без шума и пыли. Перехитрите копов и участвуйте в еженедельных квалификационных заездах, чтобы добраться до Гранд-заезда — главной уличной гонки. Заполните свой гараж уникальными модифицированными машинами и покажите на улицах класс.",
"203140": "Легендарный киллер возвращается! Преданный Агентством и затравленный полицией, Агент 47 ищет искупления в испорченном и изуродованном мире.",
"1272080": "PAYDAY 3 — это кооперативный шутер от первого лица для 1-4 игроков и абсолютная фантазия об ограблении, действие которой разворачивается в самом узнаваемом городе мира. Исчезните без следа или прорвитесь сквозь град пуль. В любом случае вы уйдете с добычей.",
"2593370": "Отправьтесь в мрачное путешествие по древнему Китаю в визуальной новелле, вдохновлённой традиционным китайским искусством с элементами современной анимации. Отведите четырёх девочек в процветающий Лоян в ветвистой истории, полной мести, каннибализма, рабства и других испытаний на пути к искуплению.",
"21690": "Эта игра является портом версии Games for Windows — Live, выпущенной в 2009 году. Если вы купите Untold Stories Bundle здесь, в Steam, это будет то же самое, что обновление до Resident Evil 5 Gold Edition.",
"274190": "Broforce — это ода свободе и динамичный сайд-скроллер, где тебе предстоит управлять хорошо вооруженной, но плохо финансируемой околовоенной организацией, которая привыкла решать вопросы исключительно силой.",
"2051620": "В Enlisted вы не одинокий боец, а командир целого отряда! В этом масштабном многопользовательском шутере о Второй мировой воссозданы ключевые сражения самой кровопролитной войны 20 века, а в каждом бою участвуют сотни солдат, танки и авиация.",
"113200": "Теперь на 20% больше зла, добавленного с бесплатным хеллоуинским обновлением!",
"214490": "Ощутите подлинный страх в мире Alien: Isolation - триллере с атмосферой ужаса и смертельной угрозы.",
"55230": "Приготовьтесь стать участником самых нелепых событий из когда-либо виденных в играх, помогая Святым 3-й улицы в борьбе с Синдикатом!",
"3097560": "Погрузись в многопользовательский онлайн-экшен в сомнительном баре, где игры опасны, как и его посетители. Садись за стол из 4 человек и проверь свои навыки в \"Костях Лжецов\" и \"Карточной Колоде Лжецов\", где ложь и блеф — ключ к победе. Готов провести ночь в Liar's Bar?",
"3070070": "Откройте свой собственный местный игровой магазин. Складируйте полки с новейшими бустерами или взломайте их и соберите карты себе. Устанавливайте свои собственные цены, нанимайте персонал, проводите мероприятия и расширяйте свой карточный магазин.",
"1562430": "DREDGE — это одиночная игра, в которой вам предстоит ловить рыбу и раскрывать зловещие тайны глубин. Продавайте улов, улучшайте свое суденышко и прочесывайте дно в поисках давно погребенных секретов. Изучите таинственный архипелаг и узнайте, почему о некоторых вещах лучше не вспоминать.",
"645630": "В новых модулях «Находки из сарая» и «Свалка металлолома» можно найти классические и уникальные автомобили. В опции «Компоновщик автомобиля» можно добавить свой собственный, самостоятельно построенный автомобиль. Строй и развивай свою собственную империю ремонтных услуг в этом необыкновенно подробном и реалистическом моделировании, в котором забота о деталях просто удивительная.",
"648350": "Погрузитесь в мир юрского периода и постройте свой тематический парк.",
"603850": "Age of History - великая стратегия, которую легко освоить, но трудно стать мастером. Ваша цель - объединить или покорить весь мир, используя лишь военную тактику и хитрую дипломатию. Будет ли мир истекать кровью или преклоняться перед вами? Выбор ваш...",
"346010": "Besiege — это основанная на физике игра, в которой вы строите машины и уничтожаете с их помощью замки, целые армии и хитроумные преграды. Проходите кампанию или сражайтесь бок о бок с друзьями в многопользовательской игре!",
"1384160": "Передовая гибридная 2D/3D-графика, впервые появившаяся в серии Guilty Gear, была поднята на новый уровень в «GUILTY GEAR -STRIVE-». Новое художественное направление и улучшенная анимация персонажей превзойдут все, что вы видели раньше в файтингах!",
"312520": "Вы кочевой слизнекот. Вы и хищник, и жертва в своей поломанной экосистеме. Хватайте копьё и отправляйтесь покорять индустриальные руины — ведь без охоты нет еды. И держите ухо востро: существа крупнее вас придерживаются того же плана, а слизнекоты выглядят очень вкусно.",
"200210": "Отправьтесь в захватывающее путешествие в пиксельное Царство Безумного Бога! Присоединяйтесь, динамичная бесплатная MMO-игра в жанре Bullet Hell. Откройте для себя мир, полный опасностей, испытаний и скрытых сокровищ, сражаясь с волнами врагов. Объединяйтесь с игроками и покоряйте подземелья, чтобы стать легендой!",
"501300": "What Remains of Edith Finch – сборник странных рассказов об одной семье из штата Вашингтон. Эдит Финч пытается понять, почему осталась единственной представительницей своего рода. Исследуя огромный фамильный особняк, вы словно познакомитесь с каждым ее родственником и переживете тот день, который стал последним для очередного члена семейства Финч, – от далекого прошлого до наших дней.",
"505460": "Foxhole - это многопользовательская интерактивная игра, в ходе которой вы и сотни других игроков сможете влиять на ход постоянной онлайн-войны. Это потрясающая тактико-стратегическая игра. Каждое ваше действие вносит Каждое ваше действие может значительно повлиять на огромный мир, который находится в состоянии войны.",
"617290": "В роли одного из последних представителей человечества, в одиночку или в компании одного-двух товарищей, вам предстоит сразиться с ордами монстров и эпическими боссами, пытаясь закрепиться на чужой земле, отстроиться и вернуть себе утраченное.",
"972660": "Spiritfarer® — это уютная игра о смерти. Попробуйте себя в роли паромщика для умерших: постройте лодку для исследования мира, позаботьтесь о дружественных душах и переправьте их через туда, где их будет ждать жизнь после смерти. Включает трогательную основную игру, а также три крупных обновления.",
"282140": "Разработчики игры \"Amnesia: Призрак прошлого\" создали новый научно-фантастический ужастик SOMA, сюжет которого перенесёт вас на дно Атлантического океана. Вам предстоит бороться за жизнь в опасном мире, который заставит вас сомневаться в собственном существовании.",
"1465360": "Встречайте новое поколение гонок по бездорожью! Вас ждут суровые просторы, мощные машины и десятки сложных заданий, которые можно выполнять в одиночку или в команде до 4 игроков!",
"1824220": "Возвращение на уникальное средневековое поле боя. Chivalry 2 — это многопользовательский слэшер от первого лица, вдохновленный средневековыми битвами из фильмов.",
"412220": "Хотите сыграть в самый сложный кооперативный 2D-платформер? Хотите никогда не заканчивать карту? Хотите часами мучиться и плакать, не получая ничего взамен? Приходите играть в DDNet с большим сообществом других больных!",
"286160": "Tabletop Simulator — единственный симулятор, в котором можно дать волю своей агрессии, перевернув стол! Никаких правил, которым нужно следовать: только вы, физическая песочница и ваши друзья. Создавайте свои собственные настольные онлайн-игры или играйте в тысячи модов, созданных сообществом. Безграничные игровые возможности!",
"1282100": "Remnant II® — продолжение крайне успешной игры Remnant: From the Ashes. Выжившим представителям человечества предстоит отправиться в жуткие миры и вступить в бой с новыми беспощадными тварями и богоподобными боссами.",
"1139900": "Игра Ghostrunner предлагает уникальный режим одиночной игры: динамичное жестокое сражение в оригинальной атмосфере, в которой научная фантастика сочетается с постапокалиптической тематикой. Игра расскажет вам историю мира, который остался в прошлом и обитатели которого вынуждены постоянно сражаться, чтобы выжить.",
"502500": "Станьте летчиком-асом, покорите фотореалистичные небеса и сбивайте противников в напряженных воздушных боях! Таких беспощадных схваток между пилотами вы еще не видели.",
"201810": "Wolfenstein®: The New OrderTM - это возрождение серии, которая когда-то положила начало жанру FPS. Разрабатываемая студией MachineGames, в которой собрались опытные мастера, создавшие не одну знаменитую игру, Wolfenstein представляет собой сочетание психологической драмы с захватывающим сюжетом, приключениями и боевой системой от первого лица.",
"108710": "Темное Присутствие преследует маленький городок Брайт-Фолс, доводя Алана Уэйка до грани здравомыслия в его борьбе за разгадку тайны и спасение своей любви.",
"1778820": "TEKKEN 8 — новая игра популярной серии TEKKEN, венец эволюции 3D-файтингов. Вступайте в схватку, выбрав любого из более 32 персонажей, и следите за продолжением эпической саги. Вас ждёт самый масштабный проект в истории TEKKEN!",
"2321470": "DEEP ROCK GALACTIC: SURVIVOR — это одиночный сурвайвор-лайк автошутер. Сражайтесь с полчищами смертоносных инопланетян, добывайте богатства и открывайте мощные улучшения, вооружившись всем арсеналом Deep Rock Galactic. Один дворф против всей планеты Хокссес!",
"678960": "Создайте своего бессмертного, найдите союзников и преодолейте испытания, чтобы вспомнить прошлое и вырваться из ада в игре CODE VEIN.",
"6060": "Присоединяйтесь к восхождению элитного 501-го легиона штурмовиков Дарта Вейдера и сражайтесь в совершенно новой сюжетной саге, где каждое ваше действие влияет на ход битвы и, в конечном счете, на судьбу галактики «Звездных войн».",
"493520": "В жестоком командном шутере GTFO вы должны сражаться как единое целое – или все поляжете в этой жуткой подземной тюрьме. А чтобы преуспеть, помните о правиле «четырех С»: скорость, скрытность, стратегия, слаженная командная работа.",
"644930": "«They Are Billions» - это стратегия в стимпанк-стиле, действие которой происходит на планете, пережившей пост-апокалипсис. Стройте и укрепляйте поселения, чтобы выжить и не позволить миллиардам инфицированных истребить последних выживших.",
"880940": "Pummel Party – забава для вечеринок с участием 4-8 игроков и возможностью состязаться как по сети, так и локально. Побеждайте друзей или ИИ с помощью нелепых предметов в режиме настольной игры и соревнуйтесь с друзьями (которые могут легко превратиться во врагов) в уникальной подборке мини-игр.",
"1418630": "Игра про выживание и предательство. Восемь исследователей ведут свой корабль по безжалостной Арктике. Два предателя в составе команды вызывают темные силы, чтобы расправиться со своими спутниками. Примечание: поддержка официальных серверов будет прекращена 1 января 2024 года",
"680420": "Outriders сочетает в себе одновременно и жестокие кровопролитные перестрелки, и детально проработанные элементы ролевой игры – настоящая смесь жанров!",
"1922560": "Сдуйте пыль со своих Горохострелов и приготовьтесь сыграть в самый умопомрачительный шутер в мире — Plants vs. Zombies Garden Warfare 2.",
"2161700": "Откройте для себя Темный час и пробудите силы в глубинах своего сердца. Persona 3 Reload — захватывающее современное переосмысление культовой ролевой игры с передовой графикой и игровым процессом.",
"2231380": "Ghost Recon Breakpoint – это тактический шутер с видом от третьего лица. Действие игры разворачивается в обширном открытом мире. Вам предстоит выживать и сражаться со спецназовцами, используя скрытность и высокотехнологичное снаряжение в одиночной или кооперативной игре.",
"1462040": "Cloud Strife, бывший оперативник SOLDIER, отправляется в питаемый энергией мако город Midgar. Мир вечной классики FINAL FANTASY VII возрождается, получив новейшую графику, новую боевую систему и дополнительные приключения с Yuffie Kisaragi.",
"1295660": "Возглавьте империи, которые развиваются или выживают на протяжении веков. Создайте то, во что верите, в Sid Meier's Civilization® VII.",
"454650": "DRAGON BALL XENOVERSE 2 развивает успешную формулу DRAGON BALL XENOVERSE, а улучшенная графика поможет вам еще глубже погрузиться в самую проработанную версию мира Dragon Ball.",
"1669980": "Подготовьте следующего монарха, найдя для нее хобби, подготовив ее к сражениям и подружившись с гражданами, которых она однажды защитит. Погрузитесь в совершенно новое приключение в виде ролевого симулятора воспитания детей, где каждое ваше решение повлияет не только на будущее вашей дочери, но и на будущее всей империи!",
"868270": "The Cycle: Frontier — это бесплатный PvPvE Extraction шутер от первого лица, где царит атмосфера напряженности и опасности. Добывайте ресурсы на заброшенной планете, охваченной смертоносной бурей, противостоя не только кровожадным монстрам, но и другим амбициозным искателям сокровищ!",
"601510": "Сразитесь с дуэлянтами со всего мира в игре «Yu-Gi-Oh! Duel Links»! Шагните в мир, который пересекает измерения и объединяет всех дуэлянтов. В Duel World любая локация превращается в Дуэльное поле, где разворачиваются жаркие дуэли!",
"253710": "Самая реалистичная охотничья игра из когда-либо созданных. Почувствуйте азарт охоты в колоссальных заповедниках с разнообразным оружием, от арбалета до дробовика.",
"843380": "Добро пожаловать! Здесь вы можете убивать своих друзей наиуютнейшим образом. Super Animal Royale — это королевская битва на 64 игрока с видом сверху, где звери бьются клыками, когтями и пулемётами, а потом отдыхают на рыбалке, гонках и выполняют квесты перед очередной смертельной битвой",
"2021910": "Сразитесь с другом в этом динамичном классовом шутере от первого лица 1 на 1. Шахматы отходят на второй план по сравнению с шутером от первого лица: вы выигрываете дуэль за дуэлью и захватываете фигуры противника, пока не победите его короля и не выиграете игру.",
"2124490": "Письмо покойной жены привело Джеймса в Сайлент Хилл – место, с которым связано множество воспоминаний. Его встречает окутанный туманом город-призрак, по которому бродят жуткие монстры. Сражайтесь с монстрами, решайте головоломки и ищите следы жены Джеймса в ремейке SILENT HILL 2.",
"219640": "Осаждайте замки и совершайте налеты на поселения в динамичном средневековом многопользовательском слешере «Chivalry: Medieval Warfare»",
"310950": "Участвуйте в напряженных ближних боях в Street Fighter® V! Выберите одного из 16 легендарных персонажей и сражайтесь против друзей в интернете или по локальной сети, используя богатый выбор опций ведения боя.",
"1657630": "Отправьтесь вместе с Беатрикс Лебо в новое путешествие через Слаймовое море к Радужному острову, в край древних тайн, и приручите множество новых непоседливых слаймов в продолжении нашумевшего хита — Slime Rancher.",
"851850": "Вспомните историю Гоку и других воинов Z в DRAGON BALL Z: KAKAROT! Деритесь, рыбачьте, ешьте и тренируйтесь вместе с Гоку, Гоханом, Веджитой и другими, живя полноценной жизнью в мире игры.",
"2338770": "Продукт станет недоступен для покупки 30/10/2025. ПРИМЕЧАНИЕ: все серверы сетевого режима игры NBA 2K24 будут отключены 31/12/2025. Начиная с этого времени, все функции игры, требующие соединения с онлайн-серверами, станут недоступны.",
"2000950": "Пройдите захватывающую кампанию или соберите команду на уникальной онлайн-площадке с многочисленными испытаниями в 'Спецоперациях' в сочетании с сетевыми режимами и картами.",
"313120": "Возьмите на себя роль выжившего после авиакатастрофы, оказавшегося где-то в Тихом океане. Столкнитесь лицом к лицу с некоторыми из наиболее опасных для жизни сценариев, которые приведут к новым впечатлениям каждый раз, когда вы играете. Собирать мусор. Обнаружить. Выживать.",
"2141730": "Визуально реалистичный кооперативный хоррор для 1–6 игроков. Пройдите 11 процедурных уровней и выживайте в Backrooms.",
"1129580": "Охотьтесь, стройте, ведите за собой и просто выживайте в суровом Средневековье! Вам предстоит основать династию и обеспечить ее процветание на долгие годы — или умереть, пытаясь! Играйте в одиночку или с друзьями: погружение в средневековую атмосферу гарантировано.",
"1369630": "История девочки Лили и бессмертных рыцарей начинается в королевстве Запределье, погибшем от «дождя смерти». Это RPG с видом сбоку, где вы будете вести поиски в прекрасном, хоть и печальном мире, и сражаться с врагами, которые могут отнять жизнь, стоит только замешкаться. Раскройте тайну этого мира.",
"273110": "Counter-Stirke Nexon - условно-бесплатный MMOFPS, в котором игроки могут сражаться в режимах PvP и PvE. Вас ждет все самое лучшее из оригинальной игры Counter-Strike, а также новые режимы игры, новые карты, новое оружие и — орды зомби!",
"403640": "В игре Dishonored 2, вы снова окажетесь в роли ассасина со сверхъестественными способностями. Сайт IGN назвал эту игру «удивительной» и «идеальным продолжением», Eurogamer признал ее «шедевром», а Game Informer считает, что «эта история о мести – одна из лучших в своем жанре и проходить мимо нее ни в коем случае нельзя»; Dishonored 2 – это продолжение знаменитого боевика Dishonored от Arkane Studios, завоевавшего более сотни наград «Игра года». Окунитесь в удивительный мир, в котором мистика и технологии живут рука об руку. Решите, за кого играть: за императрицу Эмили Колдуин или за защитника короны, Корво Аттано. Выберите свой стиль: пройдите игру, не попавшись никому на глаза, воспользовавшись всем арсеналом убийственных приемов или соединив оба подхода так, как вам нравится. Найдите уникальное сочетание способностей, оружия и снаряжения, позволяющее с легкостью уничтожать врагов. Игра реагирует на каждое ваше решение: в зависимости от ваших действий у каждого задания может быть разный исход.",
"253230": "A Hat in Time — это чертовски милый 3D-платформер, в котором рассказывается о маленькой девочке, которая шьет шляпы для злых сил! Свободно исследуйте гигантские миры и собирайте Части Времени, чтобы покорить новые высоты!",
"2878980": "Управляйте каждой площадкой с аутентичностью и реализмом благодаря технологии ProPLAY™, которая дает вам полный контроль над вашей игрой в NBA 2K25. Создайте свое наследие в MyCAREER, MyTEAM, MyNBA и The W. Проявите себя со множеством вариантов настройки и исследуйте совершенно новый режим The City.",
"427410": "Совместная игра на выживание с созданием предметов (для 1–6 игроков) в исследовательском центре, наводнили паранормальные угрозы. Вы — величайшие ученые Земли, и вам придется трудиться сообща, создавая гениальные устройства и оружие, чтобы выжить единственным известным вам способом: убивая наукой!",
"633230": "Соберите группу из 4 ниндзя и сразитесь с другими игроками по сети! Графика в SHINOBI STRIKER создавалась с нуля. Посмотрите на мир свежим взглядом и докажите, что вы — сильнейшие ниндзя во всем мире!",
"418460": "Серия Red Orchestra — во Вьетнаме: матчи на 64 игрока, более 20 карт; морская пехота и Армия США, ВНА, НФОЮВ (ВК); австралийцы и войска ВСРВ; более 50 видов оружия; 4 вертолета; мины, ловушки и туннели. Безжалостность. Историчность. Суровый реализм. Изменение персонажей. И запах напалма по утрам.",
"621060": "Постройте свой идеальный бизнес по ремонту, сборке и диагностике компьютеров. Соберите ПК мечты из реальных лицензионных комплектующих — симуляция еще не была настолько точной!",
"470220": "UNO™ – знаменитая карточная игра, где вас ждут обновленный разнообразный геймплей и широкие возможности персонализации. Играйте в одиночку или с друзьями, меняйте правила и игровое пространство по своему вкусу и участвуйте в часах удачи!",
"1562700": "SANABI — это увлекательный экшен-платформер, действие которого разворачивается в антиутопическом мире. Вы — легендарный ветеран с механической рукой, которая поможет прыгать с утесов и небоскребов, уворачиваться от пуль и побеждать противников.",
"2208920": "Assassin’s Creed Вальгалла – экшн-приключение, героя которого взрастили на легендах о битвах и воинской славе. Исследуйте динамичный открытый мир Англии темных веков. Совершайте набеги и развивайте поселение, чтобы заслужить место среди богов в Вальгалле.",
"1128810": "Захватите мир в игре RISK (РИСК) Мировое господство — в культовой стратегической настольной игре.",
"2300320": "Игра «Симулятор фермы 25» приглашает в приятную сельскую жизнь, в одиночку или в совместной игре. Хозяин здесь вы!",
"1845910": "Объедините Стражу Завесы и бросьте вызов богам в «Dragon Age™: На страже Завесы», захватывающей одиночной ролевой игре.",
"1256670": "«Можете ли вы найти свою книгу в этом месте». Борьба между гостями и библиотекарями разворачивается, как на сцене. Побеждённые гости превращаются в книги, а Библиотека растёт. И, в конце концов, возьмите в руки… Единственную, идеальную книгу.",
"223750": "Почувствуйте всю мощь современной боевой авиации! Займите место в российском штурмовике Су-25Т и сбросьте на головы противника несколько тонн бомб! Утомляет гул реактивных двигателей, хочется прикоснуться к чему-то раритетному? Тогда ваш выбор учебно-тренировочный самолет TF-51D, модификации легендарного истребителя P-51D “Mustang”! Отрабатывайте фигуры высшего пилотажа и полеты на предельно малой высоте, практикуйтесь в выполнении посадки в ветреную погоду и темное время суток. Добро пожаловать в DCS World!",
"881020": "Вас ждет грандиозное приключение в небе! Сформируйте группу из четырех человек из разнообразного списка небесных путешественников и рубите, стреляйте или колдуйте — свой путь к победе над коварными врагами в этой ролевой игре. Выполняйте задания в одиночку или с помощью других в совместной игре до 4 игроков!",
"1119730": "Строительство. Фермерство. Охота. Торговля. Быть владельцем ранчо — явно не самая простая работа. Думаете, вам по силам сделать захудалое семейное ранчо самым процветающим в округе? Тогда вперед, в провинцию — вас ждет симулятор в открытом мире с возможностью одиночной и многопользовательской игры!",
"1288310": "Случайный пожар на похоронах вынуждает полицию заново расследовать закрытое дело о массовом убийстве. Линь Лисюнь случайно участвует в повторном расследовании. По мере углубления расследования постепенно всплывает прошлое жертв. Однако дело становится еще более запутанным.",
"386940": "Вы когда-нибудь хотели стать лошадью, причём не обычной, а скачущей по стенам, ставящей ловушки и мастерски уворачивающейся от стрел, и в этой ипостаси попробовать обогнать своих зверей-приятелей в полной опасностей и преград гонке по вместе построенной вами же трассе?",
"1809540": "Nine Sols — это 2D экшн-платформер с насыщенным сюжетом и боевой системой, вдохновленной Sekiro. Погружайтесь в азиатский фэнтезийный мир, исследуйте земли древней инопланетной расы и помогите герою в его квесте уничтожить 9 Солов — грозных правителей забытого мира.",
"529340": "Paradox Development Studio предлагает вам построить идеальное общество в суматохе безумного XIX века. Найдите способ уравновесить общественные противоречия и заслужите место под солнцем в Victoria 3 — одной из самых ожидаемых игр в истории студии.",
"8190": "Погрузитесь в наполненные адреналином приключения на 400 квадратных милях пересеченной местности и с сотнями видов оружия и транспортных средств.",
"48000": "В страхе за судьбу сестры, мальчик входит в ЛИМБ.",
"2420510": "Играйте за своих любимых втуберов из Hololive! Сражайтесь, исследуйте и прокладывайте себе путь сквозь армии фанатов и спасите их от контроля над разумом в этой неофициальной бесплатной фан-игре.",
"239820": "В Game Dev Tycoon вы воссоздаете историю игровой индустрии, основав в 80-х годах собственную компанию по разработке видеоигр. Создавайте самые продаваемые игры. Исследуйте новые технологии и изобретайте новые типы игр. Станьте лидером рынка и приобретите поклонников по всему миру.",
"599140": "Новая игра от создателей Punch Club - Graveyard Keeper. Самый недостоверный симулятор средневекового кладбища в этом году.",
"310560": "DiRT Rally — самая реалистичная из ныне существующих гоночных игр. (Проверено игроками сообщества DiRT, прошедшими 80 милл. миль.) Почувствуйте напряжение пилота, который знает, как высока цена ошибки.",
"1817190": "После событий «MARVEL Человек-Паук. Обновленная версия» юный Майлз Моралес пытается привыкнуть к своему новому дому и продолжает дело своего наставника Питера Паркера в качестве нового Человека-паука. Когда его дому грозит страшная опасность, Майлз надевает костюм и становится Человеком-Пауком.",
"1250": "Кооперативный хоррор на выживание для 6 игроков во всей красе! Бесплатные обновления, бесплатные специальные мероприятия и невероятное веселье!",
"1080110": "F1® 2020 позволяет создать свою команду и соревноваться с официальными командами или же бросить вызов друзьям в режиме разделения экрана. Вас ждут классические и современные болиды на 22 трассах.",
"1244460": "Jurassic World Evolution 2 — долгожданное продолжение популярной игры Jurassic World Evolution от студии Frontier, которое открывает славную новую эру в истории франшизы и развивает новаторские идеи управленческого симулятора, вышедшего в 2018 году.",
"8500": "Перед вами — затейливая научно-фантастическая онлайн-песочница с огромной густонаселённой вселенной, где вас ждёт множество опасностей, возможностей и достижений. Сражайтесь, стройте, торгуйте и сами определяйте будущее этого мира.",
"109600": "Neverwinter – бесплатная MMORPG с активной боевой системой по вселенной Dungeon & Dragons. Эпический сюжет, яростные битвы и классическая ролевая система ожидают смелых героев, готовых отправиться в фантастический мир Neverwinter!",
"307780": "Встречайте продолжение популярнейшей серии файтингов! Mortal Kombat X – это кинематографическая подача невероятного качества и обновленная игровая механика.",
"2212330": "Оттачивайте свою технику, выполняйте яркие комбо и перехитрите противников по всему миру, кадр за кадром. Замедлите ход времени, чтобы отточить свой стиль боя в этом инновационном пошаговом боевом симуляторе. Сокрушайте своих друзей и ставьте захватывающие боевые сцены. Режим обучения не требуется.",
"690790": "В игре DiRT Rally 2.0 вам предстоит проложить путь через культовые места для ралли во всех уголках мира. В вашем распоряжении будут самые мощные внедорожники на свете, однако малейшая ошибка может привести к завершению этапа.",
"1062090": "Людей давно нет. Кто сможет жить в мире, страдающем от засухи и токсичных отходов? Может, бобры-лесорубы? Строительный симулятор-песочница с изобретательными животными, «вертикальной» архитектурой, физикой воды и терраформированием. И кучей древесины.",
"1987080": "Inside the Backrooms — это многопользовательская игра в жанре ужасов, смешанная с различными механиками, которая заставит вас провести напряженную ночь с друзьями. Исследуйте, думайте, взаимодействуйте, но будьте осторожны, ходят слухи, что есть несколько сущностей, желающих вас найти...",
"1644960": "ПРИМЕЧАНИЕ: все серверы сетевого режима игры NBA 2K22 будут отключены 31/12/2023. Начиная с этого времени, все функции игры, требующие соединения с онлайн-серверами, станут недоступны.",
"1225330": "ПРИМЕЧАНИЕ: все серверы сетевого режима игры NBA 2K21 будут отключены 31/12/2022. Начиная с этого времени, все функции игры, требующие соединения с онлайн-серверами, станут недоступны.",
"884660": "CRSED: Cuisine Royale — брутальный ММО-шутер на выживание с реалистичным оружием, элементами кровавой мистики и невероятными сверхспособностями.",
"920210": "В новой игре вы сможете пережить события всех фильмов о Скайуокере. В этой далекой, далекой галактике вас ждет более 300 персонажей, более 100 транспортных средств и 23 планеты! *Содержит персонажа \"Оби-Ван Кеноби - классический вид\"",
"1501750": "В Lords of the Fallen, новом ролевом боевике в жанре тёмного фэнтези, вас ждёт огромный мир. Вы станете тёмным крестоносцем и отправитесь в путешествие, чтобы свергнуть бога-демона Адыра. Теперь доступна версия 2.5, которая включает общий прогресс и бесплатный пропуск для друга.",
"1210320": "Potion Craft – симулятор алхимика, в котором вы физически взаимодействуете с ингредиентами и инструментами в процессе варки зелий. Придумывайте новые рецепты, привлекайте клиентов и экспериментируйте! На вас рассчитывает весь город!",
"675010": "MudRunner — это бескомпромиссные гонки по бездорожью, в которых вам предстоит покорять экстремальное сибирское бездорожье за рулем навороченного транспорта повышенной проходимости, имея при себе лишь карту и компас!",
"1259970": "В честь 25-й годовщины игр серии PES мы предлагаем обновление eFootball PES 2021 Season Update* по специальной цене!",
"12200": "Bully рассказывает историю озорного 15-летнего Джимми Хопкинса, переживающего веселый и неловкий подростковый период. Побеждайте спортсменов в вышибалы, разыгрывайте мажоров, спасайте ботаников, целуйте девчонку и перемещайтесь по социальной иерархии в худшей школе вокруг.",
"4500": "S.T.A.L.K.E.R.: Тень Чернобыля рассказывает о выживании в Зоне – крайне опасном месте, где нужно бояться не только радиации, аномалий и смертоносных существ, но и других \"сталкеров\", преследующих собственные цели.",
"480490": "В игре Prey в 2032 году вы просыпаетесь на борту «Талоса 1», орбитальной космической станции. Вы ключевая часть эксперимента, который должен был навсегда изменить человеческую расу, но привел к катастрофическим последствиям. Космическую станцию захватили враждебные пришельцы, которые теперь ведут на вас охоту. Пытаясь раскрыть мрачные тайны на «Талосе 1» и в вашем собственном прошлом, вам предстоит выживать, полагаясь на подручные средства, а также смекалку, оружие и сверхспособности.",
"1449690": "The Walking Dead: The Telltale Definitive Series содержит все четыре сезона, дополнение 400 Days и The Walking Dead: Michonne — всего 23 уникальных эпизода, которые подарят игрокам более 50 часов игры.",
"1876890": "Wandering Sword — это китайская ролевая игра о боевых искусствах, в которой вы играете за молодого фехтовальщика, оказавшегося втянутым в вражду и чуть не погибшего. Спасаясь от события, вы встанете на путь освоения высшей формы боевых искусств и исследования мира бокса, чтобы стать великим героем, которым вам всегда суждено быть.",
"555160": "Онлайн-шутер в VR с ручной перезарядкой и режимами в стиле Counter-Strike.",
"367500": "Бои игры Dragon’s Dogma: Dark Arisen разворачиваются в огромном открытом мире. Игроки отправляются в эпическое приключение по живописному краю с тремя ИИ-спутниками — «пешками».",
"704850": "Станьте лучшим из воров. Собирайте информацию, воруйте вещи и продавайте их, чтобы купить высокотехнологичное оборудование. Делайте все, что делают настоящие воры.",
"1190000": "Создайте собственную империю по обслуживанию автомобилей. Не бойтесь замарать руки в мире высоко реалистичного симулятора с тщательно проработанными деталями. Посетите аукционный дом, где можно покупать машины в разном состоянии.",
"933110": "Age of Empires III: Definitive Edition предлагает игрокам новый стратегический опыт в историческом сеттинге. *Примечание: чтобы разблокировать все функции игры, необходимо приобрести полную версию.",
"2378900": "Приключение «прогулка и разговор» с легкой головоломкой. Брат и сестра практикуют каннибализм после того, как стали свидетелями неудачного сатанинского ритуала.",
"413410": "Расследуйте убийства, ищите улики и пообщайтесь с одноклассниками, чтобы подготовиться к суду, где вам предстоит смертельная словесная игра с подозреваемыми. Оспаривайте их заявления и обращайте их слова против них же, чтобы выявить ложь! Есть только один способ выжить — спустить курок!",
"834910": "Отправьтесь в незабываемое пиратское путешествие! Отправьтесь в грандиозное приключение вместе с тысячами других игроков в одном из крупнейших игровых миров, когда-либо созданных (и даже заявите права на его часть, чтобы назвать ее своей). Постройте свой корабль, соберите команду, плывите в открытом море и станьте легендой пирата!",
"1241100": "POLYGON — тактический многопользовательский командный шутер от 1-го лица. Используя различное оружие, вы будете сражаться с 32 игроками на масштабных картах. Грамотно управляя своим арсеналом и навыками, вы приведете свою команду к победе!",
"269210": "Hero Siege — это динамичная ролевая игра в стиле пиксельной графики с обширным списком уникальных классов, глубокими экспериментами по построению и управляемой игроками экономикой.",
"265630": "Многопользовательский шутер с видом от первого лица, наполненный экшеном и требующий высокого навыка игры, созданный в стиле Дикого Запада. Уникальное сочетание безостановочной перестрелки и медленного, но мощного оружия.",
"438040": "Shakes & Fidget — это веселая ролевая сатира в жанре фэнтези и в то же время отмеченная наградами ролевая игра! Звучит безумно? С более чем 50 миллионами увлеченных игроков она входит в число самых знаменитых ролевых онлайн-игр во всем мире!",
"2369390": "Возглавьте революцию в этом повстанческом шутере от первого лица в открытом мире. Сражайтесь самодельным оружием, путешествуйте разными способами и создайте повстанческую сеть, чтобы свергнуть режим Кастильо.",
"2531310": "Погрузитесь в мир игры, удостоенной более 300 наград «Игра года»: теперь и на ПК! Окунитесь в историю Элли и Эбби с обновленной графикой, новыми игровыми режимами (например, «Без возврата» в стиле «роглайк») и другими улучшениями.",
"655500": "MX Bikes — это реалистичный симулятор мотокросса, основанный на созданном с нуля физическом движке, который точно имитирует динамику мотоцикла и параметры настройки.",
"597170": "В Clone Drone in the Danger Zone вас ждут сражения на мечах, которыми можно отрубить любую часть тела. Ваш разум был загружен в робота-гладиатора. Чтобы выжить — проходите коварные испытания на арене.",
"32470": "Командуйте или покорите целую галактику в полной коллекции стратегий «Звездных войн». Это время галактической гражданской войны. Возьмете ли вы в свои руки бразды правления Восстанием, возьмете на себя контроль над Империей или будете править подземным миром «Звездных войн»?",
"1557740": "Поединки один на один с элементами рогалика, которые усложняются с каждым последующим раундом. Проигравший открывает интересные улучшения, позволяющие улучшить свою сборку и взять реванш.",
"787480": "Примерьте на себя роль Феникса Райта и испытайте острые ощущения, защищая клиентов в зале заседаний. Сыграйте во все 14 эпизодов, освещающих события первых 3 игр, в составе 1 великолепной коллекции.",
"244450": "Men of War: Assault Squad 2 предлагает новые миссии, масштабные мультиплеерные бои, улучшенную графику, продвинутый AI и Режим прямого управления. Командуйте пятью фракциями на 65 картах, используйте более 250 видов техники и 200 типов пехоты – всё это в одной из самых детализированных WWII-RTS.",
"1088850": "Отправляйтесь бороздить космос вместе со Стражами Галактики Marvel! В этом приключенческом боевике вы попробуете себя в роли Звездного Лорда – возглавите причудливую команду, от которой зависит судьба Галактики! Вы справитесь. Наверное.",
"751780": "Крайне популярный забавный «кликер, в который хочется играть непрерывно». Исследуйте все вокруг, создавайте предметы, добывайте и используйте ресурсы, раскрывайте тайны и стройте базы буквально из ничего! Больше земли — больше приключений!",
"1997040": "MARVEL SNAP — это все, что вы знаете и любите в коллекционных карточных играх, но быстрее… НАМНОГО быстрее. Вы можете наслаждаться всей PvP-стратегией с высокими ставками и сбором колоды, не наблюдая, как ваш оппонент раскладывает пасьянс. ЭТО то, чем должна быть бесплатная игра.",
"1135690": "Unpacking — медитативная игра, где нужно доставать вещи из коробок и размещать их в новом доме. Частично это головоломка, частично — обустройство интерьера, и вам нужно красиво и уютно обставить дом, в процессе узнавая подробности о владелице.",
"1544020": "Выживите, чтобы избежать ужасов Каллисто и раскрыть темные тайны мертвой луны Юпитера.",
"2651280": "Достичь большего. Вместе. Невероятная сила симбиота становится серьезным вызовом для Питера Паркера и Майлза Моралеса. В этой части знаменитой франшизы им предстоит искать баланс между личной жизнью, дружбой и долгом, призывающим помогать людям.",
"638230": "Лети над песками, скользи среди развалин и раскрывай тайны древнего и загадочного мира Journey.",
"2475490": "Пять членов экипажа космического корабля «Тулпар» застряли в открытом космосе. Вокруг — вечный закат. Бог отвернулся от них.",
"666140": "Начните новую жизнь в очаровательном городе Портии! Восстановите мастерскую своего отца и верните ей былую славу! Выполняйте заказы, выращивайте урожай, заботьтесь о животных и заводите друзей среди своеобразных обитателей очаровательного постапокалиптического мира!",
"1971870": "Откройте возрожденную вселенную Mortal Kombat, которую создал Бог огня Лю Кан. Mortal Kombat™ 1 провозглашает новую эру культовой франшизы с новой боевой системой, игровыми режимами и фаталити!",
"1134570": "В F1® 2021, официальной игре ЧЕМПИОНАТА МИРА «ФОРМУЛЫ 1» FIA 2021 ГОДА, у каждой истории есть начало. Вас ждут сюжетный режим «Формула победы», парная карьера и старт в реальном сезоне.",
"895400": "Шутер в открытом мире, сочетающий в себе элементы PvP и PvE. Ищите ценную добычу, прячьте её и стройте базы, чтобы выжить в суровых условиях. Вас ждут динамичные перестрелки, превосходная графика и отличная производительность!",
"1184370": "Исследуйте захваченный демонами мир в новой эпической ролевой игре от создателей культовой Pathfinder: Kingmaker. Познайте суть добра и зла, узнайте истинную цену власти и станьте Мифическим Героем, способным на подвиги, превосходящие ожидания смертных.",
"2186680": "Начните свое путешествие в первой cRPG в мрачной вселенной 41-го тысячелетия. Станьте Вольным Торговцем - наследником древней династии дерзких каперов, правящих собственной торговой империей и исследующих границы Империума с благословения Бога-Императора Человечества.",
"585420": "Строй машины и врывайся в открытый мир Trailmakers! Найди в себе таланты к созданию невероятных механизмов! Уникальная песочница для строительства и удивительно творческое игровое сообщество.",
"997070": "Соберите команду Величайших героев Земли, примите свою силу и воплотите в жизнь мечты о подвигах.",
"1703340": "The Stanley Parable: Ultra Deluxe — это расширенное переосмысление игры The Stanley Parable, вышедшей в 2013 г. Вы сыграете за Стэнли и не сыграете за Стэнли. Вы будете делать выбор и будете лишены выбора. Победить здесь нельзя. The Stanley Parable — игра, которая играет в вас.",
"625960": "Stoneshard это хардкорная пошаговая RPG про суровую жизнь наёмника: путешествуйте на своём караване, спускайтесь в подземелья, изучайте множество веток умений, выживайте вопреки голоду и травмам, и помните, что любая ошибка чревата смертью и потерей прогресса.",
"805550": "Assetto Corsa Competizione — новая видеоигра, выпущенная самим чемпионатом GT World Challenge. Выдающееся качество симуляции позволяет прочувствовать атмосферу гонок FIA GT3 и вступить в борьбу против официальных пилотов на автомобилях и трассах реального чемпионата.",
"1466060": "Погрузитесь в мрачное переосмысление артурианских легенд в этом RPG от первого лица с открытым миром. Исследуйте мир, застрявший в вечной осени, станьте свидетелем падения легенд и принимайте значимые решения, вплетённые в сложный, разветвлённый сюжет.",
"823500": "BONEWORKS — это VR-приключение с экспериментальной физикой. Используйте найденное физическое оружие, инструменты и предметы, чтобы сражаться в опасных игровых ландшафтах и ​​загадочной архитектуре.",
"1144400": "Senren＊Bank — это визуальный роман в японском стиле, созданный Yuzusoft, японским разработчиком романтических виртуальных сетей. Эта игра посвящена 10-летию Yuzusoft. В год своего выпуска в Японии он получил множество наград за искусство, музыку и персонажей. Она заняла второе место на церемонии вручения наград Moe Game Awards 2016 года и заняла первое место в общем рейтинге премии Getchu Bishoujo Game Awards 2016 года.",
"1325200": "В этом ролевом приключении вам предстоит сражаться против полчищ ёкай. Создайте персонажа и отправьтесь покорять просторы Японии периода Сэнгоку. Используйте новую способность «Облик ёкай», чтобы истреблять даже самых опасных ёкай, и готовьтесь пробираться через кишащий врагами Мир тьмы. Дайте волю своей внутренний тьме в Nioh 2!",
"493490": "City Car Driving – реалистичный симулятор вождения автомобиля, который поможет вам освоить базовые навыки управления машиной в различных дорожных условиях, с погружением в среду, максимально приближенную к реальной.",
"2221490": "Станьте агентом Спецотряда в этом тактическом шутере в открытом мире. Участвуйте в напряженных перестрелках с укрытиями, объединяйтесь с друзьями и создайте идеального агента для спасения Вашингтона.",
"447530": "VA-11 HALL-A: Cyberpunk Bartender Action — это выпивка о вайфу, технологиях и пост-антиутопической жизни.",
"476600": "Call of Duty®: WWII - захватывающий опыт, переосмысливающий Вторую мировую войну.",
"1282730": "Лич заточил мир во вневременную петлю, и всех его обитателей поглотил нескончаемый хаос. В вашем распоряжении растущая колода загадочных карт, с помощью которой вам предстоит размещать врагов, здания и элементы ландшафта на пути отважного героя в каждом из его неповторимых путешествий.",
"555570": "The New Z Бесплатная игра с разными игровыми режимами. Выживайте в режиме SURVIVAL с друзьями,обменивайтесь,добывайте и сохраняйте игровые вещи. Сражайтесь с группами других игроков в OPEN WORLD. Все 3 разных режима находятся в ОДНОЙ ИГРЕ.",
"953490": "CARRION — хоррор, в котором вам предстоит оказаться в роли хищника, аморфного существа неизвестного происхождения.",
"1211020": "Wobbly Life — это яркая песочница с правдоподобной физикой и открытым миром. Играй с друзьями по сети или локально, пробуй разные профессии, проходи мини-игры и потрясные сюжетные задания. Покупай одежду, машины и дома. Потряси этот мир!",
"1336490": "Возродите цивилизацию и спасите ее от смертоносных дождей в градостроительном симуляторе в мире темного фэнтези. В роли наместника королевы возглавьте людей, бобров, ящеров, лис и гарпий и подчините себе природу.",
"2142790": "Начните новую жизнь! Постройте ферму вашей мечты и исследуйте мир, полный возможностей. Магия, романтика и приключения ждут вас в этой ностальгической фермерской ролевой игре — симуляторе жизни.",
"582500": "Вы заблудились в ледяной пустоши и оказались в заброшенном замке без своего спутника. Единственное, что у вас осталось, — это рация и знакомый голос в ней. Сможете ли вы вдвоем вовремя найти выход?",
"554620": "Life is Strange: Before the Storm - это новая игра в серии-победителе премии BAFTA, состоящая из 3 эпизодов, сюжет которой разворачивается за три года до событий первой игры. В этот раз вам предстоит сыграть за юную бунтарку Хлою Прайс, которая подружилась с Рейчел Эмбер в новой драматической истории.",
"236430": "Разработчики из FROM SOFTWARE дарят вам DARK SOULS™ II - долгожданное продолжение нашумевшего хита 2011 года - игры Dark Souls. Это уникальная ролевая игра старой школы, покорившая игроков по всему миру. Здесь вас ждут труднейшие испытания и невероятное чувство удовлетворения. Dark Souls II привносит традиционный для серии высокий уровень сложности и инновационный игровой процесс как в однопользовательскую, так и в коллективную игру.",
"383980": "RIVALS OF AETHER — это инди-файтинг, в котором враждующие цивилизации призывают силы Огня, Воды, Воздуха и Земли. Играйте с четырьмя игроками локально или онлайн.",
"200710": "Torchlight II — это море новых приключений! Полностью случайный мир этой экшен-RPG полон невероятных сокровищ, за которые придется сразиться с эпическими врагами. Отправьтесь в путешествие вместе с друзьями, начав игру по Интернету или локальной сети.",
"1374490": "На забытом континенте Ashenfall компании RuneScape проснулись драконы. Собирайте, стройте, развивайте навыки и мастерите в этом совместном приключении на выживание. Только освоив выживание и раскрыв древние тайны, вы сможете надеяться встретиться лицом к лицу со свирепой Королевой Драконов.",
"2322010": "Кратос и Атрей отправляются на поиски ответов в преддверии неотвратимо надвигающегося Рагнарёка. Теперь игра доступна и на PC.",
"400750": "Call to Arms - Gates of Hell - реалистическая историческая стратегия про ВМВ. Примите на себя командование всех видов войск в одиночной и динамической кампании, кооперативе и мультиплеере - реиграбельность не имеет границ. Вы готовы погрузиться в пучину войны?",
"1989270": "Ты здесь, чтобы покончить с Принцессой. Не верь ее лживым речам.",
"701160": "Собирайте монеты, укрепляйте оборону и в одиночку или на пару с приятелем отвоюйте свое королевство. Раскрывайте древние тайны, осваивайте новые технологии и отбивайте ночные нападения орд Жадности в пиксельном мире игры Kingdom, сочетающей в себе элементы микростратегии и «башенок».",
"1040200": "Однажды связавшись с мафией, вы никогда не сможете покинуть ее. Но они платят достойную зарплату, и все, что вам нужно делать, это убирать за ними грязную работу, но вы знаете, что делаете. Так что убирайте места преступлений, обманывайте полицию и готовьтесь к следующему заданию.",
"3017860": "DOOM: The Dark Ages — зрелищное сказание о Палаче Рока и его ярости, раскрывающее предысторию DOOM (2016) и DOOM Eternal. Игроки вновь наденут броню Палача Рока и прольют кровь демонов в средневековой войне с адом.",
"967050": "Онлайн-хоррор для совместной игры, в котором вам предстоит умиротворять, ослаблять и захватывать сверхъестественных существ. Каждый уровень отличается собственным сюжетом, монстрами и вариантами финала. Играйте в одиночку или с друзьями. В игре доступен голосовой чат с забавными эффектами.",
"653530": "Пропало без вести в 1803 ТОРГОВОЕ СУДНО «ОБРА ДИНН»",
"939400": "\"Что такое любовь?\" Мы пытаемся ответить на этот вопрос этой игрой. Игра побуждает людей иметь теплое, мягкое и понимающее сердце.",
"250320": "Создатели «Игры года 2012: The Walking Dead» представляют триллер, основанный на отмеченных наградами комиксах Fables. Играя за Бигби Вульфа, вы обнаружите, что жестокое, кровавое убийство — это лишь часть того, что произойдет в серии игр, где каждое ваше решение может иметь огромные последствия.",
"225840": "Sven Co-op — это кооперативная игра, изначально основанная на Half-Life от Valve Software. В этой игре игроки должны работать вместе против врагов, управляемых компьютером, и решать головоломки в команде.",
"1527950": "Wartales — ролевая игра с открытым миром, в которой вам предстоит вести отряд наемников к богатству в огромной средневековой вселенной. Исследуйте мир, нанимайте спутников, получайте награды и раскрывайте тайны гробниц древних!",
"939960": "Вы отправитесь в постапокалиптический округ Хоуп штата Монтана через 17 лет после ядерной катастрофы. Возглавьте борьбу с рейдерами, которые хотят захватить последние в мире ресурсы.",
"417860": "Emily is Away — это интерактивная история. Создайте псевдоним и выберите свой путь в разветвленном повествовании.",
"105450": "Впервые в истории студия Microsoft предлагает вам приобрести все 3 игры из серии Age of Empires III в одном наборе.",
"2290180": "Ворвитесь на масштабную мультиплеерную площадку! Мчитесь на велосипеде, лыжах, сноуборде или в вингсьюте по открытому миру, настоящему спортивному раю, где вы сами устанавливаете правила – или нарушаете их.",
"1392820": "Маленькая история о том, какими испытаниями могут быть, казалось бы, повседневные мелочи. Помогите девушке купить молоко, станьте первым, кто не разочарует её.",
"364360": "Старый Свет покорен вашей воле. Возглавьте легендарных лордов и решите судьбу выбранной вами расы, вступив в битву с Хаосом в пошаговой кампании с магическими битвами в реальном времени.",
"460920": "Катайтесь в огромном открытом мире альпийских склонов, где снег всегда свеж, а трассы бесконечны. Покоряйте горы в одиночку или в компании друзей - на лыжах, сноуборде, параплане или в вингсьюте. Поделитесь лучшими трюками в социальных сетях.",
"266840": "Эпоха мифологии возвращается! Выберите своего бога и отправляйтесь на поле битвы в этой классической игре, улучшенной за счет полной интеграции со Steamworks и расширенных функций.",
"261640": "Окунитесь во вселенную Borderlands и стреляйте и собирайте добычу в совершенно новом приключении, которое перенесет вас на луну Пандоры в Borderlands: The Pre-Sequel!",
"1180380": "Stay Out - это MMORPG с элементами шутера, в основу которого лег дух сталкерства - исследования таинственных, забытых и заброшенных человечеством, участков планеты.",
"1213210": "Переиздание Command & Conquer и Red Alert в разрешении 4K от бывших сотрудников Westwood Studios включает в себя все 3 дополнения, переосмысленный многопользовательский режим, современный интерфейс, редактор карты, галерею бонусных материалов и более 7 часов переработанной музыки.",
"1483870": "Онлайн-игра для вечеринок в стиле «рисуй и угадывай» для 16 игроков с различными режимами. Проявите свои выдающиеся (или не очень) способности к рисованию и угадыванию!",
"228380": "Эпические столкновения, нешуточная борьба до самого финиша и миллион способов гнуть и корежить металл - вот что ждет вас в Wreckfest, новой гоночной игре со сверхреалистичной симуляцией физики от легендарного разработчика Bugbear, подарившего миру FlatOut 1 & 2!",
"1931770": "В уникальной лингвистической головоломке вам предстоит стать путником, который преодолеет непонимание и объединит народ Башни. Наблюдайте, слушайте, и древние языки заговорят с вами во вселенной, вдохновленной легендой о Вавилонской башне.",
"1262350": "Действие этого хоррора на выживание происходит в мрачном будущем, в котором человечество открыло страшную тайну. Разгадай загадку, сбеги от кошмарных тварей и обыщи внепланетный завод вместе с техником-репликой Эльстер, которая пытается найти свои потерянные сны.",
"368500": "Лондон, 1868 год. Возглавьте подпольную организацию в самый разгар Промышленной революции, чтобы поднять народ на борьбу с жестокой хваткой власть имущих в динамичном приключении, полном интриг и сражений.",
"110800": "Детектив полиции Лос-Анжелеса Фелпс честно служит закону и неустанно ведет борьбу с преступностью, пустившей корни даже в рядах его коллег. Ему предстоит выяснить, кто стоит за серией поджогов, жестоких убийств и заговоров.",
"17410": "В городе, где информация тщательно контролируется, курьеры, называемые «бегунами», перевозят конфиденциальные данные. В этом, казалось бы, утопическом раю было совершено преступление, и за вами ведется охота. Вы — бегун по имени Фейт, и эта инновационная приключенческая игра от первого лица — ваша история.",
"767560": "War Robots - это драйв массовых командных сражений 6 на 6 в режиме реального времени! Вступай в ряды железных бойцов!",
"745920": "Temtem — это онлайн-приключение по сбору существ. Приручайте 165 уникальных существ на 7 ярких островах, сражайтесь с другими укротителями, исследуйте мифические логова, гоняйтесь за вариантами Лумы и Умбры и разводите своих любимых темов — вместе с друзьями! Погрузитесь в красочное приключение по ловле монстров, так что готовьте Temtem!",
"527230": "For The King — это стратегическая RPG, которая сочетает в себе элементы настолки и рогалика в захватывающем приключении, меняющем судьбы королевств. Можно играть в одиночку или в компании с другими игроками как онлайн, так и по локальной сети.",
"942970": "Что, если бы вы могли слышать каждое слово, произнесенное на месте преступления? Для тестирования нашего нового устройства требуются «Акустические детективы»! Вернитесь на место преступления на слух и используйте голоса, которые вы слышите, чтобы идентифицировать потенциальных подозреваемых и раскрыть тайны. Что связывает эти, казалось бы, не связанные друг с другом случаи?",
"2218750": "Убивайте полчища монстров в этом рогалике на выживание. Спускайтесь в Залы мучений, где вас ждут Повелители подземного мира. Сокровища, волшебные безделушки и всё новые и новые герои помогут вам победить пришедшие извне ужасы. Как долго вам удастся выжить?",
"418240": "Япония, 1615 год. К власти приходит новый сегун, и повсюду воцаряется мир. Для борьбы с заговорщиками и мятежниками правитель нанимает пятерых мастеров: безупречных убийц, искусных саботажников и шпионов. Но чем они готовы пожертвовать ради мира на самом деле?",
"2273430": "Насладись напряженными и яркими боями с невероятными комбо-приемами и максимально удобным управлением! Множество персонажей — каждый со своим собственным уникальным стилем игры — и огромное количество открываемых приемов и улучшений! Этот экшн задает новую планку для своего жанра!",
"334230": "Вдохновленная играми для вечеринок «Оборотень» и «Мафия», Town of Salem — это игра об убийствах, тайнах и обмане.",
"337000": "Став тайным агентом, Адам Дженсен вынужден действовать в мире, который презирает ему подобных. Используя обновленный арсенал современного оружия и аугментаций, он должен найти верных людей и подобрать к ним подход, чтобы раскрыть впечатляющий всемирный заговор.",
"1718570": "Сразитесь со временем и судьбой в 2D-ролевой игре Astlibra Revision. Исследуйте тщательно проработанные миры, сражайтесь в жестоких битвах с боссами и улучшайте свои навыки, чтобы уничтожать врагов, скрывающихся за каждым углом.",
"288160": "Таинственное приглашение ведет на чердак заброшенного дома. В комнате чугунный сейф, украшенный странной резьбой, а сверху записка от вашего далекого спутника. Оно обещает что-то древнее и удивительное, спрятанное в железной камере — вам нужно только найти путь внутрь.",
"39140": "Классика RPG – FINAL FANTASY VII – возвращается на PC с новыми сетевыми возможностями!",
"569480": "Королевства и Замки это игра о том как вырастить королевство из маленькой деревушки до процветающего города и великолепного замка.",
"40800": "Печально известный и сложный платформер выходит в Steam с играбельным персонажем-главным крабом (эксклюзивно для Steam)!",
"916440": "Создайте собственную империю на заре индустриальной эпохи в зарекомендовавшей себя градостроительной игре. Возглавляйте общество и принимайте стратегические решения, осваивайте сложные производственные цепочки, делайте открытия, договаривайтесь и управляйте экономикой.",
"1284210": "Guild Wars 2 — отмеченная наградами ролевая онлайн-игра с динамичными боями, глубокой настройкой персонажей и не требующая абонентской платы. Выбирайте из арсенала профессий и оружия, исследуйте огромный открытый мир, соревнуйтесь в режимах PVP и многое другое. Присоединяйтесь к более чем 16 миллионам игроков прямо сейчас!",
"1476970": "Инкрементная MMO-игра в режиме ожидания, в которой ваши герои продолжают сражаться, пока вас нет! Тратьте свою добычу на улучшения, открывайте классы от волшебника-элементаля до пирата-пушки, а также уникальные навыки 20-го уровня, такие как сельское хозяйство, парусный спорт и строительство!",
"1659420": "«UNCHARTED: Наследие воров. Коллекция» – это лучший способ познакомиться с двумя самыми захватывающими приключениями от отмеченной наградами студии Naughty Dog, обновленными и улучшенными специально для PC.",
"1584090": "Совершенно новый симулятор ресторана в пиксельной графике, основанный на проекте Touhou Project! Играйте за Мистию, владелицу небольшой изакая. Собирайте ингредиенты днем, обслуживайте клиентов ночью, изучайте рецепты знакомых персонажей и станьте лучшим владельцем изакая во всем Генсокё!",
"12110": "Добро пожаловать в Вайс Сити. Добро пожаловать в 1980-е. Из десятилетия пышных волос, излишеств и костюмов пастельных тонов пришла история восхождения одного человека на вершину криминальной пирамиды.",
"905370": "Овладейте искусством осадного дела в Conqueror's Blade, тактической MMO. Создайте героя, командуйте отрядами средневековых воинов и сражайтесь в эпических онлайн-битвах в огромном открытом мире. Играйте бесплатно уже сегодня!",
"1268750": "Starship Troopers: Extermination – кооперативный шутер от первого лица на 16 игроков, в котором вам предстоит вести тотальную войну против жуков на далёких планетах! Собирайте свой отряд, хватайте винтовку и исполните свой долг бойца элитного Звёздного десанта, отбив захваченные арахнидами планеты!",
"1948280": "Stacklands — это игра для строительства деревень, в которой вы складываете карты, чтобы собирать еду, строить постройки и сражаться с существами. 🃏 Например, если перетащить карту деревенского жителя поверх карты Берри Буша, появятся карты ягод, которые жители деревни могут съесть, чтобы выжить. 🃏 Разыгрывайте свои карты правильно и расширяйте свою деревню!",
"975370": "Самая глубокая и сложная симуляция мира в истории. Легендарная Dwarf Fortress — теперь и в Steam! Постройте крепость и помогите своим дварфам выжить в мире с глубочайшей генерацией.",
"337320": "Paint the Town Red — это хаотичная игра в ближнем бою от первого лица, действие которой происходит в разных местах и ​​в разные периоды времени. Воксельных врагов можно бить, бить, пинать, колоть и резать совершенно динамически, используя практически все, что не прибито гвоздями.",
"257510": "The Talos Principle - головоломка от первого лица в лучших традициях научно-философской фантастики. Разработана Croteam, создателями Serious Sam, в соавторстве с Томом Жубертом (FTL, The Swapper) и Йонасом Киратзесом (The Sea Will Claim Everything).",
"326460": "Создавайте свой танк и разносите танки друзей на куски из сотен улучшаемых видов оружия в адреналиновой танковой онлайн-игре для нескольких игроков. Зарабатывайте опыт, повышайте свой уровень и открывайте новые танки, виды оружия и снаряжение. Сражайтесь с друзьями в командным режимах или против них, когда каждый сам за себя.",
"464920": "Добро пожаловать домой! Пришло время высадиться на Марсе и основать первую в истории человечества действующую колонию на Красной планете. Все, что вам нужно — это припасы, кислород, десятилетия упорных тренировок, навык выживания в песчаных бурях и решительность, с которой вам предстоит постичь назначение этих странных черных кубов, возникших словно из ниоткуда. Это будет отличное местечко! Если немного здесь прибраться.",
"444640": "Сражайтесь лицом к лицу с другими игроками в захватывающей битве за победу. Эта совершенно новая игра Battles от создателей бестселлера Bloons TD 6 специально разработана для многопользовательских сражений и предлагает возможность напрямую управлять шариками и посылать их в обход защиты противника.",
"383120": "Empyrion - Galactic Survival – это открытый трехмерный мир, космическое приключение с выживанием, в котором вы можете путешествовать в космосе и приземляться на планеты. Стройте, исследуйте, сражайтесь и выживайте во враждебной галактике, полной скрытых опасностей.",
"704270": "Generation Zero — это шутер с элементами скрытности, в котором вам предстоит вести партизанскую войну против механической угрозы. Исследуйте просторную карту мира, вдохновленную эпохой холодной войны в Швеции, встаньте в ряды Сопротивления в одиночку или с тремя друзьями в кооперативном режиме.",
"335240": "Transformice – это MMO платформер, в котором десятки мышей бегают за сыром! Поможет ли вам всемогущий Шаман или только все сломает? Миллионы уровней, забавная физика, древо умений и самое важное… шляпы!",
"47810": "Исследуйте потрясающий мир, делайте сложный моральный выбор и участвуйте в сокрушительных битвах с огромными и устрашающими существами. Ultimate Edition включает Dragon Age: Origins, Dragon Age: Origins - Awakening и все девять пакетов контента.",
"242860": "«Verdun» – первый многопользовательский шутер от первого лица в реалистичном сеттинге Первой мировой войны. Безжалостная окопная война предлагает уникальный опыт сражений, погружая вас и ваш отряд в напряженный бой.",
"1681430": "На 50% человек, на 50% робот — на 100% герой: окунитесь в мир Старого Детройта в роли легендарного полицейского и вершите правосудие.",
"1049410": "Восприятие – это реальность. В этой умопомрачительной головоломке от первого лица вам предстоит сбежать из сюрреалистического мира снов, решая невозможные загадки при помощи перспективы.",
"2252570": "Создайте команду мирового уровня, готовую побеждать своих соперников в самых престижных футбольных соревнованиях. Прогресс никогда не останавливается, когда вы стремитесь к футбольному величию.",
"32370": "Прошло четыре тысячи лет, прежде чем Галактическая Империя и сотни рыцарей-джедаев пали в битве против безжалостных ситхов. Вы последняя надежда Ордена джедаев. Сможете ли вы овладеть потрясающей мощью Силы в своем стремлении спасти Республику? Или вы поддадитесь соблазну темной стороны?",
"211500": "RaceRoom предлагает реалистичную физику и точно воссозданный Force Feedback. Участвуйте в официальных сериях DTM, FIA WTCC и WTCR и исследуйте большой выбор автомобилей и трасс, включая самую актуальную версию Нордшляйфе.",
"1359090": "Zero Hour — это тактический командный онлайн шутер от первого лица с управлением ресурсами. Его события разворачиваются в различных вымышленных локациях с атмосферой Бангладеш, созданных в реалистичных пропорциях, что дарит ощущение настоящего ближнего боя.",
"744900": "Мрачнейший онлайн-хоррор. Как один из выживших после вспышки заражения, Вы будете бороться за жизнь в разлагающихся руинах общества. Собирайте добычу, улучшайте навыки, торгуйте с игроками. Следите за инфицированными, таящимися за каждым углом.",
"977400": "Эволюция никогда не заканчивается",
"578650": "The Outer Worlds – это отмеченная наградами научно-фантастическая ролевая игра от Obsidian Entertainment и Private Division. Создайте персонажа, исследуйте космическую колонию и влияйте на ход сюжета. В системе уравнений колонии вы - непредвиденная переменная.",
"19680": "Сумеет ли Алиса спасти Страну чудес и себя от безумия?",
"541570": "Погрузитесь в мрачное приключение мальчика с протезом на лице и тяжелым прошлым. Распутайте зловещую тайну истории Салли, чтобы отыскать правду, скрытую завесой тьмы.",
"1189630": "Path of Wuxia сочетает в себе классический мир уся и юношескую школьную жизнь со стилем аниме, а также включает в себя игровой процесс-симулятор, хорошо известный поклонникам Heluo. Играйте за молодого Ся, который присоединяется к академии, известной как Эрмитические павильоны Ся, становитесь сильнее вместе с различными одноклассниками и ищите свой собственный путь Ся.",
"107100": "Откройте секреты Бедствия, таинственной катастрофы, разделившей мир на части.",
"1235140": "Итибан Касуга строит жизнь с нуля в пошаговой JRPG с тонной юмора.",
"230290": "Создавайте и разрушайте в невиданных масштабах с симулятором космоса, объединяющим в реальном времени гравитацию, климат, столкновения и взаимодействия материи. Вы увидите красоту вселенной и хрупкость нашей планеты. Поддерживает все основные шлемы VR.",
"304240": "Признанная классика жанра ужасов снова с нами! Встречайте обновленное издание игры Resident Evil в формате HD.",
"237930": "Откройте для себя мир Transistor — научно-фантастической игры в жанре Action RPG от создателей Bastion.",
"954850": "Kerbal Space Program 2 — продолжение полюбившегося публике космического симулятора Kerbal Space Program. Новые детали, неисследованные локации, потрясающая графика, а также обновлённые интерфейс и вид карты ждут вас в новом поколении космических приключений!",
"1966900": "Отстреливайся от постоянно наступающей толпы Лавкравтовских монстров. Разблокируй новых персонажей с уникальными способностями, новое оружие, выбери из множества улучшений, чтобы сделать своего уникального война, который сможет пережить эту ночь.",
"322500": "SUPERHOT — это шутер от первого лица, где время движется только вместе с тобой. Здесь не будет восполняемой полоски здоровья. Не будет стратегически разбросанных боеприпасов. Только ты — один против всех, с голыми руками. Выхватывай оружие у падающих врагов, стреляй, руби и уворачивайся от пуль, как Нео.",
"1284410": "Герои из мира «Ведьмака» ждут вас в захватывающих карточных сетевых сражениях!",
"373420": "Соберите свою команду и приготовьтесь к потрясающей новой версии игры 2014 года для ПК по версии GameSpot. Часы нового контента, новые игровые режимы, полная озвучка, многопользовательский режим с разделенным экраном и тысячи улучшений — лучшее время для исследования эпического мира Ривеллона еще никогда не было!",
"1262580": "Need for Speed™ Payback - Издание Deluxe дает вам преимущество над соперниками. Выделитесь из толпы, получив эксклюзивные возможности кастомизации, скидки в игре, бонусы к репутации и пять поставок в качестве приветственного подарка.",
"1817230": "Поймайте ритм вместе с начинающей рок-звездой Чаем и его командой, чтобы бросить вызов злобной мегакорпорации! Hi-Fi RUSH — это новый боевик от Tango Gameworks, в котором всем заправляет музыка!",
"1343400": "RuneScape — это MMORPG в стиле фэнтези с открытым миром. Исследуйте постоянно меняющийся и развивающийся живой мир, где вас ждут новые испытания, навыки и квесты. Благодаря беспрецедентной свободе игрока вы сами выбираете, как играть, приключения и развитие.",
"4700": "Охватывая самую бурную эпоху в истории Запада, ваши поиски территории и власти проведут вас через Европу, Африку, Ближний Восток и даже к берегам Нового Света.",
"1455840": "Dorfromantik - это мирная стратегия-головоломка, в которой вы создаёте красивый деревенский пейзаж путём размещения плиток на поле. Исследуйте разнообразные красочные биомы, разблокируйте новые плитки и выполняйте задания, чтобы наполнить свой мир жизнью!",
"521890": "Hello Neighbor — игра в жанре хоррор, в которой игроку нужно проникнуть в соседский дом и узнать, что скрывает его зловещий сосед. Твой противник - искусственный интеллект, который учится на всех твоих действиях: любишь забираться в дом через окно? — Не попадись в капкан. Пытаешься убежать? — Он найдёт способ перехватить тебя.",
"1066780": "Transport Fever 2 — новый золотой стандарт в жанре транспортных симуляторов. Исследуйте новый мир, передвигаясь по земле, воде и воздуху. Да здравствует прогресс и процветание!",
"1106840": "Hydroneer это песочница про добычу и строительство. Добывайте золото и другие ресурсы чтобы получать прибыль и улучшать ваши добывающие системы. Стройте механизмы, куйте оружие, рыбачьте, и копайте глубже!",
"325610": "На мрачном фоне голода, болезней и войны в великих степях Востока поднимается новая сила. С миллионом всадников за спиной приближается величайший король-воин, и его взгляд устремлен на Рим… Total War: ATTILA: следующая часть отмеченной множеством наград серии для ПК, сочетающей пошаговую стратегию с тактикой в ​​реальном времени, переносит игроков в 395 год нашей эры. Время апокалиптических потрясений на заре Темных веков.",
"261030": "«Ходячие мертвецы: второй сезон» продолжает историю Клементины, молодой девушки, осиротевшей в результате апокалипсиса нежити. Оставшись на произвол судьбы, она была вынуждена научиться выживать в сошедшем с ума мире.",
"2909400": "Неведомые странствия продолжаются... Выбравшись из города Мидгар, Клауд и его друзья отправляются в путешествие по планете. Новые приключения ждут вас во второй части трилогии обновленной FINAL FANTASY VII!",
"774801": "Пробирайтесь по экзотическим островам, сочетая плавные движения и стремительные бои, чтобы стать Чемпионом по крабам в этом шутере от третьего лица в стиле рогалик.",
"589290": "Holdfast: Nations At War это многопользовательский шутер от первого и третьего лица, действие которого разворачивается на полях сражений Наполеоновских войн и Первой мировой. Участвуйте в сражениях со 150 и более игроками на одном сервере!",
"535930": "Создавайте шикарные больницы, лечите диковинные болезни и разбирайтесь с ненадёжными сотрудниками, расширяя охват своего медицинского учреждения в округе Две Вершины.",
"3059520": "Перепишите гоночную историю с абсолютной гоночной эволюцией: EA SPORTS™ F1® 25: 2026 Season Edition. Приобретите F1® 25 и 2026 Season Pack в одном комплекте для максимально полного опыта Formula One®.",
"622650": "Bendy and the Ink Machine® — игра-головоломка в жанре ужасов от первого лица, которая навсегда разрушит вашу детскую любовь к мультфильмам.",
"641990": "Мастерите, воруйте, деритесь и убегайте! Совершите побег из строгих тюрем мира, вернувшись к жизни заключенных в The Escapists 2. Теперь и с возможностью игры по сети! А у вас хватит сил на побег?",
"1468260": "Сдувайте листья, улучшайте свое снаряжение и автоматизируйте свой прогресс, исследуя Вселенную Листа. Увлекательная пошаговая игра в режиме ожидания, в которой каждый сдутый лист приближает вас к следующему большому обновлению. Просто, расслабляюще и бесконечно полезно. Пусть листья опадают, а ваш прогресс растет!",
"365360": "Командуйте отрядом наемников в тактической ролевой игре в процедурно созданном открытом мире мрачного средневекового фэнтези. Решайте, куда пойти, кого нанять, с кем сразиться, какие взять контракты, как обучить и снарядить бойцов.",
"47780": "НОЧНОЙ КОШМАР ВОЗВРАЩАЕТСЯ.",
"1408720": "Легкий в освоении полностью модифицируемый шутер от первого лица с продвинутой механикой движения. Полностью настраиваемый с помощью модов, пользовательских карт и тысяч предметов, которые можно разблокировать.",
"996470": "Испытайте несравненную реалистичность и подлинность в главном футбольном симуляторе этого года: PES 2020.",
"420290": "Blackwake — это многопользовательский морской шутер от первого лица, ориентированный на командную работу и сотрудничество. Стреляйте из пушек, топите вражеские корабли или захватывайте их с помощью огнестрельного оружия и стали.",
"475150": "В десятый день своего рождения Titan Quest заиграет новыми красками. Юбилейное издание объединяет в одну игру Titan Quest и Titan Quest Immortal Throne, которые претерпели серьезную переработку, чтобы вы могли как следует насладиться нашей action RPG.",
"2066020": "Сразитесь с Владыками бездны и их приспешниками, соберите камни души и станьте богом в динамичном экшен-рогалике! Откройте секретные заклинания, создайте могущественное оружие и раскройте разрушающие баланс синергии, чтобы покорить силу бездны.",
"427730": "Who's Your Daddy - динамичная многопользовательская игра: спасайте младенца от опасностей в доме, полном неожиданностей, играя с друзьями. Более 69 опасных предметов, увлекательная физика!",
"494840": "Игра UBOAT представляет собой симулятор подводной лодки периода Второй мировой войны. В основе ее механики лежат микроменеджмент и выживание в открытом мире, а главной темой является жизнь немецких подводников. Субмарина - их дом, способный в любую секунду превратиться в братскую могилу.",
"1262540": "Вырывайтесь вперёд",
"2679460": "Король убит, и, согласно его завещанию, нового монарха должен избрать народ. Найдите друзей и завоюйте престол расколотого королевства в фэнтезийной ролевой игре, отмеченной множеством наград. Соберите отряд, изучайте архетипы, участвуйте в жарких битвах и исследуйте неизведанный мир.",
"394510": "HELLDIVERS™ — это хардкорный, использующий оба мини-джойстика шутер для совместной игры. Игроки управляют Адскими Десантниками, элитными бойцами, вместе защищающими Супер-Землю и истребляющими врагов человечества в напряженной межгалактической войне.",
"2280": "Самые полные версии улучшенных изданий DOOM и DOOM II, разработанные студией id Software и впервые выпущенные в 1993 и 1994 годах, теперь доступны в сборнике.",
"287290": "RE Revelations 2 продолжает классическую серию игр в жанре ужасов, совмещая борьбу за жизнь с борьбой за правду.",
"1262560": "Пристегнулись? Вперед, сеять хаос!",
"412830": "Игра STEINS;GATE была разработана компаниями 5pb. и Nitroplus, получила престижную награду Game of Excellence журнала Famitsu, и в опросе журнала была названа одной из самых эмоциональных и «вызывающих слезы» игр всех времен. По этому роману уже выпущены манга и аниме. Вот, наконец-то, и в Steam!",
"238010": "Вы играете Адама Дженсена, бывшего специалиста спецназа, которого выбрали для надзора за оборонными потребностями одной из самых экспериментальных биотехнологических фирм Америки. Когда врывается спецназ и убивает тех самых ученых, которых вы наняли защищать, все, что вы знали о своей работе, меняется.",
"392160": "Исследуй звезды, веди торговлю, участвуй в сражениях, строй станции, покупай и оснащай корабли, командуй флотами в живой, полностью симулированной вселенной, которая реагирует на каждое твое решение.",
"1692250": "Вступайте в новую эру Formula 1® с EA SPORTS™ F1® 22, официальной видеоигрой чемпионата FIA Formula One World Championship™ 2022.",
"699130": "World War Z — ураганный, динамичный и кровавый шутер от третьего лица против полчищ зомби (до 4 игроков).",
"226700": "Infestation — это MMO в жанре ужасов на выживание, которая погружает игроков в кишащий зомби постапокалиптический мир, в котором вирусная вспышка уничтожила человеческое население, оставив после себя кошмар эпических масштабов.",
"3117820": "Переживите правление безумного султана в этой жестокой ролевой игре по управлению ресурсами. Вытягивайте карту каждые семь дней и выполняйте задание. Сделайте ужасный выбор, чтобы остаться в живых: умрете ли вы верным слугой, станете убийцей королей или вызовете суд богов?",
"48190": "Пришло время присоединиться к Братству.",
"312530": "Вступайте в футуристический 1984 год, эпоху, когда утки дичают в безумной битве за славу. Взрывайте своих друзей из дробовиков, сетевых пистолетов, лучей контроля над разумом, саксофонов, магнитных пистолетов и многого другого. Это УТИНАЯ ИГРА. Не моргайте.",
"2698940": "Добро пожаловать на Motorfest – невероятный гоночный фестиваль в открытом мире. Исследуйте живописный Гавайский регион, где постоянно появляются новые локации, испытания и транспортные средства. Опробуйте бесплатно в течение 5 часов!",
"784150": "Превратите бедную советскую республику в индустриальную сверхдержаву в градостроительном симуляторе с цепочками производства и глобальной экономикой. Жизни граждан, от образования и работы до верности партии и преступности, в вашей власти!",
"355840": "Survarium - это онлайн-шутер в жанре пост-апокалипсиса. Если вы ищете шутер, где навыки имеют значение, вы его нашли! Противники и смертельные аномалии явно не станут препятствием к победе, верно? Тогда вступайте в бой прямо сейчас!",
"774181": "Спасайте пациентов своим мастерством ритма! Rhythm Doctor — это ритм-игра, в которой вы лечите пациентов, проводя дефибрилляцию в такт ударам их сердца. Изучите уникальное сердцебиение каждого пациента и победите вирусов-боссов, пытающихся саботировать ваш ритм, под душевную, успокаивающую душу музыку.",
"1645820": "SurroundDead — игра на выживание в открытом мире. Действие происходит в мире, разрушенном апокалиптической катастрофой. Мертвые правят свободно и не остановятся ни перед чем, чтобы убить вас.",
"1222730": "Освойте искусство сражений на звёздных истребителях в реалистичном симуляторе полёта STAR WARS™: Squadrons. Участвуйте в многопользовательских воздушных схватках от первого лица и примерьте на себя роль пилота в грандиозной истории STAR WARS™.",
"1171690": "Станьте Путником, выбрав тропу развития и игровой стиль, чтобы сразиться со зловещими силами, захватившими мир. В этой ARPG с совместным режимом можно объединиться с друзьями, чтобы создать бесчисленное множество приключений: вместе Путники куда сильнее.",
"756800": "Выполняйте обязанности инспектора пограничной службы в коммунистическом государстве 1980-х годов, где контрабанда, коррупция и подделки документов – в порядке вещей. Будьте бдительны и добейтесь благосклонности начальства.",
"302830": "BLOCKADE 3D! Шутер от первого лица в процедурном кубическом мире. Огромный арсенал оружия, противостояние 4 команд и до 32 игроков одновременно на одной карте. Большой выбор игровых режимов!",
"1127400": "Безграничная игра в жанре «башенная защита» с упором на управление ресурсами.",
"794260": "Ни один великий путь не был пройден без великого труда. В Outward холод ночи или загноившаяся рана могут быть так же опасны, как скрывающиеся во тьме хищники. Исследуйте огромный мир Аурайи в одиночку или в режиме совместной игры. Definitive Edition включает в себя оба дополнения и общие улучшения.",
"41700": "S.T.A.L.K.E.R.: Зов Припяти – прямой сиквел к S.T.A.L.K.E.R.: Тень Чернобыля. В роли майора Александра Дегтярева вы должны расследовать падение правительственных вертолетов на территории Зоны и разобраться в том, что там происходит.",
"35450": "Включает в себя весь контент для «Rising Storm»!",
"1337520": "\"Культовая roguelike-игра Risk of Rain возвращается — она стала ещё больше и лучше! Новые стили игры, уникальная добыча, новые выжившие, обновлённый многопользовательский режим, полюбившиеся игрокам особенности из Risk of Rain 2 и многое другое!\"",
"1677280": "Company of Heroes 3 переносит вас в Средиземноморье — регион ожесточённых боёв, где надо принимать важные стратегические решения. Тут за каждой битвой стоит история… Какова же ваша?",
"571740": "Отправьтесь в увлекательное путешествие вместе с Golf It! Берите клюшку, соберите друзей и погрузитесь в эпическое приключение в мини-гольфе. Покоряйте бесчисленные поля, сохраняйте незабываемые воспоминания и совершенствуйте свои навыки, чтобы стать абсолютным чемпионом по мини-гольфу. Ваша захватывающая одиссея в гольф начинается здесь!",
"583950": "Теперь Artifact — это две игры: Artifact Classic, оригинальная коллекционная карточная игра в мире Dota 2, и Artifact Foundry, особая версия с упрощённым геймплеем, новыми картами, одиночной игрой и улучшенным игровым опытом.",
"1062520": "Dinkum — это симулятор выживания и жизни на острове, вдохновлённом суровой австралийской глушью.",
"1056640": "ММО-боевик Phantasy Star Online 2 New Genesis. Станьте воинами ARKS Defenders, исследуйте планету Halpha и победите в эпических сражениях! Дайте волю фантазии в редакторе персонажа и воплотите мечты.",
"1169040": "Стройте, выполняйте задания и покоряйте бескрайний процедурно генерируемый мир в одиночку или с друзьями. Развивайте поселение, исследуйте подземелья, сражайтесь с монстрами, добывайте руду, создавайте снаряжение, нанимайте мастеров – и это далеко не все!",
"2515020": "Мрачное фантастичное приключение, в котором судьбу мира решат айконы и управляющие ими доминанты. Узнайте историю Клайва Розфилда — несчастного воина, желающего отомстить темному айкону Ифриту, который оставляет после себя лишь разрушения.",
"260230": "Valiant Hearts: The Great war — история о 5 людях и несчастной любви в мире, где бушует война. Это оживший комикс с загадками, приключениями и боевыми сценами. Помогите солдату вернуться к любимой!",
"1044720": "Возглавьте своих людей и постройте город в диких землях на краю изведанного мира. Обеспечьте их всем необходимым для добычи ресурсов, охоты, рыбалки, земледелия и выживания. Занимайтесь ремёслами и торговлей, боритесь со стихиями и отражайте нападения врагов.",
"2027330": "Физическая песочница, где ломается всё, включая вас. Создавай, строй и разрушай с помощью Reality Crusher. Включает GoreBox Animosity и ранний доступ к GoreBox 27, новой версии с многопользовательской онлайн-игрой.",
"557340": "My Friend Pedro — это жестокая смесь дружбы, фантазии и стремления уничтожить всех на своем пути по приказу разумного банана. Стратегическое использование раздельного прицеливания, замедленного движения и старого доброго вышибания окон позволяет выстраивать одну сногсшибательную боевую сцену за другой.",
"609320": "Путешествуйте по высушенном морскому дну, усыпанному останками умирающей цивилизации. Управляйте уникальным кораблем, преодолевайте многочисленные препятствия и боритесь с опасными погодными условиями. Как далеко вам удастся пройти? Что вы найдете в конце пути?",
"409720": "В BioShock 2 вы вступаете в шкуру самого культового жителя Восторга, Большого Папочки, и исследуете ветхий и красивый павший город, преследуя невидимого врага в поисках ответов и собственного выживания.",
"332950": "Смерть ждет вас в Dark Deception, сюжетной игре-лабиринте от первого лица. Некуда спрятаться и негде перевести дух. Беги или умри - это твой выбор. Оказавшись в ловушке кошмарных лабиринтов вместе с загадочной женщиной, ваша единственная надежда на выживание — найти способ сбежать.",
"1940340": "Darkest Dungeon II — путешествие обречённых в жанре рогалик. Создавайте группу, снаряжайте Дилижанс и отправляйтесь спасать мир, освещая умирающие земли искрой последней надежды. Но помните, что главные угрозы могут прийти не извне…",
"2437170": "24/7 начнется 27 АВГ Станьте богом и сражайтесь в SMITE 2, продолжении легендарной экшен-MOBA от 3-го лица на основе Unreal Engine 5. Сильные соперники, динамичные бои, мощные способности, верные союзники, легендарные боги – вот за что более 40 млн игроков любят SMITE.",
"584400": "Sonic Mania — это двухмерное приключение в духе первых игр о Сонике на новый лад. Вас ждут потрясающая графика в стиле ретро и анимации с частотой 60 кадров в секунду.",
"1240210": "Здесь нет игры. Так что не надо тут ничего портить, нажимая на всё подряд. Вы ведь не хотите, чтобы вас выгнали из видеоигрового мира? Конечно же нет!",
"1084600": "Отправляйтесь в пустыню Песчаного Взгорья и попробуйте себя в роли начинающего мастера! Собирайте ресурсы, стройте машины и механизмы и превратите заброшенную мастерскую в отлично отлаженную фабрику, чтобы вырвать город из когтей грозящего ему разорения!",
"99900": "Вступайте в ряды игроков Spiral Knights. Оказавшись в неземном мире, вы должны будете изучать вечно-меняющиеся подземелья Clockworks.",
"531510": "Just Shapes & Beats - хаотичный кооперативный музыкально-пулеметный ад, основанный на трех простых понятиях: избегай Фигур, двигайся к надирающим задницы Битам и умирай... многократно.",
"324800": "Shadow Warrior 2 — потрясающее продолжение оригинального шутера от первого лица, созданное компанией Flying Wild Hog.",
"934700": "По Лос-Анджелесу разносится смертоносный вирус, превращающий носителей в зомби. Укус, заражение и больше чем просто иммунитет: узнайте правду об эпидемии и выясните, кем — или чем — вы стали. Выживание и эволюция — таков путь истребителя зомби!",
"1149620": "Купите заброшенную заправочную станцию и восстановите ее во всей красе. Ремонт, модернизация и расширение предлагаемых услуг, чтобы идти в ногу с требованиями ваших клиентов.",
"332800": "Добро пожаловать обратно в новую, улучшенную пиццерию Freddy Fazbear's Pizza! Как всегда, Fazbear Entertainment не несет ответственности за смерть или расчленение.",
"213610": "Переживите два уникальных приключения как с новыми, так и с хорошо знакомыми героями и злодеями. Сразись за судьбу мира!",
"563560": "Бесплатный совместный шутер с видом сверху. Эпическая охота на жуков, сочетающая в себе совместную игру и тактические приёмы на уровне отряда.",
"1263850": "Новые функции и улучшения обеспечат глубину, драматичность и реалистичность игры. FM21 дает вам возможность проявить себя как менеджера и привести клуб к успеху.",
"1022450": "War Selection — динамическая стратегия с постройкой базы, добычей ресурсов и военными столкновениями. Десятки игроков в одном матче сражаются на случайной карте. Каждый игрок начинает с Каменного века. В ходе матча он проходя 7 исторических эпох выбирает свою культуру, а затем и конкретную страну.",
"1509960": "PICO PARK — это совместная многопользовательская игра-головоломка локально/онлайн для 2–8 игроков.",
"316010": "БОЛЬШЕ КАРТ. БОЛЬШЕ СТРАТЕГИИ. ГРАНДИОЗНЫЙ СЮЖЕТ. Соберите более 1300 карт, сразитесь более чем в 60 заданиях одиночной кампании и побеждайте в эпических сетевых дуэлях.",
"1127500": "Mini Motorways — это стратегия развития дорог растущего города. Стройте сеть дорог, одна дорога за один раз, чтобы создать кипящий мегаполис. Перепланируйте дороги и проводите автострады, чтобы каждый получил оптимальный проезд по цели.",
"250600": "Муха поднимается в небо, размышляя о бессмысленности своего недолгого существования.",
"247080": "Crypt of the NecroDancer — удостоенная множества наград сложная ритм-игра в жанре «рогалик». Двигайтесь в такт музыке и выбивайте ритм на черепах врагов! Играйте под великолепный саундтрек авторства Дэнни Барановски, используйте MP3-файлы из своей коллекции — выбор за вами!",
"393420": "Hurtworld - это хардкорный многопользовательский шутер с уклоном на глубокую систему выживания, которая не становится тривиальной после обеспечения базовых потребностей. Созданная для хардкорных игроков, Hurtworld нацелена наказывать.",
"274940": "Окунитесь в темный подводный мир, где вам предстоит стать акулой или водолазом и одолеть своих врагов с помощью смекалки, командной игры и скрытности. Приготовьтесь познать беспощадный экшн и напряженность охоты. В Depth вам всегда придется быть начеку, ведь ИИ-противники или другие игроки не дадут вам отдохнуть ни секунды.",
"517630": "Независимый агент Рико Родригес попадает на Солис, огромный остров в Южной Америке, разрываемый конфликтами, тиранией и природными катаклизмами. Облачайтесь в вингсьют, хватайте полностью настраиваемый крюк и готовьтесь нести разрушения!",
"1388770": "Захватывающий силовой фэнтезийный симулятор с элементами тактического стелса, действие которого происходит в мире мусора, наполненном сточными водами.",
"690830": "Foundation — это бесклеточная спокойная игра в жанре средневекового градостроения с акцентом на гармоничном развитии, сооружении монументов и управлении ресурсами.",
"212500": "Присоединяйтесь к крупнейшему в мире сообществу игроков в отмеченном наградами онлайн-воссоздании легендарного Средиземья Дж. Р. Р. Толкина.",
"314160": "Поднимитесь в небо в любимом во всем мире авиасимуляторе! Отмеченный множеством наград Microsoft Flight Simulator X впервые появляется в Steam. Взлетайте из любой точки мира на самых знаковых самолетах мира в любой из 24 000 пунктов назначения. В Microsoft Flight Simulator X Steam Edition обновлена ​​многопользовательская игра и поддержка Windows 8.1.",
"474960": "Встречайте Quantum Break, игру о манипулировании временем от мастеров кинематографичных блокбастеров Remedy Entertainment. Quantum Break состоит из двух частей: игры и сериала, причем решения, принятые в игре, отразятся на ходе событий в сериале.",
"202970": "Call of Duty®: Black Ops II расширяет границы того, что фанаты привыкли ожидать от рекордной развлекательной франшизы, и переносит игроков в Холодную войну недалекого будущего.",
"475550": "Вы назначены на должность смотрителя многоквартирного дома в тоталитарной стране. Подслушивайте разговоры, обыскивайте квартиры и изучайте каждого жильца. Всё, что вы найдёте, вы сможете использовать против граждан. Точнее, вы ОБЯЗАНЫ так поступить. Но поступите ли?",
"1583320": "Pro Soccer Online — это многопользовательская онлайн-игра в футбол от первого/третьего лица, требующая высоких навыков. Он предлагает впечатления от спортивных игр, непохожие ни на один другой, с плавным, основанным на физике, управляемым вводом игровым процессом, который является конкурентоспособным и полезным, без какой-либо механики, требующей оплаты за победу.",
"736190": "В этом повседневном симуляторе, действие которого происходит в Китае, вы вступаете в роль обычного ребенка от рождения до окончания средней школы. Учитесь усердно, веселитесь, заводите друзей и примите участие в главном испытании — «Гаокао». Какой будет ваша жизнь после этого? А когда у вас родится ребенок, станете ли вы родителем-тигром?",
"2239150": "Минималистичная игра о строительстве и защите вашего маленького королевства.",
"245170": "--Игра на главной сцене Evo 2022! -- Непревзойденное впечатление от Skullgirls: 14 анимированных вручную персонажей, полностью озвученный сюжетный режим, бесчисленные палитры и беспрецедентный многопользовательский сетевой код на основе GGPO.",
"1372880": "The Day Before предлагает уникальное переосмысленное путешествие в постапокалиптический открытый мир в жанре MMO с элементами выживания, действие которой разворачивается в наши дни после разрушительной глобальной пандемии.",
"447020": "Farming Simulator 17 разработанный компанией Giants Software, приглашает вас попробовать себя в роли современного фермера. Решайте задачи, которые встают перед вами, занимайтесь животноводством, выращиванием зерновых, продажами и лесозаготовкой.",
"637090": "Возьмите под свое командование отряд боевых машин 'Mechs с пилотами MechWarriors и постарайтесь выжить в жестокой межзвездной гражданской войне.",
"2198150": "Tiny Glade – милая медитативная игра про строительство причудливых замков, уютных коттеджей и романтичных руин. Камешек к камешку, дощечка к дощечке – никаких битв, никакой возни с ресурсами или боязни ошибиться. Просто устройтесь поудобнее и стройте сказочные замки на заросших лугах.",
"17470": "Вы — Исаак Кларк, инженер космического корабля USG «Ишимура». Ты не воин. Ты не солдат. Однако вы — последняя линия защиты для оставшегося в живых экипажа.",
"813230": "Исследуйте пугающий лабиринт и разгадайте его секреты. Собирайте предметы, чтобы разительно изменить мир вокруг вас. Встречая разнообразных существ, попытайтесь выжить вопреки тому, что скрывается во тьме. Все не то, чем кажется.",
"837470": "Это прекрасный день в деревне, а вы — ужасный гусь.",
"299740": "Miscreated — это многопользовательская хардкорная онлайн-игра на выживание, действие которой происходит в постапокалиптическом будущем. Вам придется выжить против мутантов, игроков и даже самой матери-природы.",
"1237320": "Sonic Frontiers — это оригинальный приключенческий экшен в открытом мире, события которого разворачиваются на островах Звездопада. Сражайтесь с могущественными врагами, изучайте новую боевую систему, разгадывайте загадки островов и спасайте друзей Соника!",
"450540": "Вы любите хот-доги? А как насчет подков? Ручные гранаты? (все любят ручные гранаты) В любом случае, у нас есть все это и оружие. ТАК МНОГО ОРУЖИЯ. Так что, если вам нравятся артиллерийские снаряды, мясо и слишком много достойных стонов каламбуров, эта VR-песочница для вас.",
"207140": "Заводная мультиплеерная игра-платформер, в которой 4 игрока соревнуются между собой локально/в мультиплеере. Бегите, прыгайте, уворачивайтесь от других игроков и используйте арсенал оружия, чтобы выкинуть соперников за экран!",
"2707900": "Погрузитесь в преступный мир японских уличных гонок. Действие происходит в период с 1990 по 2009 год. Присоединяйтесь к местным командам уличных гонщиков в битве за контроль над территорией. Исследуйте реальные открытые миры, соревнуйтесь в гонках ставок, сражайтесь с другими командами и улучшайте свои автомобили с помощью детальной настройки автомобилей.",
"368230": "Kingdom — это 2D-гибрид стратегии с боковой прокруткой и управления ресурсами, выполненный в минималистском стиле, завернутый в красивую современную эстетику пиксельной графики.",
"274520": "Darkwood — это новый взгляд на хоррор с выживанием. Собирайте ресурсы, исследуйте насыщенный открытый мир днем, а ночью укрывайтесь в убежище и молитесь о скором рассвете.",
"841370": "Вот уже 20 лет серия NBA 2K задает направление развития в спортивных играх — от лучших в своем классе графики и игрового процесса до захватывающих режимов игры и реалистичного открытого мира Neighborhood. NBA 2K19 продолжает раздвигать границы жанра: теперь игра еще точнее передает культуру и эмоциональную заряженность баскетбола.",
"2537590": "Исследование мира и авиационная карьера: огромный парк самолетов и симуляция нового уровня в Microsoft Flight Simulator 2024.",
"16900": "Умный шутер от первого лица со сложной системой настройки персонажа и оружия. Создатель игры — один из разработчиков оригинального Rainbow Six® и Ghost Recon®. Не спешите. Подумайте. Сделайте.",
"208580": "Спустя пять лет после событий знаменитого оригинала Старая Республика находится на грани уничтожения лордами Ситхов. В роли одинокого Джедая-изгнанника вам предстоит принять решение: следовать за светлой стороной или поддаться темной?",
"1466640": "Автостопом навстречу свободе. Сумасшедшее процедурно-генерируемое дорожное приключение от именитых инди-разработчиков. У каждого своя дорога!",
"1401590": "Отдохните в уютном мире, наполненном волшебством Диснея и Пиксара! Откройте для себя богатые истории и постройте идеальную Долину вместе с более чем 50 героями и злодеями в этой приключенческой игре-симуляторе жизни.",
"42700": "Встречайте продолжение Call of Duty®: Modern Warfare 2, последнюю часть самой крупной серии экшенов с видом от первого лица, Call of Duty®: Black Ops.",
"567640": "Шестнадцать новых персонажей оказываются похищенными и запертыми в школе, где кто-то убьет, кто-то умрет, а кого-то покарают. Взгляните на рискованные быстрые расследования по-новому: вам предстоит раскрывать запутанные убийства и приговаривать одноклассников к смерти.",
"780310": "The Riftbreaker — динамичная игра в жанре выживания с элементами ролевого боевика и строительством базы. Играйте в одиночку или в кооперативе до 4 человек. Стройте свою базу, создавайте мощное оружие и исследуйте новые технологии, чтобы выжить.",
"629820": "Испытайте невероятный опыт, став хищником с вершины пищевой цепочки: гигантской акулой! Терроризируйте прибрежные зоны. Разрывайте пловцов и дайверов на части: дайте людям повод вас бояться!",
"2138710": "Sifu — это реалистичный боевик от третьего лица с напряженными боями в стиле кунг-фу и кинематографическими драками. Герой игры — одинокий воин, который ищет возмездия.",
"1985810": "Действие продолжения Call of Duty®: Black Ops, получившего название Black Ops Cold War, происходит в начале 1980-х годов - в один из напряженных периодов холодной войны.",
"783770": "Окунитесь в отчаянную войну за ресурсы между регулярными войсками и ЧВК в новом сетевом шутере от первого лица. Используй более 50 видов вооружения, динамическое окружение, широкий спектр гаджетов, а так же боевых и тактических дронов.",
"1124300": "HUMANKIND™– главный труд Amplitude Studios, историческая стратегия, где ВЫ перепишeте историю человечества. Это слияние культуры, истории и ценностей позволит вам создать уникальную цивилизацию. КАК ДАЛЕКО ВЫ ЗАВЕДЕТЕ HUMANKIND?",
"1432860": "Стройте свою ферму и отношения с местными жителями или продвигайтесь в квесте магии, монстров и драконов. Увеличивайте уровень через дерево навыков в многопользовательском режиме на 8 человек или отправляйтесь в приключение в одиночку!",
"236110": "Dungeon Defenders II — это совместная игра в жанре Action Tower Defense, наполненная ролевыми элементами, такими как добыча, прокачка персонажей и домашние животные.",
"519860": "Сражайтесь с натиском мистических культистов из захолустья, одержимых боевиков и еще более темных сил, пытаясь узнать, что скрывается под землей, в этом ретро-шутере от первого лица, вдохновленном легендами 90-х.",
"24200": "...сражения эпических масштабов, новые легендарные персонажи и совершенно новое оружие.",
"384190": "ABZÛ — это красочное приключение в подводном мире от создателей Journey®, где вам предстоит заниматься дайвингом. Погрузитесь в живописный мир океана, полный загадок и ярких красок. Но будьте осторожны, в морских пучинах вас ждет опасность.",
"1158160": "Coral Island — яркая и расслабляющая игра, новый взгляд на симулятор фермы. Будьте кем хотите и наслаждайтесь очаровательной жизнью на острове в своём ритме: растите овощи, заведите животных, налаживайте связи с островитянами и делайте мир вокруг живее и гармоничнее.",
"24240": "Возьмите на себя роль закоренелого преступника, выполняя интенсивные, динамичные налеты в погоне за очередным кушем",
"41070": "Serious Sam 3: BFE — это великолепное возвращение в золотой век шутеров с видом от первого лица и приквел оригинальной инди-сенсации Serious Sam: The First Encounter!",
"1458140": "Столкнитесь лицом к лицу с опасностями в Олимпийской зоне отчуждения, где машина — ваш единственный шанс на спасение в этом приключении на выживание! Собирайте ресурсы, грузите их в свой универсал и давите на газ, чтобы выжить.",
"1686940": "Играй онлайн или с друзьями, соревнуясь невероятными возможностями. Вам доступно множество вариантов, к примеру, уменьшающий луч, создание черных дыр, остановка времени и использование ракетного двигателя, чтобы избавиться от сцены. Выбирай выигрышные комбинации, чтобы победить в каждом раунде!",
"2784470": "Динамичная стратегия о строительстве королевства в жанре «роглайк», в которой вы будете расширять империю и сражаться в масштабных битвах против могучих правителей. Побеждайте, применяя безумные стратегии, и станьте сильнейшим из королей!",
"1549970": "Aliens: Fireteam Elite — это совместная игра на выживание от третьего лица в культовой вселенной Чужих. Сражайтесь с ордами ксеноморфов, повышайте уровень, усиливайте персонажа и снаряжение, пытаясь сдержать вечно растущую угрозу.",
"268050": "Новый проект от создателя легендарной серии Resident Evil Синдзи Миками и талантливой команды разработчиков Tango Gameworks, The Evil Within - настоящее воплощение жанра Survival Horror. Мир перевернется с ног на голову, увлекая вас в коварное хитросплетение интриг и непрекращающуюся череду кошмаров. Сможете ли вы разорвать порочный круг? Новейшие технологии освещения и анимации, доступные благодаря движку id Tech 5, окружат вас реалистичными порождениями больной фантазии и заставят испытать по-настоящему животный страх.",
"311560": "Assassin’s Creed Изгой – это самая мрачная глава в истории Assassin’s Creed. Станьте свидетелем превращения главного героя из убеждённого ассасина в жестокого охотника за ними. Следуйте вашему собственному кредо и отправляйтесь в захватывающее путешествие по просторам северной Америки, кварталам Нью-Йорка, долинам бурных рек и холодным атлантическим водам. Теперь ваша цель – уничтожить Ассасинов!",
"630": "Бесплатная кооперативная игра с открытым доступом к исходному коду.",
"2828860": "The Forever Winter — это тактический шутер, в котором вы и ваш отряд должны грабить мертвецов, чтобы выжить под гигантскими военными машинами в антиутопическом будущем, где искусственный интеллект-автоматы, кибернетически усовершенствованные солдаты и бесконечные конфликты. Спустя миллионы смертей, война продолжается в нашем последнем обновлении!",
"238090": "Действия новейшей главы всемирно известной серии игр Sniper Elite 3 разворачиваются на суровых и экзотических территориях боевых действий времен Второй мировой войны в Северной Африке. На этот раз вас ждет новый и смертельно опасный враг.",
"1182900": "Брат и сестра отправляются в новое странствие в суровом, полном тьмы мире. Решайте, на что вы готовы пойти, чтобы выжить и спасти своих любимых. Что бы вы ни выбрали, к вашим услугам богатый арсенал оружия, инструментов и магических сил.",
"10500": "Командуй морями, контролируй землю, создай новую нацию и завоюй весь мир",
"9900": "В Star Trek Online вселенная «Звездного пути» впервые появляется в по-настоящему огромном масштабе. Игроки занимают капитанское кресло и командуют своим звездолетом и командой. Исследуйте странные новые миры, ищите новую жизнь и новые цивилизации и смело отправляйтесь туда, куда еще никто не ступал.",
"1094520": "Вас перенесут в экзотическую пустыню, где вы будете набирать, обучать и вести свои войска в битву с конкурирующими городами и фракциями. Отправьтесь в уникальное приключение; Настраиваемые персонажи, профессии и фракции. Земля наполнена множеством скрытых тайн.",
"1097840": "Новая глава знаменитой саги Gears стала самой масштабной игрой серии. На пороге войны Кейт Диаз пытается выяснить природу своей таинственной связи с врагом и узнаёт, что истинная угроза для Серы — она сама.",
"2680010": "The First Berserker: Khazan — это беспощадный ролевой экшен, в котором вам предстоит стать Казаном, великим генералом империи Пелос, сумевшим преодолеть саму смерть. Отправьтесь на поиски тех, кто обрёк вас на погибель, и расквитайтесь с ними.",
"410900": "Раскройте свой творческий потенциал и стратегическое мастерство в Forts — бодрой стратегии в реальном времени, где соблюдаются законы физики! Придумывайте, стройте и адаптируйте грандиозные крепости, заполняя их под завязку разрушительным оружием, чтобы разнести базы врагов в пух и прах!",
"1934680": "Age of Mythology: Retold — игра от создателей культовой серии Age of Empires. Вам предстоит выйти за рамки привычной истории и погрузиться в мифическую эпоху, где бок о бок сосуществуют боги, чудовища и люди.",
"425580": "Уникальные события перенесут вас в залы давно забытого склепа. Единственный способ спастись — запертый в каменном постаменте вместе с запиской от вашего таинственного союзника. Его слова обещают помощь, но служат лишь для того, чтобы увлечь вас в захватывающий мир тайн и исследований.",
"2668510": "Игра-предшественница знаменитой Red Dead Redemption 2 впервые стала доступна на PC. В ней вам предстоит прожить историю бывшего бандита Джона Марстона, который пытается выследить уцелевших членов банды Ван дер Линде.",
"736260": "Baba Is You — это игра-головоломка, в которой правила, которым нужно следовать, представлены в виде блоков, с которыми можно взаимодействовать. Управляя ими, вы можете изменить работу игры, переназначить вещи, которые вы найдете на уровнях, и вызвать удивительные взаимодействия!",
"1601580": "Развивайте город в игре на выживание, действие которой происходит через 30 лет после того, как апокалиптическая Вьюга опустошила Землю. Во Frostpunk 2 вы будете противостоять не только бесконечной зиме, но и интригам в Совете.",
"220440": "Являясь пересказом истории становления личности Данте на фоне альтернативной современности, DmC Devil May Cry™ сохранила стильную постановку боя.",
"204450": "Золотые прииски и грязь салунов: Call of Juarez®: Gunslinger отдает дань почета историям о Диком Западе. Совершите эпическое путешествие по диким землям в роли безжалостного охотника за головами самых отъявленных преступников.",
"2334730": "Спуститесь в преисподнюю в поисках самой Смерти! Выбирайте из данных Богом сил, чтобы уничтожить орды его приспешников. Разблокируйте новых героев, собирайте мощные предметы и создавайте потрясающие синергии в этой игре про выживших в стиле рогалик.",
"1343370": "Лучшая ретро-фэнтезийная MMORPG на планете. Старая школа — это RuneScape, но… старше! Это открытый мир, который вы знаете и любите, но таким, каким он был в 2007 году. Сказав это, он даже лучше: Old School формируется вами, ее игроками, с регулярным новым контентом, исправлениями и расширениями, за которые проголосовали фанаты!",
"1604000": "Прямое продолжение игры Milk inside a bag of milk inside a bag of milk. Окунитесь в безумный и странный мир еще раз и помогите девочке стать немного счастливее.",
"736590": "Operation: Harsh Doorstop — это идеальная бесплатная песочница в тактическом шутере. Играйте в одиночном, многопользовательском или кооперативном режимах и исследуйте тысячи карт, оружия и транспортных средств, созданных сообществом, в Мастерской Steam. Создан разработчиками отмененного проекта Project Reality 2.",
"1448440": "Экшен-RPG в стиле темного фэнтези, посвященное Троецарствию. От Team NINJA, разработчиков Nioh.",
"429050": "Охотьтесь и ешьте другую рыбу – просто превращайтесь в более крупных зверей!",
"362680": "Fran Bow — жуткая приключенческая игра, рассказывающая историю Фрэн, молодой девушки, которая борется с психическим расстройством и несправедливой судьбой.",
"32440": "Ударьте кирпичом с I по VI! Пройдите все шесть фильмов «Звездных войн» в одной видеоигре! Добавление новых персонажей, новых уровней, новых функций и впервые возможность строить и сражаться в веселой галактике «Звездных войн» на своем ПК!",
"2420110": "Полное издание позволяет в полной мере насладиться «Horizon Запретный Запад» с бонусными материалами и сюжетным дополнением «Пылающие берега». В дополнении «Пылающие берега» содержатся дополнительные материалы для приключения Элой: новые сюжетные линии, персонажи и локации.",
"1583230": "Людям угрожает инопланетный картель, который хочет использовать их в качестве наркотика. Твоя задача — освободить и взять в напарники харизматичное говорящее оружие, победить Гармантюоза и его банду и спасти мир!",
"2080690": "Приготовьтесь к игре в жанре выживания в стиле \"Водный мир\", с модульным строительством базы, поисковом затопленных городов, крафтом, защитой базы и нашествиями NPC-кланов ради ресурсов и территории. Готовы к водной апокалипсису?",
"285920": "TerraTech — это приключенческая песочница с открытым миром, где вам предстоит проектировать и строить, крафтить, участвовать в битвах и исследовать. Придумывайте транспортные средства из библиотеки блоков. Собирайте обломки, создавайте и покупайте новые детали, чтобы выжить и стать лучшим планетарным старателем.",
"882100": "XCOM: Chimera Squad — это совершенно новый сюжет и пошаговые тактические бои во вселенной XCOM.",
"894020": "Сбор душ умерших от звонка до звонка — серые будни любой вороны, зарабатывающей на жизнь честным трудом. Однако работа может заиграть новыми красками, когда порученная тебе душа похищена, а отчаянный вор скрылся в краях, неподвластных смерти.",
"57300": "Замок, темнота и память, которую ты стёр сам. Хоррор, который научил всех прятаться в шкафах.",
"372000": "Tree of Savior (далее сокращенно TOS) — это MMORPG, в которой вы отправляетесь в путешествие на поиски богинь в мире хаоса. Сказочные цвета в сочетании с красивой графикой в ​​TOS заставят вас вспоминать драгоценные моменты на протяжении всей игры.",
"2248760": "Покупайте подержанные автомобили и мотоциклы, торгуйтесь с продавцами и узнавайте их реальную стоимость. Ремонтируйте, красьте и улучшайте технику, продавайте её с прибылью, расширяйте автосалон и станьте лучшим дилером города!",
"1812450": "Основывайте и расширяйте свои поселения, освобождайте земли и помогайте их жителям. Привлекайте других к своему делу, одновременно узнавая больше о жизни, которую вам пришлось оставить позади. Командуйте своими войсками, докажите свою храбрость в бою и закрепите за собой статус героя своего народа.",
"903950": "Не останавливайтесь, мир гибнет! В многопользовательской игре-выживалке про кочевников вам предстоит строить передвижные базы, осваивать новые пути, добывать пропитание, пиратствовать и торговать ради выживания. Присоединяйтесь к клану и защищайте свою территорию!",
"71340": "Отпразднуйте двадцатилетие Соника в новом приключении, призванном доставить удовольствие как новым, так и старым фанатам синего ежа!",
"297000": "Самая популярная игра в серии – теперь в HD-качестве! Сыграйте в обновленную версию пошаговой стратегии: помогите королеве Катрине Железный Кулак восстановить мир в родных землях и вернуть себе трон Эрафии. Судьбы героев снова в ваших руках! Создайте великую армию, не стесняйтесь использовать магию – одерживайте победы, о которых станут слагать легенды! Heroes® of Might & Magic® III – пошаговая стратегия, увидевшая свет в феврале 1999 года.",
"681280": "Descenders - современный экстремальный фрирайд-даунхилл с процедурно-генерируемыми трассами, где ваши ошибки имеют реальные последствия. Достигнет ли ваша команда славы и станет новой легендарной иконой?",
"670290": "Real Pool 3D (Poolians) - одна из лучших онлайн-игр в бильярд. Играйте против компьютера или реальных игроков со всего мира! Он поддерживает 8 различных типов игр в бассейне и режим командной игры.",
"8980": "Приготовьтесь к головокружительному безумию! Играйте за одного из четырех наемников, готовых к стрельбе, и уничтожьте все, что стоит на вашем пути! Borderlands с захватывающим экшеном, безумным шутером от первого лица, огромным арсеналом оружия, элементами ролевой игры и совместной игрой для четырех игроков — это прорывной опыт, бросающий вызов всем традициям современных шутеров.",
"283640": "Исследуйте призрачный и карающий остров в этой стилизованной 2D-ролевой игре. Salt and Sanctuary сочетает в себе быстрые и жестокие 2D-бои с хорошо развитой ролевой механикой в ​​проклятом мире забытых городов, пропитанных кровью подземелий и оскверненных памятников.",
"1520370": "Соберите настоящий спорткар из развалюхи своими руками. Зарабатывайте на жизнь срубая деревья, ночными гонками или доставкой пиццы. Создайте империю по созданию Кленового сиропа или вы хотите стать гонщиком и построить большой гараж?",
"1291340": "Город-игрушка. Размещайте блоки домов на парящих над морем платформах и смотрите, как по вашей воле возникают идиллические городки, пасторальные сады или масштабные мегаполисы.",
"359870": "FINAL FANTASY X/X-2 HD Remaster объединяет две самые любимые и популярные игры во всемирно известной серии, полностью обновленные для высокого разрешения и теперь доступные на ПК / Windows!",
"667970": "VTOL VR - это игра о боевых полетах в недалеком будущем, созданная специально для виртуальной реальности. Управляйте продвинутыми многоцелевыми самолетами, собственными руками переключайте тумблеры, нажимайте кнопки и управляйте виртуальными приборами.",
"47870": "Станьте лучшим полицейским города Seacrest County или самым опасным гонщиком!",
"303210": "«Руководство для начинающих» — повествовательная видеоигра от Дэйви Ридена, создателя The Stanley Parable. Он длится около полутора часов и не имеет никакой традиционной механики, никаких целей или задач. Вместо этого он рассказывает историю человека, изо всех сил пытающегося справиться с чем-то, чего он не понимает.",
"1096530": "Проявляйте инициативу, делайте внеочередные атаки, следите за тем, где герои стоят на поле боя и не забывайте, что позиция на возвышенности дает преимущество — игра использует набор правил SRD 5.1. В мире Соласты выбор делаете вы, но судьбу решает бросок игральной кости.",
"492720": "Эль Президенте возвращается! Станьте грозным диктатором или миролюбивым слугой народа в островном государстве Тропико и пройдите вместе со своими согражданами через четыре разные эпохи.",
"1102190": "Monster Train — стратегическая игра-«рогалик», основанная на построении колод и имеющая свою изюминку. В захватывающем путешествии по Аду на поезде вам придется принимать тактические решения, защищая несколько расположенных друг над другом полей сражений.",
"631510": "Популярные стильные экшены Devil May Cry, Devil May Cry 2 и Devil May Cry 3 Special Edition возвращаются в составе особой коллекции!",
"601430": "Детектив Себастьян Кастелланос потерял все, в том числе свою дочь. Чтобы спасти Лили, он должен спуститься в полные кошмаров глубины STEM.",
"262410": "World of Guns: Guns Disassembly - настоящий оружейный симулятор. В игре можно изучить оружие, посоревноваться в разборке/сборке. Пострелять в тире. Доступны более 290 моделей.",
"2384580": "Погрузитесь в мир захватывающих битв Троецарствия.",
"418530": "Spelunky 2 основывается на уникальных случайных испытаниях, которые сделали оригинал классическим рогаликом, предлагая огромное приключение, призванное удовлетворить как старых, так и новых игроков. Познакомьтесь с новым поколением исследователей, оказавшихся на Луне в поисках сокровищ и пропавшей семьи.",
"1904540": "Создайте команду своей мечты, перехитрите соперников и испытайте острые ощущения от больших европейских вечеров в Лиге чемпионов УЕФА. Вас ждет путь к футбольной славе.",
"1761390": "Займите центральное место в главной ритм-игре Хацунэ Мику с участием виртуальной поп-звезды №1 в мире! С потрясающим сет-листом и огромным гардеробом, это идеальный тур Мику — все, что ему нужно, — это вы.",
"979690": "The Ascent — экшн-RPG в духе киберпанка с режимами одиночной и кооперативной игры. Владеющая всем (и вами) мегакорпорация «Асцент Груп» внезапно прекращает свое существование. Сумеете выжить без нее?",
"788100": "Neon Abyss — это динамичный платформер в жанре roguelike, где вам предстоит войти в сформированный Аидом Мрачный отряд и ворваться в Бездну. Игра предоставляет бесконечные возможности использования предметов, а благодаря системе эволюции подземелий каждый сеанс станет испытанием. Ад ждет!",
"2990": "Испытайте драйв своей жизни, когда вы бросаетесь на трассу и за ее пределы, вызывая разрушение заборов, взрывы стенок шин, цистерны с водой и бочки с водой летят через трассу в другие машины.",
"527430": "Войдите в кишащий хаосом сектор Калигари, и уничтожьте нечисть с самыми могущественными агентами Империи человека. Warhammer 40,000: Инквизитор - Мученик это мрачный Action-РПГ с участием нескольких классов инквизиции, которые будут выполнять волю Императора.",
"1241510": "Вы ответите на ряд вопросов, которые откроют истину глубоко внутри. Эти вопросы могут вас смущать, но большие знания влекут за собой большие жертвы. Сможете ли вы пройти Испытание до конца, и если да, уверены ли вы, что хотите получить ответы, которые ищете?",
"24010": "Ваш спутник в лучшем железнодорожном хобби вот уже более 15 лет! От исторических паровозов до современных высокоскоростных и грузовых поездов — Train Simulator Classic создан любителями поездов для любителей поездов.",
"1161580": "Вы сильно задолжали корпорации LYNX, так что берите новейшие инструменты и отправляйтесь пускать на металлолом космические корабли в поисках ценных материалов. Улучшайте снаряжение и берите более выгодные контракты, чтобы выплатить долг в миллиард кредитов!",
"859580": "Покорите античное Средиземноморье в Imperator: Rome — глобальной стратегии от Paradox Interactive. Бороздите опасные воды политики и дипломатии, укрепляйте провинции и завоевывайте новые территории. К игре прилагается дополнительный контент, а также цифровой артбук.",
"235600": "В этом напряженном стелс-экшене террористическая группировка, известная как «Инженеры», начинает операцию под названием «Черный список», с каждой атакой нанося все большой вред интересам США. Только один человек способен остановить террористов: легендарный тайный агент Сэм Фишер.",
"201870": "Эцио Аудиторе идет по стопам великого наставника Альтаира прямиком в опасное путешествие, полное новых открытий.",
"557600": "Gorogoa – изящное развитие жанра головоломок, чудесная художественная история, которую придумал и нарисовал Джейсон Робертс.",
"269950": "Будущее авиасимуляторов уже наступило! X-Plane 11 — детальный, реалистичный и современный симулятор, которого вы так долго ждали. Интуитивно понятный пользовательский интерфейс, трехмерные кабины, новые эффекты, трехмерный звук, живые аэропорты и пейзажи со всего мира.",
"1451190": "Станьте бесспорным в самой настоящей на сегодняшний день игре о боксе! Благодаря реалистичной графике, потрясающим действиям и большему количеству лицензированных боксеров, чем когда-либо прежде, Undisputed дает вам беспрецедентный контроль над каждым дюймом ринга.",
"1637320": "Отражайте атаки инопланетных захватчиков и добывайте ресурсы в новой уникальной игре в жанре roguelike. Собирайте уникальные гаджеты и улучшайте оборудование, чтобы повысить шансы на выживание и не дать врагам уничтожить ваш купол!",
"692890": "Roboquest - быстрый Шутер-Роуглайт в выжженном мире будущего. Вы - перезагруженный Хранитель, готовый надрать металлические задницы! Сражайтесь бок о бок с другом или в одиночку, и уничтожайте орды смертоносных ботов в постоянно меняющихся локациях.",
"1599600": "Готовьте и подавайте собственные блюда, продумывайте дизайн и декор своих ресторанов и расширяйте границы своей кулинарной империи, разблокируя новые функции, возможности и блюда в локациях на базе процедурной генерации. Классическая кулинарная игра с постоянным прогрессом по принципу roguelite.",
"42910": "Комплект для четверых уже доступен!",
"590380": "Отразите угрозу, командуя могучими мехами из будущего. В этой пошаговой стратегии каждая попытка спасти мир – это новая ситуация, создаваемая случайным образом.",
"1929610": "Demonologist - это кооперативная игра ужасов, в которую могут играть как минимум 1 и до 4 игроков. Ваша цель - определить вид злого духа в проклятых местах и изгнать его, используя свое оборудование, в одиночку или вместе с командой.",
"955900": "Отправляйтесь на поиски бессмертия в этом стратегическом симуляторе и управленческой игре, основанной на китайской мифологии. Восстановите свою секту и обучайте новых учеников по пути совершенствования. Исследуйте магию и собирайте мистические артефакты, сталкивайтесь с древними опасностями и другими сектами на своем пути к духовному вознесению.",
"2427700": "PvP-битвы с инвентарем! Покупайте или создавайте мощные предметы, а затем стратегически размещайте их в рюкзаке.",
"3244220": "Минималистичная игра о копании ямы в саду недавно приобретенного дома. Собирайте ресурсы, продавайте их, улучшайте свое оборудование и раскройте таинственную тайну. Стоит всего одну чашку кофе!",
"997010": "Добро пожаловать в Брайтон! Примерьте значок полицейского и окунитесь в будни офицера полиции из выдуманного американского города.",
"104900": "Работайте вместе, чтобы выжить в разрушительной орде динозавров в огромных, бесконечных средах.",
"1592190": "BONELAB — это экспериментальная физическая игра в жанре экшен. Исследуйте загадочную лабораторию, наполненную оружием, врагами, испытаниями и секретами. Побег из своей реальности или сеять хаос. Никаких неправильных ответов.",
"736220": "Объединяйтесь и вступайте на передовую в Squad 44, самом реалистичном тактическом шутере о Второй мировой войне. Испытайте безжалостный реализм с огромным арсеналом точно воссозданного оружия и транспортных средств на огромных полях сражений Второй мировой войны.",
"2772750": "Глобальная военная стратегия, в которой судьба цивилизаций находится в ваших руках - объединятся ли они под вашим руководством или разрушатся в конфликте? Пройдите через всю сагу человеческой истории, от самых ранних дней до футуристической эры, создавая своё наследие век за веком.",
"895870": "Project Wingman — это экшен с полетами, позволяющий сесть за штурвал реактивного истребителя и стать настоящим асом. Сражайтесь в различных заданиях и игровых режимах — от напряженных воздушных боев до крупномасштабного наземного штурма в альтернативной реальности с выжженной землей.",
"1672970": "Пробивайтесь через врагов в совершенно новой динамичной игре во вселенной Minecraft, созданной по мотивам классических подземных приключений!",
"1397920": "Разбогатей или навечно стань частью шахты! Пробивай путь к сокровищам через бесконечные лабиринты из пещер, чтобы раскрыть тайны, сокрытые глубоко в недрах земли!",
"577800": "Лучшая* ежегодная серия спортивных симуляторов для текущего поколения консолей возвращается – встречайте NBA 2K18. Вас ждет беспрецедентный уровень достоверности и новые улучшения на игровой площадке. *Согласно данным сайта за 2008–2016 гг.",
"55150": "В игре Warhammer 40,000 Space Marine вам отводится роль капитана Титуса, космодесантника ордена Ультрамаринов, закаленного в огне бесчисленных сражений.",
"2646460": "Избежав смерти на ритуале жертвоприношения, вы находите могущественную маску с таинственными силами. Пройдите суровые испытания, уготованные природой, соберите последователей, создайте собственное племя, исследуйте цивилизации этого мира и раскройте истину, которую скрывает маска…",
"1012880": "Пост-апокалиптическая чёрная комедия возвращается — обновлённая и ещё более радиоактивная! Соберите запасы, спасите свою семью и приготовьтесь выживать в бункере. Принимайте трудные решения, воюйте с тараканами… и, может, вам удастся выжить. Или нет.",
"1275670": "На вашем рабочем столе появилась потерявшаяся девушка. Помогите ей собрать файлы с воспоминаниями, раскиданными по вашему компьютеру, и станьте друзьями.",
"330020": "Children of Morta - это сюжетная RPG-игра о необычной семье героев. Веди Бергсонов со всеми их недостатками и достоинствами против предстоящей коррупции. Сможете ли вы пожертвовать всем, чтобы спасти тех, о ком вы заботитесь?",
"707010": "Will To Live - MMORPG-шутер, действие которого разворачивается в суровом постапокалиптическом мире. Исследуй мир, вступай в схватки с мутантами и с другими выжившими, вступай в кланы в борьбе за существование и докажи свое право на Жизнь.",
"434650": "Lost Castle — это ролевой экшн с элементами roguelike, в который может играть до 4 человек по сети или локально. Побеждайте полчища монстров на рандомизированных уровнях!",
"221640": "Super Hexagon — это минималистичный экшен от Терри Каваны с музыкой Чипзеля.",
"378860": "ПУТЕШЕСТВИЕ В МИР АВТОСПОРТА В Project CARS 2 вас ждут захватывающие впечатления, прекрасные автомобили и невероятные трассы, а еще реалистичное управление, динамическая погода и множество режимов.",
"544920": "В проекте «Дарвин» десять заключенных должны выжить в стихиях, выслеживать друг друга, сражаться, создавать инструменты и использовать свои социальные навыки, чтобы остаться последними. Это уникальный подход к королевской битве, в котором режиссер шоу влияет на ход матча, а взаимодействие со зрителями позволяет создать единственное в своем роде игровое шоу.",
"729040": "Сыграйте в классику кооперативных шутеров с дропом оружия – но теперь с улучшениями! Берите любого из 4 безбашенных наемников и покорите пустынную планету Пандора.",
"3191030": "Рогалик в стиле Плинко, где ты работаешь на фабрике чисел. Запускай своего сферического друга, Набби, по доске с шариками, чтобы получать всё большие и большие числа! Но будь осторожен, если не сможешь насчитать производственную квоту, то солнце взорвётся.",
"918570": "Century: Age of Ashes представляет собой бесплатный онлайн-шутер 6-на-6 на командной основе, с ездой верхом на драконах. Развивай свои навыки с различными классами и драконами, участвуй в горячих боях на арене и командуй небесами вместе со своей командой в ходе стремительных воздушных сражений.",
"962730": "Испытай непревзойденный контроль над скейтом и быстроту реакции, катаясь по знаковым локациям из реального мира. Это эволюция геймплея скейтбординга. Благодаря системе отдельного управления ногами и основанному на физике уникальному геймплею любители скейтбординга наконец-то получили те возможности управления, о которых всегда мечтали",
"669330": "Командуйте огромными армиями в эпическом автобаттлере. Собирайте войска, меняйте юнитов, продумывайте разные построения и крушите врагов в детализированных 3D-боях. Главное — стратегия, защелкать мышью не выйдет. Победите соперников в режимах 1 на 1, 2 на 2, «Каждый сам за себя» или в режиме выживания.",
"350080": "Wolfenstein®: The Old Blood™ — это отдельный приквел к получившему признание критиков приключенческому шутеру от первого лица Wolfenstein®: The New Order. Это приключение состоит из восьми глав и включает в себя отличительные черты MachineGames — захватывающий экшен, захватывающий сюжет и напряженные сражения в жанре шутера от первого лица.",
"544730": "Торгуйте – стройте – селитесь: станьте повелителем Катана! Познакомьтесь с Катаном и сыграйте стартовый сценарий в многопользовательском режиме. Купите полную базовую игру, дополнения, карточную игру и многое другое, чтобы открыть для себя всю Вселенную Катана.",
"682990": "Вы когда-нибудь задумывались о создании собственной криминальной империи без юридических и моральных последствий? СИМУЛИРУЙТЕ ЭТО! Вползите в темные переулки уличного бизнеса в этой оригинальной игре про наркоторговлю и заработайте целое состояние! Сиквел игры - DDS2 - вышел уже сейчас",
"312990": "Экспендаброс собрал и нацелился на силы безжалостного торговца оружием Конрада Стоунбэнкса в лесах Восточной Европы.",
"337340": "Два врача путешествуют в обратном направлении через воспоминания умирающего, чтобы исполнить его последнее желание. Это самостоятельное продолжение To the Moon, но в него также можно сыграть первым.",
"34030": "В издании Total War: Definitive Edition выходит игра Total War: NAPOLEON вместе со всеми обновлениями и дополнениями.",
"893520": "Добро пожаловать в мир творческого разрушения, где все полностью разрушимо! Creative Destruction — это новая игра на выживание в жанре FPS/TPS-песочница, в которой невероятно весело строить и стрелять.",
"40700": "Machinarium — это отмеченная наградами приключенческая игра от создателей Phonopolis, CHUCHEL и серии Samorost. Помогите роботу Йозефу спасти его подружку Берту, похищенную бандитами из Братства Чёрных Шляп!",
"246900": "В Viscera Cleanup Detail вы вступаете в роль уборщика космической станции, которому поручено убирать после различных ужасающих научно-фантастических событий. Вместо пулеметов и плазменных винтовок ваши инструменты — швабра и ведро. Этот герой устроил беспорядок, и вам предстоит разобраться с последствиями.",
"1258080": "Shop Titans — отличный симулятор магазина с элементами ролевой игры. Изготавливайте мощное снаряжение, наполняйте лавку товарами и продавайте их начинающим героям... с наценкой! Скучать не придется!",
"463530": "Командуйте армией муравьев в боях ранее невиданных масштабов, сочетающих стратегию в реальном времени и строительство базы. Неприступные гнезда, тактическое использование феромонов и стремительная эволюция – ключи к выживанию в опасном мире насекомых.",
"1999360": "Идеальная высокотехнологичная симуляция резиновой утки Placid Plastic Duck подарит вам опасный уровень расслабления. С прохладной музыкой, мечтательной 3D-графикой и множеством разных счастливых уток, ваш единственный приоритет - плавать вокруг.",
"961200": "Вдохновленная наследием Paragon, созданная с любовью сообщества и работающая на движке Unreal Engine 5, Predecessor - это идеальный сплав шутера и MOBA-стратегии. Присоединяйтесь к более чем 2 000 000 игроков и играйте бесплатно прямо сейчас!",
"1361320": "После исчезновения инженера и его высокопоставленной жены начинается охота за обнаруженным ими ценным артефактом. Расследование приводит вас на чердак их дома, где стоит очень старый и странный кукольный домик...",
"1114150": "Покоряй горные склоны, автомагистрали и улицы города. Создай автомобиль мечты с детальным тюнингом, раскрывающим потенциал физики “CarX Technology“©. Участвуй в захватывающих гонках, наслаждаясь реалистичным геймплеем и динамичным управлением.",
"481510": "NIGHT IN THE WOODS — это приключенческая игра, ориентированная на исследование, сюжет и персонажей. В ней представлены десятки персонажей, которых можно встретить, и множество дел в пышном, ярком мире.",
"509980": "Вы – охотник на снежных людей, у которых важная миссия: раз и навсегда положить конец слухам и доказать себе, что снежный человек – это не просто миф или выдумка разума...",
"990630": "«Последний костер» — это история о приключениях потерявшегося уголька. Оказавшись в загадочном месте, он ищет путь домой, а заодно и свое предназначение.",
"641320": "Реалистичный кулинарный симулятор, в котором каждый ингредиент реагирует на реальную физику. Освойте более 80 в режиме карьеры дайте волю фантазии в песочнице. Готовьте, экспериментируете или устройте полный хаос на полностью интерактивной кухне.",
"292000": "No More Room in Hell 2 — напряжённый кооперативный зомби-шутер для 8 игроков. Сдержите натиск бесконечной нежити. Избегайте заражения. Выживайте вместе.",
"1286680": "Вас ждет грандиозное приключение, полное шуток, чудес и крупнокалиберных стволов! Создайте мультиклассового героя и отправляйтесь грабить, стрелять, рубить и колдовать. Ваша задача – остановить деспотичного Повелителя драконов.",
"1307550": "Craftopia — это совершенно новая многопользовательская игра на выживание, созданная в Японии. Для разработки этой игры мы объединили многие функции, которые нам нравятся, такие как охота, сельское хозяйство, рубка, строительство и автоматизация.",
"20510": "S.T.A.L.K.E.R.: Чистое Небо – самостоятельный приквел к знаменитой S.T.A.L.K.E.R.: Тень Чернобыля, который рассказывает вам историю группировки Чистое Небо, которая исследует Зону и хочет ее понять.",
"323470": "Благодаря настраиваемому аватару и классическим персонажам, DRAGON BALL XENOVERSE позволит вам заново посетить знаменитые битвы серии. Новые особенности включают в себя город Токитоки, новую механику героев и многое другое!",
"673950": "Создавайте собственную ферму самостоятельно или сотрудничайте с друзьями.",
"40970": "Долгожданный сиквел бестселлера Stronghold, Stronghold Crusader HD бросит вас в исторические битвы и осады времён походов Крестоносцев. В игре представлены новые ИИ, юниты и 4 исторические кампании, а также более 100 уникальных миссий.",
"292730": "Infinite Warfare включает в себя три уникальных режима игры: кампанию, cетевую игру и режим \"Зомби\".",
"2108330": "Тормозите позже всех в EA SPORTS™ F1® 23, официальной видеоигре чемпионата FIA Formula One World Championship™ 2023. Новая глава в увлекательном сюжетном режиме «Формула победы» погружает вас в стремительный водоворот переживаний и напряжённого соперничества.",
"627270": "Снарядите легендарных героев и злодеев вселенной DC и и придайте им новый облик в INJUSTICE 2. Ваша легенда. Ваша битва. Ваш Injustice.",
"3156770": "Witchfire — это ролевой шутер от первого лица в мире темного фэнтези, в котором вы играете за нечестивого грешника, ставшего охотником на ведьм и отправляющегося в свою последнюю миссию, чтобы обрести спасение.",
"866800": "Клементина наконец-то может обрести свой дом, но ей придется многим пожертвовать, чтобы защитить его.",
"858820": "Яркая и динамичная ролевая игра с элементами выживания для 1–10 игроков! Создавайте легендарные предметы, развивайте свою базу и отправляйтесь в эпическое путешествие по процедурно сгенерированным мирам, кишащим существами, готовыми на всё, чтобы начать Рагнарёк. Вальгалла подождёт, эйнхерий!",
"302670": "Call to Arms предлагает инновационное сочетание стратегии в реальном времени и управления от третьего и от первого лица. Действие игры разворачивается во времена современной войны. В игре представлены реалистично смоделированные транспортные средства и тяжелое вооружение. Приведите свои войска к победе или сражайтесь в одиночку в режиме действия от 3-го или 1-го лица.",
"447820": "Шутер от первого лица по Второй мировой войне, в который можно играть друг против друга или совместно. Призывайте огневую поддержку, захватывайте рубежи, отбрасывайте войска противника, участвуя в боях исторически точных подразделений армии США, Британского Содружества и немецкого Вермахта.",
"210970": "Вы просыпаетесь в одиночестве на острове, полном сложных и удивительных загадок.",
"2114740": "Blasphemous 2 вновь повествует о бесконечной борьбе Кающегося против Чуда. Погрузитесь в новый мир, полный опасностей, загадок и секретов. Проложите путь через полчища врагов, отделяющих вас от цели, чтобы навсегда положить конец темному циклу.",
"1533420": "Neon White – это сверхдинамичный экшн-платформер от первого лица, действие которого происходит за жемчужными вратами Рая.",
"1089090": "Откройте мир One Piece с новой стороны в Pirate Warriors 4! Сокрушайте армии врагов, переживите легендарные события аниме и ощутите мощь любимых героев в стремительных сражениях!",
"2725260": "Продолжение экшн-RPG «ENDER LILIES». Мир на краю гибели, где рукотворные живые существа — гомункулы — восстали против своих создателей. Исследуйте этот прекрасный жестокий мир, побеждайте могучих врагов вместе с соратниками и узнайте, что ожидает людей и гомункулов.",
"985890": "Среди лучших когда-либо созданных серий бит-эм-ап, джампинговых битов 90-х и потрясающих уличных боев, культовая серия Streets of Rage возвращается с мастерской данью уважения и возрождением классических боевиков, которые обожают фанаты.",
"606150": "Moonlighter - игра в жанре action-RPG с элементами rogue-lite, которая по-новому показывает нам привычный жанр. Вы погрузитесь в повседневную жизнь Уилла, отважного торговца, который втайне мечтает стать героем.",
"1880330": "В 2000 году на телеэкране городского новостного канала Шаньчэн необъяснимым образом появилась старая реклама, а представителем рекламы был умерший мальчик с особыми способностями - ребенок с тремя глазами. Ходят слухи, что призрак трехглазого ребенка похитил телевизионные сигналы. Бюро расследований было поручено провести расследование. По мере углубления расследования постепенно выявляется преступная группировка, скрывающаяся во тьме.",
"445980": "Wizard of Legend — игра о стремительных походах в подземелья с упором на динамичные сражения и магию. Не зевайте, шевелитесь и колдуйте! Быстро творя заклинания, вы сможете увязывать их в цепочки и применять эти разрушительные сочетания против врагов!",
"392110": "Endless Space 2 - это пошаговая военно-политическая sci-fi стратегия, в которой вам выпадет уникальная возможность стать правителем целой цивилизации и повести ее к холодным глубинам космоса. Ваши амбиции - залог ее будущего.",
"506540": "Настоящая королевская битва! Оттачивайте свои навыки и убивайте всех на своем пути, охотясь за оружием, снаряжением и славой на огромном поле битвы, где только ОДИН может быть назван ПОСЛЕДНИМ ВЫЖИВШИМ ЧЕЛОВЕКОМ. Зарабатывайте денежные призы в ежемесячных конкурсах,",
"512900": "Покоряй случайно сгенерированные города: грубой силой, скрытностью или хакерством — решать только тебе! Эта игра — коктейль из Nuclear Throne и Deus Ex с изрядной примесью анархии в духе GTA. В ней облегченный роглайк скрестили с симулятором в отлично проработанном мире и замешали все это на чистом безумии.",
"2071280": "Павшие герои из забытых легенд вернулись, чтобы сразиться с захватившим мир Кошмаром. Близится час решающей битвы! В этом приключенческом roguelike от создателей Curse of the Dead Gods© доступна как одиночная игра, так и онлайн-кооператив.",
"368260": "СРАЖАЙТЕСЬ И РАЗРАБАТЫВАЙТЕ СТРАТЕГИЮ, КАК СУПЕРГЕРОЙ, В САМЫХ ТЕМНЫХ УГОЛКАХ ВСЕЛЕННОЙ MARVEL. Играйте в качестве Охотника, легендарного истребителя демонов, который должен возглавить команду супергероев и сверхъестественных воинов перед лицом растущей апокалиптической угрозы.",
"1629520": "A Little to the Left — это уютная игра-головоломка, в которой вам предстоит сортировать, складывать и упорядочивать предметы домашнего обихода, одновременно присматривая за озорным котом с шаловливыми лапками. В веселой и понятной головоломке надо навести порядок в ста с лишним местах!",
"2365810": "Глубоко в царстве сна Сибилла оказывается втянутой в искаженный замок. Станьте сильнее и разблокируйте новые способности, чтобы создать глубокую систему движений, сражаться с врагами, находить секреты и освобождать утомленную душу замка Санса в этом 3D-платформере Metroidvania в стиле ретро.",
"329050": "Популярный стильный экшен DMC4 вернулся и стал лучше, чем когда-либо, и может похвастаться новыми игровыми персонажами и игровыми режимами!",
"437220": "Королевская битва возвращается! На отдаленном райском острове у 16 ​​участников есть 25 минут, чтобы исследовать, собирать предметы, создавать оружие, строить ловушки, охотиться и убивать друг друга. Победителем станет только один. Хватит ли у вас смелости выжить?",
"1669000": "Правьте волшебным королевством в Age of Wonders 4! Вас ждёт фирменное сочетание 4X-стратегии с пошаговыми тактическими сражениями.",
"367450": "Дайте волю своей инженерной мысли и творческим порывам в симуляторе строительства мостов с физическим движком. Насладитесь многочисленными задачками в кампании и сочиняйте собственные в режиме песочницы!",
"1029780": "Возведите поселение в стенах крепости посреди диких земель и приведите его к процветанию. Постройте самую могущественную колонию по эту сторону апокалипсиса в Going Medieval: играйте в стратегию на выживание с подробной системой управления и миром-песочницей, который поддерживает моды.",
"1100600": "Воплотите в жизнь ваше видение идеального футбола и в этом сезоне приведите ваш клуб к самым вершинам! Вас ждут новые функции, отполированная механика, невероятная глубина и насыщенность, а также полная ответственность за судьбу своей команды. В FM20 каждое ваше решение имеет значение!",
"241560": "The Crew — это революционная многопользовательская онлайн-игра, разработанная специально для консолей следующего поколения и высокопроизводительных ПК, которая использует новые аппаратные возможности для подключения игроков к сети, как никогда раньше. The Crew отправит вас и ваших друзей в безумное путешествие по огромному открытому миру Соединенных Штатов, наполненному захватывающими испытаниями. The Crew, щедрая по содержанию и адаптированная для подключенного поколения, представляет собой игру нового поколения, которая переосмысливает динамичное вождение.",
"293760": "Сделайте автомобили своей мечты реальностью с помощью непревзойденных инструментов проектирования автомобилей и двигателей Automation. Получите конкурентное преимущество благодаря продуманным инженерным и бизнес-решениям, которые помогут вам построить автомобильную империю. Станете ли вы лидером отрасли или просто сноской в ​​истории автомобилестроения?",
"291650": "Встречайте мир, где каждый ваш поступок и выбор так или иначе влияет на судьбу ваших героев. Obsidian Entertainment – студия-разработчик Fallout: New Vegas™ и South Park: The Stick of Truth™ – и Paradox Interactive с гордостью представляют вам игру Pillars of Eternity.",
"3058630": "Assetto Corsa EVO – новая, еще более реалистичная и технологичная версия одного из популярнейших мультиплатформенных автосимуляторов. Вас ждут машины и трассы различных видов и эпох.",
"1190970": "Покупайте, ремонтируйте, продавайте и станьте местной легендой. Или возьмите инструменты и постройте все с нуля! Благодаря онлайн-режиму совместной игры для 2-4 игроков вы сможете вместе играть как в режиме Песочницы, так и в сюжетном режиме.",
"365450": "Hacknet — увлекательный хакерский симулятор с интерфейсом компьютерного терминала. Следуйте указаниям покойного хакера, чья смерть, вопреки репортажам в СМИ, была вовсе не случайной.",
"1715130": "Классический шутер от первого лица от Crytek возвращается с динамическим игровым процессом, режимом \"\"песочницы\"\" и захватывающими эпическими битвами. В игре вас ждет обновленная графика, оптимизированная для оборудования нового поколения.",
"553420": "Исследуй земли, полные легенд, древних сил и яростных монстров. В изометрическом экшене TUNIC тебе предстоит большое путешествие в роли маленького лисенка.",
"374040": "Миры стали БОЛЬШЕ! Оставьте привычный мир и отправляйтесь в путешествие в неизведанное с Portal Knights! Участвуйте вместе с друзьями в остросюжетном творческом приключении, знакомясь с причудливыми трехмерными мирами-конструкторами. Создайте свое приключение. Создайте своего героя. Станьте лучшим Рыцарем Порталов!",
"954740": "Terminator: Resistance — это шутер от первого лица, действие которого разворачивается во время сценария «Войны будущего», который лишь мельком можно было увидеть в культовых фильмах «ТЕРМИНАТОР» и «Т2: СУДНЫЙ ДЕНЬ». Машины обречены на поражение, но какой ценой?",
"731490": "Всеобщий сумчатый любимец Crash Bandicoot™ возвращается! В коллекции N. Sane Trilogy он стал еще шустрее, веселее и обаятельнее! Переживите заново любимые моменты игр Crash Bandicoot™, Crash Bandicoot™ 2: Cortex Strikes Back и Crash Bandicoot™ 3: Warped, увидев их во всем блеске полностью переработанной графики!",
"248570": "Toribash - это инновационный бесплатный пошаговый онлайн-файтинг, основанный на физике ragdoll, в котором вы можете сами создавать свои движения. Полный контроль над телом персонажа, сотни игровых модов и моря крови с полным расчленением тела - уничтожайте своих врагов так, как нигде прежде!",
"1954200": "экшен-приключение с захватывающим сюжетом, где исследование мира органично сочетается с динамичными боями. Вам предстоит играть за юную проводницу духов Кену, отыскивать священный горный храм и расследовать события прошлого.",
"1465460": "Возглавьте группу выживших в своем городе. Выберите базу, а потом отстройте и отремонтируйте окружающие здания, чтобы создать автономное поселение. А по ночам защищайте зону от зараженных! Для загрузки карт в российских сетях требуется VPN!",
"1139980": "Создавайте, выращивайте, и стройте! В Travellers Rest вам придётся использовать все доступные инструменты, чтобы стать лучшим трактирщиком в королевстве. Готовьте уникальные блюда и напитки, чтобы порадовать своих клиентов, открывая для себя мир и его колоритных персонажей.",
"1577120": "После заката солнца в последний день летнего лагеря для вожатых «Хэкеттс Куори» начинается ночь, полная ужасов. Их преследуют мрачные охотники, перепачканные в крови, и куда более жуткие создания — но ещё страшнее решения, которые им придётся принять, чтобы выжить.",
"2780980": "Игра в жанре социальной дедукции от первого лица, сочетающая экшен в реальном времени и общение, рассчитанная до 16 игроков. Большинство игроков будут сотрудничать, чтобы выполнять задачи и достичь победы, а небольшая группа диссидентов сделает всё возможное, чтобы им помешать, не будучи раскрытой.",
"1296610": "Peglin — это рогалик Пачинко. Сражайся с врагами, собирай различные шары и разбивай штыри, чтобы наносить урон. Получай реликвии, которые радикально изменят игру и гарантируют, что у тебя не будет двух одинаковых забегов. Целься осторожно, чтобы выжить в этой уникальной пошаговой RPG!",
"1238820": "Наслаждайтесь полной свободой и сражайтесь так, как вам хочется. Изучайте 29 огромных сетевых карт и используйте богатый арсенал техники, оружия и устройств, чтобы повысить накал схватки. Сражаясь, вы с каждой секундой будете приближаться к новому званию и множеству бонусов. Так что вперёд, в бой!",
"1435790": "Головоломка от первого лица, в которую можно играть как в одиночку, так и в кооперативе по сети. Исследуйте множество интерактивных квест-комнат. Передвигайте мебель, собирайте и осматривайте все, разбивайте горшки и взламывайте замки! Играйте в тысячах комнат, созданных сообществом, через редактор уровней.",
"1766740": "Путешествуйте по острову в старом поезде, периодически улучшайте его и используйте для борьбы со злым пауком по имени Чарльз.",
"355180": "Codename CURE является игрой от первого лица для совместной игры против зомби, и поддержкой до пяти игроков, обеспечивающая динамическую, быструю игру с превращением зомби в ошмётки, ​как с миссиями, так и с целью выживания.",
"1490890": "Станьте клинком, рассекающим демонов!",
"562810": "НАЧНИТЕ СВОЙ ПУТЬ К УСПЕХУ! «Monopoly+» с ее объемными городскими пейзажами и забавными второстепенными персонажами выводит классическую франшизу на совершенно новый уровень.",
"368340": "\"CrossCode — это экшен-RPG с 2D-графикой в духе ретро-игр. Это 16-битная графика в стиле SNES, потрясающая физика, динамичная система боя, увлекательные загадки и захватывающая фантастическая история. \"",
"388410": "Получите максимум впечатлений от DARKSIDERS 2! Разрешение 1080 точек. Переработаны и отрегулированы игровой баланс и распределение добычи. Улучшен графический движок (особенно освещение и тени). Улучшена графика уровней, персонажей и окружения.",
"323850": "Move or Die - абсурдно быстрая игра для четырёх игроков (локально или онлайн), где правила меняются каждые 20 секунд. Идеальная игра, портящая отношения с друзьями.",
"1341290": "Вы с товарищем очнулись в зловещем замке Касл-Рок. Вас предали, или вы оказались здесь по своей глупости? Узнайте правду в новой части серии совместных головоломок We Were Here! Сможете ли вы противостоять темным силам или же останетесь здесь... навсегда?",
"292120": "Final Fantasy XIII — это фэнтезийная ролевая игра, в которой группа отважных людей борется с судьбой в утопическом небесном городе Кокон и первобытном мире Пульс. Следуйте за стремительными сражениями и приключениями стильной героини Лайтнинг в загадочном новом мире.",
"706990": "Процедурный кубический шутер в лучших традициях жанра. Игра представляет собой насыщенный коктейль, состоящий из самых популярных и функциональных игровых решений. Кастомизация персонажей, открытие кейсов и улучшение имеющегося арсенала — все это доступно в игре уже сейчас!",
"10680": "Выживайте и охотьтесь за добычей в смертельных джунглях и болотах в новой и захватывающей игре от первого лица.",
"763890": "В Wildermyth вы проследите за героями на протяжении всей их жизни — от дней, когда они были зелеными новичками, до расцвета сил, а затем до старости. Это ролевая игра с генерируемым сюжетом, в которой тактические боевые и сюжетные решения меняют мир и вашу команду героев.",
"216150": "Присоединяйтесь к более чем 260 миллионам игроков по всему миру в MapleStory, крупнейшем в мире 2D-приключении MMORPG! Играйте сейчас бесплатно.",
"391460": "Free2Play-шутер о противостоянии двух непримиримых сторон, представленных правительственными военными организациями и вооруженными наемниками. Испытайте свои силы в виртуальных битвах с невероятной динамикой и ураганным геймплеем в духе классических шутеров.",
"394690": "ИГРАЙТЕ, ТВОРИТЕ, ВЕЧЕРИНАЙТЕСЬ! Tower Unite — это игра для вечеринок в виртуальном мире, основанная на сообществе, с онлайн-играми, развлечениями, мероприятиями и абсолютно НИКАКИМИ микротранзакциями.",
"489940": "Battalion — это ода любимым соревновательным шутерам и классический игровой процесс в игре нового поколения. Побеждайте в динамичных боях 5 на 5, используя разнообразное оружие и тактику. Помимо самой игры в комплект Battalion 1944: First to Fight Edition входит цифровая копия саундтрека игры и военные наборы (5 шт.), а также эксклюзивная для этого издания окраска оружия.",
"421020": "Лучшие гонки по бездорожью возвращаются! В DiRT 4 вы насладитесь самыми мощными машинами и внедорожными режимами. Система игры Your Stage позволит создать миллион маршрутов одним нажатием кнопки.",
"605740": "Станьте представителем закона или спасайте жизни! В Flashing Lights вы можете играть в одиночном режиме или мультиплеере до 10 человек. Вас ждет открытый мир с заданиями для полиции, экстренных служб и скорой и с кучей модификаций от игроков — с таким обилием возможностей вы точно не заскучаете!",
"314650": "Научно достоверный и фотореалистичный трехмерный космический симулятор, моделирующий всю Вселенную. Первый интерактивный планетарий с процедурной генерацией, используемой в неизученных областях Космоса.",
"1574820": "Судьбоносная встреча запускает цепную реакцию, изменившую жизнь Марка. Люди пропадают, а воспоминания оказываются ложными. В этой приключенческой игре вы должны вместе с Марком и его друзьями добраться до правды и раскрыть тайну, пока не поздно.",
"1180660": "«Скажи мне, почему» — это удостоенная множества наград эпизодическая приключенческая игра от Dontnod Entertainment, в которой близнецы используют свою сверхъестественную связь, чтобы узнать правду о своем тревожном прошлом.",
"1164940": "Trepang2, сумасшедший кровавый шутер от первого лица в мире далекого будущего, сделает вас крепким орешком. Враги пожалеют, что они родились на свет, увидев, как вы уклоняетесь от пуль и оставляете за собой одни разрушения в этой лихорадочной стрелялке не для слабонервных.",
"374280": "Hired Ops — сессионный онлайн-шутер, посвященный боевым операциям, в котором игроку придется пойти на все ради господства на мировом рынке наемников.",
"1046030": "ISLANDERS – это минималистичная стратегия про строительство городов на красочных островах.",
"488860": "MADNESS: Project Nexus — это игра от третьего лица Run n' Gun/Beat'Em Up, наполненная аркадным экшеном и жестокой игрой, требующей нажатия кнопок. Пробейтесь сквозь толпы плохих парней в сюжетной кампании или создайте свою идеальную машину для убийств в нескончаемом натиске в режиме арены.",
"300": "Классическая игра про Вторую мировую войну от Valve — теперь и на Mac.",
"1364020": "Boundary — это многопользовательский тактический космический шутер, в котором участвуют ожесточенные командные перестрелки в условиях невесомости и выполняются операции в условиях низкой гравитации на орбитальных космических объектах против других вражеских астроператоров и других объектов.",
"406150": "Refunct - это мирный, короткий платформер от первого лица о восстановлении красочного мира.",
"233130": "Shadow Warrior — это смелое переосмысление классического шутера 3D Realms от независимого разработчика Flying Wild Hog (Hard Reset) с легендарным и сообразительным воином Ло Вангом.",
"1746030": "«Убийства на реке Янцзы» — это детективная игра в стиле Ace Attorney, которая отправляет вас в путешествие по Китаю начала 20-го века и раскрывает серию интригующих дел. Используйте свои логические рассуждения и навыки дедукции, чтобы находить улики, допрашивать подозреваемых и разгадывать загадки.",
"241600": "Rogue Legacy представляет собой генеалогическую игру в жанре rogue-\"LITE\", в которой героем может стать любой. Каждый раз, когда вы погибаете, на ваше место встает ваш ребенок. Каждый ребенок уникален. Один может быть дальтоником, другой — страдать от головокружения, а третий может даже быть карликом. Но это нормально, ведь идеальных людей не бывает, и добиться успеха может любой.",
"2909110": "Отправляйтесь в путь в составе специализированной команды игроков, которым поручено добыть секретные материалы, уклониться от вируса черной слизи и кошмарных существ, которые он породил. Время истекает, прежде чем правительство США инициирует разрушительный ядерный удар, чтобы сдержать распространяющуюся угрозу.",
"1496790": "Бэтмен мёртв. Теперь всё зависит от семьи Бэтмена: Бэтгёрл, Найтвинга, Красного Колпака и Робина. Только они способны защитить Готэм.",
"251060": "Новый справочник в РТС во всей красе! Серия Wargame возвращается в строй, крупнее, богаче и зрелищнее, чем когда-либо прежде. В Wargame Red Dragon вы участвуете в крупномасштабном конфликте, в котором западные силы сталкиваются с коммунистическим блоком.",
"2399420": "Окунитесь в мир гонок на выносливость и примите участие в официальной игре чемпионата мира по гонкам на выносливость FIA и «24 часа Ле-Мана». Соревнуйтесь на новейших гиперкарах, машинах LMGT3, LMP2 и GTE на трассах с лазерным сканированием с динамической погодой, рейтинговыми онлайн-соревнованиями, асинхронным кооперативом и виртуальной реальностью.",
"973760": "Встречайте новую ролевую игру от разработчиков «Ведьмак 3: Дикая Охота». Угроза неизбежного вторжения вынуждает Мэву, закалённую в боях правительницу Лирии и Ривии, вновь вступить на тропу войны и пройти мрачный путь потерь и мести.",
"257420": "Крутой Сэм 4 вновь разжигает классическую серию шутеров от первого лица в образе мощнейшего приквела, заряженного взрывным арсеналом, мясорубкой межгалактического масштаба и крутыми фразочками.",
"42680": "Самая продаваемая за всю историю серия шутеров от первого лица возвращается с эпическим продолжением игры Call of Duty®: Modern Warfare® 2",
"221680": "Играй на гитаре или бас-гитаре и начинай своё музыкальное путешествие с Rocksmith 2014 Remastered Learn & Play! Идеально для новичков и профессионалов, учись в своём собственном ритме с 60 треками и настраиваемыми инструментами. Подготовься к рок-н-роллу!",
"257850": "Исследуйте красивый, огромный и разрушенный мир, полный опасностей и утраченных технологий.",
"2488620": "Выезжайте на старт и попадите в 20-ку. Станьте величайшим пилотом в EA SPORTS™ F1® 24, официальной видеоигре чемпионата мира FIA Formula One World Championship™ 2024.",
"356670": "Сможете ли вы пережить 1000 комнат милого ужаса? Или ты сломаешься, когда привлекательность начнет угасать, и ты спасаешься бегством от невыразимо отвратительных существ, которые трясутся и корчатся в недрах этого дома? Они ждут тебя, они ждут и жаждут встречи с тобой. Они жаждут наконец встретиться с вами и показать, насколько гибкой может быть ваша кожа после того, как она пропиталась кровью. Сможете ли вы выдержать это путешествие, готовы ли вы победить невозможное, безумное и бестелесное?",
"388090": "В этой последней главе оригинальной истории Five Nights at Freddy вам придется еще раз защитить себя от Фредди Фазбера, Чики, Бонни, Фокси и еще худших существ, скрывающихся в тени.",
"1371580": "Myth of Empires — многопользовательская военная игра-песочница с высокой степенью свободы. Выживайте и творите в мире множества цивилизаций! Собирайте армии, захватывайте PVE и PVP территории и создайте целую империю! Myth of Empires – DLC Цивилизации Западных земель официально в сети!",
"536220": "Четыре года спустя после того, как зомби разодрали общество на части, в хаосе возникают карманы цивилизации. Но какой ценой? Можно ли доверять людям на этом последнем рубеже?",
"24980": "Вы готовы потерять все, чтобы спасти галактику? Вы должны быть готовы, капитан Шепард. Пришло время собрать самых сильных союзников и заручиться помощью лучших бойцов галактики, чтобы дать отпор Жнецам.",
"343780": "Начните на острове с простой удочкой. Станьте мастером-котом-рыболовом, владеющим радаром, и прочесывающим море в поисках самой большой и опасной рыбы. Каждая рыба обладает уникальным поведением, которое вы научитесь использовать, адаптируя свой арсенал удочек под свой стиль игры. Мррроу!",
"228280": "Возвращение классики! «Baldur’s Gate: расширенное издание» — это восстановление изначального приключения и дополнения Tales of the Sword Coast, но с улучшениями производительности, чтобы вы могли пережить бессмертное путешествие по Dungeons & Dragons без всяких препятствий.",
"1150440": "Отправьтесь в захватывающее путешествие с Aliens: Dark Descent — отрядном однопользовательском экшном в культовой вселенной «Чужих». Остановите распространение нового жуткого вида ксеноморфов на луне Лета, командуя солдатами в реальном времени.",
"1113120": "IXION - это неумолимая одиссея по строительству среди звезд. В роли администратора Тиккуна, прототипа космической станции DOLOS, вам предстоит найти баланс между выживанием и освоением, управляя инфраструктурой, ресурсами и экипажем. Сможете ли вы сохранить пламя человечества в холодной темноте?",
"2634950": "Звание «самого быстрого» никогда не меркнет. Гоняйте по закрытым ночным шоссе Токио будущего на своем настроенном автомобиле. Побеждайте соперников в «SP Battle», где водители сражаются, истощая очки духа. Уникальная гоночная игра, в которой важны только правила победы.",
"2840770": "«Аватар: Рубежи Пандоры™» — приключенческая игра с видом от первого или третьего лица. Сюжет разворачивается на просторах Западного рубежа. Вернитесь к своим забытым корням и узнайте, каково это — быть на'ви.",
"1928980": "Nightingale — это игра на выживание в открытом мире, в которой вам предстоит путешествовать по загадочным и опасным Царствам Фейри. Будучи отважным путешественником по царству, вы будете побеждать чудовищных врагов, выживать во враждебных условиях и строить сложные поместья в визуально потрясающем мире Gaslamp Fantasy.",
"3228590": "Deadzone: Rogue — это roguelite-шутер от первого лица, действие которого разворачивается в космосе. Прорывайтесь сквозь орды враждебных машин, комбинируйте мощные улучшения и элементы, чтобы создать свой билд, и становитесь сильнее с каждым забегом — в одиночку или в кооперативе.",
"212070": "Star Conflict — динамичный космический экшен, позволяющий сесть за штурвал боевого звездолёта и принять участие в масштабных сражениях. Соберите собственную флотилию и отправляйтесь исследовать галактику!",
"35720": "Трем героям предстоит совершить полное опасностей путешествие в фантастическом сказочном мире. Решайте задачки, наслаждайтесь графикой и не забудьте про друзей!",
"2103140": "«Magicraft» — это roguelike-игра с бесконечными возможностями комбинирования заклинаний. Создавайте эффекты, о которых не подозревали даже разработчики.",
"617670": "Минимальная физическая головоломка со взрывами",
"2415010": "Сражайтесь и романтизируйте с тем, кто охотится за вашей душой, в «Свидании со смертью», симуляторе романтического чата, где вы встречаетесь (?) с самим Мрачным Жнецом. Создайте своего персонажа, украсьте свою квартиру и общайтесь с очаровательным, но опасным Мрачным Жнецом с помощью текстовых сообщений и видеозвонков.",
"578310": "Brain / Out — это многопользовательский шутер в духе пост-советского пространства! Вас ждут динамические сражения с внушительным выбором оружия и спец. средств для уничтожения противника! Экипируйтесь и Вступайте в бой прямо сейчас!",
"498240": "В этой жесткой и полной насилия истории от отмеченных наградами создателей The Walking Dead (компания A Telltale Games Series) вы обнаружите то, что разрушит как мир Bruce Wayne, так и уже пошатнувшийся уклад коррумпированного Gotham City. Ваши действия и решения определят судьбу Batman.",
"451340": "Стань золотоискателем. Тяжело работай, глубоко копай, найди золото и стань самым богатым человеком на Аляске. Используй различные специальные машины, чтобы добыть как можно больше золота!",
"299360": "Пятеро своих. Пятеро чужих. Столкнитесь лицом к лицу в тактическом сражении, где все, что вы строите, рушите, создаете или простреливаете, влияет на весь игровой мир. Выстройте оборону и бросайтесь в бой, чтобы уничтожить противника. Используйте внезапность: проройте ходы под картой или катапультируйтесь над ней! Будьте хитры, будьте изобретательны, будьте разрушительны! Вы можете стать огромным металлическим роботом, безумным ученым, смертоносным ниндзя и много кем еще. Стройте из множества видов блоков, работайте сообща и станьте одной командой в шутере от первого лица, где игры никогда не повторяются. Приготовьтесь! Пришло время Block N Load.",
"330830": "Действие всех пяти эпизодов игры разворачивается в беспощадном мире Пандоры в промежутке между событиями Borderlands 2 и Borderlands 3. История о пути к величию двух искателей приключений отличается фирменным юмором в стиле Borderlands.",
"242680": "Nuclear Throne — это шутер-«рогалик» с видом сверху, действие которого происходит в постапокалиптическом мире. В этом мире у человечества нет никакой «последней надежды». Оно вымерло, и теперь планету населяют мутанты и чудовища. Сможете ли вы добраться до Ядерного трона?",
"627690": "Idle Champions of the Forgotten Realms — это стратегия в мире Dungeons & Dragons, где воители из разных уголков мультивселенной D&D отправляются в грандиозные приключения.",
"402710": "Osiris: New Dawn — это беспощадная игра на выживание в космическом будущем ближайшего будущего с кинематографической атмосферой и элементами ужаса. Играйте в качестве специалиста по миссиям в одиночном или многопользовательском режиме, чтобы построить свою планетарную базу, пилотируемые транспортные средства и управляемые дроны, исследуя опасную солнечную систему вдали от Земли.",
"1574580": "Strange Horticulture — мистическая головоломка про магазин загадочных растений. Ищите и изучайте образцы, заботьтесь о коте, подружитесь с ведьмами или вступите в секту. Меняйте сюжет с помощью своей растущей коллекции и раскрывайте мрачные тайны Андермира.",
"2904000": "Игра в жанре survivors с ОНЛАЙН-КООПЕРАТИВОМ (1-4 игрока). Сразите полчища с друзьями-волшебниками. Командные задачи, улучшения и мощные магические синергии. Дружественный огонь в аду пуль: никто не в безопасности! Быстрый рогалик-экшен.",
"1233570": "СЕТЕВЫЕ ФУНКЦИИ ЭТОЙ ИГРЫ ОТКЛЮЧЕНЫ. Mirror's Edge™ Catalyst выводит приключенческий экшн на новый уровень и погружает игроков в историю сражающейся за свободу Фейт.",
"1102130": "В свои 25 Флоренс Йео словно топчется на месте. Жизнь свелась к тому, что девушка только работает, спит и убивает время в соцсетях. Но однажды она встречает виолончелиста по имени Криш – и ее взгляды на мир полностью меняются.",
"12100": "Добро пожаловать в Либерти Сити. С чего все началось. Великолепная озвучка, мрачно-комический сюжет, потрясающий саундтрек и революционный игровой процесс с открытым миром делают Grand Theft Auto III игрой, которая определила жанр открытого мира для целого поколения.",
"859570": "Secret Neighbor - захватывающий многопользовательский хоррор, в котором группа детей пытается спасти своего друга из жуткого подвала Соседа. Единственная проблема в том, что один из детей - это замаскированный сосед.",
"738520": "Погрузитесь в историю простого мужика с простыми потребностями, пытающегося выжить в пучинах открытого космоса. Исследуйте, стройте, пинайте трупы и тычьте во всё курицей.",
"405640": "Pony Island - это напряженная игра с ложным обличием. Вы находитесь в чистилище, внутри зловещего и неисправного игрового автомата, разработанного самим дьяволом. Это вовсе не игра о пони.",
"911400": "Переживите события Американской революции заново в обновленной версии Assassin's Creed® III с улучшенными графикой и игровой механикой. В комплект входят все дополнения для одиночной игры и обновленная версия Assassin's Creed Liberation.",
"17460": "В роли командира Шепарда вы возглавите элитный отряд в героическом, насыщенном событиями приключении по всей галактике.",
"1324780": "Easy Red 2 - игра для тех, кто хочет окунуться в атмосферу огромных сражений Второй мировой войны в реалистичном и имитационном ключе. Пробивайтесь сквозь солдат, танки и взрывы и узнайте, как выжить на поле боя вместе со своим отрядом.",
"397950": "Clustertruck — это симулятор грузовика, основанный на хаотичной физике. Прыгайте через безумные уровни в игре «Пол — лава» на мчащихся грузовиках, которыми управляют ужасные водители.",
"1063660": "Bendy and the Dark Revival® — это игра ужасов на выживание от первого лица, действие которой происходит в самой жуткой из когда-либо существовавших мультипликационных студий. Откройте для себя правду. Побег из студии. Прежде всего, бойтесь Чернильного Демона… и выживите.",
"339340": "Обновленная версия Resident Evil 0 - это потрясающая HD-графика, улучшенные элементы управления и многое другое.",
"282800": "100% Orange Juice — это цифровая многопользовательская настольная игра, в которой участвует звездный состав разработчиков Orange Juice. Персонажи из Flying Red Barrel, QP Shooting, Suguri и Sora объединяются с совершенно новыми персонажами, чтобы сразиться... с игрой в кости.",
"1515210": "The Past Within — новый кооперативный опыт от Rusty Lake! Играйте вместе с надежным человеком: один будет в Прошлом, другой — в Будущем. Изучайте окружение и передавайте информацию партнеру. Решайте головоломки и раскройте план Альберта Вандербума.",
"1267910": "Melvor Idle — это приключенческая игра в стиле RuneScape, в которой было отброшено все лишнее, но сохранена суть! Это богатая на возможности пассивная игра, сочетающая классические элементы с новым игровым процессом. Прокачайте более 20 навыков и познайте истинный дзен.",
"986130": "Действие этого научно-фантастического стелс-детектива в стиле нуар происходит на улицах города, погрязшего в преступности и коррупции. Насладитесь захватывающей игрой в жанре песочницы с полной симуляцией событий. Примерьте на себя роль частного сыщика и выполняйте различные контракты.",
"2163330": "Орда приближается, но вы готовы сражаться с ней! Соберите свою команду и определите улучшения, чтобы найти наиболее эффективные синергии против тысяч нежити. Выживайте. Затем развивайтесь. И затем преодолейте все границы в этом на удивление простом, но захватывающем реверсном пулевой ад.",
"6000": "Вы — лидер элитного отряда республиканских коммандос, ваша миссия — проникнуть, доминировать и, в конечном итоге, уничтожить врага. Ваш отряд будет следовать вашим приказам и руководству, работая вместе как одна команда — инстинктивно, разумно, мгновенно. Вы их лидер. Они ваше оружие.",
"270150": "RUNNING WITH RIFLES - тактический шутер с видом сверху с открытым миром и RPG механикой. В RWR, ты присоединишься к рядам армии как обычный солдат, каких тысячи вокруг тебя.",
"239350": "Spelunky — это уникальный платформер со случайными уровнями, которые каждый раз предлагают новые захватывающие впечатления. Путешествуйте глубоко под землей и исследуйте фантастические места, наполненные всевозможными монстрами, ловушками и сокровищами.",
"1611600": "Реалистичный, захватывающий, невероятный. WARNO – лучший симулятор боев Третьей мировой войны от мастеров стратегии Eugen Systems. Холодная война станет горячей, когда вы начнете управлять сотнями юнитов на прекрасном и жестоком поле битвы. Перехитрите, одолейте и приведите войска к полной победе!",
"17480": "Отчаявшееся руководство обреченного Советского Союза отправляется в прошлое, чтобы изменить историю и возродить славу Матушки-России.",
"1170880": "Лаванда, проснувшись этим утром, не ожидала, что окажется в окружении толпы взволнованных незнакомцев, облачённых в маски в форме черепов, в руках держащих торт и шарики. Всё же, это ведь не был её день рождения; и это не был её дом.",
"865360": "В ходе исследования этой морозной пустыни нас снова постигло несчастье. В страшную метель небо осветила сигнальная ракета, затем по рации раздался крик о помощи... крик умирающего... Больше никто не сможет прийти ему на помощь. Но выберемся ли мы назад — вместе?",
"1216710": "Cyber ​​Manhunt — это сюжетно-ориентированная игра-головоломка, в которой основное внимание уделяется большим данным, хакерству, конфиденциальности граждан и социальным работникам. Основное внимание уделяется социальным проблемам, таким как кибернасилие и нарушение конфиденциальности.",
"1782120": "ZERO Sievert - напряженный экстракшен-шутер с видом сверху, проданный тиражом более 600 000 копий. Обыскивайте постоянно меняющуюся пустошь, добывайте снаряжение и исследуйте то, что осталось от разрушенного мира. Когда всё против вас, одного выживания будет недостаточно...",
"559650": "Witch It — игра в прятки по сети. Здесь отважные охотники гоняются за ведьмами, те проклинают их деревни, а вокруг царит веселье и волшебство!",
"1331550": "Big Ambitions — это революционный ролевой бизнес-симулятор. Вам предстоит пройти путь до крупнейшего бизнесмена в Нью-Йорке, развивая небольшие компании или неспешно строя огромные корпорации — так, как нравится вам.",
"1556790": "Интенсивные бои в самом сердце Альп подвергнут испытанию ваши тактические навыки в этом аутентичном FPS о Первой мировой войне. Великая война на итальянском фронте оживает и достигает неожиданных высот!",
"285190": "Вступите в жестокую битву между тремя враждующими фракциями В игре Dawn of War III у вас нет выбора: после того, как на таинственной планете Ахерон было найдено чудовищное сверхоружие, вам остается только встать навстречу врагам.",
"969990": "Вы готовы, дети? Культовая история возвращается в обновленном виде! Играйте за любимых персонажей и спасите Бикини-Боттом!",
"977880": "Добро пожаловать в практически безлюдный мир Eastward! Вооружившись верной сковородкой Джона и таинственными способностями Сэм, отправляйтесь в путешествие по руинам цивилизации. На пути вас ждут прекрасные города, странные звери и еще более странные люди…",
"234630": "Project CARS - это потрясающее гоночное путешествие!",
"289130": "Endless Legend — глобальная пошаговая стратегия от создателей Endless Space и Dungeon of the Endless. Спасите свой родной мир, Ауригу, управляя всеми аспектами развития своей цивилизации. Создайте собственную легенду!",
"1017900": "Age of Empires, легендарная стратегия в реальном времени, положившая начало 20-летней саге, возвращается. Обновлённый игровой процесс, потрясающая графика в разрешении 4К, сетевые сражения для 8 игроков и множество других нововведений. Добро пожаловать в историю.",
"503560": "это игра, в которой вы играете роль оператора службы экстренной помощи и решаете сложные задачи, давая инструкции и управляя подразделениями. Играйте на карте любого города мира!",
"1318690": "shapez — это минималистичная игра про строительство фабрик, в которой нужно добывать фигуры и обрабатывать их на конвейере. Адаптируйте производство для все более сложных фигур и расширяйте свою фабрику. Вас может остановить только ваше воображение!",
"341800": "Окажитесь взаперти один на один с тикающей бомбой. У ваших друзей есть руководство к обезвреживанию, но они не видят бомбу, поэтому объяснять придется на словах и как можно быстрее! Для этой совместной локальной игры необходимо два и более игроков.",
"550900": "Станьте частью легендарной и захватывающей восточной ММО — теперь и в Steam! Покажите себя в эпических сражениях с драконами и зловещими князьями демонов, ведите беспощадные дуэли с другими игроками и станьте мастером боевых искусств!",
"301640": "Эта культовая серия шутеров подходит к апокалиптической развязке; переделана, переснята и выпущена с совершенно новой третьей кампанией!",
"298630": "Игра Escapists – это юмористический взгляд на каждодневную жизнь заключенных в тюрьме. Само собой, ваша главная цель – сбежать!",
"996580": "В коллекции Spyro™ Reignited Trilogy вы сможете любоваться чешуей и огненным дыханием дракончика Spyro в разрешении HD. Дайте волю его пламени в трех обновленных играх Spyro™ the Dragon, Spyro™ 2: Ripto's Rage! и Spyro™: Year of the Dragon.",
"250760": "Shovel Knight: Treasure Trove - это полная коллекция Shovel Knight, включающая все 5 игр эпической саги! Копайте, взрывайте, секите и сшибайте врагов в этом фантастическом пиксельном платформере, вдохновленном 8-битными играми, с запоминающимися персонажами и первоклассным геймплеем.",
"208480": "Американские колонии, 1775 год. Индеец-ассасин, сражаясь ради защиты своей земли и людей, разожжет огонь национальной революции.",
"21090": "История оригинальной F.E.A.R. развивается в дополнениях F.E.A.R. Extraction Point и F.E.A.R. Perseus Mandate.",
"462780": "Поддавшись лживым вестям сил зла о конце света, один из четырех всадников апокалипсиса, Война, обвиняется в нарушении священного закона и провоцирования войны между Раем и Адом.",
"921570": "Восемь странников. Восемь героев. Восемь обличий. Отправляйтесь в приключение по прекрасному миру Орстерры и узнайте о необычных судьбах каждого из восьми героев.",
"2310": "Quake® — революционный шутер от первого лица в стиле тёмного фэнтези, разработанный студией-лауреатом многих наград id Software и вдохновляющий создателей современных ретро-шутеров. Играйте в обновлённую и улучшенную версию Quake с усовершенствованной графикой.",
"2162800": "Заскучали без дела? Отправляйтесь строить гигантские космические фабрики! Автоматизируйте производство без ограничений. Наслаждайтесь процессом: здесь не нужно отвлекаться на врагов или время.",
"65980": "«Цивилизация Сида Мейера: За пределами Земли» — это новая научно-фантастическая игра в отмеченной наградами серии «Цивилизация». В составе экспедиции, отправленной в поисках дома за пределами Земли, ведите свой народ к новым рубежам, исследуйте и колонизируйте чужую планету и создайте новую цивилизацию в космосе.",
"850190": "Пилгор вернулась! Собирайте стадо и отправляйтесь в Goat Simulator 3 — новую (для Steam, во всяком случае) реалистичную «песочницу» на ферме. Пригласите до трёх друзей в совместную игру локально или по сети. Сейте хаос, соперничайте в мини-играх. А потом можете рассориться навеки.",
"548570": "Ощутите на себе, что такое постапокалипсис, в котором нет ни закона, ни порядка. Avalanche Studios и id Software представляют вам RAGE 2. В этой игре можно идти куда угодно и стрелять во что угодно.",
"1061910": "Сокрушайте врагов, следуя за тактом метала и своей мести, в адском путешествии по восьми областям преисподней. Пусть они боятся ритма. Metal: Hellsinger — ритм-шутер от первого лица, где вас ждет множество демонов, крутого оружия и тяжелой музыки.",
"1399780": "Spellbreak — многопользовательская экшн-игра, в которой с помощью заклинаний можно разбудить в себе боевого мага. Оттачивайте искусство владения магией стихий, подходящей вашему стилю игры, и колдуйте мощные сочетания заклинаний, чтобы победить прочих игроков и править Пустыми землями.",
"2666510": "Расслабляющий симулятор фермерства, который находится внизу экрана, пока вы занимаетесь другими делами.",
"265550": "В городке Los Perdidos кишат зомби, военные готовятся разбомбить его со всеми жителями, задача – успеть оттуда спастись.",
"746850": "Неоново-нуарная история в дождливом киберпанк-метрополисе. Сегодня ваша первая смена в службе доставки Клаудпанк. Правила два: привозите в срок и не спрашивайте, что в посылке.",
"410340": "Liftoff® — это симулятор дрона, который переносит полет дрона от первого лица в цифровой мир. Присоединяйтесь к крупнейшему сообществу виртуальных гонок FPV и фристайла!",
"1390350": "Перепрыгивайте с дерева на дерево, плетите липкую паутину и знакомьтесь с другими насекомыми! Станьте очаровательным паучком своей мечты!",
"1302240": "Labyrinthine - кооперативная хоррор игра, которая научит Вас не останавливаться внутри лабиринта. Вы и ваши друзья могут почувствовать совместный опыт в истории от Джона, а также почувствовать мистическую составляющую этого места. Здесь все зависит от Вашего выбора, помните, Вы не одни!",
"6910": "На дворе 2052 год. Мировая экономика близка к коллапсу, а разрыв между безумно богатыми и отчаянно бедными становится все шире. Хуже всего то, что многовековой заговор, стремящийся к мировому господству, решил, что настало время выйти из тени и взять под свой контроль.",
"1328660": "Почувствуйте азарт погони и получите настоящий драйв, гоняйте на самых крутых и мощных машинах мира в Need for Speed™ Hot Pursuit Remastered — невероятном мире захватывающих гонок, где можно состязаться вместе с друзьями.",
"1016920": "Unrailed! — многопользовательская игра, в которой вам предстоит построить железную дорогу в бесконечном процедурно генерируемом мире. Вам придется работать сообща, улучшать вагоны, следить, чтобы поезд не сошел с рельсов, и быть готовыми ко всему!",
"851100": "Touhou Luna Nights — это игра в жанре метроидвания, в которой особое внимание уделяется исследованиям и действиям. Разработано командой Ladybug, создателями множества фантастических экшен-игр.",
"775500": "Выбирайте между Юито и Касанэ: у каждого из этих элитных псиоников есть способность к телекинезу и собственные причины для того, чтобы сражаться. Пройдите обе их истории, чтобы узнать все тайны будущего в стиле «брейнпанк» на стыке технологий и псионики.",
"1569040": "Игра, максимально близкая к управлению настоящим футбольным клубом. FM22 открывает новые прогрессивные способы побеждать, находить преимущество, прививать команде свой стиль и завоевывать трофеи.",
"2104890": "Вы – глава компании, которая специализируется на восстановлении районов, пострадавших от стихийных бедствий. Используйте свою технику для перезапуска местной промышленности. Расчищайте территорию, реконструируйте дороги, мосты и другие объекты!",
"34870": "Sniper: Ghost Warrior 2 поднимает меткость предшественника до невиданных ранее высот!",
"428690": "Станьте самым популярным ютубером на планете! подпишите договор с эксклюзивной сетью и обставьте свое жилище крутейшими штуками. Развивайтесь, и в итоге сможете позволить себе особняк в открытом космосе!",
"1239690": "Неоновые огни, пальмы, синтвейв, суперкары 80-х, разгоняющиеся по бесконечному шоссе... Добро пожаловать в Retrowave!",
"780290": "Возглавьте свою банду наемников в стране Мрачной Гавани, сотрудничайте с сомнительными личностями, определяйте судьбу региона, пробивайтесь через ужасающие места и разбогатейте или умрите, пытаясь в этой безжалостной тактической ролевой игре.",
"784080": "На дворе 3015 год. На полях сражений доминируют боевые машины, известные как BattleMechs. Выравнивайте целые города и уничтожайте врагов в своем боевом мехе. Следуйте за славой и местью. Управляйте расширяющейся компанией наемников. Сражайтесь плечом к плечу с друзьями в кооперативном PvE-режиме для четырех игроков.",
"1971650": "Эта игра является продолжением серии OCTOPATH TRAVELER, первая часть которой, выпущенная в 2018 году, была продана в количестве более 3 миллионов копий.",
"235540": "Vermintide – это эпическое приключение в жанре сражения от первого лица с возможностью кооператива, действие которого происходит в Конце Времен легендарной фэнтезийной вселенной Warhammer.",
"9450": "Третье, заключительное дополнение к общепризнанному лидеру жанра стратегии в реальном времени - Dawn of War. В Soulstorm появляются две новые армии: Сестры Битвы и Темные Эльдары, общее число доступных армий возрастает до девяти. Революционная мета-игра, впервые опробованная в Dark Crusade, теперь расширена до межпланетного масштаба, и игроки могут сражаться по всей звездной системе.",
"232430": "7 июня 1995 года, 1:15 ночи. Возвращаешься домой после года жизни за границей, и, казалось бы, тебя должна встречать вся семья. Но что-то не так, в доме никого! Где все? И что тут случилось? Попробуй разгадать эту тайну в Gone Home – сюжетной приключенческой игре, созданной The Fullbright Company.",
"774861": "Project Winter — многопользовательская игра для 8 игроков, основанная на социальной маскировке и выживании. Чтобы спастись, выжившим необходимо общаться и работать в команде. Собирайте ресурсы, ремонтируйте постройки и покоряйте дикую природу плечом к плечу.",
"311340": "Всемирно известная компания Kojima Productions представляет франшизу Metal Gear Solid в Steam с METAL GEAR SOLID V: GROUND ZEROES. Играйте за легендарного героя Снейка и проникните на кубинскую военную базу, чтобы спасти заложников. Сможешь ли ты выбраться живым?",
"448510": "OVERCOOKED – кулинарная игра для 1-4 игроков. Работайте в команде и готовьте блюда, пока клиенты не покинули ресторан. Заточите ножи и отряхните поварские куртки! Стейки очень высоки!",
"2075070": "KinitoPET — это психологический хоррор, действие которого происходит с помощью Kinito, виртуального помощника начала 2000-х годов. Kinito может ходить, говорить, просматривать страницы, адаптироваться и играть в игры, поскольку Kinito не похож ни на один другой благодаря своей адаптивной технологии!",
"2232840": "Зайдите в детский сад Банбана — и вы обязательно найдёте себе друзей. Исследуйте это загадочное заведение и постарайтесь не лишиться жизни и рассудка. Раскройте ужасающую правду, скрывающуюся за этим местом, но будьте осторожны: вы здесь далеко не одни…",
"424030": "War of Rights — это многопользовательская игра от первого лица, в которой участвуют 400 игроков с упором на историческую достоверность, командную игру и погружение. Действие происходит в опасные дни Гражданской войны в США, в кампании Мэриленда в сентябре 1862 года.",
"1789480": "Marauders — это многопользовательский тактический шутер с видом от первого лица, действие которого разворачивается во вселенной научно-фантастической антиутопии. Станьте пиратом и бороздите просторы галактики в одиночку или в составе команды до четырех игроков.",
"861650": "Игра, созданная скейтерами для ценителей: dual stick controls подарят ощущение доски под ногами и реалистичный игровой опыт. Создайте скейтбордиста, снарядите его брендовыми вещами и испытайте силы на легендарных площадках",
"2688950": "Стройте и персонализируйте великолепные американские горки и невероятные аквагорки, управляйте идеальным парком развлечений и делитесь своими фантастическими творениями. Вы готовы поймать волну?",
"237990": "Погрузитесь в эпическую ролевую сагу о викингах, в которой каждое решение напрямую влияет на сюжет. Собирайте союзников, путешествуя со своим караваном по удивительному, но опасному маршруту.",
"601840": "Griftlands — это карточная roguelite-игра, в которой вам предстоит договариваться, сражаться, воровать или иными способами убеждать других действовать в ваших интересах. Каждое ваше решение имеет значение: и выполненная работа, и встреченные друзья, и собранные карты.",
"287450": "Rise of Nations возвращается! Играйте в обновленную классическую версию с полной интеграцией Steamworks и расширенными функциями!",
"965200": "Одиночный шутер про зомби с крутой многоугольной графикой и элементами RPG.",
"265300": "Окунитесь в мир мрачного фэнтези в жанре экшен-RPG, подчиняя могучую магию и осваивая сложную, но увлекательную боевую систему. Жестокий бог Адыр вторгся в царство смертных, желая отомстить за свое длительное заточение, и человечество обратилось за помощью к необычному спасителю — грешнику Харкину.",
"2795000": "Кайл — уборщик. Он тоже оборотень. И теперь у него ночная смена. Постарайтесь никого не убить, работая за зарплату, в этой стелс-комедии, где сюрпризы ждут вас на каждом углу.",
"1105670": "Защитите последний бастион человечества вместе с вашим отрядом героев! Уничтожайте злобных чудовищ с помощью магии и грубой силы ночью, а днём восстанавливайте разрушенную городскую оборону ​​в этой тактической ролевой игре с механикой rogue-lite.",
"760060": "Возглавьте команду мутантов-путешественников в мире после людей! Mutant Year Zero: Road to Eden — приключенческая тактическая игра, в которой пошаговые бои в стиле XCOM сочетаются с увлекательным сюжетом, скрытностью, стратегией и исследованием мира. В команде разработчиков — дизайнеры HITMAN и один из создателей PAYDAY.",
"2677660": "Раскройте одну из величайших тайн истории в приключенческой игре от первого лица. В 1937 году зловещие личности начинают искать ключ к древней силе, связанной с большим кругом, и остановить их может только Индиана Джонс.",
"313160": "Farming Simulator 15 - это открытый мир и улучшенная графика и физика. Работайте на ферме в одиночку или в сетевой игре. Разводите животных, собирайте и продавайте урожай и покупайте мощную технику.",
"1283410": "Tails of Iron – это ролевая игра с бескомпромиссной боевой системой. Примерьте на себя шкурку Реджи, наследника Крысиного престола. Отправляйтесь в поход по обманчиво уютному мирку. Соберите отряд храбрых спутников. Спасите свое королевство. Изгоните свирепых Лягушек!",
"872410": "Победите над землей, возьмите в свои руки судьбу Китая! Завоевывайте территории и летайте под своим флагом!",
"391720": "Психологический хоррор от первого лица с упором на атмосферу и сюжет. Исследуйте постоянно меняющийся викторианский особняк в роли художника, стремящегося завершить свой шедевр даже ценой собственного рассудка.",
"361280": "Бурите нефтяные скважины как в 1899 году! Turmoil предлагает пользователям сыграть в очаровательную шутливую пародию на симуляцию по мотивам нефтяной лихорадки XIX века в Северной Америке.",
"597820": "BIOMUTANT® — это игра сочетающая в себе постапокалипсис, кунг-фу и фэнтези. В ней вы сможете использовать ближнего, дальнего боя и способности мутанта.",
"335670": "Несчастные приключения сломленного человека...",
"393080": "Call of Duty® 4: Modern Warfare®, одна из самых популярных игр в истории, возвращается с режимом высокой четкости, улучшенными текстурами, реалистичной физикой, расширенным динамическим диапазоном освещения и другими технологиями нового поколения.",
"1475810": "Население Токио исчезло без следа, а на улицах города властвуют смертоносные потусторонние силы. Используйте силы стихий, чтобы раскрыть тайну исчезновения людей и спасти Токио.",
"4760": "Управляйте и покоряйте величайшую империю, когда-либо известную человечеству.",
"1548850": "Six Days in Fallujah — это невероятно реалистичный тактический шутер от первого лица, основанный на реальных событиях одного из самых жестоких городских сражений этого столетия.",
"445220": "Космическая песочница с процедурно генерируемым миром и режимом совместной игры, где игроки могут строить корабли из динамически масштабируемых блоков. Участвуйте в битвах, исследуйте мир, добывайте руду, торгуйте, воюйте и постройте собственную империю, чтобы спасти галактику от неизвестного врага.",
"456750": "Не устояв перед соблазном, вы прибываете на далекий остров, где оказываетесь заперты внутри зловещего особняка. Вам предстоит, собрав все свои умения, пройти испытания таинственного незнакомца, называющего себя «Мастером». Удастся ли вам выбраться на свободу?",
"1361510": "Teenage Mutant Ninja Turtles: Shredder’s Revenge — это яркий, сделанный с любовью скроллер в жанре beat ’em up, в основе которого лежит легендарный образ черепашек из 1987 года. Эта игра — дань уважения классическим играм о черепашках, таким как Turtles In Time.",
"371970": "Barony — лучший рогалик от первого лица с кооперативной игрой! Отправляйтесь в путешествие в одиночку или соберите команду из знаковых и необычных ролевых классов, чтобы сразиться с жестокими подземельями. Проверьте свою находчивость, смекалку и дружбу в стремлении снять проклятие злого лича!",
"1488200": "Вас ждет Танра – мир, истерзанный войной. Из скромного выпускника академии вы станете великим полководцем и выступите против коварного врага. Собирайте героев, сплотите их и ведите в пошаговые бои. Тактика, ландшафт, боевой дух – всё это поможет вам вернуть мир в эти земли.",
"1382330": "Присоединяйтесь к Призрачным ворам и нанесите ответный удар коррупции, охватившей города по всей Японии. Летние каникулы с близкими друзьями принимают неожиданный поворот: появляется искаженная реальность; раскройте правду и искупите сердца тех, кто оказался в центре кризиса!",
"201790": "Are We There Yeti? уже доступна! Доставайте свои варежки, ведь боевые маги и волшебницы уже готовы защитить крепости великого снежного севера!",
"1338770": "SGW Contracts 2 — современный тактический шутер. Место действия — Ближний Восток, вы — Raven, наемный киллер-снайпер, и вас ждет сложнейшая одиночная кампания по уничтожению целей с расстояния больше 1000 м.",
"313340": "Экзистенциальное моделирование природы",
"3480": "Сделайте свой лучший выстрел в захватывающей аркадной игре! Цельтесь, стреляйте, убирайте оранжевые колышки, а затем расслабьтесь и подбадривайте, пока 10 причудливых учителей приведут вас к величию Peggle.",
"342200": "MechWarrior Online™ Legends — это тактический онлайн-шутер, действие которого происходит в огромной вселенной BattleTech. Возьмите на себя роль элитного мехвоина, пилотирующего мощные боевые роботы и сражающегося за господство над Внутренней Сферой.",
"12140": "Макс Пэйн – человек, которому нечего терять в жестокой ночи замерзшего города. Он работал под прикрытием, пока его не подставили, обвинив в убийстве. Теперь на него ведут охоту полицейские и мафия. Макс зажат в угол, и в этой войне ему не победить. Приготовьтесь к боли…",
"1201240": "Мир мегахита манги и аниме BLEACH приходит в Steam в этой захватывающей 3D-игре-экшене! Создайте команду, используя своих любимых персонажей из вселенной BLEACH!",
"35700": "Трое героев преодолевают невыразимые опасности в сказочном мире великих замков и странных механизмов, где вас ждут основанные на физике головоломки, красивые виды, а также возможность совместной игры по сети и по локальной сети.",
"287980": "Mini Metro - симулятор строительства метро в развивающемся городе. Прокладывайте линии между станциями и запускайте их в эксплуатацию. Следите за загрузкой линий и изменяйте их маршрут при открытии новых станций. Решайте, как использовать ограниченные ресурсы. Узнайте, хороший ли вы менеджер метро?",
"1676840": "Сражайтесь против королевы Фарула в одиночку или в составе группы из четырех игроков в продолжении For The King — знаменитой и популярной пошаговой настольной roguelite-RPG. Сможете ли вы разгадать ужасную тайну когда-то всеми любимой королевы?",
"315210": "«Отряд самоубийц: Конец Лиги справедливости» – это бросающий вызов жанру шутер от третьего лица от создателей трилогии Batman: Arkham, в котором банда неудачников должна совершить невозможное: уничтожить Лигу справедливости.",
"2457220": "Avowed — это фэнтезийная ролевая игра с видом от первого лица, разработанная Obsidian Entertainment.",
"835960": "The Talos Principle 2 — головоломка от первого лица, которая не раз заставит вас задуматься. Она во многом развивает философские темы первой игры и предложит вам немало потрясающих уровней с очень непростыми загадками.",
"1056960": "Wolfenstein: Youngblood — первая игра серии, ориентированная на совместное прохождение. Играйте с другом, используя новое оружие, приспособления и приёмы. Освободите Париж от нацистов.",
"1029550": "Создайте свой автомобиль, подберите цвет на свое усмотрение, заработайте спонсоров и соревнуйтесь на мировой арене в реалистичных ПАРНЫХ ОНЛАЙН-СОРЕВНОВАНИЯХ, чтобы стать КОРОЛЕМ ДРИФТА!",
"875210": "Серия «Kingdom Heroes» — это классическая однопользовательская игра с горизонтальными сражениями, разработанная компанией Userjoy, которая выпускалась уже семь поколений с 1998 года. Последний сиквел «Kingdom Heroes 8» будет отличаться новым внешним видом и захватывающими сражениями, интерпретирующими великолепную эпоху Трех Королевств.",
"885970": "Total War: ROME REMASTERED предоставляет вам возможность заново пережить события одной из частей знаменитой серии стратегических игр. Это ставшая классикой игра в разрешении 4К с множеством улучшений графики и игрового процесса.",
"1850740": "Ghost Watchers - кооперативный онлайн хоррор. Вам предстоит исследовать и ловить призраков в заброшенных домах",
"228200": "Рассказывая о жестокой Второй мировой войне, Company of Heroes представляет стратегию в реальном времени в новом свете, воплощая в жизнь героизм солдат, разрушенные города и динамичные поля битвы. Другие обзоры игроков можно прочитать на странице \"Company of Heroes - Legacy Edition\".",
"39510": "Gothic II: Золотое Издание включает оригинальную игру Gothic II и официальное дополнение \"Ночь Ворона\"!",
"1525700": "Суть Мастера Таверны — управление твоей средневековой таверной. Ты начинаешь с очень маленькой комнатой, парой скамей и столов и постепенно развиваешься до огромной успешной таверны с кухней, комнатами для гостей, коллективом преданного персонала и многим другим!",
"339610": "Испытай несравнимую ММО уличного баскетбола Freestyle 2! Обновленная версия первой в мире ММО стритбола Freestyle1 с улучшенной графикой и 3х3 системой игры! Каждый матч - захватывающее зрелище, освещение каждого движения игрока! Все это возможно только в FreeStyle2: Street Basketball!",
"1115690": "Трудные времена сейчас, Ваша Милость. С нашими ресурсами сложно удовлетворять даже заурядные запросы населения, а о войне и говорить нечего. Необходимо тщательно расставлять приоритеты. Трон ждёт.",
"232890": "Stronghold Crusader 2 — это долгожданный сиквел оригинального castle-сима Stronghold: Crusader. Спустя 12 лет Stronghold возвращается в 1189 год в пустыни Среднего Востока, но уже с новым 3Dдвижком и реалистичной системой разрушения замков, созданной при помощи Havok Physics. Firefly Studios воссоздают аутентичный симулятор замков с быстрым и захватывающим геймплеем.",
"469600": "Бесконечно воспроизводимый многопользовательский режим и однопользовательская защита башни. Защищайтесь от волн врагов и уничтожьте вражеского короля, прежде чем враги уничтожат вашего. Legion TD 2 - это игра, основанная на тактике, совместной работе и предсказаниях. В группе от 1 до 8 игроков.",
"418030": "Subsistence - это PvE-выживание от первого лица с одиночным и совместным режимами. Выживайте в открытом мире со сменой времён года, стройте базу, делайте предметы и снаряжение. Защищайтесь от дикой природы и охотников, которые тоже строят свои базы.",
"493900": "Наконец-то Лорду Подземелья удалось объединить под своим началом все силы тьмы и основать империю зла. Пришло время сделать следующий шаг – расширить границы своих владений!",
"606280": "В Darksiders III вы вернетесь на мертвую Землю в роли ЯРОСТИ, которая намерена найти и уничтожить Семь смертных грехов. Самая загадочная из четырех всадников, ЯРОСТЬ должна преуспеть там, где потерпели неудачу другие: восстановить равновесие сил на Земле.",
"1674170": "Тщательно сбалансируйте подвижность, огневую мощь и броню в специальном конструкторе танков. Затем неосторожно испытайте их в серии боевых сценариев, развивающихся на протяжении веков танка. Здесь ваш предел — это то, что вы можете поместить внутри корпуса и башни, сохраняя при этом возможность двигаться вперед.",
"224600": "Присоединяйтесь к футуристическому онлайн-шутеру с открытым миром, в котором тысячи игроков исследуют преображенную Землю, соревнуясь за инопланетные технологии.",
"377840": "Было продано более пяти миллионов копий с момента выпуска в 2000 году. FINAL FANTASY IX с гордостью возвращается в Steam! Теперь вы можете пережить приключения Зидана и его команды на ПК!",
"1301720": "Твое единственное желание — проведать коллегу на больничном. Но тебе сложно было вообразить, с чем ты столкнешься. Раскрой секреты коллеги и выберись из ловушки.",
"621830": "Пройдите 13 ралли WRC в достоверно воссозданном окружении. Выступите в роли лучших гонщиков чемпионата за рулем их новых машин. В одиночку или по сети, пройдите Epic Stages, поучаствуйте в еженедельных состязаниях и покажите свое мастерство в WRC!",
"1504570": "Cultivation Tales — это онлайн-игра о выживании в открытом мире. Вы испытаете коллекционирование, создание, охоту, сражения, строительство и исследования в диком мифическом мире. Сражайтесь за свой клан и за себя, от смертного до божества!",
"264200": "Испытайте кинематографические сражения кунг-фу в самой быстрой и напряженной драке, которую когда-либо видел инди-мир! Благодаря уникальной системе реакции 1:1 в One Finger Death Punch игроки почувствуют немедленную отдачу от каждого сокрушительного удара. Отдайте дань уважения мастерам, используя пять классических стилей кунг-фу, смешанных с дополнительным оружием. Объедините бой лицом к лицу с метанием оружия, чтобы воссоздать сложную боевую хореографию, или просто отправляйте плохих парней в полет через стеклянные окна. Исследуйте карту мира с более чем 250 этапами, 13 режимами и 3 уровнями сложности. Разблокируйте 21 различный навык, который можно комбинировать тысячами способов, чтобы помочь вам в вашем путешествии. Испытайте свое кунг-фу в режиме выживания.",
"813630": "Сыграйте в демоверсию! Смесь между Portal, Zelda и Metroid. Исследуйте, находите секретные улучшения, решайте головоломки, сражайтесь с монстрами, находите новые способности, которые помогут вам достичь новых секретных мест. Время прохождения: ~ 15-30ч.",
"688420": "Bad North — это очаровательный, но жестокий околорогалик и тактика в реальном времени. Защитите мирное островное королевство от полчищ викингов и возглавьте отчаянный исход его жителей. Отдавайте приказы верным подданным, используя тактические преимущества, обусловленные уникальной формой каждого острова. На карту поставлено буквально все. Одна ошибка — и землю оросит кровь ваших подданных.",
"375230": "Эльдары, орки, Хаос или космические десантники в жесточайших битвах за всеобщий мир любыми средствами. Попробуйте бесплатную демо-версию или купите полную премиум-игру ниже. Мы не сдадимся.",
"1238060": "Устраните угрозу террора вместе.",
"872790": "Симулятор, доведенный до совершенства. Создайте собственную футбольную историю — управляйте любимым футбольным клубом. Вы обладаете полным контролем над этим поразительно реалистичным игровым миром — принимаете или делегируете каждое решение.",
"333420": "Казаки 3 — возвращение классики RTS. Добывайте ресурсы, отстраивайте города и исследуйте новые технологии, руководите огромными армиями и громите войска противников в грандиозных исторических баталиях на суше и море!",
"2181930": "ДОКТОР ЛИВСИ: АХАХАХАХАХХААХХАХАХА, джентльмены, отныне слово рум и слово смерть для вас означает одно и то же.",
"332310": "Вас ждут скопления миров, сделанных полностью из блоков LEGO. ИССЛЕДУЙТЕ гигантские ландшафты, ОТКРЫВАЙТЕ бесчисленные сюрпризы и СОЗДАВАЙТЕ все, что только можете себе представить, используя блоки LEGO.",
"1016800": "Научно-фантастическая игра в жанре ужасов с элементами выживания. Исследуйте невероятно реалистичную зону отчуждения Чернобыльской АЭС, воссозданную с помощью 3D-сканеров, и погрузитесь в нелинейную историю, дабы выяснить правду о вашем прошлом.",
"1239080": "Командуйте войсками специального назначения в захватывающих тактических схватках с террористическими группировками на Ближнем Востоке. Продолжение «Лучшей тактической игры 2014 года» по версии RockPaperShotgun.",
"915320": "Pixel Strike 3D — это многопользовательский шутер от первого лица с динамичным игровым процессом и широкими возможностями настройки игрока. Сражайтесь с друзьями и врагами со всего мира в более чем 20 уникальных игровых режимах и с более чем 70 видами оружия.",
"411300": "ELEX — тщательно проработанная динамическая ролевая игра, создаваемая удостоенными наград авторами серии Gothic. Ее действие разворачивается в новой постапокалиптической научно-фантастической вселенной: игроков ждет огромный бесшовный мир, полный ярких персонажей, гротескных мутантов, моральных дилемм и напряженных приключений.",
"872670": "SCP: 5K — это кооперативный или одиночный тактический хоррор-шутер от первого лица, в котором игроки оказываются в центре заговора, в рамках которого Фонд SCP обратился против человечества. Наслаждайтесь ранним доступом, поскольку мы продолжаем работать над завершением полной версии проекта!",
"3830": "Совершите психоделическое путешествие по разумам чудаков, монстров и безумцев. Этот классический экшен-платформер от известной компании-разработчика Double Fine Productions поведает вам историю о ментально одаренном ребенке по имени Разпутин.",
"607080": "Psychonauts 2 — это платформер о невероятных парапсихических способностях и таинственных заговорах, стильный, зрелищный и с отличным юмором.",
"1061090": "Примите вызов и погрузитесь в мир настоящего платформера Jump King, где ставка очень высока! Стремление к высоте приблизит вас к Горячей Девчонке, воспетой в легендах. Но будьте осторожны в своих поисках - один неверный прыжок может привести к очень долгому падению.",
"437920": "Пора в Tricky Towers вам поиграть, где можно вовсю магию применять! Блок ставьте на блок, будет ждать вас успех. Узнайте, чья башня устойчивей всех. Сражайтесь с друзьями, чтоб стать самым первым, Но только свои берегите вы нервы.",
"909080": "Paradox – это кроссовер игры Cube Escape и короткометражки Rusty Lake! Сыграйте за детектива, который должен выбраться из зловещей комнаты в параллельных вселенных.",
"712100": "Действие игры A Total War Saga: Thrones of Britannia происходит на рубеже эпох, когда гэлам, англосаксам и переселенцам-викингам предстоит сразиться за обладание Британией. Сумеете ли вы покорить острова и стать верховным правителем?",
"12150": "Max Payne 2: The Fall of Max Payne – это жестокая история любви в стиле нуар. Мрачная, трагическая и напряженная, эта история – шокирующий аттракцион невероятных поворотов и откровений. Любовь убивает.",
"2707940": "FPV Kamikaze Drone — тактическая игра о применении FPV-дронов в современной войне. Управляйте дроном от первого лица в одиночном и кооперативном режимах, а в мультиплеере играйте солдатом от третьего лица, находя и используя дроны в бою.",
"1382070": "Обычный фотоаппарат поможет вам преобразить реальность, усомниться в собственном восприятии и даже изменить мир. Viewfinder — новая одиночная игра-головоломка, которая увлечёт вас на много часов. Раскройте давно забытые тайны!",
"613830": "Классическая RPG возвращается в новом обличье! Отправьтесь в удивительное путешествие — в забытое прошлое, в далекое будущее и к концу времен. Именно вам предстоит спасти мир от разрушения.",
"732690": "Five Nights at Freddy’s: Help Wanted — это сборник классических и оригинальных мини-игр, действие которых происходит во вселенной Five Nights. Испытайте ужас в плоском режиме (без VR) или VR. Поддерживаются Oculus Rift и HTC Vive. Для игры НЕ требуется VR-гарнитура.",
"1244090": "Sea of ​​Stars — это пошаговая ролевая игра, вдохновленная классикой. В нем рассказывается история двух Детей Солнцестояния, которые объединят силы Солнца и Луны, чтобы творить Магию Затмения, единственную силу, способную отразить чудовищные творения злого алхимика, известного как Плотманер.",
"1066890": "Automobilista 2 — это все гоночные симуляторы, которые вы когда-либо хотели, — всего в одном. Невероятно разнообразная коллекция автомобилей и трасс, смоделированных вместе, с невероятной графикой и качеством звука, динамичными погодными условиями и условиями трассы, а также лучшей поддержкой виртуальной реальности для неповторимых гоночных впечатлений.",
"2440510": "Превзойдите соперников в режиме карьеры. Испытайте более 500 автомобилей и соревнуйтесь с игроками по всему миру в гонках на 27 знаменитых трассах, в том числе увлекательнейшей Нюрбургринг Нордшляйфе!",
"34270": "Коллекция Mega Drive и Genesis Classics от SEGA выходит в новом поколении и теперь дополнена еще большим количеством функций: многопользовательская онлайн-игра, достижения, зеркальный режим, перемотка назад, сохранение состояний, VR и многое другое! Более 50 классических игр в одном великолепном пакете. Окунитесь в классику!",
"9200": "Испытайте насыщенный экшен от первого лица и сумасшедшие битвы на автомобилях, исследуйте громадный мир, и насладитесь потрясающей графикой новейшего движка id Tech® 5.",
"65800": "Создайте героя для спасения Этерии в этом ролевом кооперативном экшене жанра «защита башен». Эксклюзивное предложение с пушкой Portal и персонажами из TF2!",
"867210": "Создавайте армии, изучайте заклинания и ведите свою империю к вечной славе в пошаговой стратегии, собравшей в себе лучшие из классических механик.",
"278360": "A Story About My Uncle - это приключенческий платформер от первого лица о мальчике, который ищет своего пропавшего дядю и попадает в мир, существование которого он не мог себе даже вообразить. Движение в A Story About My Uncle является важнейшей частью геймплея. Акцент делается на передвижениях по миру с помощью силового крюка, который предоставляет игроку невероятное ощущение скорости и свободы. Поприветствуйте игровой мир с уникальным визуальным стилем и загадочной историей, которая развернется перед вами.",
"394310": "Тренируйся, найди свою любовь и набей крокодилу зеленую рожу. Стань лучшим бойцом и раскрой тайну жестокого убийства своего отца в этом стратегическо-приключенческом тайкуне бойца.",
"847370": "Sunset Overdrive превращает апокалипсис открытого мира в вашу тактическую игровую площадку. Мчитесь, бегайте и бегайте по стенам Сансет-Сити с нетрадиционным арсеналом. Сверхловкость, уникальное оружие и настраиваемые способности обеспечат взрывное и дерзкое приключение в последние времена.",
"2294660": "Отправляйтесь в авантюрное путешествие, чтобы исследовать вселенную Quinfall. Станьте частью уникальных сражений и захватывающего сюжета с десятками различных профессий в глубинах средневековья в совершенно новой MMORPG.",
"1128920": "EVERSPACE 2 — это скоростной космический шутер для одного игрока. Исследуйте просторы космоса, собирайте ресурсы, улучшайте корабль и создавайте предметы. Погрузитесь в захватывающую историю, действие которой разворачивается в красочном мире ручной работы, полном загадок и опасностей.",
"256290": "Аврора, молодая девушка из Австрии 1895 года, просыпается на затерянном сказочном континенте Лемурия. Чтобы вернуться домой, ей предстоит сразиться с темными созданиями Царицы Ночи, похитившими солнце, луну и звезды. На кону не только Лемурия, но и истинная судьба Авроры.",
"799600": "Постройте звездолёт своей мечты! Возглавьте экипаж и ведите его в эпические битвы — на покорение полного опасностей космоса. Играйте в одиночку или с друзьями, испытайте свой корабль в сетевых PvP-битвах. Пусть воображение ведёт вас к звёздам!",
"233290": "MURDERED: SOUL SUSPECT™ переносит игроков в совершенно новое царство тайн, где дело является личным, а улики недоступны, бросая игрокам вызов раскрыть самое сложное дело из всех… их собственное убийство.",
"350640": "Попробуйте фантастическую головоломку с уникальным игровым процессом, сочетающим в себе расследования, стремительное действие и леденящий кровь триллер, который заставит вас понервничать и призадуматься. Играйте за великого сыщика и выследите зло в самых темных уголках Лондона и человеческой души…",
"327070": "Gloria Victis - это MMORPG (Массовая многопользовательская ролевая онлайн-игра) с акцентом на реализм, действия которой происходят в открытом мире в средневековье. Наслаждайтесь бесконтактным боем, основанным на навыках, открытыми PVP состязаниями с контролем территории, глубокой, расширенной системой обработки, игровой экономикой и развитой сюжетной линией, плюс представлена красивая реалистичная графика и захватывающая атмосфера. Выберите одну из двух фракций: гордые Мидландцы, обитающие на зеленых землях или мстительные Исмиры с ледяного Севера и присоединяйся к поединку!",
"2239550": "Действие Watch Dogs: Legion происходит в ближайшем будущем. Лондон переживает тяжелые времена. Организуйте сопротивление, чтобы спасти город.",
"204340": "Serious Sam II — инъекция адреналина прямо в сердце всем любителям стрельбы от первого лица. Серьезно!",
"1182620": "Безумный, замкнутый во времени, загадочный трагикомедийный триллер про убийства от создателей To the Moon и Finding Paradise, включающий в себя множество случайных совпадений и одного подозрительного кота.",
"206210": "Gotham City Impostors теперь доступна бесплатно! Присоединяйтесь к «помощникам» Бэтмена или младшему Джокерзу на улицах Готэма, полных пуль, тел и медвежьих ловушек.",
"389570": "Погрузитесь в микроскопический мир Mitos.is! Ешь или будь съеденным—стани окончательной клеткой в этой увлекательной многопользовательской игре. Разнообразные режимы, ежедневные турниры, гильдии и снаряжение ждут вас! ЛУЧШАЯ игра 2015 года вернулась!",
"320300": "Новые автомобили, новые инструменты, новые опции, больше деталей и еще больше удовольствия в следующей версии Car Mechanic Simulator! Возьми свой гаечный ключ! Создайте и расширяйте свою империю по ремонту автомобилей. Car Mechanic Simulator 2015 перенесет вас за кулисы повседневной жизни автосервиса.",
"3035570": "Играйте за смертоносного мастера-ассасина в ярком экшен-приключении. Исследуйте улицы Багдада IX века и смотрите на мир глазами Басима. Вступите в ряды Незримых в поисках справедливости и устраняйте врагов.",
"333640": "Caves of Qud — это эпичный рогалик в жанре научного фэнтези, где вас ждет ретрофутуризм, глубокая симуляция и разумные растения. Погрузитесь в экзотический мир и прорубайтесь сквозь слои тысячелетних цивилизаций.",
"244160": "Погрузитесь в эпические космические стратегии, которые дали новое определение жанру стратегий в реальном времени. Контролируйте флот кораблей и постройте собственную армаду, пройдя более чем 30 одиночных миссий. Выбирайте типы кораблей, построения флота и боевую тактику в зависимости от стратегической ситуации. Применяйте самые передовые исследования, чтобы строить широкий спектр кораблей — от обычного истребителя до гигантского авианосца.",
"714120": "Во главе со своим новым другом, Мистером Голос, Неудача отправляется в лес, в котором раскрываются тайны и случаются неприятности.",
"610370": "Desperados III — это хардкорная тактическая игра в жанре «стелс» с захватывающим сюжетом, события которой происходят на безжалостном Диком Западе. Играйте с умом, если хотите победить. Хороший план — единственное, что выведет вас из-под дула пистолета.",
"212480": "Промчитесь по земле, воде и воздуху на невероятных трансформирующихся машинах, которые могут превращаться в лодки и самолеты прямо во время гонки.",
"244930": "SNOW — The Ultimate Edition — единственная игра о зимних видах спорта с открытым миром. Исследуйте огромную гору, настраивайте своего персонажа с помощью одежды и снаряжения, соревнуйтесь в соревнованиях, чтобы стать лучшим. Доступ ко всем горам, трассам, мероприятиям, включая всю косметику, лыжи, сноуборды, дроны и снегоходы.",
"278080": "«Dynasty Warriors 8: Xtreme Legends» представляет совершенно новые уровни веселья в обновленном игровом процессе, побеждая толпы врагов с помощью могучих воинов из «Dynasty Warriors 8».",
"222480": "Resident Evil® Revelations возвращается в обновленном виде для ПК с высококачественной HD-графикой, улучшенными световыми эффектами и захватывающим звуком.",
"102500": "Умы автора бестселлеров New York Times Р.А. Сальваторе, создатель Spawn Тодд Макфарлейн и ведущий дизайнер Elder Scrolls IV: Oblivion Кен Ролстон объединились, чтобы создать Kingdoms of Amalur: Reckoning, новую ролевую игру, действие которой происходит в мире, который стоит спасти.",
"1277400": "Во второй части пошаговой ролевой игры в мире Monster Hunter вас ждут новые захватывающие приключения! Станьте Наездником, подружитесь с дружелюбными Монстриками и вместе с ними участвуйте в эпических битвах.",
"1594940": "«Маленькая ведьма в лесу» рассказывает историю Элли, ученицы ведьмы. Исследуйте мистический лес, помогите очаровательным жителям и окунитесь в повседневную жизнь ведьмы.",
"344760": "Боритесь за выживание в суровом средневековом мире. Охотьтесь на диких животных, добывайте ресурсы, стройте сооружения и создавайте оружие и доспехи, чтобы защитить себя. Вы можете создать гильдию, объявить войну всем противникам и попытаться захватить трон и стать королем!",
"204300": "Конфликт, распространивший на звезды, в котором огромные армии роботов скованы долгой битвой. Выходите на поле боя со своими друзьями в этом динамичном платформере с игрой 3 на 3.",
"2993780": "Погрузитесь в эту неторопливую RPG, где вы сможете свободно переключаться между 14 уникальными профессиями - «Жизнями,» и наслаждаться беззаботным существованием в фэнтезийном мире.",
"690640": "Самая продаваемая серия Trine возвращается к волшебству 2.5D! Присоединяйтесь к трем легендарным героям, которые отправляются в путешествие по фантастическим сказочным пейзажам, чтобы спасти мир от теней Кошмарного Принца.",
"826630": "Классическая стратегия в реальном времени с потрясающей одиночной кампанией, многопользовательским режимом и возможностью совместной игры, действие которой происходит в альтернативной реальности 1920+",
"926990": "Живите жизнью дикого волка!",
"1895880": "Отправляйтесь в межпространственное путешествие со старыми знакомыми Рэтчетом и Кланком – теперь на ПК! Помогите им одолеть злого императора из параллельной реальности, перемещаясь по удивительным мирам и даже за их пределами на бешеной скорости!‎",
"1162520": "«Richman10» — это классическая шахматная игра, в которой игроки зарабатывают деньги с помощью удачи (игры в кости) и стратегии (покупка земли и карты), чтобы побеждать других игроков. Изобразительное искусство использует чистую 3D-версию оригинального стиля живописи. Игровые режимы включают в себя: сюжетный режим, биографический режим, режим горячего сиденья для нескольких человек, сетевой режим. «Richman10» разработана компанией Softstar Technology (Beijing) Co., Ltd. и также является десятой игрой из серии игр «Richman».",
"1566690": "Командуйте мобильной заставой и возьмите с собой XEN Firearm, чтобы отправиться вглубь запретной зоны наблюдения Signet. Собирайте уникальные единицы оружия. Увеличьте огневую мощь аванпоста, который сражается вместе с вами. Это игра FTD — шутер от первого лица, защита башни, строительство базы и многое другое одновременно.",
"39120": "Выберите свою сторону. Боритесь с наступающим противником. Войдите во вселенную RIFT®.",
"1605220": "Стратегия в реальном времени с 4X-элементами от разработчиков знаменитой Northgard. Действие игры происходит в невероятной вселенной «Дюны» Фрэнка Герберта. Вам предстоит возглавить фракцию и сражаться за контроль над суровой пустынной планетой Арракис.",
"48240": "Постройте свое общество будущего, колонизируйте острова и создайте постоянно расширяющиеся мегаполисы с множеством зданий, транспортом и ресурсами.",
"1766060": "HumanitZ — это изометрическая sandbox‑игра на выживание в открытом мире, уничтоженном зомби‑апокалипсисом. Выживайте в одиночку или с друзьями, исследуя, создавая, строя и сражаясь. Прошлое неизменно, но за будущее можно бороться.",
"506610": "Добро пожаловать в мир пиццы Circus Baby's, где семейное веселье и интерактивность превосходят все, что вы видели в *других* пиццериях! Сейчас на работу: Техник, работающий допоздна. Должен наслаждаться тесными пространствами и чувствовать себя комфортно рядом с работающими механизмами. Не несет ответственности за смерть или расчленение.",
"415200": "Станьте менеджером высокоэффективной команды автогонщиков. Motorsport Manager - это лучший в своем классе спортивный менеджер для любителей автогонок. Управление командой, создание автомобилей и полное погружение в увлекательный спортивный мир. В борьбе за чемпионский титул нет второстепенных деталей. Решения за доли секунды на трассе и тщательная подготовка к заезду, создание автомобиля, тюнинг, тактика гонки - все влияет на ваш результат и предопределяет блестящую победу или горькое поражение. Хватит смотреть, начинайте побеждать. Берите в свои руки управление гоночной командой.",
"2187290": "Исследуйте загадочный мир Стены на огромном робо-пауке: копайте шахты в поисках ценных ресурсов, улучшайте снаряжение для борьбы с полчищами монстров и открывайте экзотические биомы в перерывах между атаками. Сможете ли вы выжить и узнать тайны Мировой Стены?",
"1611910": "Командуйте Серыми Рыцарями, величайшими воинами человечества, в динамичной пошаговой тактической ролевой игре. Используйте тактические умения и таланты вашего личного отряда из охотников на демонов, чтобы искоренить галактическую инфекцию в зрелищной сюжетной кампании.",
"1049800": "BLOCKADE Classic! Шутер от первого лица в процедурном кубическом мире. Огромный арсенал оружия, противостояние 4 команд и до 32 игроков одновременно на одной карте. Большой выбор игровых режимов!",
"673880": "Возьмите под контроль самые технологически продвинутые силы человечества в Империуме — Адептус Механикус. В этой пошаговой тактической игре от каждого вашего решения зависит исход миссии. Благословит ли вас Омниссия?",
"242550": "В этом зарекомендовавшем себя платформере вам предстоит бегать, прыгать и пробиваться сквозь красочные миры Луговины Снов, сражаться с эпическими боссами и собирать вместе друзей в локальном кооперативном режиме для 4 игроков.",
"773951": "Это уникальная комбинация FPS в сочетании со стратегией и элементами RPG, в которой игрок берёт на себя роль командира и зарабатывает деньги, строит армию, встречается с врагом в бою, атакует вражеские территории, удерживает свои и приходит к доминации в мире.",
"473690": "Absolver — сетевые многопользовательские сражения, где игроки скрываются под масками Претендентов по воле вездесущих Проводников, новых правителей падшей империи Адал, которые решают, достойны ли вы пополнить ряды их элитного корпуса силовиков.",
"1229380": "НЕОРДИНАРНАЯ ПРИКЛЮЧЕНЧЕСКАЯ RPG, действие которой происходит в неописуемом мире, наполненном увлекательными музыкальными битвами и странными приятными встречами. Проще говоря: вас ждёт уникальный опыт.🍄",
"223100": "Возглавьте сопротивление превосходящим военным силам в партизанской войне в открытом динамичном мире Homefront®: The Revolution и разожгите революцию, а угнетенные поднимутся на борьбу с оккупантами.",
"386070": "Управляйте огромными армиями и развяжите войну посреди целых солнечных систем. Разбейте вражеские силы с помощью сокрушительных ТИТАНОВ и уничтожьте целые планеты с помощью высокотехнологичного супер оружия!",
"317360": "Double Action — это бесплатная стильная многопользовательская игра, в которой вам предстоит нырять, переворачиваться и скользить в хаосе боевиков.",
"382310": "Попробуйте создать цивилизацию, которая будет в состоянии противостоять столкновению с метеоритом, и не уничтожить экосистему во время ее развития.",
"1273400": "Construction Simulator возвращается —теперь еще масштабнее и увлекательнее! Утолите амбиции и постройте успешный строительный бизнес с нуля, а ваш наставник Хапе вам в этом поможет.",
"914800": "Coffee Talk - это симулятор варки кофе и разговоров по душам, про выслушивании проблем современных людей с фэнтезийными чертами и помощи им, благодаря подаче тёплого напитка или двух.",
"389430": "Великая битва между Карусом и Эль Морадом уже доступна в Steam! Присягните на верность одной из наций и испытайте свои навыки в одной из лучших PvP-систем во вселенной MMORPG!",
"2408820": "Приготовьтесь исследовать, заниматься фермерством, рыбалкой, добычей ресурсов, крафтом и выращиванием волшебных Лум, решая головоломки на острове Лума. Играйте в одиночку или в кооперативе до 4 игроков. Выберите режимы \"Уютненько\", \"Приключение\" или \"Героический\".",
"2552430": "KINGDOM HEARTS -HD 1.5+2.5 ReMIX- это коллекция из 6 незабываемых приключений серии KINGDOM HEARTS, перевыпущенных в разрешении HD. Вооружитесь ключом-клинком (Keyblade), чтобы спасти миры Disney от тьмы.",
"6020": "Выковайте свое оружие и следуйте путем джедая Рыцарь-джедай: Академия джедаев — это последняя часть знаменитой серии «Рыцарь-джедай». Возьмите на себя роль нового ученика, стремящегося изучить пути Силы у мастера-джедая Люка Скайуокера. Взаимодействуйте со знаменитыми персонажами «Звездных войн» во многих классических локациях «Звездных войн», и перед вами стоит окончательный выбор: сражаться за добро и свободу на светлой стороне или следовать по пути силы и зла на темную сторону.",
"423230": "Тюремщик — путь на волю. Убей его, и ты свободен.",
"874260": "Вернитесь на 2000 лет в прошлое, чтобы увидеть последние дни проклятого римского города: стоит одному жителю преступить закон, и погибнут все. Разгадайте тайну поселения, попавшего во временную петлю — исследуйте его улицы, расспрашивайте жителей, решайте головоломки. Судьба города в ваших руках.",
"593600": "Добро пожаловать в PixARK, огромный мир дикой природы, злобных динозавров, волшебных существ и бесконечных приключений!",
"700600": "Сатирическая шпионская игра со строительством, в которой самый главный злодейский разум — это вы! Стройте базу, обучайте прислужников, защищайте свои операции от сил правопорядка и подчините себе весь мир!",
"1594320": "Постройте промышленную империю на острове. Добывайте ресурсы, меняйте ландшафт экскаваторами, стройте плантации, возводите фабрики, прокладывайте железные дороги и торгуйте с внешним миром. Изучите более 100 технологий — от выплавки металлов до ядерной энергетики и космической программы.",
"48720": "Новейшая часть серии Mount & Blade!",
"332570": "Удивительная лягушка? это игра с открытым миром, песочницей и физикой. Grand Frog Auto в Суиндоне с пукающими лягушками-рэгдоллами.",
"320240": "We Happy Few — экшен/ приключение, сценой которому служит наводненный наркотиками ретрофутуристический город альтернативной Англии 1960-х. Применяйте навыки маскировки, адаптации и ведения боя. Отыщите выход из этого бредового, подсаженного на Joy мира.",
"228300": "«Помни меня™» — это приключенческий боевик от третьего лица, в котором игроки берут на себя роль Нилин, бывшего элитного охотника за воспоминаниями, способного проникать в сознание людей и красть или даже изменять их воспоминания.",
"286940": "S.K.I.L.L. - Special Force 2 - это быстроменяющийся остросюжетный шутер, выполненный на Unreal Engine 3. Здесь представлены широкий диапазон режимов игры, массы карт и огромный выбор оружия.",
"209650": "Call of Duty®: Advanced Warfare демонстрирует величественный театр боевых действий будущего, где технологии и тактика эволюционировали, чтобы вступить в новую эпоху битв за право голоса.",
"702670": "Donut County – сюжетная головоломка с реальной физикой, где игрок управляет постепенно разрастающейся дырой в земле. Общайтесь с симпатичными персонажами, крадите у них всякий хлам – и сбрасывайте в глубокую дыру.",
"2445690": "«Потерянный замок 2» - это двухмерный сайд-скроллер в жанре Rogue-Lite. Добывайте многочисленные сокровища, овладевайте различными видами оружия и проявите накопленные силы в бою с могучими чудовищами. Новые приключения зовут кладоискателей!",
"2653790": "Вы попали в бесконечный подземный переход. Внимательно наблюдайте за своим окружением, чтобы добраться до «Выхода 8».",
"1170950": "Шагните в Нейв, огромный фэнтезийный мир-песочницу с управляемой игроками экономикой, постоянным жильем и глубокой системой крафта. Вступайте в PvP-сражения от первого лица с другими игроками и опасными противниками. Стройте, исследуйте и побеждайте в неумолимом мире. Земля твоя — кем ты станешь?",
"1369320": "Виртуальный коттедж дает вам удобное место для отдыха и продуктивной работы, не отвлекаясь ни на что. Откройте игру, поставьте себе цель и наслаждайтесь атмосферой.",
"1275890": "Baldi's Basics® Plus — это активный стелс-рогалик, пародирующий дешевую образовательно-развлекательную игру 90-х с тонкими нотками ужасов! Играйте в прятки вместе с Балди, который преследует вас по процедурно генерируемым уровням, используя ваше окружение, предметы и игровые знания, чтобы обратить хаос в вашу пользу.",
"268650": "Более 1000 уникальных блоков помогут вам построить любую, даже самую невероятную технику! Куйте вашу стратегию, заключайте союзы и формируйте ваш флот, чтобы сокрушить 8 уникальных фракций! Дикая помесь стратегии, симулятора, конструктора и РПГ.",
"846770": "Оставьте убежище. Разрушьте все. Покиньте проклятый остров. ⚔️🔨🎣🌱🌵🍰 Впереди исследования. Сражения. Развитие. Выживание. Добыча. Строительство. Охота. Фермерство. Решение загадок. Готовка. Жизнь. Все сладости и горечи постапокалипсиса!",
"973580": "Примерьте на себя роль идеального убийцы в самой реалистичной на сегодня игре про снайперов. Вас ждет захватывающая сюжетная кампания для одного игрока на огромных открытых картах. От вас потребуется наличие боевой смекалки, умение действовать бесшумно и точно поражать цели с большого расстояния.",
"769560": "«Ночь полнолуния» — это отдельная карточная игра в стиле рогалик. Отправьтесь в приключение в Шварцвальд. Случайное событие, случайный сюжет приводит к разным концовкам.",
"732430": "Superflight — это насыщенная и простая в освоении игра в вингсьюте с бесконечным количеством красивых процедурно генерируемых карт. Отличная игра, позволяющая расслабиться на полчаса и погнаться за своим последним рекордом!",
"399810": "Год 1924-й. Частный детектив Эдвард Пирс расследует трагическую гибель семьи Хокинсов... Погрузитесь в мир надвигающегося сумасшествия и космического ужаса. Тайные зацепки, загадочные фигуры и откровенный ужас станут потрясением на пути к решению потусторонней тайны и в попытке сохранить рассудок.",
"1353300": "Idle Slayer - это инкрементальная игра с пассивной и активной механикой игры, средневековой пиксельной графикой и 8-битными ретро звуками и музыкой.",
"1272320": "“Diplomacy is Not an Option” - это стратегия в мире средневекового фэнтези. Стройте города, окружайте их оборонительными сооружениями, вооружайте огромные армии и уничтожайте несметные орды врагов. Как долго вы сможете выживать?",
"290340": "Armello — игра в жанре фэнтези на базе настольных игр. Это стратегия, карточная тактика с элементами RPG и куча приключений. Воюйте, нанимайте агентов, используйте магию, яды и уловки на пути к трону!",
"1801110": "BOKURA — приключенческая игра-головоломка для двух игроков. Играйте за двух мальчиков, которые сбежали из своих домов, и работайте вместе, чтобы отправиться куда-то далеко-далеко. Оживите дружбу своего детства через путешествие двух мальчиков.",
"1522820": "Режьте, поджигайте, расплющивайте, испепеляйте, перемалывайте и потрошите огромные орды отвратительных орков в этом долгожданном продолжении прославленной серии Orcs Must Die!",
"707030": "POSTAL 4: No Regerts - это сатирический комедийный шутер от первого лица с открытым миром и долгожданный настоящий сиквел того, что с любовью было названо «The Worst Game Ever ™», POSTAL 2!",
"349700": "Играйте с друзьями в мире, кишащем зомби, сталкиваясь с остатками орд зомби и восстанавливая общество в поистине огромном мире-песочнице. Выбирайте, как вы хотите играть: сотни предметов, скинов, оружия, настроек персонажей, строительства баз, крафта, зомби и многого другого!",
"1042550": "В Digimon Story Cyber Sleuth: Complete Edition вас ждут увлекательные истории, классические пошаговые сражения и дигимоны — все, что так нравится поклонникам игр Digimon Story.",
"1785150": "Захватывающий сетевой PvP-шутер, сочетающий составление колоды карт с огненными перестрелками. Выбирайте персонажа, собирайте колоду из способностей и оружия и готовьтесь к бою!",
"206500": "AirMech® Strike — это динамичная игра в жанре Action-RTS, в которую можно играть в одиночку, в кооперативе или соревноваться по сети. Зарабатывайте славу и опыт в боях и разблокируйте обширную коллекцию авиамехаников и юнитов, практикуя идеальную стратегию, чтобы выйти победителем!",
"300380": "Road Redemption — это гоночная экшн-игра, в которой вы возглавляете банду байкеров в эпичном путешествии по стране — грандиозном приключении с ожесточенными сражениями на дорогах. Огромная кампания, десятки видов оружия, полный режим совместного разделенного экрана для 4 игроков и онлайновая мультиплеерная игра.",
"1285670": "Post Void — это гипнотическая смесь раннего дизайна шутеров от первого лица, в которой скорость превыше всего. Держите голову полной и достигайте конца; Убивайте всё, что можете, чтобы увидеть, как это исправляется; Получите высокий балл или попробуйте снова.",
"294860": "Признанная критиками игра Valkyria Chronicles теперь доступна на ПК в разрешении True HD 1080p, включая все ранее выпущенные DLC!",
"215080": "Погрузитесь во вселенную ВАКФУ в этой бесплатной многопользовательской ролевой игре. Выберите свой класс, исследуйте мир, найдите других искателей приключений и бросьте вызов сильным монстрам в эпических пошаговых поединках.Участвуйте в экономике и политике королевства, создавая собственную легенду!",
"329110": "Добро пожаловать в Gems of Wars, – новый гибрид головоломки с ролевой игрой от создателей оригинальной РПГ на сопоставление 3 предметов Puzzle Quest!",
"2695940": "PANICORE - это игра в жанре survival horror, в которой сочетаются permadeath, монстры с искусственным интеллектом и кооперативный режим. Постарайтесь сбежать и не попасться, но берегитесь: они слышат не только ваши шаги, но и ваш голос.",
"306020": "Пятизвездочная защита башни с непревзойденной глубиной и возможностью повторного прохождения. Bloons вернулись в полном HD качестве, и на этот раз они серьезно настроены! Стройте потрясающие башни, выбирайте любимые улучшения, нанимайте новых специальных агентов и уничтожайте все вторгшиеся шары в самой популярной серии Tower Defense в истории.",
"764790": "Армия демонов осаждает родную деревню молодого ниндзя, вынуждая его отправиться в проклятый мир, чтобы доставить свиток, от которого зависит выживание его клана.",
"530700": "Окунитесь в головокружительные сражения в этой официальной, самостоятельной и БЕСПЛАТНОЙ версии Arma 3. Argo представляет собой хардкорный тактический шутер от первого лица, в котором вы сражаетесь с противниками на неограниченной местности, где каждый выстрел на вес золота.",
"234670": "Проживите жизнь, сражаясь с всемогущими боссами в эпоху 4-ой великой войны ниндзя или же бросьте вызов друзьям в динамичных онлайновых и оффлайновых сражениях ниндзя!",
"400910": "Уклоняйтесь от пуль, ракет и лазеров в бою, надев костюм девочки-кролика! Комбинируйте удары своим могучим Пико-Молотом или используйте различные заклинания издалека вместе со своей огненной подругой-феей. Исследуйте и взрывайте остров Раби-Раби, собирая бонусы и раскрывая секреты...",
"650700": "Это игра, в которой вы путешествуете по чрезвычайно темному миру во сне.",
"1385380": "Окунитесь в мир карточной игры, где важен каждый шаг! Собирайте мощные колоды, собирайте друзей и ведите команду к победе через королевство Сенентии!",
"1708520": "Станьте частью Formula 1® с официальной лицензией F1® Manager 2022. Управляйте составом команды, выбирайте водителей и механиков 2022 года.",
"1207650": "В роли президента Рейна вам предстоит встать у руля государства Сордленд (Sordland). Окунитесь в пучину политических интриг, общайтесь с министрами и другими значимыми личностями, боритесь с коррупцией или поощряйте ее, формируйте идеалы нации. Каким будет ваше правление?",
"442080": "Поднимитесь в небо, участвуя в фантастических боях на летающих скакунах, не похожих ни на что, что вы видели раньше в Riders of Icarus, новой беспрецедентной приключенческой MMORPG, в которой вы сможете кататься и сражаться на спине самых опасных крылатых зверей королевства… драконов.",
"253250": "Откройте для себя живой мир, полный тепла, героизма и тайн. Помогите небольшой группе поселенцев построить себе дом на забытой земле. Обеспечьте запасы продовольствия, постройте жилье, защищайте своих людей, следите за их настроением и найдите способ расти и расширяться, сталкиваясь с проблемами на каждом этапе.",
"1276790": "Дайте отпор Погибели - Соберите отряд чемпионов из League of Legends, исследуйте Билджвотер и отправьтесь на Сумрачные острова, чтобы раскрыть тайны смертельно опасного черного тумана в этой захватывающей пошаговой ролевой игре.",
"1944430": "Amnesia: The Bunker — хоррор от 1-го лица, действие которого происходит в заброшенном бункере времён 1-й мировой войны. Столкнитесь с угнетающими страхами, преследующими вас во тьме. Ищите и используйте доступные инструменты и оружие. Не дайте свету погаснуть и выберитесь живым.",
"1938010": "Освойте древние технологии, позволяющие охотиться на гигантских чудищ. Являя собой свежий взгляд на жанр охотничьих игр, WILD HEARTS™ предлагает использовать научные достижения прошлого, чтобы побеждать впитавших силы природы существ. Охотьтесь в одиночку или с друзьями.",
"1057240": "Crucible — это бесплатный командный PvP-шутер. Выберите инопланетянина, человека или робота-охотника и сражайтесь в матчах 4 на 4.",
"242720": "GunZ 2: The Second Duel — это бесплатная 3D-игра от первого лица и самый динамичный и жесткий шутер.",
"718670": "Тайное станет явным. Слугами станут боги. Плоть станет пищей. Cultist Simulator — это игра о страсти на краю пропасти, созданная Алексисом Кеннеди, автором игр Fallen London и Sunless Sea. Место её действия — мир, в котором за декорациями из двадцатых годов прошлого века прячутся боги и пишутся секретные летописи. Её действующие лица — те, кто алчет проклятых тайн.",
"1898300": "Станьте вождем новой эры викингов. Оснуйте колонию в мифическом открытом мире, где правят холод и чудовища. Завоюйте благосклонность богов и привлеките уникальных жителей, чтобы построить могучее поселение и защитить свое племя — соло или в кооперативе!",
"495890": "Монтаро - казуальная игра-забег, предназначенная для того, чтобы на душе стало чуточку теплее.",
"529180": "На создание этого шедевра в жанре песочницы, разработчики потратили 12 лет. При помощи игрового движка 4 Unreal, был создан невероятно огромный магический мир, с фантастическими существами. В этом мире, каждый игрок может исследовать магические места, приучить диких животных к послушанию, добывать себе пищу, материалы для строительства, создавать себе оружие для защиты, и все необходимое что нужно для выживания. Уникальная погодные условия заставят вас добывать огонь чтобы не замерзнуть, укрываться в теплых местах когда на улице идет дождь, и многое другое. Высокая степень свободы позволяет игроку путешествовать по миру и создавать свои собственные кланы для защиты своего дома.",
"1849250": "Ощутите весь драйв сезона ралли 2024 с новыми местами, моментами, трассами, высокопроизводительными машинами, новыми раскрасками и лицензированными экипажами. Приготовьтесь окунуться в бесконечный мир ралли.",
"2676840": "Спустя 12 лет после отставки старшего инспектора Чон Гён, её посетил молодой офицер полиции: девушка, которая умоляет пересмотреть дело Совон. Но с каждым новым воспоминанием одна вещь становится ясна: все, кто был причастен, лгали.",
"731040": "Задумайтесь о превосходстве людей в The Invincible – философском сюжетном путешествии по фантастическому атомпанковому миру Лема. Исследуйте планету Регис III в поисках своего экипажа, справляйтесь с опасностями и принимайте важные решения.",
"792300": "The Beast Inside - свежий взгляд на триллер и survival horror. Погрузитесь в историю, полную тайн прошлого, личных трагедий и безумия. Играйте за двух героев с одним мрачным наследием. Сражайтесь, решайте головоломки и испытайте ужас в полноценном 3D.",
"2849080": "Пока возникает мощное зло, формируется неожиданный союз! Чтобы его остановить, потребуются лучшие воины Линиреи и неумолимая Темная армия. Будьте осторожны! Хоть они и могут идти бок о бок, но переменчивые ветра судьбы могут быстро изменить их курс.",
"329430": "Покажите зомби зубы и не дайте человеческому роду сгинуть в небытие. Исследуйте бескрайние просторы игрового мира, но помните: жизнь здесь не замирает ни на секунду, и на каждом шагу вас подстерегает опасность. Сколотите боеспособную группу из тех, кому удалось выжить и кем вы сможете играть. У каждого из этих персонажей есть уникальные таланты и навыки. Постройте базу, а затем превратите ее в неприступную крепость, которая сможет выдержать затяжную осаду",
"428550": "“Reverie Under the Moonlight” – четвёртая часть любимой фанатами серии 2D-платформеров Momodora. Проделайте себе путь через проклятое королевство с помощью комбо и уворотов, получите аудиенцию у Королевы и изгоните зло, угрожающее всему живому.",
"1177980": "Вы — маленькая киса в большом городе, которую ждет настоящее приключение по пути домой. Исследуйте закоулки города, знакомьтесь с другими животными, собирайте разнообразные головные уборы и... творите хаос! Да, хаос. А как иначе?",
"1295510": "Definitive Edition — это высоко оцененная критиками DRAGON QUEST XI, а также дополнительные сюжетные линии, оркестровый саундтрек, 2D-режим и многое другое! Это издание позволит насладиться DQXI как новичкам, так и преданным поклонникам игры.",
"1745510": "Тех, кто не нужен на поверхности, сбрасывают в Великий Колодец. Найдите в непроглядной тьме Древнего – вашу последнюю надежду на спасение. Lunacid — это игра про исследование подземелий в атмосфере тёмного фэнтези, вдохновленная Shadow Tower и King's Field.",
"17450": "Когда история расскажет историю Пятого Мора, что будет сказано о герое, переломившем ход борьбы с порождениями тьмы? Определите свое наследие и сражайтесь за Тедас в роли благородного гнома, эльфа вдали от дома, ученика мага или героя, созданного по вашему собственному желанию. Испытайте множество уникальных историй происхождения в своем стремлении объединить королевства и победить древнее зло.",
"327030": "Вступайте в бой и ведите своих беспозвоночных в атаку в культовой двумерной артиллерийской аркаде. Здесь серьёзная стратегия на пару с абсурдным оружием решают, кто из червей останется, а кто пойдёт ко дну.",
"1085510": "Garfield (Гарфилд), знаменитый кот-любитель лазаньи, вернулся, чтобы бросить вызов Jon, Odie & Cie в гонке, где нет запрещенных приемов!",
"368360": "60 Seconds! - это чёрная комедия о выживании и приключениях в условиях ядерного взрыва. Собери запасы и спаси свою семью до того, как взорвётся бомба. Выживи в своём противоатомном убежище. Принимай трудные решения, разделяй запасы и воюй с тараканами. И может, тебе удастся выжить. Или нет.",
"861540": "Стань огромным игральным кубиком на ножках и сражайся до конца в постоянно меняющихся подземельях!",
"537800": "Подготовьте экипаж к самой опасной миссии и отправляйтесь на воздушную экспедицию в стратегическом симуляторе на выживание Bomber Crew.",
"710920": "Вы узнаете, что происходило в мире до начала событий DARKSIDERS, и сможете примерить роль четвертого всадника Апокалипсиса — РАЗДОРА.",
"814370": "Уникальное сочетание жанров: дрессировка монстров и метроидвания в одной игре! Собирайте и обучайте монстров, а потом отправляйте их в битву в очаровательном пиксельном мире с видом сбоку.",
"354140": "Спустя тридцать лет после того, как Freddy Fazbear's Pizza закрыла свои двери, события, произошедшие там, стали не более чем слухами и детскими воспоминаниями, но владельцы «Fazbear's Fright: The Horror Attraction» полны решимости возродить легенду и сделать этот опыт максимально аутентичным для посетителей, делая все возможное, чтобы найти что-нибудь, что могло бы пережить десятилетия пренебрежения и разрушения. Сначала были только пустые ракушки, рука, крючок, старая кукла из бумажной тарелки, но потом было сделано замечательное открытие... В аттракционе теперь есть один аниматроник.",
"115320": "Станьте идеальным оружием-метаморфом!",
"555220": "Detention — это атмосферный хоррор, действие которого разворачивается в Тайване 1960-х годов, где действует военное положение. Игра, включающая религиозные элементы, основанные на тайваньской/китайской культуре и мифологии, предоставила игрокам уникальную графику и игровой опыт.",
"979110": "Соберите команду и отправляйтесь в космос на поиски нового дома. Стройте космические корабли, заботьтесь об оптимизации экосистемы, следите за нуждами экипажа и исследуйте Вселенную в этом симуляторе космической колонии!",
"458710": "Отправляйтесь в эпической при(зло)ключение: командуйте войсками и защищайте экзотические земли от драконов, растений-людоедов и жутких обитателей подземного мира — и все это в окружении ярких новых башен, уровней, героев и полезных предметов, которые помогут вам сокрушить врагов в нашей фэнтезийной экшен-игре в жанре башенной защиты.",
"464060": "RUINER — это брутальный экшн-шутер, действие которого разворачивается в 2091 году в киберметрополисе Ренгкоке. Киборг-социопат сражается против коррумпированной системы, чтобы докопаться до правды и вернуть своего похищенного брата под присмотром загадочной помощницы-хакерши.",
"1030210": "В Torchlight III Новастрайе снова угрожает вторжение, и именно вам предстоит ее защищать от Нетерим и их приспешников. Cобирайтесь c мыслями, и вперед – на рубежи, навстречу славе, известности и новым приключениям!",
"1377380": "'Night of the Dead' - это игра в открытом мире, которая сочетает в себе элементы исследования, обороны башни, выживания и крафтинга. Пересекайте мир, охваченный зомби, собирая различные ресурсы и мощное снаряжение. Постройте крепость, чтобы выжить в стаи зомби, которые атакуют каждую ночь!",
"1147550": "Сегодня вечер выборов! Новая политическая партия одержала победу, но редактор Вечерних новостей сбежал и теперь вам, уборщику, предстоит управлять комнатой вещания. Как вы поступите — поддержите новое правительство, пока страна скатывается в антиутопию? Или сделаете все, чтобы его остановить?",
"1065310": "Зловещая угроза нависла над Диким Западом. В одиночку или сообща сражайтесь с кровожадными чудищами в беспощадных, взрывных боях и покажите всем, как это делается. Искореняйте полчища вампиров заправленной молнией рукавицей и станьте супергероем Дикого Запада.",
"2194530": "Управляйте отелем и нанимайте сотрудников, включая Смерть, дракона, Охотника за духами и горничную-биороида. Увеличьте свое богатство различными способами и отточите свои стратегии на основе предсказаний оракулов. Все сотрудники могут завязать романтические отношения в зависимости от вашего выбора.",
"2933130": "Единственный симулятор выживания во времена Четвертой эпохи Средиземья™",
"666220": "CS2D — это бесплатный многопользовательский динамичный шутер с видом сверху. Игра включает в себя множество различных режимов, встроенный редактор карт и многое другое.",
"891040": "Бильярд 2D - это бесплатная бильярдная игра, включающая 8, 9, 15, 3, вращение и блэкджек. Графика впечатляет, а физика реалистична и точна. Играете ли вы против компьютера или против реальных игроков со всего мира онлайн, действие происходит плавно и быстро!",
"589590": "Добро пожаловать в детский сад! Получайте удовольствие, пытаясь учиться и делиться... и не умереть. Это тоже важно. В школе, которая не совсем правильная, важно быть дружелюбным... и устранять тех, кто неправильный.",
"2088570": "Tiny Rogues — это сложная фэнтезийная игра в жанре «рогалик» и адских подземелий с элементами ролевой игры. Создавайте нового уникального персонажа в каждом забеге и сражайтесь в одной комнате, кишащей монстрами, за другой! Открывайте уникальное оружие, собирайте магические предметы и повышайте уровень, чтобы стать все сильнее и сильнее!",
"1281800": "Вы очнулись в странной незнакомой комнате. Сможете ли вы найти выход? Samsara Room — это ремейк одноименного предшественника известной серии игр Rusty Lake и Cube Escape.",
"673750": "Кооперативный платформер с отличной физикой про парня в костюме кролика! Зовите друга, а то и сразу трех (для игры локально или по сети), чтобы проходить уровни, искать морковки и скакать наперегонки с временем. Станьте поехавшим кроликом и сейте морковный хаос! Теперь вы Super Bunny Man!",
"206190": "Gunpoint — это стелс-игра-головоломка, которая позволяет вам перенастраивать уровни, чтобы обманывать людей. Вы играете шпионом-фрилансером, который берет работу у своих клиентов, чтобы проникнуть в здания с высоким уровнем безопасности и украсть конфиденциальные данные.",
"2132850": "RABBIT & STEEL — это кооперативный рогалик, воссоздающий суть высокоуровневых MMO-рейдов в случайном, упрощенном виде размером с кролика. Выберите свой класс, соберите своих кроличьих ушей и пробейтесь к Лунной вершине!",
"694280": "Орды Гитлера вернулись, чтобы получить больше в этом леденящем кровь шутере от создателей Sniper Elite 4! Отвратительные оккультные враги, эпическое оружие и новая мучительная кампания для 1–4 игроков ждут вас в Европе 1940-х годов, когда вы сражаетесь за спасение человечества от Армагеддона нежити!",
"1307580": "Отправьтесь в увлекательное путешествие и держите камеру наготове, чтобы раскрыть тайны TOEM в нарисованной от руки приключенческой игре. Общайтесь с причудливыми персонажами, помогайте решить их проблемы с помощью фотографий и любуйтесь прекрасными пейзажами!",
"790740": "Вы с другом попали в ловушку в странном мире. Решайте загадки наперегонки со временем, чтобы спастись. Работайте сообща, чтобы увидеть картину целиком! Играйте на двух устройствах рядом или на расстоянии. Главное — голосовое сообщение.",
"1404850": "«Удачи, арендодатель» — это стратегия-симулятор в жанре roguelite, где нужно с помощью игрового автомата зарабатывать деньги на аренду и победить капитализм. Это не азартная игра, здесь нет ставок на реальные деньги и микротранзакций.",
"204880": "Возглавьте космическую империю в Sins of a Solar Empire: Rebellion, новом независимом дополнении, совмещающем в себе глубину 4X-стратегий и динамику игр в реальном времени.",
"202170": "Опробуйте новое дополнение «Nightmare in North Point»!",
"280160": "Aragami — это стелс-игра от третьего лица, в которой вы играете за убийцу-нежить, способного управлять тенями. Телепортируйтесь в любую тень, станьте невидимым, материализуйте оружие или даже вызовите теневого дракона, чтобы проникнуть в ряды врага и уничтожить свои цели.",
"496300": "В игре Kingdom: New Lands вы столкнетесь с различными задачами, справиться с которыми помогут предметы, персонажи и загадочные статуи. Однако сначала вам предстоит понять, как именно использовать эту помощь в постройке и защите собственного королевства.",
"311310": "Парусному флоту БЫТЬ!",
"572890": "Pikuniku потрясающе абсурдная игра, в которой вам предстоит разгадывать головоломки и исследовать странный, но красочный мир, где не все так безоблачно, как может показаться. Помогайте местным жителям и поднимите знамя революции в этой невероятно милой антиутопии!",
"409160": "15-минутный симулятор ограблений от студии Crows Crows Crows под руководством Уильяма Пью (The Stanley Parable). Примерьте на себя роль лучшего мастера-вора, на счету которого величайшие ограб- о, господи, всё, надоело, я ухожу. удачи там с описанием для steam. -тина",
"1486920": "Командуйте различными фракциями в отчаянной борьбе за власть и ресурсы в Tempest Rising — классической стратегии в реальном времени, действие которой происходит на Земле после ядерной войны.",
"528230": "SYNTHETIK - это беспощадный шутер-рогалик в мире, который захватили машины. Героя ждёт мощное оружие, апгрейды и уровни, полные безжалостных роботов. Найди свой стиль и убей их всех! Пусть рефлексы тебя не подведут.",
"282900": "Насыщенный динамичными пошаговыми ролевыми действиями, ломающими четвертую стену и разрушительными диалогами, а также большим количеством настроек предметов, оружия и костюмов, чем вы можете потрясти на уровне. 1 Держитесь, Gamindustri — это мир, который переворачивает концепцию JRPG с ног на голову!",
"552620": "ATOM RPG это пост-апокалиптическая инди-игра вдохновлённая классическими CRPG: Fallout, Wasteland, Deus Ex, Baldur's Gate.",
"1367550": "Настало время расплаты! Возглавьте мощную темную армию, и пусть Королевство трепещет от каждого вашего шага! Сразитесь со свирепыми врагами и величайшими боссами. Найдите самые смертоносные комбинации из могучих башен и осадных орудий. Обучайте легендарных героев и ведите их к победе!",
"238430": "Contagion — это не обычный зомби-шутер, а более реалистичный и отличный от популярного жанра подход с уникальными персонажами, окружением, оружием, предметами и встроенной системой, которая делает каждый раунд совершенно непредсказуемым, а ресурсы, цели и пути постоянно меняются.",
"1118310": "RetroArch — это кроссплатформенный интерфейс/фреймворк с открытым исходным кодом для эмуляторов, игровых движков, видеоигр, медиаплееров и других приложений.",
"365300": "TE120 – короткая одиночная игра во вселенной Half-life демонстрирующее оружие, которое игнорирует гравитацию и позволяет запрыгивать на здания и выдерживать большие падения. История разворачивается в таинственном месте и времени. Где Вы? Зачем Вас послали?",
"1259980": "Вы готовы сыграть в лучшую игру, о которой может мечтать любитель мотоциклов? RIDE 4 разожжет в вас дух соревнования благодаря сотням мотоциклов, десяткам треков и абсолютно новому уровню реализма.",
"1677770": "Новый вид детективной игры, которая позволяет вам свободно думать и исследовать. Найдите подсказки, связанные с 12 странными и ужасными смертями, и постройте свою собственную теорию. Выберите подозреваемого, определите мотив, раскройте ужасную правду.",
"482400": "Битва насмерть от первого лица в глубинах космоса!",
"1255630": "ПРИМЕЧАНИЕ: все серверы сетевого режима игры WWE 2K22 будут отключены 31/12/2023. Начиная с этого времени, все функции игры, требующие соединения с онлайн-серверами, станут недоступны.",
"362960": "Сыграйте в ролевую игру, в которой из-за вашего выбора меняется сам игровой мир.",
"1054490": "Wingspan (Крылья) — спокойная карточная стратегия про птиц, предназначенная для 1–5 игроков. Каждая птичка в вашей колоде усиливает цепочки особых свойств одной из трех доступных сред обитания, в которых вам предстоит отыскать редких и необычных пернатых и привлечь их в свои заповедники.",
"536270": "Ancestors: The Humankind Odyssey от Panache Digital Games — симулятор выживания с видом от третьего лица. Исследуйте открытый мир, расширяйте свои владения и развивайте клан, чтобы перейти на следующую ступень эволюции.",
"1128000": "Cube World — это воксельная ролевая игра с упором на исследование. Действие происходит в процедурно генерируемом фэнтезийном мире, полностью состоящем из кубов.",
"1608230": "В мире, объединившем величие природы и бессердечность машин, девочка и ее спутница должны опираться только на свою связь, чтобы выжить и защитить то, что им дорого. Эта история о надежде, утрате и любви останется с вами надолго — даже после окончания путешествия.",
"356570": "3 часа ночи. Громкая вечеринка по соседству. Останови их! Party Hard тактическая стратегия про конец вечеринки, в любом смысле.",
"2140020": "Приветствуем вас, сир! Ваша крепость ждет вас. Развивайте свои земли и осаждайте замки колоритных противников в «симуляторе замка», заложившем основы жанра. Играйте в классическую RTS с новой графикой, улучшенным игровым процессом, Steam-мультиплеером и новой кампанией.",
"614570": "От удостоенных наград разработчиков Arkane® Studios выходит Dishonored®: Death of the Outsider, следующее отдельное приключение в получившей признание критиков серии Dishonored®.",
"418340": "RWBY: GRIMM ECLIPSE — это совместная онлайн-игра для 4 игроков, основанная на международном популярном сериале RWBY от Rooster Teeth.",
"396750": "EVERSPACE™ — сочетание стремительных схваток с элементами Rogue-подобных игр, чудесной графикой и захватывающим сюжетом. В непростом путешествии по изменчивой и прекрасной вселенной вас ждет множество сюрпризов.",
"397340": "Стройте самолеты, соединяя детали, проектируя секции крыльев и прикрепляя двигатели. В любой момент вы можете пристегнуться к кабине и посмотреть, как он летает, с реалистичной физикой. Если у вас нет настроения строить, более 100 000 самолетов доступны для бесплатного скачивания.",
"1571440": "Встречайте Lunch Lady: онлайн-кооперативный хоррор на выживание для 1-4 игроков. Приближаются выпускные экзамены, и вам с друзьями не пришло в голову ничего лучше, чем украсть ответы на тест. Найди все 10 страниц и не попадись кровожадной Lunch Lady, тётке из школьной столовой!",
"245620": "Возвращайтесь на удаленный остров Тропико в новом эпизоде популярного \"симулятора диктатуры\". Расширьте владения своей династии и займитесь торговлей, научно-техническими разработками и изысканиями.",
"429790": "Король Бездны тайно собирает армию. Смерть выбрала тебя своим защитником, чтобы победить его. Приключения и квесты вместе с друзьями в этой причудливой кроссплатформенной MMORPG от создателей оригинала с комично-избыточным названием... AdventureQuest! Еженедельные выпуски!",
"1324130": "Покоряйте новый мир в симуляторе выживания Stranded: Alien Dawn. Только от вас зависит, как сложится судьба небольшой группы людей, оказавшихся на далёкой планете. Погрузитесь в мир игры и принимайте важные стратегические решения ради защиты группы выживших.",
"573100": "Battlefleet Gothic: Armada 2 — это новая стратегия в реальном времени, основанная на знаменитой настольной игре компании Games Workshop и повествующая о грандиозных космических битвах во вселенной Warhammer 40,000.",
"1740720": "Have a Nice Death —это экшен в жанре roguelike. Его главный герой —смертельно задолбавшийся директор Смерть, чьи подчиненные совсем потеряли берега и перевернули с ног на голову баланс прихода и ухода душ. Взявшись за верную косу, Смерть отправляется показывать сотрудникам, кто тут все-таки главный.",
"678800": "Очистите нежить! Напряженный шутер с глубокими элементами ролевой игры, включая улучшаемое оружие и броню, уникальные классовые навыки и специальные способности класса. Всю игру можно проходить в одиночку или в кооперативной онлайн-игре для 4 игроков, включая PvP-события, такие как Last Man Standing.",
"597220": "West of Loathing — фарсовая комедийная приключенческая ролевая игра с фигурками Дикого Запада.",
"1012790": "Into the Radius — однопользовательский VR-шутер на выживание. Исследуйте пустоши Радиуса, полные монстров и опасных аномалий. Защищайтесь с помощью реалистичного оружия, собирайте удивительные артефакты и раскрывайте секреты аномальной местности.",
"237310": "Elsword — это бесплатная онлайн-ролевая игра, в которой используется классическая игровая механика с боковой прокруткой в ​​захватывающем мире, вдохновленном мангой.",
"799960": "Дайте волю своей внутренней магии и приготовьтесь разгадать тайны, окружающие профессора-смерти, ставшего мошенником. Тьма угрожает поглотить Спираль, пока вы осваиваете мощные заклинания, исследуете более 22 причудливых миров и объединяетесь с друзьями в этой ностальгической MMORPG с пошаговой сборкой колод.",
"394230": "БЕСПЛАТНАЯ ПРОБНАЯ ВЕРСИЯ PVP-РЕЖИМА! Отряд безбашенных героев пытается защитить последнюю звезду во Вселенной от таинственных злых сил в этом геройском шутере от создателей Borderlands.",
"242640": "Styx: Master of Shadows — это игра-проникновение с элементами ролевой игры, действие которой происходит в темной фантастической вселенной, где вы пробираетесь, крадете и убиваете, играя за Стикса, гоблина двухвекового возраста.",
"809960": "Добро пожаловать в Радикальные Высоты, экстремальную игру бесплатного доступа. Примите участие в перестрелке с высокими ставками, где вы будете грабить оружие, гаджеты, косметику и деньги! Выжить до конца или рисковать всем в этой вызывающей экшен-игре, где каждый хочет быть богатым и известным!",
"31280": "Приготовьтесь к непохожему ни на что покеру в непохожем ни на что покерном клубе и сыграйте против хорошо знакомых лиц.",
"1473350": "(the) Gnorp Apologue — это путешествие гнорпов, в котором вы ведете их к цели восхитительного накопления чрезмерного богатства.",
"375950": "Вырастите небольшой горшок с суккулентами, которые растут в реальном времени. Вириди — это безопасная гавань, место, куда вы можете вернуться на минутку тишины и покоя, когда вам это понадобится.",
"2060160": "Запрограммируйте дрон, чтобы автоматизировать работу на ферме, и смотрите, как он делает все за вас. Собирайте ресурсы и разблокируйте новые технологии. Станьте самым успешным фермером в мире. В процессе вы разовьете навыки решения задач и написания кода.",
"952860": "Ho Tu Lo Shu: The Books of Dragon предлагает полную свободу игры в открытом мире в стиле уся. Благодаря реалистичному художественному стилю и богатому развитию персонажей вы сможете исследовать огромный мир уся и создать собственное приключение в компании различных запоминающихся персонажей.",
"362930": "Присоединяйтесь к Гарфилду и его друзьям в самой веселой быстрой и яростной игре! Каким персонажем вы хотите играть? Гарфилд, Оди, Джон, Нермал... выбирай ты! Примите участие в безумных гонках без ограничений.",
"1585180": "\"Drova - Forsaken Kin\" — это пиксельное экшен-RPG, вдохновленное мрачными классиками жанра и мистическим очарованием кельтской мифологии.",
"505230": "Боритесь с чумой. Делайте лекарства. Лечите людей. Делайте вскрытия. Торгуйте, чтобы достать необходимое. Деритесь и убивайте, если потребуется. Выживайте. “Мор” - сюжетная песочница о борьбе врача с эпидемией смертельной болезни в далеком степном городке.",
"1718870": "В Spaceflight Simulator вы будете строить ракеты, планировать запуски и полёты, пытаться их посадить, доставлять полезную нагрузку и исследовать новые миры.",
"2461850": "Продолжение Hellblade: Senua's Sacrifice — саги, покорившей критиков и игроков. Исландия эпохи викингов полна мифических существ и человеческих страданий.",
"1316680": "Сражайтесь под натиском мутированных людей, одержимых солдат и еще более мрачных боссов. Пытайтесь выжить и выяснить, что делать дальше в этой жизни, попутно разрывая на куски своих врагов.",
"2420660": "Это трогательная история о девушке и её дружбе с величественным волком. Вместе они совершают захватывающее путешествие по стремительно угасающему миру.",
"1286350": "BPM — это ритмичный шутер от первого лица с элементами rogue-like-игр, в котором тебе предстоит вести огонь, прыгать и уклоняться от атак в ритме эпического саундтрека в стиле рок. Отправляйся в случайно генерируемые подземелья, в которых одна пропущенная нота может стоить жизни.",
"403190": "Руководите группой космических поселенцев, пытающихся основать базу на далекой планете. Выращивайте еду, собирайте энергию, добывайте ресурсы, переживайте катастрофы и стройте самодостаточную колонию в суровых и беспощадных условиях.",
"588030": "Управляйте огромными поездами и стройте свою карьеру в масштабной железнодорожной сети открытого мира. Играйте на PC или в VR.",
"32800": "Работайте вместе или умрите в одиночку в этом эпическом приключении, чтобы переломить ход Войны Кольца.",
"257350": "Вернитесь к бессмертному шедевру ролевых игр. «Baldur’s Gate II: расширенное издание» — это возрождение приключения 2000 года с тщательно продуманными современными улучшениями. Соберите отряд и снова погружайтесь в эпическое фэнтези, где всё зависит от ваших решений.",
"1615290": "Кулинарный симулятор в жанре хоррор, где за разгадкой секретного ингредиента кроется злодеяние. Улучшайте свою лавку, покупая новые инструменты и обслуживая клиентов.",
"2058180": "Боритесь за правду и раскройте запутанные преступления, скрывающиеся глубоко под поверхностью Токио. В этом юридическом триллере баланс между справедливостью и милосердием балансирует на грани.",
"234650": "Мир Shadowrun, смесь киберпанка и фэнтези, был придуман четверть века тому назад и c тех пор обрёл большое количество поклонников. Его создатель Джордан Уайзман вернулся к Shadowrun, чтобы осовременить классику и превратить её в тактическую пошаговую ролевую игру. В поисках загадочного убийцы, обитающего в метроплексе Сиэтла, вы побываете в мрачных трущобах и самых влиятельных корпорациях города. Чтобы докопаться до истины, вам придётся действовать очень осторожно, заручиться помощью других раннеров и овладеть передовыми технологиями и магией.",
"1426450": "Age of Darkness: Final Stand — это стратегия в реальном времени в жанре «темное фэнтези», где вам предстоит освещать территории, строить и защищать последний оплот человечества от полчищ Кошмаров.",
"470310": "TROUBLESHOOTER: Abandoned Children — это первый сезон пошаговой стратегии SRPG, действие которой разворачивается в мире Troubleshooter.",
"2285150": "The Front — боевой симулятор выживания с открытым миром. Перенеситесь в прошлое, чтобы переписать ход истории и предотвратить рассвет жестокой Империи. Исследуйте мир, стройте базы, создавайте технологии — поработите всех, кто встанет у вас на пути, и выполните вашу миссию!",
"2378620": "ANOMALY AGENT — экшен-платформер в стиле киберпанк, интересный подвижными боями, закручивающим время сюжетом, необычными персонажами и цепляющим синтвейв-саундтреком. Колотите и расстреливайте врагов, принимайте решения, меняющие ход событий, и остановите аномалии, иначе мир погрузится в хаос!",
"1546990": "Grand Theft Auto: Vice City: Добро пожаловать в 1980-е... Проживите историю Томми Версетти, полную предательств, возмездия и неоновых огней тропического Вайс-Сити. Все богатства этого города станут вашими – нужно только протянуть руку.",
"388880": "Oxenfree — это мистический триллер о группе друзей, которые случайно открывают разлом в призрачный мир. Вам предстоит примерить на себя роль Алекс, девушки, которая только что привезла своего новоиспеченного сводного брата на вечеринку на острове, где всё пошло не так.",
"2186320": "Ages of Conflict — это уникальная игра-симулятор мировой войны, в которой ИИ-нации воюют в безграничном количестве миров. Управляйте нациями, чтобы подтолкнуть мировые события по вашему вкусу.",
"238370": "Самый дерзкий кооперативный приключенческий боевик в мире возвращается! В следующей главе Magicka игроки поднимаются из руин Альдхейма, чтобы увидеть Мидгард, почти полностью очищенный от волшебников после Войн волшебников, а те немногие, кто остался, либо сошли с ума, либо крайне враждебно относятся ко всем остальным.",
"1361000": "In Silence - многопользовательская игра ужасов. Один игрок берет на себя роль монстра, который обладает гиперчувствительными слуховыми способностями и почти полностью слеп. Другие игроки (2-6) играют как выжившие, пытаясь сбежать или охотиться на монстра.",
"1137460": "[3D-игра с бессмертной смертью от третьего лица] Постарайтесь до конца преодолевать различные препятствия.",
"249050": "Dungeon of the ENDLESS™ — это игра в жанре Rogue-Like Dungeon Defense, в которой игрок и его команда героев должны защищать генератор разбившегося корабля, исследуя постоянно расширяющееся подземелье, сталкиваясь при этом с волнами монстров и особыми событиями, пытаясь найти выход...",
"1007040": "Встаньте и сражайтесь за человечество. Действие этого аркадного шутера происходит в 2022 году, когда Силы обороны Земли отражают тотальную атаку неизвестных форм жизни. Станьте солдатом EDF, сражайтесь с бесконечными ордами огромных врагов и восстановите мир на земле.",
"1262600": "Сотрите грань между одиночной и многопользовательской игрой в непримиримом соперничестве полиции и гонщиков. Заходите в мир, где ваши друзья уже уходят от погони и гонятся за нарушителями",
"211400": "«Пожалуй, лучшее предложение на рынке загружаемых игр в данный момент.» 9 из 10 —",
"1049890": "Управляйте милой маленькой ведьмочкой Нобетой, исследуйте неизвестный загадочный замок и постепенно узнайте правду!",
"1205520": "Искусство имитирует смерть",
"108800": "Спасите человечество от уничтожения в битве за Нью-Йорк. Станьте оружием.",
"2140510": "Игра обмана и дедукции. Среди жителей Салема есть те, кто работает против невинных. Убийство, тайна, магия и многое другое!",
"1069740": "Одинокий ребенок отчаянно пытается сбежать из своего темного мира.",
"939850": "Антология The Dark Pictures — цикл нелинейных киноигр в жанре хоррор с поддержкой игры вдвоём по сети. В Man of Medan пятеро друзей отправились на дайвинг, но шторм превратил их поездку в настоящий кошмар.",
"656350": "Динамичный приключенческий roguelike с щепоткой RPG. Забирайтесь поглубже в Шахту и находите мощные реликвии, смертоносных врагов, спрятанные секреты друзей, которые помогут выжить и победить.",
"446800": "Transport Fever — это железнодорожная экономическая стратегия. Игроки начинают в 1850 и строят процветающую транспортную компанию. Будучи новоиспеченным магнатом, игрок возводит станции, аэропорты, доки и зарабатывает деньги, соединяя области, которым нужно транспортное сообщение. Стройте сложные автомобильные, железнодорожные, водные и воздушные пути сообщения и пройдите по 150-летнему пути развития транспорта. Удовлетворяйте потребности людей и наблюдайте, как растут города. Обеспечивайте промышленность грузоперевозками и размещайте транспортные сети для роста экономики. Постройте транспортную империю!",
"227860": "Castle Story — это креативная воксельная стратегическая игра, в которой вы можете строить замки по одному кирпичику, используя армию маленьких существ под названием Бриктроны. Проектируйте и стройте свои собственные замки, расширяйте свою территорию на обширном ландшафте и защищайте свои Бриктроны от нападений враждебных существ.",
"690040": "Третья игра в серии SUPERHOT, MIND CONTROL DELETE, подарит вам новые тайны мира SUPERHOT, новые сюжетные повороты и больше полюбившегося вам игрового процесса. Вас ждет танец разрушений в замедленной съемке — и насладиться им вы сможете дольше, чем когда-либо раньше.",
"2012510": "Stormgate — это стратегия в реальном времени нового поколения. Ее действие разворачивается в новой вселенной, которая объединяет в себе научную фантастику и фэнтези. Проходите постоянно развивающуюся кампанию, играйте втроем в кооперативном режиме против ИИ или сражайтесь в битвах один на один.",
"1202130": "Starship Troopers: Terran Command — захватывающая стратегия в реальном времени, действие которой разворачивается во вселенной фильмов «Звёздный десант». Командуйте Мобильной пехотой и исполните свой долг в сражениях с арахнидами. Галактика для людей, а не для насекомых!",
"215280": "Secret World Legends — это сюжетная ролевая игра с общим миром, которая погружает игроков в призрачную войну со сверхъестественным, где древние мифы и легенды переходят в современность.",
"378540": "Добро пожаловать в CREO – корпорацию, которая спасает мир! Отныне вы в числе ее сотрудников. И в первый же день случается катастрофа. Сознание ускользает, вы проваливаетесь в темноту...",
"208200": "Армия ада захватила научную базу ОАК на Марсе, и вы оказались среди немногих выживших. В этом знаменитом хоррор-шутере от первого лица, который стал переосмыслением концепции оригинальной DOOM, вам предстоит пройти через пекло и обратно, сокрушив полчища демонов.",
"1372280": "Новая игра в серии 2D-файтингов, созданная TYPE-MOON, нарисована в фантастическом мире полнометражного причудливого визуального романа \"Цукихимэ\". Продолжение истории, в которой сражаются персонажи \"Tsukihime -A piece of blue glass moon-\".",
"221260": "Игра от дизайнеров World of Goo и Henry Hatsworth. Бросайте свои игрушки в огонь и играйте с ними, пока они горят. Оставайтесь в тепле. Снаружи становится холоднее!",
"611670": "В Skyrim VR открытый мир оживает. Вас ждут битвы с древними драконами, странствия по горам и многое другое. В Skyrim VR также вошли все официальные дополнения.",
"1911610": "Суперскоростной кооперативный roguelike/экшен для 1-3 игроков от авторов Dead Cells. Бросайся в бой, уклоняйся, круши врагов на обломках расколотого мира. Создавай невероятные сборки, пускай в ход мощные иноатаки и бросай вызов Воронке.",
"252610": "Управляйте машиной, полной придурков, пока они исследуют города, набирают странных людей, спасают собак, спорят друг с другом и сталкиваются с гигантскими толпами медленных зомби. Генерируется случайным образом для новой истории и редких событий каждый раз, когда вы играете!",
"1957780": "Ghosts of Tabor — это игра на выживание в жанрах FPS, PVP и PVE, предназначенная только для виртуальной реальности, где вам придется использовать свой ум, навыки и ресурсы, чтобы выжить. Вдохновлен такими играми, как Escape from Tarkov и DayZ, с различными сценариями: от сбора мусора до грабежа и крафта. Сможете ли вы выжить достаточно долго, чтобы выбраться живым?",
"1162750": "Songs of Syx — это фэнтезийный градостроительный симулятор с масштабными сражениями, в которых симулируются тысячи горожан и солдат. Начните с небольшой деревни и стройте, планируйте и пробивайтесь к могучей империи. Механика глубока и реалистична: крошечные события могут привести к краху королевств.",
"1111460": "Испытайте веселую и очаровательную игру электронной коммерции в волшебном мире, где люди и монстры воюют. Помогите скромной кроличьей фее расширить ее интернет-магазин по продаже домашней моркови. Раскройте скрытые секреты, развивая бизнес и становясь успешным предпринимателем.",
"816090": "Space Hulk: Deathwing - Enhanced Edition разворачиваются во вселенной Warhammer 40,000. Примерив на себя роль космодесантника, вступите в отчаянную схватку с генокрадами. Зарабатывайте навыки и разрушительное оружие, играя в одиночку или совместно с 4 другими игроками.",
"1176470": "Инопланетное вторжение разделило человечество на 7 идеологических фракций с уникальным видением будущего. Возглавьте одну из них, установите контроль над Землей, а затем и всей Солнечной системой, и сражайтесь с вражескими флотами в пошаговых боях.",
"2096600": "В Crysis 2 Remastered вы сможете вновь окунуться в мир легендарного боевика Crysis 2, оптимизированный для современных систем.",
"1071870": "Biped — это динамичная приключенческая 3D-игра с реалистичной физикой для совместного прохождения. В ее основе — взаимодействие двух игроков, которые должны помогать друг другу в точно выбранные моменты.",
"39500": "Вы спасали остров Хоринис от сил зла в Gothic I и Gothic II.",
"273350": "Играйте в Evolve бесплатно! Evolve Stage 2 уже ждет вас! Evolve Stage 2 – бесплатный сетевой шутер нового поколения, где захватывающие бои проходят в режиме «4 против 1». Монстр, которым управляет один из игроков, должен перехитрить команду из четырех охотников с уникальными способностями.",
"677160": "Вам грозит смертельная опасность, и вдруг вы замечаете вдалеке огромное сооружение, которое возвышается среди беспощадной бури. Раскройте тайны мрачного замка, общаясь с напарником в этой кооперативной приключенческой игре.",
"1369670": "Наслаждайтесь реалистичным вождением в открытом мире. Упрощение доставки грузов или вождение автобусов и налогов даст вам достаточно денег для покупки новых автомобилей и запчастей. Вы можете проверить свои навыки вождения на гоночной трассе. Все дело в чистом удовольствии от вождения!",
"913740": "Испытайте тихий ужас этого однобитного любовного письма Дзюндзи Ито и Х.П. Лавкрафт. Путешествуйте по адской реальности рогалика с пошаговыми боями и неумолимым выбором. Поэкспериментируйте со своей колодой карт событий, чтобы открывать новые формы космического ужаса в каждом прохождении. Неизбежное ждет...",
"803330": "Культовая классика возвращается! Терроризируйте землян 1950-х годов в роли злобного пришельца Крипто-137. Извлекайте их ДНК, чтобы свергнуть правительство США – как и положено в боевике про нашествие инопланетян. Аннигилируйте ничтожных хомосапиенсов супероружием и суперспособностями. Палите по городам с летающей тарелки! Давите, жгите, испепеляйте!",
"1857090": "В этом симуляторе средневекового поселения вы возглавите знатный род и столкнетесь с восстаниями, распрями и интригами. Заботьтесь о крестьянах, стройте коварные планы против врагов и ищите утерянное знание павшей империи.",
"1227690": "Стильный и интуитивно понятный шутер от первого лица для одного игрока с динамической системой трюков, уничтожаемым объемным окружением, множеством визуальных эффектов «bullet time», необычной однорукой героиней и мрачным электронным саундтреком.",
"604240": "Shotgun Farmers - многопользовательский онлайн шутер, где ваши пули вырастают в пушки. Быстро собирайте урожай оружия для большего количества боеприпасов или позвольте им расти дальше для большего сбора.",
"2300": "Армия ада вторглась на Землю. Чтобы спасти планету, вы должны уничтожить ещё более опасных демонов, используя самое мощное оружие. Приготовьтесь к напряженным перестрелкам в популярном продолжении революционной игры DOOM (1993).",
"753420": "«Дангрид» — двухмерный сайд-скроллер с элементами rogue-lite. Вы примерите на себя роль искателя приключений, исследующего вечно меняющееся подземелье, чтобы спасти город от разрушения. Уничтожайте врагов, используйте разнообразное оружие и магию, ешьте еду и победите зло в подземелье!",
"436520": "Динамичный шутер от первого лица с высокой свободой настройки. От настройки игрового режима до глубокой настройки оружия и системы крепления до детальной настройки персонажей, хотя он был разработан так, чтобы вы могли выбрать либо высокую производительность, либо графическую точность без высокопроизводительного ПК.",
"491950": "Большой брат уже здесь — теперь это вы. Исследуйте жизни граждан, чтобы найти виновных в серии террористических актов. Информация из интернета, личные сообщения и файлы — у вас есть доступ ко всему. Но будьте осторожны, любая предоставленная информация будет иметь последствия.",
"675260": "В этой последней главе от отмеченной наградами студии, создавшей Batman - The Telltale Series, Брюсу Уэйну и Бэтмену придется сыграть новые опасные роли. Загадочник вернулся, чтобы терроризировать Готэм-сити, но его ужасные загадки лишь предвещают еще больший кризис.",
"1764390": "выберите протагониста и исследуйте множество разнообразных жутких судеб!",
"1307890": "Городской строитель с симулированными гражданами на процедурно сгенерированной карте мира. Развивайте свое королевство на протяжении эпох из крошечной средневековой деревушки в процветающую глобальную империю! Сотрудничайте или соревнуйтесь в режиме реального времени со своими друзьями в многопользовательском режиме.",
"375480": "Используйте волшебное устройство, известное как Хроникон, чтобы путешествовать в души и воспоминания павших героев и заново пережить их великие истории! Вас ждут эпические приключения, полные добычи и монстров!",
"407130": "Ремонтируйте и стройте танки Второй мировой войны. Разбирайте танки полностью, используя различные инструменты. Превратите их из ржавых и разрушенных в полностью рабочие. Проверьте их на тренировочном полигоне, продайте или поставьте в свой собственный музей.",
"594330": "Игра Visage — это психологический триллер от первого лица. Исследуйте таинственный, постоянно изменяющийся особняк в атмосферном игровом мире, где время течет неспешно, а неправдоподобно уютные интерьеры сменяются чудовищно реалистичными сценами, наводящими неподдельный ужас.",
"24790": "2047 год. Огромный ядерный гриб высоко в ночном небе знаменует трагическое начало Третьей тибериевой войны, а вместе с ним и долгожданное возвращение самой революционной серии стратегий в реальном времени.",
"4570": "Полный набор для Warhammer 40,000: Dawn of War в одном издании. Вас ждет культовая стратегия в реальном времени во всем своем кровавом великолепии с 4 дополнительными кампаниями и 9 полностью доступными фракциями.",
"515180": "Окунитесь в повседневную жизнь водителя автобуса в большом открытом городе. Для вас оригинальные лицензионные автобусы автобусы лучших производителей: Mercedes-Benz, Setra, MAN и IVECO. Доставляйте пассажиров безопасно и вовремя в одиночном либо многопользовательском режиме.",
"2683150": "Вас ждет потрясающий микс из жанров: кооперативный симулятор фентезийной таверны от первого лица в открытом мире, экшен, рыбалка, охота, исследование, прохождение веселых и разнообразных квестов. И, конечно, ГОТОВКА! Играйте с друзьями и накормите весь мир!",
"251150": "Эта первая глава продолжающейся саги Trails, провозглашенная одной из крупнейших, самых длинных и тщательно детализированных пошаговых JRPG всех времен, закладывает основу для того, что быстро стало самой популярной и самой продаваемой франшизой разработчика Ys Nihon Falcom за всю их более чем 30-летнюю историю.",
"2916430": "Добро пожаловать в самое хаотичное место в мире! Играйте в одиночку или в кооперативе с 6 игроками. Управляйте рестораном быстрого питания и вместе с друзьями расширяйте свой бизнес. Принимайте заказы, готовьте бургеры и увеличивайте свой доход, общаясь с клиентами.",
"674140": "Ловите загадочных живых вкусняшек и угощайте друзей в этом необычном приключении!",
"595520": "FINAL FANTASY XII: THE ZODIAC AGE — возвращение классики! Встречайте обновленный игровой процесс, полностью адаптированный для ПК.",
"686200": "Спасайте заложников, обезвреживайте бомбы и становитесь настоящими героями в этом олдскульном 2D-экшне с ретро-графикой и атмосферой ностальгии. Включает в себя Сетевой и локальный кооператив.",
"2742830": "Monster Train возвращается с новыми кланами, вражескими фракциями, испытаниями, режимами и многим другим! Защищайте свое Пекло в классической трехуровневой вертикальной игре, благодаря которой первая часть карточного «рогалика» стала хитом.",
"307960": "«Ил-2 Штурмовик: Битва за Сталинград» - это документальная игра, продолжение легендарной серии авиасимуляторов «Ил-2 Штурмовик», более чем на 10 лет ставшей эталоном в жанре и получившей мировое признание.",
"32430": "Игра, которая покажет геймерам самую глубокую и темную сторону Силы в истории, которая приведет их к столкновению с самим Люком Скайуокером.",
"1504500": "Echo of Starsong — приключенческая игра в стиле визуальной новеллы. Эда, девушка, способная слышать таинственные звуковые волны, известные как звездная песня, пересекается с молодым человеком в поисках их источника. Вместе они отправляются в самое сердце космоса, чтобы разгадать древний миф.",
"632300": "Ролевая игра Hobo: Tough Life посвящена выживанию бездомного бродяги в большом городе. В нее можно играть как в одиночку, так и в совместном режиме через Интернет. Изучайте улицы Праслава, добывайте еду и другие припасы, попрошайничайте, воруйте и делайте все возможное, чтобы пережить зиму.",
"897330": "Расслабляющая игра-раскраска по номерам. Наслаждайтесь созданием разнообразных изображений разной тематики, сложности и размера.",
"252530": "Переходим в следующий раунд! Испытайте новый симулятор омнибуса с OMSI 2 и начните открывать для себя Шпандау, управляя омнибусом. OMSI 2 является преемником известного и отмеченного наградами комплексного симулятора «OMSI - The Bus Simulator».",
"255220": "Все дело в командах, соперниках и гонках: вы становитесь наемным гонщиком, специализирующимся на своих любимых дисциплинах, или побеждаете их всех в напряженном мире профессионального автоспорта.",
"459220": "«Halo Wars: расширенное издание» предлагает улучшенную графику и весь загружаемый контент из этой эпохальной игры. Проживите вместе с героями игры масштабную кампанию или сразитесь в сетевых боях, командуя мощными войсками из мира Halo.",
"40950": "Stronghold HD, являясь самым знаменитым замковым симулятором, позволит вам строить и разрушать исторические замки. Начните средневековую войну против ИИ и в онлайне с 8 игроками.",
"1771980": "Добро пожаловать в ФДР. Как наш новый Оператор, вы должны использовать свои навыки, чтобы помогать нашим агентам и расследовать преступления. Используйте передовое программное обеспечение ФДР для поиска улик, решения головоломок и раскрытия истины.",
"2933080": "Crime Boss: Rockay City — кооперативный FPS-шутер про ограбления с увлекательной стелс-механикой и безумными перестрелками. Также доступна соло-роглайк кампания, сочетающая FPS, стратегические элементы и угарнейшую озвучку, которая не раз заставит улыбнуться.",
"384180": "Добро пожаловать в Prominence Poker, карточную игру, в которой игроки со всего мира сражаются друг с другом и с коварным искусственным интеллектом, чтобы заработать репутацию, престиж и банкролл, необходимые для того, чтобы стать лучшими из лучших и победить их.",
"544550": "Stationeers позволяет вам контролировать строительство и управление космической станцией, которой вы можете управлять самостоятельно или онлайн с друзьями. Сложные атмосферные, электрические, производственные, сельскохозяйственные и гравитационные системы всегда требуют вашего внимания и управления!",
"2140330": "Оцените новую версию FieldSENSE™ в Madden NFL 24. Благодаря более реалистичному движению игроков и улучшенному ИИ вы получаете контроль, возможность реализовать свою стратегию игры и уверенность в том, что вы справитесь с любым соперником.",
"4920": "Многопользовательский шутер в быстром темпе, который сталкивает людей против пришельцев в стратегической и футуристической борьбе за выживание!",
"360170": "Живым или мертвым? Пора принимать решение, незнакомец. Нежить в Луизиане не пользуется особым почетом... Выживай в одиночку или с друзьями, пытаясь удовлетворить базовые потребности в еде, воде и укрытии. Создавай собственные инструменты и оружие, защищая свой лагерь от полчищ кровожадных зомби.",
"1288320": "Станьте новым владельцем охотничьего домика в изумительно красивом месте, полном диких зверей. Исследуйте обширный открытый мир и используйте реально существующие образцы охотничьего вооружения. Наслаждайтесь увлекательной охотой в одиночку или с друзьями!",
"3059070": "Кооперативная хоррор-игра, где вы играете за команду из 1-4 журналистов, готовых исследовать Нью-Йорк, захваченный смертоносными существами, чтобы сделать потрясающие снимки. Ваша единственная цель: попасть на первые полосы... и выжить, чтобы их прочитать.",
"519190": "Next Day: Survival - многопользовательский SURVIVAL с элементами RPG в вымышленном постсоветском государстве, выполняйте задания, изучайте навыки и улучшайте своего персонажа, устраивайте перестрелки с противниками и зарабатывайте репутацию.",
"496240": "Onward — самый захватывающий тактический VR-шутер. Присоединяйтесь к своему отряду и примите участие в самых разных режимах соревновательной PvP, совместной PvE и одиночной игры, включая интенсивные многопользовательские сражения или совместные миссии для 4 игроков. Реалистичное вооружение и боевая механика доведут ваши навыки выживания и боя до предела.",
"616560": "Вот песочница, не похожая ни на одну другую. Создавайте масштабные сражения без каких-либо ограничений. Хотите увидеть, как 10 000 цыплят сражаются с армией римлян?? Конечно, почему бы и нет. Хотите увидеть, как рота американских солдат времен Второй мировой войны сражается с 11 000 средневековых солдат?? В UEBS просто нет пределов кровавой бойне, которую вы можете устроить.",
"2320": "Вы — последняя надежда человечества в борьбе со строггами, враждебной инопланетной расой, которая объявила войну Земле. Вас ждёт улучшенная версия знаменитого шутера. В комплекте: новая кампания, Quake II 64, поддержка игры по сети и совместного прохождения… и не только.",
"1475380": "TheDawn — это игра-стрелялка от третьего лица о путешествии Майи, сверхспособности, способной управлять временем, и Макса, хакера, который ей помогает. Смогут ли они спасти человечество и встретить новый рассвет?",
"652980": "Игра о бесконечной проблеме с загрузочными экранами. Мы все сталкивались с этим, играя в игры, скачивая что-то, устанавливая операционную систему и т. д. И теперь вы можете испытать это еще раз в Loading Screen Simulator: Steam edition.",
"48220": "Heroes VI — это стремительная эпическая история, в которой Ангелы собираются завершить — раз и навсегда — войну со своими древними врагами, Безликими.",
"17080": "В это издание входят DLC с оружием из десяти предыдущих расширений, а также новый контент.",
"2135150": "Преемник ролевой игры-рогалика «Элона». Приключения, выживание, ремесло, строительство домов, передаваемые мифы и истории о людях и Элее. Какие шрамы ты оставишь на земле Илвы?",
"202750": "Новая, интригующая история, толпы ужасающих врагов, мощное вооружение и красивые виды Аризоны, приправленные веселым, но бросающим вызов, новым игровым режимом!",
"532110": "Испытайте на себе начало и конец жизненного пути персонажей, создайте собственное родословное древо! Rusty Lake: Roots - вторая превосходная игра жанра point-and-click adventure от создателей серии Cube Escape и Rusty Lake Hotel.",
"1328840": "Отправляйтесь в путешествие с братом и сестрой, которые заблудились на просторах собственного воображения. Теперь Тото и Гел должны держаться вместе и решать головоломки, чтобы вернуться домой. Приключенческая игра с головоломками погрузит вас в атмосферу мультфильма!",
"1003590": "Tetris® Effect: Connected — это такой Tetris, какой вам еще не доводилось видеть, слышать или чувствовать: невероятно затягивающая, уникальная и потрясающе красивая реинтерпретация одной из самых популярных игр-головоломок в истории.",
"331600": "Оригинальная история ONE PIECE: от деревни Фуся до таинственного королевства Дресс Роза. Хватит ли вам решимости одолеть самых опасных пиратов, в том числе и самого Дофламинго?",
"719890": "Играйте за динозавра и станьте частью экосистемы, созданной игроками! Beasts of Bermuda — многопользовательская игра, в которой игроки преодолевают разрушительные шторма и сражаются с опасными противниками на пути к достижению гигантских размеров. Сможете ли вы выжить в Бермудском треугольнике?",
"1249800": "Xuan-Yuan Sword VII — это ARPG от третьего лица, сюжет которой уходит корнями в китайскую историю и мифологию. Игрокам предстоит выступить в роли Тайши Чжао, спокойного и надежного мечника с трагической судьбой.",
"352720": "Проведите цивилизацию от каменного века до космической эры в градостроительном симуляторе бога. Управляйте ресурсами, исследуйте технологии, переживайте стихийные бедствия и угрозы пришельцев, защищайте или карайте свои творения божественными силами и колонизируйте далёкие планеты.",
"268420": "Aura Kingdom — это бесплатная аниме-MMORPG с сильными элементами PVE, уникально детализированным миром и захватывающим, хорошо продуманным сюжетом. Aura Kingdom дает игрокам возможность стать посланниками Гайи, одаренными личностями, которые берут на себя роль одного из пятнадцати классов.",
"900270": "Единственное нелинейное приключение со 100 разными концовками. Не просто вносите меня в список желаний. Я не такой уж и дорогой... и посмотрите на эти отзывы!",
"298610": "Приключения ждут тебя и твоих друзей в мире Ylands! Собирай ресурсы, создавай инструменты, строй всё подряд и исследуй земли! Построй корабль и отправляйся в плавание, где тебя ждут мифические животные, различные морские обитатели, всевозможные враги и многое другое!",
"868360": "Станьте выдающимся врачом, амбициозным архитектором и успешным менеджером одновременно. Спроектируйте собственную больницу, настроив все мелочи или использовав один из предустановленных вариантов, чтобы сразу приступить к лечению больных.",
"2060130": "«Возвращение на Остров Обезьян» — неожиданное и невероятное возвращение создателя серии Рона Гилберта, продолжающее историю легендарных приключенческих игр.",
"1021950": "«Когда наступает тьма» — это симулятор ходьбы, чья запутанная и мрачная история пытается проиллюстрировать тяготы депрессии и тревоги с помощью множества воображаемых цифровых пейзажей.",
"593280": "Cat Quest - замуррчательная РПГ, чье действие происходит в мире, населенном котиками! Отправляйтесь в пуррртешествие по Фелингарду, чтобы найти похищенную сестру. Исследуйте огромный мир, полный пурриключений и заводите новых друзей!",
"462770": "Pyre — это отрядная ролевая игра от создателей Bastion и Transistor. Приведите отряд изгнанников к победе, одержав победу в древних состязаниях режима кампании, или вызовите друга на динамичный ритуальный поединок в режиме противостояния.",
"368370": "Полиция семь раз допрашивала женщину. Выполните поиск в базе данных видео и изучите сотни подлинных клипов, чтобы узнать ее историю в этой новаторской и отмеченной наградами повествовательной игре.",
"690530": "Soul at Stake — хоррор-игра на выживание 1 на 4 в восточной тематике. Когда-то существовал заманчивый городской миф, гласивший, что если кто-то выиграет игру, он получит бесчисленные деньги, и его/ее судьба мгновенно изменится и в одночасье станет самым могущественным. Всем участникам нужна только одна ставка — их души.",
"1343240": "Thymesia — это жестокий и динамичный ролевой экшн с тщательно продуманной системой болезнетворного оружия. В роли таинственного Корвуса вам предстоит выживать в королевстве, где свирепствует смерть. Выслеживайте врагов, овладейте силой чумы и докопайтесь до правды в своих собственных воспоминаниях.",
"1578650": "Вы – беглый рабочий на нелегальной космической станции. Исследуйте ее, заводите друзей, разбирайтесь с собственным прошлым и стройте будущее в новой ролевой игре в жанре TTRPG. На обломках межпланетного капитализма напишут наши имена!",
"1301210": "Создайте свою команду и выясняйте отношения с другими игроками в Knockout City™, сражаясь в поистине ЭПИЧЕСКИХ МНОГОПОЛЬЗОВАТЕЛЬСКИХ МАТЧАХ В ВЫШИБАЛЫ. Бросайте, ловите, пасуйте, уклоняйтесь и перехватывайте без остановки, чтобы стать непобедимым чемпионом вышибал!",
"40100": "Включает 47 достижений Steam, доски почета и статистику!",
"398710": "Станьте лесорубом, рубите дрова и избегайте веток. Почти 30 миллионов игроков не могли ошибаться: игра признана одной из лучших казуальных игр.",
"933820": "Endzone - это градостроительный симулятор о возрождении цивилизации после экологической катастрофы. Дайте дом своим согражданам и помогите им выжить на руинах старого мира, несмотря на радиацию, ядовитые дожди, песчаные бури и засухи.",
"2111190": "MULLET MADJACK — это динамичный шутер от первого лица для одного игрока, который перенесет вас прямо в КЛАССИЧЕСКОЕ АНИМЕ. АРКАДНАЯ игра с некоторыми НЕБОЛЬШИМИ элементами roguelite. Выберите любимое оружие и доберитесь до последнего этажа; побейте свое лучшее время или попробуйте еще раз.",
"937170": "«Приключения Отаку» — это другой вид AVG. История рассказывает об отаку, который много лет был одинок и жаждет любви. Нечаянно отправляясь в фантастическое путешествие, он в конце концов завоевывает любовь девушек. Игра сочетает в себе повествование с альтернативным ТАКАГИЗМом и мини-играми.",
"226860": "Постройте цивилизацию на века в самой большой космической стратегии в истории! Выберите одну из десятка уникальных рас и заявите о себе с помощью дипломатии, шпионажа, технологий и других возможностей.",
"214420": "Почувствуйте адреналин, управляя своим уникальным танком в многопользовательской аркадной игре! Создайте свою лучшую военную машину, используя более миллиона различных комбинаций. Итак, что вы выберете: грохочущие гусеницы или ползущие паучьи лапки?",
"1104450": "БОМБЕРГРАУНДЫ: погрузитесь в бесплатную многопользовательскую и насыщенную событиями арену, вдохновленную классическими играми о бомбардировщиках. Мчитесь, бомбите, бейте и взрывайте на пути к победе. Ваш мир безжалостных аркадных действий находится на расстоянии одного клика — погрузитесь в него и управляйте территорией!",
"205950": "Рисуйте, катайтесь и слушайте музыку в хите для SEGA – игре Jet Set Radio!",
"312670": "Ведьма-царица Сетеки вновь вернулась с того света и лишь один отряд отважных героев сможет остановить ее страшную армию мумий: Странная Бригада!",
"468920": "Устали ждать клева? Хотите порыбачить? Вам повезло - в Ultimate Fishing Simulator рыба клюет без остановки! Спиннинги, поплавки, прикормка и многое другое!",
"321360": "Охотьтесь на людей, убивайте динозавров. Выберите свою сторону в хаотическом доисторическом PvP... новое обновление: больше динозавров, больше оружия, новая игровая механика, расширенные знания и многое другое! Думайте быстро, иначе вы вымерли.",
"598700": "Проведите странствующую наёмницу по имени Вивиан по нелёгкому пути от тихой деревушки у берега через таинственные леса, замки с привидениями и разрушенные места боевой славы. Что сможет её утешить, когда бесчисленные орды врагов обратятся в прах?",
"360940": "Примите участие в величайшей битве в истории: Зелёные против Бежевых. Сражайтесь онлайн вместе с другими игроками и против них. Прыгайте, стреляйте и катитесь к победе в динамичном игровом процессе, построенном на выполнении задач. Порой величайшие битвы ведут самые маленькие солдаты. The Mean Greens — сетевой многопользовательский шутер от третьего лица, в котором вы играете за игрушечных солдатиков.",
"587620": "Вас ждет бесспорный шедевр, основанный на знаменитой технике рисования тушью суми-э и представленный в потрясающем высоком разрешении.",
"366090": "Colony Survival — уникальная стратегия от первого лица от дуэта разработчиков. Стройте колонию в воксельном мире. Управляйте стражниками, фермерами, шахтерами и другими колонистами. А по ночам защищайте поселение от полчищ монстров!",
"376870": "В этой игре, состоящей из пяти частей, вы будете играть \"Jesse\" и отправитесь в опасное приключение через Рай, через Nether, к самому краю мира и за его пределы. Вы и ваши друзья служите легендарному Ордену Камня: Воин, Инженер Redstone, Беспредельщик и Архитектор; убийцы дракона Ender.",
"1173770": "Оригинальная FINAL FANTASY возвращается с новой графикой и звуком в пиксельном 2D-переиздании! Переработанное 2D-издание первой игры знаменитой серии FINAL FANTASY! Нестареющая история, дополненная чарующей графикой в стиле ретро.",
"1624540": "Storyteller – удостоенная наград головоломка о том, как сочинять сказки. Вам дают название, условия и персонажей, а вы придумываете из них свою историю. Впереди сюжеты о любви и предательстве, об интригах, преступлениях и чудовищах – и о многом другом!",
"1179080": "То, что вы собираетесь сделать, не одобрено Ватиканом.",
"1593030": "Terra Nil — это глубокая экологическая стратегия, в которой вам предстоит вдохнуть новую жизнь в бесплодную пустошь. Очищайте почву и океаны, сажайте деревья и возрождайте фауну, чтобы преобразить безжизненный мир, а затем покинуть его, не оставив ни единого следа своего присутствия.",
"327410": "Экспериментальный короткометражный фильм от создателя фильма «На Луну и в поисках рая»: простой и сюрреалистичный часовой интерактивный мультфильм о мальчике и раненой птице, рассказанный без диалогов. Если вы ищете опыт, похожий на To the Moon, я бы посоветовал сначала сыграть в Finding Paradise.",
"209080": "Соберите свою команду и поднимитесь в небо в лучшей PvP-боевой игре на дирижаблях. В Guns of Icarus Online вам предстоит управлять огромными дирижаблями, стрелять из больших турелей и работать в команде ради господства в небе. Все как один, победа или смерть, вместе.",
"1272160": "Хардкорная нарративная ролевая игра о мире, которым правят реальные, но жестокие боги. Пройди путь от рождения до смерти, где каждый выбор имеет свою цену и ведет к необратимым последствиям. Станешь ли ты инквизитором, судьей или бунтарем? Выбор за тобой!",
"1810580": "Nobody – The Turnaround – реалистичный симулятор выживания в параллельном мире, отражающем наше общество. Управляйте своим временем и ресурсами с умом, преодолевайте трудные времена и ищите выход из ситуации, в которой оказались.",
"57690": "...включает эксклюзивный остров (Исла Нублар), костюм для Эль Президенте (Истребитель), и 50 достижений Steam. Эль Президенте вернулся, чтобы править всем!",
"1682970": "FPV-Новичок или АЗМ-Профи, учись с нуля или прокачивай свои навыки в Uncrashed - новом ультра реалистичном FPV симуляторе. Благодаря простым настройкам перенесите свой настоящий дрон в Uncrashed и тренируйтесь в реальности!",
"1641960": "Игра на выживание от первого лица, действие которой происходит на Земле после экологической катастрофы. Играйте в одиночку или с 3 друзьями, постройте свой дирижабль, собирайте ресурсы и ищите лекарство, которое поможет спасти человечество.",
"1911390": "Два рыцаря, крепкая связь и долгое путешествие. Примите участие в гонке за розой, скачите из города в город и укройтесь до наступления темноты любыми необходимыми способами! Если ваша связь сильна и ваша лошадь хорошо дрейфует, вы можете стать получателем легендарной розы. К счастью, вы взяли с собой оружие!",
"1811990": "Сразись со стихией в Wildfrost, тактическом ролевом конструкторе колод! Путешествуй по замерзшей тундре и собирай сильные карты, чтобы изгнать вечную зиму...",
"489630": "Warhammer 40,000: Gladius – Relics of War перенесёт вас в мир ужаса и жестокости. Четыре фракции схлестнутся в кровопролитной войне за ресурсы планеты в первой пошаговой 4X-стратегии по вселенной Warhammer 40,000.",
"22350": "Вам решать, какую роль вы хотите сыграть в битве за мир Brink, сражаясь за спасение себя и всего человечества!",
"768200": "Большое приключение в крошечном масштабе! Оказавшись в самом низу пищевой цепочки, нужно готовиться ко всему. Создавайте оружие и броню, седлайте невиданных зверей, стройте базы и исследуйте причудливые земли.",
"15620": "Полный набор для Warhammer 40,000: Dawn of War II в одном издании. Сыграйте в удостоившуюся наград стратегию во всем ее великолепии. В издание входят 3 кампании, 6 фракций для сетевой игры и режим «Last Stand» для совместной игры с 8 героями.",
"1000360": "Реалистичная 3D-игра о боях на мечах, основанная на физике. Погрузитесь в кинематографическое приключение, используя настоящие боевые искусства боя на мечах и разнообразное исторически достоверное оружие, чтобы выжить в жестоких дуэлях в Польше 17 века. Доступны однопользовательские режимы и ЛОКАЛЬНЫЙ режим для двух игроков.",
"973230": "Сражайтесь на аренах и пройдите путь от жалкого раба до чемпиона! Завоюйте свободу – или умрите, пытаясь. В этой гладиаторской роглайт-RPG вас ждут продуманная система построения карьеры и уникальная по реализму физика боя. Идущие на смерть, я приветствую вас!",
"2144740": "Кровь прольется в Ghostrunner 2 — хардкорном слэшере от первого лица, действие которого происходит в киберпанковом мире. Станьте совершенным киберниндзя и приготовьтесь к схваткам с боссами, интерактивной истории, новым режимам и синтвейв-саундтреку.",
"427100": "Fernbus Coach Simulator - первый симулятор, позволяющий присоединиться к популярным междугородним перевозкам. Благодаря сотрудничеству с компанией FlixBus, Fernbus Coach simulator передает мир пассажирских перевозок по немецким автобанам и мелким дорогах в мельчайших подробностях.",
"665360": "Хватит ли у вас таланта противостоять другим комикам в комедийном шоу в прямом эфире? Проверьте свой репертуар на прочность перед лицом безжалостных зрителей, которые могут в любой момент прогнать вас со сцены, а также беспощадных словесных выпадов со стороны других исполнителей.",
"298240": "Разрушайте, разбивайте и взрывайте на пути к победе! Используйте современное оружие и транспортные средства, чтобы доминировать на поле боя.",
"897450": "В The Survivalists, приключенческой игре-песочнице во вселенной The Escapists, вас ждет целый мир — живой, открытый, полный сюрпризов, опасностей и тайн. Исследуйте, создавайте предметы, стройте дома, обучайте обезьян и сражайтесь за свою жизнь вместе с тремя друзьями. Хватит ли у вас смелости?",
"537180": "DMO — это MMO, основанная на неизменно популярной франшизе Digimon. Эта долгожданная игра будет включать в себя более глубокий опыт ролевой игры, улучшенную графику и захватывающие адреналиновые бои в реальном времени. Как новые, так и давние поклонники дигимонов теперь могут погрузиться в это новое эпическое приключение со своими собственными дигимонами.",
"589360": "Помогите юному королю Эвану пережить изгнание, основать свое государство и найти новых друзей, чтобы вместе с ними объединить мир и спасти свой народ от ужасного врага.",
"1497440": "COCOON – новая игра от Йеппе Карлсена, ведущего гейм-дизайнера LIMBO и INSIDE. Это путешествие по мирам внутри других миров. Овладейте механикой прыжков по мирам, решайте изящные головоломки и разгадайте космическую тайну.",
"297130": "Между нашим миром и миром за его пределами лежат Души Титанов, духовный источник всего живого. Разбросанный среди руин и охраняемый праздными титанами, которым поручена их забота, одинокий герой, вооруженный единственной стрелой, собирает осколки Души Титана в поисках истины и силы.",
"1056600": "Home Sweet Home возвращается со своим волнующим душу продолжением, которое будет преследовать вас до смерти! Погрузитесь в мир тайских мифов, давайте вместе бороться, чтобы выбраться из этого ужасающего мира. Игра 4 на 1, которая подарит вам опыт охоты и охоты в одной игре.",
"597760": "Присоединитесь к Брайану Пастернаку в его первый рабочий день в одной из самых больших компаний в мире, Синтракорп. Есть ли у неуверенного, неподготовленного и абсолютно неквалифицированного Пастернака то, что поможет ему найти свое место в иерархии Синтракорп? Все зависит от того, как он справится со своим первым заданием... и выживет ли он.",
"919640": "Стальная дивизия II – это стратегия в реальном времени по ВМВ, проходящая на Восточном фронте. Она включает пошаговое командование армией в масштабе 1:1 и тактические сражения в реальном времени, где под вашим началом будут тысячи бойцов.",
"9010": "В мире бушует Вторая мировая война, государства рушатся одно за другим. Чтобы окончательно разгромить союзников, нацисты решили использовать жуткое сочетание оккультных наук и передовых технологий. Вы — рейнджер армии США Уильям «Би-Джей» Бласковиц. Пронзите черное сердце Третьего Рейха и остановите врага — любой ценой.",
"1148590": "Играйте в улучшенное издание оригинальной игры, выпущенной в 1997 году для Nintendo 64. Прошло несколько лет с тех пор, как вы остановили вторжение демонов на Землю. Научный комплекс ОАК на Марсе был опечатан на карантин, и про него забыли… до сегодняшнего дня.",
"248610": "Door Kickers - инновационная стратегия в реальном времени, ставящая Вас во главу отряда спецназа в ходе тактического вторжения.",
"218680": "Удостоенный множества наград бестселлер приходит на домашние компьютеры в формате HD.",
"1088150": "Scribble It! - это многопользовательская игра, в которой нужно рисовать и отгадывать слова. До 16 игроков могут играть в лобби, выбирать из тысяч официальных слов и тематик высокого качества в 3 режимах игры. Идеально подходит для игровых вечеров, вечеринок или просто посиделок с друзьями.",
"617830": "Забудь о реальном мире. Погрузись в игру душой и телом. Испытай себя в неповторимом, элегантно жестоком мире SUPERHOT VR. Враги лезут в комнату со всех сторон, десятки пуль рассекают воздух... Стоп. Что-то тут не так...",
"490110": "Город Аверно, 1983 год. На улицах хозяйничают банды, а ваш отец оказался в могиле. Наведите порядок в городе и выясните правду. Вас ждет неоново-нуарная полицейская песочница с захватывающими погонями на автомобилях и разрушаемым окружением.",
"70000": "Только что обновлено! Теперь вы сможете сыграть за Тиранозавра Рекса, два новых классов динозавров и опробовать новую карту Гела!",
"520440": "Потрясающая 3D-анимация клеток и огромный объем контента — файтинг нового поколения «GUILTY GEAR Xrd REV 2» теперь доступен в Steam! Всего 25 уникальных персонажей и множество игровых режимов. Приготовьтесь ЗАМЕЧАТЬ!",
"1016120": "Играйте против профессионалов. Играйте со своей командой. В PGA TOUR 2K21 вы можете играть по правилам или создать свои собственные, включив новый режим карьеры PGA TOUR, лицензионные курсы и многое другое! При поддержке гольф-клуба.",
"266510": "Hand of Fate, или \"Рука судьбы\" - это новая жизнь карточных игр. В каждой игре вас ждут новые серии заданий. Выигрывайте новые карты, собирайте себе колоду и попробуйте сыграть против нее! Вытягивайте карты по одной и узнайте свою судьбу.",
"206480": "Окунитесь в мир опасностей и приключений с Dungeons & Dragons Online®, основанным на любимой ролевой игре, с которой все началось.",
"17430": "Вы никогда не думали, что все обернется таким образом. Тотальная погоня, в которой на вас охотятся. И охотник. Теперь вам придется сесть за руль и рискнуть всем, чтобы проникнуть в безжалостный международный преступный синдикат и уничтожить его.",
"449960": "Book of Demons это гибрид Hack & slash и карточной игры, в котором ТЫ опредяеляешь длительность игры. Возьми в руки магические карты вместо обычного оружия и уничтожай армии тьмы в подземельях под Старым Собором. Спаси охваченную ужасом Бумажную Вселенную из когтей самого Архидемона.",
"1996010": "На дворе 1990-й. Прошло два года с тех пор, как Эдвард Кроу загадочно исчез, а его парк развлечений «Страна Ворон» внезапно закрылся. Но ваше появление, Мара Форест, нарушило сложившуюся тишину. Если вам нужны ответы, за ними придётся отправиться в тёмные глубины «Страны Ворон»...",
"286570": "Станьте чемпионом F1 2015. Новый движок и система «ТВ-трансляции» позволят вам оказаться в самом сердце гонки.",
"252330": "Слендермен возвращается еще более устрашающим, чем когда-либо. Вы сами по себе. Никто не сможет вам помочь. Никто не услышит, как ты кричишь. Переживите этот ужас заново с помощью ультрасовременной графики обновления, посвященного 10-летию, и испытайте ужас выживания во всей его красе.",
"747610": "Zula — это интенсивный бесплатный шутер от первого лица, в котором вы можете играть вместе со своими товарищами по команде, чтобы свергнуть вражескую сторону. Вы можете наслаждаться новым контентом еженедельно и получать подарки каждый день. Разнообразие карт и оружия из реального мира, позволяющее погрузиться на 100%.",
"999220": "Новое погружение во тьму от создателей культовой серии Amnesia. Преодолевая отчаяние и безысходность, вам предстоит проверить на прочность человеческую способность выносить страдания. Для тех, кто хочет познакомиться с сюжетом и погрузиться в историю без элементов ужаса, доступен режим приключения.",
"253430": "CastleMiner Z — это бесконечный мир, наполненный глубокими местами, которые нужно исследовать, и ужасающими монстрами, которых нужно убить. Стройте конструкции из блоков, создавайте оружие и инструменты из сырья и исследуйте огромный и пугающий мир вокруг вас.",
"625340": "Динамичный шутер на выживание с открытым миром, где PvPvE-сражения проходят против наёмников и смертоносных XOIDS. Добывайте ресурсы в одиночку или с союзниками, стройте и защищайте базу, прячьте снаряжение и выживайте. Вы охотник и добыча одновременно, а роботы никогда не спят…",
"491540": "Перевозите пассажиров в городском автобусном симуляторе The Bus по маршрутам 1:1 в Берлине, мимо Колонны Победы, Бранденбургских ворот и Alexanderplatz. В Scania Citywide LF и других лицензированных автобусах продавайте билеты, справляйтесь с трафиком и доставляйте всех безопасно.",
"367580": "Hook — минималистичная расслабляющая головоломка: снимите с поля все крючки, один за другим, без спешки, очков и таймеров.",
"352400": "Вас ждут захватывающие приключения в мире юрского периода вместе с игрой LEGO® Jurassic World™, которая впервые позволяет игрокам пережить историю всех четырех фильмов.",
"2366980": "Thank Goodness You're Here! — это абсурдная комедия, происходящая в сюрреалистическом городке Барнсворт в Северной Англии. В роли чудаковатого коммивояжера помогите местным жителям, жаждущим обрушить на вас ворох весьма странных поручений...",
"217200": "Бесстрашные беспозвоночные бандиты возвращаются в любимой поклонниками классике Worms™ Armageddon. Вспомните деньки былой славы — прорывайтесь на территорию врага, зачищайте его позиции и сделайте так, чтобы последний уцелевший червяк был вашим.",
"1229240": "Хватайте меч, концентрируйте свои волшебные силы или вооружайтесь боевыми механизмами. Chained Echoes — это RPG с графикой в 16-битном стиле в удивительном мире, где можно встретить и драконов, и управляемые боевые машины.",
"1546970": "Grand Theft Auto III. Все начинается в Либерти-Сити. Grand Theft Auto III позволяет идти куда угодно и делать все, что вам захочется. Безжалостный криминальный мир станет вашим, если у вас хватит смелости его покорить.",
"584980": "Late Shift - криминальный FMV-триллер с невероятно высокими ставками. Вы окажетесь в эпицентре лондонского ограбления и выберете своё приключение в интерактивном кинофильме с меняющейся историей, ведущей к одной из семи концовок. Ваши решения определяют вас.",
"351290": "\"Человек человеку - волк\". Хотите выжить? - Вооружайтесь и выживайте. Крафтинг, перестрелки, транспорт и многое другое ждет тебя в игре Survival. А что случилось с миром вокруг и почему он погиб - вы возможно узнаете. Но это ли сейчас главный вопрос?",
"951440": "Шутер в открытом мире, где нужно выживать и строить базу (ну... вместо базы будет огромный бур). Играйте в одиночку или с друзьями: исследуйте остров, где извергается жуткий вулкан, улучшайте бур и сражайтесь с роботами. И однажды вы узнаете, какую тайну скрывает толща скал.",
"4580": "Глубоко под центральной пустыней Кронуса, в обширных сотах туннелей и погребальных камер пробуждается раса Некронов. Много эонов тому назад это были бульвары и площади великого некрополя. Он был построен для погребения останков рас, павших под натиском Некронов. Наконец, и сами Некроны ушли навечно в этот город. За прошедшие миллионы лет песок и камень погребли их, но неудачные раскопки вновь пробудили бессмертных. Играйте за любую из семи рас, стремящихся к власти над Кронусом. Захватывайте крепости других рас в жарких боях на разнообразных картах, индивидуальных для каждой крепости.",
"916840": "Выживание среди ходячих мертвецов в затопленном Новом Орлеане.",
"674500": "ДЛЯ КОМАНДИРОВ ПО ЗВАНИЮ, НО СОЛДАТ В ДУШЕ. Выбирайте сторону, размещайте армию и управляйте ей в крупнейших битвах Второй мировой с честным расчетом «физики». Огромное число отрядов, которые понимают, что такое тактика, помогут разгромить врага.",
"1942660": "WWE 2K23 стала Еще Сильнее благодаря расширенным возможностям, великолепной графике и обширному списку суперзвезд и легенд WWE. Режим 2K Showcase возвращается в виде интерактивного спортивного документального фильма, посвященного 20-летней карьере Джона Сины, и WarGames наконец-то тоже здесь!",
"435400": "Ищите спрятанных человечков в интерактивных областях, нарисованных от руки. Залезайте в палатки, дразните крокодилов, пробирайтесь через кусты, и делайте многое другое! А-р-р-р-р-р-р-р-р-р!!!!!",
"313690": "Крестоносец в плаще объединяет силы с супергероями из комиксов по вселенной DC и улетает в космос, чтобы помешать злобному Брейниаку уничтожить Землю.",
"1293160": "Исследуйте миры живых и мертвых в этом психологическом хорроре от третьего лица. В роли медиума отправляйтесь в заброшенный отель, раскройте его жуткие тайны, столкнитесь с голосами из прошлого и узнайте, какую цену платят те, кто видит больше одной правды.",
"1150760": "Gloomwood — это приключенческая игра от первого лица, вдохновленная иммерсивными симуляторами и классическими играми жанра survival horror конца 90-х — начала 2000-х годов.",
"213330": "Легенды объединяются! К динамичному дуэту Бэтмена и Робина присоединяются знаменитые супергерои, такие как Супермен, Чудо-Женщина, Зеленый Фонарь, а значит, отъявленным злодеям Джокеру и Лексу Лютеру, задумавшим разрушить Готэм, несдобровать.",
"647830": "ВРЕМЯ наконец настало! Вместе с любимыми супергероями и суперзлодеями сразитесь с путешествующим во времени Кангом Завоевателем в этой новой оригинальной приключенческой игре — LEGO® Marvel Super Heroes 2!",
"578330": "Присоединяйтесь к Чейзу! В игре LEGO® CITY Undercover вы примерите на себя роль Чейза Маккейна — офицера полиции, которому поручена операция под прикрытием по поиску преступника Рекса Фьюри.",
"342180": "Разработанная исключительно для виртуальной реальности, игра \"Солнечная Аризона\" погружает вас в самый эпицентр зомби-апокалипсиса. Реалистичные движения при обращении с оружием, открытый для исследования постапокалиптический мир, возможность испытать свои навыки выживания в виртуальной реальности.",
"21100": "В F.E.A.R. 3 вы найдете все качества, присущие серии F.E.A.R.: ужасающие паранормальные события, жаркие битвы и драматичный сюжет.",
"578620": "Гладиаторские бои в VR с комичной физикой и литрами крови.",
"619150": "Вы программист. Ваш кот — программист получше. Решайте визуальные головоломки на реальных идеях машинного обучения — от деревьев решений до нейросетей — и соберите переводчик с кошачьего. Берите заказы, прокачивайте железо и стартапы, наряжайте кота. Кодить не нужно.",
"1194630": "4 студента и профессор застряли в заброшенном городе Литтл Хоуп и пытаются скрыться от демонов, которые неустанно преследуют их в непроходимом тумане.",
"2751000": "Отправьтесь навстречу приключениям в захватывающем платформере, действие которого разворачивается в мифологическом мире Персии.",
"1373960": "Играйте в игру от третьего лица, события которой разворачиваются в альтернативной России конца XIX в. Здесь религия сталкивается с жестокой реальностью. INDIKA повествует о монахине, которая отправилась на поиски себя, заручившись поддержкой самого дьявола.",
"1070330": "Самый реалистичный симулятор жизни русского человека. Накапливай пенсию с рождения, собирай бутылки чтобы выжить и стань частью увлекательнейшей истории длиною в жизнь.",
"2446550": "Эта классическая серия STAR WARS: Battlefront доступна для игры на онлайн и офлайн.",
"236690": "Blood Bowl 2 со всей силой сталкивает Warhammer и американский футбол — и на выходе получается взрывной коктейль из пошаговой стратегии, чёрного юмора и беспощадной жестокости, адаптированный по мотивам знаменитой настольной игры Games Workshop.",
"1013320": "Ваши герои никогда не прекращают сражаться. Соберите непобедимую команду в бесплатной фэнтезийной idle RPG с AFK-прогрессом. Собирайте героев и мощное снаряжение, совершенствуйте формации, побеждайте эпических боссов и возвращайтесь за большими наградами и бесконечным инкрементальным развитием.",
"1701520": "Afterimage — это двумерный приключенческий боевик с динамичными сражениями, настройками персонажа, нелинейными уровнями и увлекательным сюжетом, разворачивающимся на руинах вымышленного мира.",
"1651560": "Fabledom — это спокойный градостроительный симулятор в сказочном мире. Наблюдайте за тем, как развивается ваше поселение, взаимодействуйте с соседями и защищайте свое королевство от волшебных существ. И все ради того, чтобы найти свою истинную любовь и жить вместе долго и счастливо!",
"2291850": "Underground Blossom — новое приключение от Rusty Lake. Выполняйте разные задачи на каждой остановке, чтобы отыскать поезд, который провезет вас через каждое важное событие жизни Лоры Вандербум.",
"450390": "Добро пожаловать в The Lab — сборник VR-экспериментов Valve, действие которых происходит в карманной вселенной внутри Aperture Science. Почините робота, защитите замок, приручите механического пса и не только — причём бесплатно!",
"70300": "На помощь! Всех телепортировало куда попало! Капитан Виридиан, именно Вам предстоит взять на себя героическую роль, найти своих друзей, вернуть их целыми и невредимыми и спасти вселенную!",
"258970": "Встречайте полностью обновленную версию классической многопользовательской кооперативной игры Gauntlet! Вы можете играть с друзьями в кооперативном режиме через Интернет или локальную сеть. Покорите тьму этим летом на ПК и Steam!",
"2703850": "В одиночку или с друзьями исследуйте масштабные карты, созданные специально для паркура. Находите скрытые участки и проходите испытания — на время, трюковые задачи или другое. Во многопользовательском режиме вас ждут такие форматы: «МЕТКИ», «Захват флага», «Битвы трюков», и т. д.",
"684410": "Посетите Центр развития Лаборатории исследования природы порталов и познакомьтесь с Bridge Constructor Portal — уникальным гибридом классических игр Portal™ и Bridge Constructor™.",
"1623940": "Bramble — это приключение, действие которого происходит в мире, основанном на мрачных скандинавских сказках. Исследуйте прекрасные, но опасные земли Bramble, пытаясь спасти сестру. Путешествуйте по чудесной местности и боритесь за свою жизнь в смертельных столкновениях со множеством жутких существ.",
"1702010": "Sengoku Dynasty перенесет вас в феодальную Японию. Стройте деревни, развивайте общину и меняйте открытый мир клинком или монетой. Укреплять власть или отдыхать в горячем источнике — решать лишь вам... или вместе с друзьями, ведь играть можно даже вчетвером!",
"3061810": "Разделите захватывающее приключение бывшего якудзы, а ныне пиратского капитана. Присоединитесь к его команде, которая участвует в захватывающих боях на суше и на море в поисках потерянных воспоминаний и легендарного сокровища.",
"1249970": "TDUSC — это не просто гоночная игра с открытым миром. Это образ жизни и платформа для общения. Посетите детально воссозданный остров Гонконг. Садитесь за руль потрясающего автомобиля, выезжайте на дорогу и живите роскошной жизнью своей мечты.",
"1092660": "Сюжетный психологический хоррор от первого лица, в основу которого легла классика жанра — «Ведьма из Блэр». Исследуйте жуткий лес Блэк-Хиллз в этом леденящем душу расследовании и столкнитесь с силами зла, что притаились глубоко в чаще.",
"369990": "Окунитесь в микроскопический мир больших взяток и огромных амбиций стимпанковского города-механизма, где гремлины борются за власть, престиж и богатство! Одиночный и сетевой режимы. Командная игра и режим зрителя. Регулярные турниры (с призами).",
"2663530": "Симулятор ходьбы. Исследуй, любуйся и слушай. Странный. Расслабляющий. Тревожный. Гипнотический. Погружающий. Здесь нет монстров, преследующих или выпрыгивающих на экран, но атмосфера может быть гнетущей и пробуждать страх заблудиться, темноты и тесных пространств. Вдохновлено backrooms.",
"1699480": "Вы, другие заключённые (до 6 игроков) и лифт, несущийся в бесконечную глубь этажей. Сумеете ли вы добраться до самого сердца Гигахрущёвки, не дав этой ржавой посудине сожрать вас?",
"1588010": "Покажите стиль на поле для гольфа в PGA TOUR 2K23. Включает доступные для игры мужские и женские профи, в том числе, Tiger Woods, новые лицензированные поля, больше функций управления, оригинальный PGA TOUR MyCAREER, Course Designer, новые архетипы и навыки игрока MyPLAYER! PGA TOUR 2K23. Больше гольфа. Больше игры.",
"250620": "Among the Sleep: Enhanced Edition — это новая и улучшенная версия удостоенной наград приключенческой игры ужасов от первого лица. В этой игре вы играете за маленькую девочку, которая отправилась искать маму, но попала в ловушку запутанных кошмаров.",
"770810": "Подбрасывайте тесто, распределяйте соус и пеките пиццу для более чем 500 чудаковатых посетителей в своей уютной пиццерии. Украшайте её в пастельных тонах, выращивайте огород, следите за трогательными главами и событиями, отдыхайте и наслаждайтесь мягким ASMR готовки пиццы.",
"1024380": "Большая карта. Огромные динозавры. Крупные пушки. Совладайте с постоянно растущей угрозой вместе с друзьями в онлайн-шутере Second Extinction.",
"2068280": "Nordic Ashes: Survivors of Ragnarok — это сложная игра в жанре roguelite-survivor, вдохновленная норвежскими мотивами, в которой вам предстоит пережить полчища существ, настигающих вас на своем пути.",
"679900": "Swords & Souls: Neverseen — это уникальная RPG, в которой повышение уровня требует мастерства! Создавайте персонажа, обучайте его и повышайте уровень, исследуя остров Неверсин и его эксцентричных жителей, а также сражаясь со злом, чтобы расстроить планы злой ведьмы!",
"597180": "Old World — это революция в жанре исторических стратегий. Возглавьте династию и проведите ее сквозь века, играя за несколько поколений царей и цариц. Объявляйте войны, управляйте царским двором и впишите имя своей семьи в историю… или наблюдайте, как империя обращается в прах.",
"405310": "Мстители, собирайтесь! В популярной серии видеоигр LEGO® Marvel вышла новая захватывающая игра о приключениях супергероев.",
"558990": "Opus Magnum — новая игра-головоломка с бесконечным игровым процессом от компании Zachtronics, создателя SpaceChem, Infinifactory и SHENZHEN I/O. Вам предстоит придумывать и строить хитроумные машины для получения зелий, ядов и других веществ с помощью механизма трансмутаций — самого мощного и совершенного инструмента в арсенале инженера-алхимика!",
"599390": "Битва за Веснот — свободно распространяемая (полностью бесплатная) пошаговая стратегия в жанре эпического фэнтези. Откройте для себя мир Ирдии в бесчисленных приключениях семнадцати одиночных кампаний и десятков многопользовательских карт.",
"1866180": "Милости просим на Остров Убийц! Ваши спутники — четверка соблазнительных убийц. Несмотря на пугающую наружность, им тоже хочется романтики. Вам предстоит покорить их сердца и раскрыть мрачные тайны. Что впереди: любовь, дружба... страшная смерть?",
"1939970": "Добро пожаловать в мрачный Нью-Йорк 2329 года, где люди обрели великий дар — бессмертие, за которое нужно платить. В этой интерактивной нуарной истории вам предстоит стать детективом Джеймсом Карра, который идёт на крупный риск, чтобы поймать серийного убийцу, устроившего охоту на элиту города.",
"352520": "Окунись в мир The Silent Age - ошеломительное приключение в жанре point-and-click. Эта потрясающая и удивительно атмосферная игра уже покорила более семи миллионов игроков на мобильных платформах и теперь доступна для Steam.",
"1972440": "Шахматы, в которых вместо армии фигур у вас один дробовик. Roguelike-стратегия с основой в виде бессмертных классических шахмат.",
"1041320": "Сразитесь с миллионами игроков по всему миру в эпической стратегии!",
"2315690": "Насладитесь захватывающим пересказом величайших моментов WrestleMania в режиме 2K Showcase of the Immortals в WWE 2K24, где вы сможете снова пережить самые незабываемые, определяющие карьеру матчи.",
"1294760": "HARD BULLET — это экшен-игра, основанная на физике, где враги наводняют залитый неоном город, принося разрушение на его улицы. Используйте замедление, огромный арсенал, чтобы выжить и разблокировать новое оружие. Подготовьтесь к следующему RIDE, оттачивая свои навыки в режимах «Песочница» и «Арена».",
"742420": "Добро пожаловать в Санто-Илесо, вымышленный оживленный город на юго-западе Америки. В мире, где царит беззаконие и банды сражаются за власть, юные друзья становятся преступниками, чтобы создать свое будущее.",
"619820": "Ролевой экшен с элементами рогалика и бесконечной прогрессией. Стройте город, снаряжайте героев и отправляйтесь на уникальные вылазки, чтобы покорить Тёмную цитадель — в одиночку или с друзьями.",
"829110": "Погрузитесь в новые приключения LEGO®, став лучшим злодеем во вселенной DC. Игроки смогут создавать новых суперзлодеев и управлять ими. К армии суперзлодеев присоединятся: Джокер, Харли Квинн и бесчисленное множество членов Лиги Несправедливости. Всех игроков ждут грандиозные приключения.",
"207490": "Сыграйте в любимый платформер, похожий на оживший мультфильм. Бейте кулаками, скользите по воздуху и исследуйте более 60 уровней в Луговине Снов – в одиночном режиме или позвав до трех друзей.",
"666150": "Возглавьте парк и создайте идеальный зоопарк для самых удивительных творений природы.",
"392950": "Гонимый бедами эльфийский народ оказывается на затерянном острове. Чтобы выжить, им понадобится не только острый клинок, но и острый ум. Захватывающее приключение в стиле «поиск предметов», рассказывающее историю о некогда великом народе эльфов, вынужденном выживать на затерянном острове.",
"1203190": "Готовы к беспределу? Wreckfest возвращается с полноконтактными гонками и небывалым разрушением! Вступите в безжалостную схватку с другими транспортными средствами за звание самого быстрого водителя. Улучшенная физика игры погрузит вас в хаос отлетающих частей машин.",
"1418100": "Swords of Legends Online — это экшен MMORPG с потрясающей графикой, фантастическим миром, сложной боевой механикой и уникальной историей, основанной на китайской мифологии.",
"2698780": "Планируйте, проектируйте, стройте и украшайте дом своей мечты в открытом мире. Разрушайте стены, делайте эскизы планировки, а затем стройте и украшайте каждый сантиметр - как внутри, так и в саду. Занимайтесь каждым ремонтом в одиночку или в компании до 4 друзей. Дом вашей мечты ждет вас!",
"581630": "«Меч с Соусом» (Sword With Sauce) — это динамичная стелс-игра, где вы выбираете оружие, гаджеты и стиль игры для устранения врагов. Действуйте громко или оставайтесь незамеченным — выбор за вами.",
"790710": "World of Warplanes — это ММО-экшен, посвященный золотой эпохе военной авиации и приглашающей вступить в бескомпромиссную борьбу за господство в воздухе.",
"946050": "Всеми любимая расслабляющая игра в жанре dungeon crawler возвращается: встречайте Soda Dungeon 2. Вас ждет новое приключение, город, создание предметов, новые классы, параллельные измерения и многое другое! Здесь есть всё, что вам так понравилось в оригинале, плюс новые функции, о которых вы просили.",
"1340480": "Познакомьтесь с историей Фортуны – ведьмы-прорицательницы, которую приговорили к изгнанию на уединённом астероиде. Создайте собственную колоду гадальных карт, верните себе свободу и определите будущее сообщества ведьм.",
"16450": "Вы берете на себя роль оперативника Беккета во время обычной миссии, постепенно превращающейся в борьбу за выживание против гнева Альмы. После того, как страшная сила Альмы вышла из-под контроля, ваш отряд вынужден прорываться через апокалиптические дебри в поисках зацепок о том, как уничтожить её!",
"598980": "Множество игровых автоматов, реалистичная физика, карнавал, дурашливые роботы, открытый мир, система глобального рейтинга и забавные призы. Игра The Coin Game от соло-разработчика включает в себя более 50 аркадных автоматов в современном стиле и ломбард, в котором можно разжиться деньгами.",
"611660": "Fallout 4 получает поддержку VR. В Fallout 4 VR входит полная версия игры с новыми системами боя, создания предметов и строительства. Огромный мир пост-апокалиптический пустоши стал еще более живым.",
"2591280": "Принесите славу своей команде в F1® Manager 2024. Встречайте новый сезон Formula 1®, а вместе с ним и самый реалистичный симулятор менеджера F1® на сегодняшний день. Создавайте историю с одним из 10 официальных конструкторов F1® или с собственной командой.",
"1049280": "«Пилигримы» — веселая приключенческая игра от создателей Machinarium и Samorost. Странствуйте в свое удовольствие, встречайте новых друзей, развлекайтесь вместе и помогайте им в их приключениях — каждый раз по-новому. Сколько подходящих решений вы сможете найти?",
"1128860": "Такой Второй мировой войны вы еще не видели! В долгожданном продолжении популярной серии «В тылу врага» вас ждут динамичный игровой процесс, новые виды юнитов, локации, кампании и битвы Восточного и Западного фронтов, воссозданные с фирменной исторической достоверностью.",
"1708850": "Что превращает человека в наркоторговца? А наркоторговца - в наркобарона? Узнайте это в DDS2, кооперативном симуляторе от первого лица, действие которого разворачивается в динамичном открытом мире. Заводите знакомства, готовьте наркотики и управляйте собственным картелем на острове Сомбра, где власть - единственный закон.",
"750130": "Используя технологии Unreal Engine 5, The Sinking City Remastered возрождает мрачный мир Окмонта с переработанными локациями и обновленным игровым процессом, что идеально подходит как для новых, так и для вернувшихся игроков.",
"435030": "Разбирая сотни пирамид разных конфигураций, выполняйте задания и квесты, получайте награды, собирайте коллекции и помогите эльфам выжить на затерянном острове.",
"2763670": "Яйцо. Две стихии, рождающие идеал. Простота белка. Насыщенность желтка. Лишь вместе они образуют гармонию — инь и ян. Знакомый вкус, словно ангельский хор на кончике языка. Забытый уют, словно та самая песня из летнего лагеря, горячая ванна или кино перед сном.",
"2497920": "Это сложная игра про восхождение.",
"13570": "Опробуйте одну из самых знаменитых игр в жанре стелс-экшен. Раскройте заговор, который повлияет на вас напрямую, и предотвратите Третью мировую войну.",
"643270": "Можете ли вы подумать два раза за секунду?",
"915810": "Хаотичная многопользовательская игра в прятки. Вселяйтесь в безобидные предметы, играя за призрака, или истребляйте привидений в роли охотника, пока часы не пробьют полночь!",
"757310": "Отправляйтесь в незабываемое священное путешествие вместе с Сэйбл, скользите через бескрайние пустыни и завораживающие пейзажи, осматривайте остовы космических кораблей и открывайте для себя чудеса древних цивилизаций.",
"443110": "Armored Warfare — это free-to-play MMO, где вы можете участвовать во взрывных танковых сражениях вместе с миллионами игроков со всего мира в режиме online.",
"956030": "Земля дрожит, лампочки лопаются, и вы понимаете, что за стенами вашей комнаты происходит нечто крайне необычное. Вооружившись острым разумом и отвагой, вы погружаетесь в мир, населенный крылатым народом и смертоносными мебельными чудищами.",
"1330460": "Becastled это стратегия о строительстве и защите замка от осад в волшебном мире!",
"2961880": "Grocery Store Simulator — это кооперативная игра для 1–4 игроков, в которой вы управляете собственным супермаркетом: наполняйте полки, устанавливайте цены, нанимайте персонал, оформляйте магазин и развивайте бизнес, удерживая клиентов довольными.",
"1070580": "Садитесь в любимую машину и устанавливайте рекорды в одиночку или с друзьями в этой уникальной аркадной игре!",
"1545560": "Наймите команду для корабля-призрака и сразитесь с Инквизицией кинжалом, клинком и магией в стелс-стратегии с нелинейным сюжетом. Прокладывайте курс, определяйте тактику, улучшайте способности – и отыщите легендарный пиратский артефакт!",
"2287520": "Five Nights at Freddy’s: Help Wanted 2 — сиквел леденящей душу VR-игры, вдохнувшей новую жизнь в легендарный ужастик. В качестве нового сотрудника компании Fazbear вам предстоит продемонстрировать все грани своего выдающегося таланта в деле управления пиццерией.",
"1860510": "Total Conflict: Resistance — это уникальный симбиоз глобальной стратегии, тактики и экшена от первого лица. Реалистичные массовые бои, множество видов бронетехники, оружия, обмундирования, уникальная механика, захватывающий свободный геймплей. Возглавьте любое государство и приведите его к величию!",
"1570010": "Атмосферная приключенческая игра о мальчике, его судне и путешествии в поисках нового дома.",
"285160": "Присоединяйтесь к Бильбо Бэггинсу, Гэндальфу, Торину и его компании гномов в эпическом приключении по Средиземью, чтобы отвоевать Одинокую Гору в этой увлекательной игре в стиле LEGO.",
"530330": "Blameless - мистическое приключение от первого лица с основным фокусом на решении головоломок и короткой истории. Игрок исполняет роль архитектора, который пытается раскрыть странные события после того, как стал свидетелем жестоких событий.",
"486310": "«Форумная» система общения посредством значков-эмоций в сетевой игре позволит старым и новым поклонникам серии Shelter вместе исследовать самобытный мир дикой природы.",
"736820": "Станьте владыкой державы и попробуйте завоевать всю Европу в этой необычной средневековой глобальной стратегии. Управляйте провинциями, собирайте армии, ведите переговоры, шпионьте за соседями. Станьте властителем своего народа и приведите его к славе.",
"2380050": "Бороздите просторы вселенной, перевозите грузы, сделайте состояние на торговле космическим мусором. И помните: в этом симуляторе звездного дальнобойщика главное – чтобы скафандр сидел!",
"207690": "Игра-приключение созданная творцами отмеченной наградами игры Machinarium.",
"1805480": "Станьте легендарным самураем Сакамото Рёмой и попадите в феодальную Японию, переживающую смутные времена. Вооружитесь мечом и пистолетом в этом динамичном приключенческом боевике, чтобы изменить ход истории и добиться справедливости.",
"1236300": "Любимые персонажи вселенной Resident Evil сошлись в смертельной битве! Испытайте себя в схватках с участием шести игроков.",
"1036890": "Отправьтесь в лихое путешествие по безумным мирам, выполненным в японской стилистике, сыграв в обновленную версию Shadow Warrior 3 с подзаголовком Definitive Edition. Вас ждет убийственная смесь из скоростных перестрелок, яростного ближнего боя и головокружительного паркура.",
"47700": "Готовьтесь к грандиозному завершению тибериевой саги.",
"22000": "World of Goo — это физическая строительная головоломка, завоевавшая кучу наград и созданная всего двумя парнями.",
"2155180": "Возродите надежду в мире, затерянном в тумане. Ведите своих первопроходцев по островам Пагонии, объединяйте разрозненные племена, создавайте процветающие общины и изучайте историю своего народа, возвращая себе мир в новой сюжетной кампании.",
"820520": "Вас ждет работа под прикрытием! Присоединяйтесь к лучшим в мире тайным агентам в этой сетевой игре, которая целиком посвящена скрытности и интриге. Сотрудники DECEIVE INC пускают в ход самые грязные трюки.",
"1274600": "Безбожный союз metroidvania и soulslike. Ключевой особенностью The Last Faith служат бескомпромиссные, требующие идеальной точности сражения с огромным количеством добивающих приемов. Вы не пощадите никого, кто встанет у вас на пути, будь то грешник, или святой.",
"1283400": "Париж, 1789 год. Революция подавлена кровопролитием, которое устроили Людовик XVI и его беспощадная механическая армия. Противостоять королю и восстановить историческую справедливость в этом ролевом экшене предстоит необычному автоматону Эгиде.",
"559210": "Мальчик из-за болезни уже долго находится в больнице. Вместе с мамой он отправляется в путешествие по прекрасному сказочному миру, во время которого узнаёт о прошлом других пациентов больницы и помогает им.",
"1262460": "Возьмите под свой контроль поезд, который станет вашим пристанищем на рельсах. Собирайте ресурсы, создавайте оборудование, стройте уютный дом на железнодорожных вагонах и путешествуйте по тщательно созданным вручную локациям, чтобы исследовать историю мира зомби-апокалипсиса.",
"2244130": "Новая игра, сочетающая в себе жанры стратегического выживания, «песочницы» и симуляции градостроительства. Наслаждайтесь симуляцией в огромном и разнообразном мире, полном приключений. Постройте собственную экономическую систему, которая поддержит Крысотопию, город Вашей мечты.",
"512470": "Привет Капитан! Отправляйтесь в сердце Карибов в самый расцвет пиратства - время черных парусов и белых черепов, голубых волн и невероятных возможностей! Встаньте за штурвал Веселого Роджера и отправляйтесь навстречу сражениям и рейдам, выкупам и сокровищам, станьте Алым Королем Антильских островов!",
"485610": "Многопользовательский футбольный симулятор. Управляй одним игроком. Играй онлайн или с ботами.",
"407530": "Арк: Выживание наиболее приспособленного-это прототип дополнение к Ark, что нарастало до 60 комбатантов друг против друга в быстро меняющейся борьбе за выживание, где игроки в конечном итоге подталкиваются в эпическое окончательное выступление Вводя армии динозавров в битву.",
"24800": "В Red Alert 3 - Uprising добавлены четыре новые мини-кампании, три из которых познакомят игроков с историей Советов, Союзников и Империи Восходящего солнца, а четвертая — с происхождением всеми любимой японской школьницы-воина с псионическими способностями Юрико Омега.",
"2161440": "В Sailing Era каждый выход в море — больше, чем просто плавание под парусом! Управляйте судном, открывайте своё дело, встречайте свою судьбу в таверне, ловите пиратов в разгар битвы, ищите сокровища на суше… Изучайте культуры других стран, совершайте удивительные открытия и уплывайте в закат!",
"1136370": "Bear and Breakfast — это неторопливая игра, посвященная управлению ресурсами. Вам предстоит построить гостиницу и управлять ею... но при этом вы медведь.",
"1351240": "Управляйте машиной и бизнесом, развозите пассажиров по всей Барселоне и развивайте свою компанию! Сможете ли вы удовлетворить транспортные запросы города, который никогда не спит?",
"1566200": "Tape to Tape - роуглайт-хоккей, где каждое решение имеет значение на пути к созданию лучшей хоккейной команды. Выбирайте свой путь, нанимайте уникальных игроков, собирайте особые способности, подкупайте судей или посещайте Мастера клинка — всё, чтобы вернуть хоккею былую славу.",
"421040": "В Plantera вы создаёте собственный сад и наблюдаете, как он наполняется новыми растениями, кустами, деревьями и животными. Расширяя сад, вы привлекаете помощников — круглых синих существ, которые помогают собирать ресурсы и урожай.",
"1148760": "В этой сюжетной карточной РПГ вам предстоит стать подростком на чужой планете. Изучайте мир, растите и теряйте голову от любви. Сделанный вами выбор и навыки, развиваемые в течение десяти лет, определят ваше будущее и будущее всей колонии.",
"705220": "ИГРАЙ СЕЙЧАС!",
"2878420": "Old Market Simulator — это кооперативная игра для 1-4 игроков, где вы управляете своим рынком, заказывая товары, выращивая продукцию, разводя животных, занимаясь рыбалкой и создавая предметы в своей мастерской, нанимая сотрудников и расширяя бизнес.",
"21980": "ДИКИЙ ЗАПАД, 1864 год. Ради спасения семьи братья Макколл готовы убить всех, кто стоит между ними и легендарным золотом Хуареса.",
"448280": "В 2050-м роботы показывают, как люди когда-то работали. Смешно и сумбурно.",
"363930": "Переживите нашествие зомби с пошаговыми боями в стиле Final Fantasy и необратимой смертью. Командуйте выжившими, создавайте материалы и принимайте трудные решения. Это нелинейная ролевая инди-игра на выживание c элементами жанра rogue-litе (наподобие FTL).",
"421120": "Samorost 3 — приключенческая исследовательская игра-головоломка от создателей известных игр Machinarium и Botanicula. Путешествуйте по девяти уникальным космическим мирам, полным ярких состязаний, существ и сюрпризов, воплощенных в жизнь с помощью красивой графики, звука и музыки.",
"821250": "Выживайте, бороздите бесконечное мусорное море и спасайте выживших в этом эффектном симуляторе строительства плавучего города. Командуйте дрифтерами, исследуйте затопленные руины, посещайте ржавые фабрики и узнавайте истории старого мира.",
"711810": "Never Split the Party - это ультра социальный рогалик! Вы - один из искателей приключений, объединившихся, чтобы иследовать процедурно сгенерированное подземелье, собирать мошные улучшения, и кооперироваться с другими искателями приключений, чтобы завоевать и уничтожить подлых боссов подземелья!",
"282440": "Невероятно увлекательный и динамичный шутер, позволяющий сразиться против игроков со всего мира. Этот наследник Quake III Arena с упором на игру по сети предлагает более 100 арен, дюжину игровых режимов и постоянно обновляемую статистику ваших успехов.",
"742300": "Мегамен снова в деле! Новейшая игра из всемирно известной серии представляет классический 2D-платформер в новом визуальном стиле, а двухскоростная система делает игровой процесс еще интереснее.",
"1227650": "Bang-On Balls: Chronicles — это безумный трехмерный платформер со сражениями и упором на собирательство! Собирайте предметы и находите секреты в роли бесстрашного героя, катаясь по почти исторически достоверным эпохам!",
"302590": "Of Guards and Thieves это многопользовательская игра, где мощные охранники противостоят быстрым и неуловимым вора в противостоянии остроумия. Перехитрить врага и простреливать свой путь к победе являются действительными стратегиями. Игра с простыми правилами, новый игровой процесс и высокая воспроизводимость, Of Guards and Thieves обязательно будет демонстратором в Вашей игровой коллекции! Постоянно обновлено с новыми игровыми режимами, картами, снаряжением и классами!",
"1137300": "В детективном триллере, действие которого происходит на опасном экзотическом острове, молодой Шерлок Холмс расследует загадочную смерть матери и пытается найти своё место в жизни.",
"1985820": "Call of Duty®: Vanguard включает в себя увлекательную одиночную кампанию, масштабную игру в день запуска с более чем 20 картами, в том числе 16, созданными для основного сетевого режима, и новый захватывающий мир зомби от Treyarch.",
"499440": "Расслабляющая головоломка: соедините все линии. Без рекламы и спешки.",
"1378990": "Это вопрос времени - получившая признание критиков игра Crash Bandicoot™ 4: Это вопрос времени теперь и в Steam!",
"588210": "После столетия проведенного в крио-сне, Вы обнаруживаете себя среди руин первой межзвёздной колонии человечества. Исследуйте заброшенные корабли и станции, добывайте сырьё в поисках воздуха, топлива и другого оборудования. Или заберите то, что Вам нужно, у других выживших. Выбор остается за Вами!",
"438640": "В самой популярной видеоигре LEGO® вы сможете погрузиться в увлекательное путешествие по мотивам блокбастера. Вы узнаете историю о том, что происходило во вселенной Звездных войн между VI и VII эпизодами.",
"2296990": "Зовите друзей, играйте онлайн, решайте головоломки и разгадайте тайны заброшенного парка. Работайте сообща, чтобы преодолеть все преграды и получить уникальный опыт игры в We Were Here.",
"803050": "Откройте для себя жанр планетостроительного симулятора! Преодолейте все препятствия, терраформировав Марс, раскрыв его природные богатства и выяснив, что стало с теми, кто уже пытался осуществить невозможное. В ваших руках – будущее человечества.",
"887570": "В этой уникальной тактической игре с элементами симулятора вам предстоит командовать собственноручно созданным космическим флотом в трехмерном боевом пространстве, используя смоделированные системы кораблей и маневры для разгрома сил противника.",
"992310": "Tails Noir – это нарративное приключение о личностной трансформации в жанре постнуар. Вживитесь в образ частного детектива-енота по имени Говард Лотор и отправляйтесь исследовать Ванкувер, населенный животными.",
"2273980": "Orcs Must Die! Deathtrap — это безумные бои от третьего лица и стратегические задачи с установкой ловушек. Ваш маг будет расти с каждым боем, а реиграбельность останется бесконечной! Сразитесь с ордами беспощадных орков в одиночку или группой до 4 игроков.",
"356400": "Thumper — это буйство ритма! Классический ритм-экшен, оглушительно быстрый и почти физически ощутимый. Станьте космическим жуком. Бросьте вызов дьявольской пустоте и сокрушите гигантскую злобную голову из будущего.",
"1544360": "LEGO Builder’s Journey — это атмосферная геометрическая головоломка, в которой иногда приходится следовать инструкциям, а иногда… нарушать правила.",
"963930": "Военный шутер в VR с классическими режимами и модами.",
"514900": "Оригинальный детективный хоррор в киберпанковом мире будущего, утопающем в свете неоновых ламп. Играя за наблюдателя, вторгайтесь в людские сознания и продирайтесь сквозь тернистые воспоминания в поисках улик, которые ведут к загадочному убийце и тайне вашего собственного прошлого.",
"375530": "XCOM объединяется с Football Manager. Развивайте свой клуб, зарабатывайте опыт в пошаговых матчах, тренируйте навыки, изучайте новые классы, улучшайте инфраструктуру, покупайте и продавайте футболистов, растите молодежь, принимайте интересные решения.",
"976590": "В Bus Simulator 21 Next Stop доступно 30 лицензированных автобусов. Самый крупный и продвинутый автобусный парк в серии. Прокатитесь по двум картам в одиночку или с другом. Пользуйтесь продвинутой системой администрирования или просто развлекайтесь.",
"1139940": "ATOM RPG: Трудоград — это пошаговая постапокалиптическая ролевая игра, продолжающая сюжет ATOM RPG, и следующая традициям классических игр, таких как Fallout, Wasteland и Baldur’s Gate.",
"1684350": "The Thaumaturge — ролевая игра с глубоким сюжетом и непростыми моральными дилеммами в декорациях Варшавы XX-го века. В этом мире существуют салюторы — потусторонние создания, чья истинная природа открыта лишь тауматургам.",
"1016950": "Жестокая, вздорная, тактическая... и это — BLOOD BOWL! Возвращение игры про американский футбол в мире фэнтези с правилами прямиком из настольной игры и новым контентом. Соберите команду и пробейте свой путь к победе... даже если ради этого придется перепрыгивать через безжизненные тела соперников.",
"1422440": "Проектируйте и воздвигайте крепости стена за стеной, чтобы противостоять бесконечным полчищам кошмаров в стратегии в реальном времени. Управляйте ресурсами, занимайтесь обороной и разведкой. Дайте отпор тьме и боритесь против созданий Тумана.",
"358130": "The Curious Expedition — это симулятор экспедиции, отправляющий вас в конец XIX века. Вместе со знаменитостями той эпохи вы совершите удивительные путешествия по еще не открытым землям — и все это ради славы, научных сенсаций и, конечно, сокровищ.",
"1026820": "Coloring Game – яркий представитель анти-стрессовых игр. Оживите пиксельную картинку, раскрасив её полностью.",
"1104380": "Механические загадки в жутком Лондоне 1908 года.",
"13560": "Погрузитесь в кинематографичный мир шпионажа со Splinter Cell – игрой, получившей культовый статус. Перевоплотитесь в Сэма Фишера – элитного тайного агента из «Третьего эшелона», сверхсекретного подразделения АНБ.",
"1161590": "Тренируйтесь, сражайтесь и стремитесь к вершинам в убийственном продолжении знаменитого бойцовского менеджмент-симулятора! Наставляйте своего подопечного и сделайте его настоящей машиной: выбирайте боевые стили, контролируйте распорядок дня и любуйтесь, как он задает жару на ринге!",
"2716400": "Отмеченная наградами детективная сага возвращается. Выясните правду, стоящую за 20 странными делами из 1970-х, которые изобилуют преступлениями, смертями и развратом. Мир изменился кардинально, а вот грехи человечества — нет.",
"1567020": "Группа документалистов получает приглашение в современную копию «Замка убийств» серийного убийцы Г. Г. Холмса. По прибытии они обнаруживают, что за ними следят. И теперь уже не до рейтингов…",
"1700870": "Clanfolk — это симулятор колонии в средневековой Шотландии. Готовьтесь к суровой зиме: рыбачьте, охотьтесь и выращивайте еду. Обуздайте природу, чтобы выжить. Стройте дома, торгуйте с кланами, заводите детей, заключайте браки — словом, живите и процветайте.",
"1590910": "Forgive Me Father - мрачный, олдскульный шутер, созданный в стилистике комиксов по мотивам романов Г.Ф. Лавкрафта. Сможете ли вы продержаться достаточно долго в охваченном безумием мире, чтобы найти ответы и искупление?",
"251950": "WWII Online — масштабный, постоянный бесплатный MMO FPS, управляемый игроками. Сражайтесь в армии, авиации или флоте, зарабатывайте VP и открывайте юниты. Один глобальный сервер. Без скриптов. Реальные исходы. Без зон. Огромный мир (300 000 км²). ЗАПИСЫВАЙСЯ!",
"2270": "Вторая мировая война. Нацисты готовятся создать непобедимую армию мутантов. Вы собирались раскрыть их план, но вас поймали и посадили в тюрьму. Судьба подарила вам шанс на спасение, однако путь к свободе пролегает через лабиринты коридоров и тысячи свирепых нацистов.",
"3020": "Call of Juarez — эпичная приключенческая FPS-игра в духе вестерна. Игрок попеременно вживается в роль двух отдельных, противоположных персонажей: трусливого беглеца Билли и охотящегося на него священника Рея.",
"1138850": "Управляйте руками космонавта из семидесятых; толкайте, подтягивайтесь и поворачивайте, чтобы продвигаться вперед, реализуя основанные на законах физики сценарии. Действие происходит в невесомости, где предметы не стоят на месте, ни на что нельзя опереться, а простые решения не работают.",
"805940": "RUSSIA BATTLEGROUNDS - это сетевой шутер в жанре Battle Royale, в котором игроки сражаются за родину. Только ваш яростный гнев и жестокость помогут вам выжить в этой кровавой бане.",
"1216060": "Готовьтесь к боям на пике возможностей в новом файтинге серии Dungeon & Fighter!",
"1695840": "Fear Therapy - это многопользовательская (1-4) и однопользовательская психологическая игра ужасов. Постарайтесь выполнить квесты и покинуть дом ужасов, пока не стало слишком поздно! Сатана злится с каждой секундой, и ничто его не сдерживает.",
"2230650": "Отправляйтесь в эпическое приключение, прокладывая путь по огромному фэнтезийному миру. Соберите свой билд и побеждайте в захватывающих битвах с боссами. В TEVI, адской метроидвании, вас ждёт история о тайнах, магии и хаосе!",
"1079800": "Идеальный герой боевика в здании. Pistol Whip — ритм-игра с элементами экшена, сочетающая в себе драйвовую музыку и навеянные фильмами адреналиновые перестрелки.",
"433550": "DARQ это игра про мальчика по имени Ллойд, который осознаёт, что спит. Сон стремительно превращается в кошмар, а все попытки проснуться оборачиваются неудачей.",
"2208570": "Dark Hours — командная игра на выживание в жанре ужасов для 1–4 игроков. Вы с подельниками планировали ограбление, но оказались заперты в здании с потусторонней сущностью. Забудьте о своих планах: теперь главное — остаться в живых. Действуйте сообща, чтобы спастись.",
"259550": "Погрузись в это Уютное приключение RPG и насладись спокойным странствием без суеты. Собирай припасы, терпеливо преодолевай преграды и помогай людям в беде. Проживи душевную историю, в которой простой юноша спасает своего отца.",
"20570": "В Dawn Of War II: Chaos Rising вы возглавите Кровавых воронов и защитите сектор от Космических десантников Хаоса – Черного легиона. Уничтожьте отбросы Хаоса и удерживайте регион целым, пока силы изменников работают изнутри, пытаясь победить Кровавых воронов.",
"2706170": "Ты бедный и лысый. Приступайте к работе.",
"1953520": "Примите вызов и сыграйте в самую полную, реалистичную и требовательную симуляцию ралли в истории. Погрузитесь в эпицентр гонки и управляйте машинами чемпионата WRC 2022, включая новые гибридные модели.",
"1304550": "Progressbar95 — это уникальная ностальгическая игра. Она превращает старые элементы интерфейса: кнопки, панели, окна, иконки — в игровые элементы! Сражайтесь против офисных помощников, калькуляторов, навязчивых поп-ап окон и различных сбоев. Заполните прогресс бар, чтобы победить.",
"1672500": "Идеальный Гандам ждет вас в новой игре Gundam Breaker! Еще больше деталей для кастомизации, чтобы вы могли создать идеального Ганпла для легендарных сражений. Сокрушайте врагов, используя новую двойную систему оружия, и пополняйте свою коллекцию деталей обломками с противников.",
"2200": "Древняя инопланетная раса собрала на арене величайших воинов всех времён и вселенных ради своего увеселения. Сражайтесь за славу в схватках с безжалостными соперниками, используя разные виды оружия и усилений в динамичном шутере в однопользовательском режиме и по сети.",
"1808680": "Помогите Снусмумрику вернуть мир и гармонию в Муми-дол в музыкальном приключении с открытым миром. Знакомые с детства персонажи помогут вам противостоять Смотрителю парка (Park Keeper).",
"2464530": "В этом слэшере от первого лица, появившемся благодаря усилиям одного разработчика, вам предстоит уничтожать орды врагов, исследовать миры тёмного фэнтези, находить мощное снаряжение и сражаться с боссами, чтобы очистить всё от скверны.",
"1123450": "Приключение с видом сверху в мире-раскраске, полном ярких персонажей. Исследуй, решай загадки, заводи друзей и рисуй на всем с помощью твоих разноцветных сил! Игра от создателей Wandersong и Celeste.",
"2726450": "Windowkill — это твин-стик шутер, в котором границы игрового окна постоянно приближаются к вам. Атакуйте границы окна чтобы двигать его по экрану, пока вы сражаетесь с врагами и уклоняетесь от боссов с их собственными окнами.",
"1310410": "Вернитесь в поместье Дерсето в этом переосмыслении Alone in the Dark, ставшем признанием в любви к культовой классической игре ужасов 90-х.",
"1730590": "Научитесь рассуждать в обратном направлении. Перехитрите невозможное. Вас ждет умопомрачительное приключение от первого лица, где вам предстоит решать оригинальные и сложные загадки, перемещая предметы во времени.",
"1206060": "Маленький мальчик засыпает и попадает в ужасный кошмар. Сможете ли вы развеселить его?",
"1245480": "В SYNDUALITY Echo of Ada вам предстоит заручиться поддержкой ИИ-напарника Магуса, отправиться в путешествие в роли скитальца и сразиться с инопланетными существами Эндерами и другими игроками.",
"983870": "Постройте идеально оптимизированный завод или создайте художественный шедевр в бесконечном воксельном мире. Добывайте и собирайте ресурсы, автоматизируйте постоянно растущие производственные линии и управляйте сложными системами в FOUNDRY.",
"893030": "Music Racer это игра-гонки, в которой трек создается на основе вашей музыки!",
"604500": "Tank Force – современный бесплатный танковый онлайн шутер. В игре вы найдёте сумасшедшие сражения на танках, где сочетаются лучшие качества танкового симулятора и захватывающие аркадные бои.",
"1243850": "This Bed We Made - это игра-детектив от третьего лица, в которой вы играете за горничную в отеле 1950-х и шпионите за комнатами незнакомцев, чтобы раскрыть их смертельные секреты. Узнайте, что связывает гостей в этой истории о любви, разбитых сердцах и убийстве!",
"1471410": "SYNTHETIK 2 — это беспощадный тактический шутер-рогалик. Играйте в одиночку или с друзьями. Собирайте мощные технологии. Оцените стрельбу нового уровня. Улучшайте своих андроидов, чтобы бросить вызов Машинным Богам.",
"615610": "Бросьте вызов гравитации в Orbt XL! Быстрая, захватывающая аркада. Оставайтесь на орбите, избегайте препятствий и набирайте очки: чем ближе к черной дыре, тем выше счет! Легко научиться, сложно освоить, идеально для коротких сессий.",
"1805360": "Мечтаете ли вы когда-нибудь разбогатеть в одночасье? Присоединяйтесь к игре \"Баунти\"! Здесь вы примете участие в королевской битве с другими людьми, у которых есть такая же мечта. В соревновании будет только один главный приз!!! Присоединяйтесь к игре \"Баунти\" и станьте победителем!!!",
"1456200": "Дрифтуй по самым легендарным перевалам Японии. Соревнуйся в эпических баттлах с друзьями или игроками со всего мира, выполняй доставки, покупай новые машины, ставь рекорды в мировых рейтингах!",
"3168600": "Оптимальная версия социальной командной игры на выживание в трех измерениях! Выживут ли члены экипажа, или же предатели победят? Роли, срочные собрания, обман, саботаж, задачи: ваш любимый хаос из оригинальной Among Us в 3D.",
"475190": "Scanner Sombre - это 3d хоррор-игра про исследование пещер, где тьма - ваш главный враг. Освещайте невидимое с помощью сканера LIDAR, открывая жуткую красоту и опасность бездны. От создателей Prison Architect это захватывающее приключение использует свет и тень для создания захватывающего опыта.",
"1249040": "Маленький человек против самого популярного реалити-шоу в мире! Встречайте American Arcadia – захватывающую историю освобождения, удачно сочетающую в себе элементы 2.5D-платформера и полноценной трехмерной игры от третьего лица.",
"326360": "Создайте героя и сражайтесь с врагами в 2D MMORPG вместе с друзьями. Огромный открытый мир, захваты замков, свободное PvP, арена, битвы между Альянсами, Гильдии, Подземелья и веселые праздники уже ждут вас!",
"1108590": "Eldest Souls – динамичная, зубодробительно сложная игра в жанре «битвы с боссами», близкая по духу к серии Souls. Чтобы напоследок отомстить всему миру, древние боги обрушили на него великий Мор. Последней надеждой человечества стал одинокий воитель... и его меч, выкованный из чистейшего обсидиана.",
"2067050": "Белка, вот тебе пистолет. Ты — самый несносный грызун на районе, и в погоне за золотыми желудями ты пойдешь на преступление. В этом шутере-«песочнице» и платформере с головоломками тебе предстоит сражаться зубами, когтями и пулями, чтобы сбежать с секретного подземного объекта и победить Агентов.",
"2305840": "В Cat Quest III вам предстоит стать настоящим мурр-ским разбойником в открытом 2,5 D-мире, кишащем крысами-пиратами. Бороздите моря в поисках сокровищ, но берегитесь! Король пиратов у вас на хвосте...",
"871980": "Digimon Survive — это визуальная новелла с элементами тактической ролевой игры, действие которой происходит в загадочном мире, полном смертоносных чудовищ и ожесточенных боев.",
"2210": "Вы — боец элитного отряда «Носорог», возглавляющего атаку землян на враждебную планету. Но вскоре вы понимаете, что есть лишь один способ победить врагов в этой тяжёлой битве за выживание человечества — стать таким же, как они.",
"321800": "Возвращение ледяной классики. «Icewind Dale: расширенное издание» сохраняет дух изначального приключения, в то же время перерабатывая его для современных игроков. Соберите отряд героев Dungeons & Dragons и покорите суровые, жутковатые и прекрасные пейзажи Хребта Мира.",
"1408230": "Мини-гольф в VR на фантастических полях. Идеально для игры с друзьями.",
"1507580": "Станьте Мией, паранормальным детективом, ищущим своего пропавшего отца внутри Периметра – места, которого не существует. Исследуйте улики, как настоящий детектив, и раскройте тайны Загадки Страха, побеждая ужасных монстров, которые попытаются вас остановить.",
"1172650": "INDUSTRIA – шутер от первого лица, который переносит вас из Восточного Берлина в параллельную реальность незадолго до окончания холодной войны. В поисках пропавшего коллеги по работе вы раскрываете тёмное прошлое мистического и сюрреалистического мира стимпанка.",
"1660080": "Поднимитесь в небо в Aloft — кооперативной «песочнице» с элементами выживания. Открывайте летающие острова и превращайте их в корабли, бороздящие небеса. Найдите утраченные знания, излечите грибковое заражение и преодолейте ураганы, чтобы восстановить экосистему.",
"2669410": "Metro Awakening — это разработанный для VR сюжетный приключенческий шутер от первого лица. Погрузитесь в атмосферу Metro с элементами исследования, стелса и боев. Надевайте противогаз и отправляйтесь навстречу разрушительной радиации в глубины метро, где на каждом шагу вас будут поджидать угрозы.",
"1670870": "Погрузитесь в захватывающую и леденящую атмосферу MADiSON. Соедините мир живых с потусторонним миром с помощью фотоаппарата мгновенной печати. Делайте снимки и проявляйте их. Решайте головоломки, исследуйте огромный жуткий дом, но самое главное — выживите.",
"663390": "Rento деловая игра. Торговля земли, строить дома, выиграть аукционы и самое главное - получать удовольствие.",
"858710": "Gravity Circuit — это яркий и динамичный 2D-платформер в духе классических консольных игр. Одинокий оперативник Кай использует таинственную энергию гравитационного замыкания в футуристическом мире, населенном разумными роботами.",
"338180": "Батла – крутой шутер про роботов, которые прилетели захватывать Землю, но оказались слишком маленького размера для этого. Им ничего не оставалось как захватить детскую комнату и выяснять в ней отношения между собой.",
"1622900": "Star Trek: Infinite — грандиозная стратегическая игра, которая позволяет создать собственную историю знаменитой вселенной.",
"488310": "Самый реалистичный настольный теннис в VR.",
"541200": "Цель в названии. Погрузитесь в виртуальный пейзаж, наполненный неоновыми огнями, бегая, скользя, взбираясь на крайние высоты, и несясь через каждый уровень со сверхзвуковой скоростью.",
"664830": "Побеждай врагов, находи оружие и экипировку, улучшай героя, получай достижения и исследуй загадочную планету Зомботрон. Но главное правило: видишь врага - стреляй!",
"2527390": "Dead Rising возвращается с обновленной графикой в издании Deluxe Remaster!",
"1268590": "Испытайте себя в пошаговой стратегии 4X, где за 10 000 лет ваша страна пройдет путь от зари человечества до космических далей.",
"1472560": "I am Fish — очаровательная приключенческая игра с реалистичной физикой. Четверых бесстрашных друзей-рыбок насильно разлучили с домом. Плывите, летите, катитесь в своем аквариуме и пробирайтесь к океану, чтобы обрести свободу и встретиться с друзьями.",
"2218400": "\"Greеdland\" - это игра в жанре \"стреляй сверху\" с элементами выживания. Уничтожай монстров, выбивайся из осады и встречай рассвет победы!",
"846470": "Moss™ — динамичное приключение с элементами головоломки для одного игрока — новая игра от Polyarc, созданная специально для VR. Она сочетает классические элементы прекрасной игры — интересных персонажей, захватывающую боевую систему, исследование мира — с новыми возможностями виртуальной реальности.",
"1150530": "Wizard with a Gun — это кооперативная онлайн-игра в жанре «песочница» с элементами выживания. Ее действие происходит в волшебной пустыне, полной загадок и опасных существ. Путешествуйте в одиночку или с другом, собирайте ресурсы и создавайте оружие для исследования неизведанного.",
"691690": "Ash of Gods — это пошаговая ролевая игра, объединяющая тактические битвы, элементы коллекционных карточных игр и постоянно развивающуюся историю, в которой никто не застрахован от смерти, включая главных героев.",
"2085360": "Город спит, часы тикают, овечки все еще прыгают через кровать. Она переворачивается с боку на бок уже в третий раз, но мысли становятся только громче... \"Бессонница\" - это нежная, милая и эмоциональная головоломка. Увы, голова моя сегодня снова беспокойна, смогу ли я спать сегодня ночью?",
"2695490": "Age of Water — приключенческая онлайн-игра о Земле будущего, полностью покрытой водой. Плывите сквозь штормы, сражайтесь и торгуйте, захватывайте чужие лодки или стройте свои, добывайте ресурсы со дна океана, раскрывайте тайны водного мира.",
"2379390": "Tom Clancy’s Rainbow Six® Эвакуация – тактический кооперативный PvE-шутер от первого лица, где вам предстоит собрать команду и вступить в бой с эволюционирующей инопланетной угрозой. Слаженная командная работа, выбор тактики и безупречное исполнение плана – ключ к победе.",
"1599660": "ИДЕАЛЬНАЯ АДАПТАЦИЯ ДЛЯ PC Легендарный Сэкбой приходит с PlayStation® на PC, чтобы участвовать в грандиозном трёхмерном платформенном приключении. Эпическое путешествие с платформенными испытаниями. Захватывающее управление. Хаотичная, весёлая и творческая совместная игра.",
"858260": "В этой игре жанра roguelite фэнтези сочетается с синтвейвом, а битвы на мечах в виртуальной реальности — с физической активностью в реальном мире. Станьте сильнее, сражаясь с магическими чудовищами в невероятном неоновом мире!",
"1676130": "Приготовься нанести серьезный удар по доходам крупнейших корпораций в Deadlink, киберпанк-шутере от первого лица с элементами roguelite. Стань мозгом боевой гуманоидной оболочки, созданной для проведения секретных военных операций.",
"24880": "Подрывайте власть захватчиков.",
"562360": "Пролетайте через полные опасностей процедурно генерируемые туннели, избегая тысяч врагов, в этом возвращении к золотому веку аркадных игр.",
"1582650": "Отправляйтесь в путешествие по обширным землям в Caravan SandWitch, увлекательном приключении в повествовательном стиле.",
"550010": "Добро пожаловать в лабораторию! Тут проводятся испытания над высокопрочными клонами людей с новейшими разработками оружия, и твоя задача возглавить эти испытания.",
"2441700": "АНДЕГРАУНДНЫЕ БОИ МЕХОВ! Управляй пятитонным металлическим мехом и круши всё на аренах, погружаясь в мрачные сцены жестокого насилия!",
"1196090": "Scars Above — научно-фантастический экшн-шутер с перспективой от третьего лица. Захватывающий сюжет, решение сложных головоломок и исследование таинственной планеты подарят вам радость первооткрывателя!",
"1999520": "Платформенная головоломка, в которой вы управляете одновременно кошкой и тостом, основанная на знаменитом «Парадоксе масляной кошки». Игра включает более 200 уровней, более 70 скинов, а также бои с боссами и мини-игры!",
"2009100": "Immortals of Aveum — одиночный магический шутер от первого лица. Узнайте историю Джека, вступившего в элитный орден боевых магов и намеревающегося спасти разрушающийся мир.",
"2878600": "Ваша следующая глава посвящена полету! Погрузитесь в чарующий мир квиддича, играя в одиночку или наслаждаясь волшебными моментами со своими друзьями и близкими.",
"314970": "Age of Conquest - пошаговый варгейм.",
"629910": "Clicker Heroes 2 — бесконечная поуровневая ролевая игра-боевик. Отправляйтесь в нескончаемое путешествие в верхний правый угол экрана.",
"2863640": "Встречайте The Midnight Walk, новое инди-приключение от авторов Lost in Random. Подружитесь с одиноким фонарем и осветите себе путь по чудесному и ужасному миру. Обхитрите монстров и изучите жуткие детали ландшафта, созданного вручную из настоящей глины и анимированного покадрово.",
"2232880": "Beast Saga — RPG с открытым миром в мире боевых искусств. Играешь за юного волка Лан Цзюси из племени. Свободно исследуй, собирай, создавай, развивай навыки, культивируй боевые искусства, заключай союзы и переживай уникальные приключения Цзянху.",
"1048100": "Peekaboo — прятки по сети. Игроки делятся на две команды: пропсы и охотники. Пропсы принимают облик предметов и перенимают их физические свойства, а охотники всеми силами пытаются их найти.",
"1694600": "THE HOUSE OF THE DEAD: Remake — это переработанная версия игры, представленной в 1997 для аркадных автоматов. Классический рельсовый шутер получил совершенно новый антураж, а игровой процесс теперь соответствует современным игровым стандартам.",
"562500": "Warstone TD - это стратегическая игра в жанре защиты башнями с кучей интересных новвоведений, приятной мультяшной графикой и захватывающей историей.",
"4850": "Казаки: Снова война содержит в себе все наработки из игр «Казаки: Европейские войны» и «Казаки: Последний довод королей», полностью удовлетворит запросы как старых, так и новых поклонников серии. В дополнение включены две новые нации: Швейцария и Венгрия.",
"447290": "REDEEMER: Enhanced Edition это жестокая и бескомпромиссная игра в жанре «избей их всех», где вы будете пробивать, прорубать и крушите врагов. Освойте глубокую боевую систему, выполняйте жестокие добивания и сражайтесь за искупление.",
"1928870": "Проникните в тайны Minecraft Legends — новой экшн-стратегии. Исследуйте земли, полные разнообразных ресурсов в пышных биомах, которым грозит опасность полного уничтожения. Вторжение пиглинов уже началось, и ваша задача — собрать союзников и повести их в бой за Верхний мир!",
"1603180": "Раскройте своего внутреннего шахтера, управляя высокотехнологичным добывающим мехом! Добывайте ценные ресурсы и улучшайте свой мех для еще более крупных уловов при исследовании подземелья. Веселитесь в одиночку или с до 7 друзей в онлайн-кооперативном многопользовательском режиме!",
"865610": "Tails Noir – это нарративное приключение о личностной трансформации в жанре постнуар. Вживитесь в образ частного детектива-енота по имени Говард Лотор и отправляйтесь исследовать Ванкувер, населенный животными.",
"1286320": "Exoprimal — это многопользовательская командная игра в стиле экшн, в которой игрокам предстоит бросить вызов самым свирепым зверям в истории с помощью новейшей разработки человечества — экзокостюмов.​​",
"2331330": "Проклятый мост 2: Эвакуация – вторая часть игры 《Проклятый мост》 Это хоррор от первого лица, в котором игрок управляет четырьмя персонажами. Действие игры происходит в университете Вэнь Ху во время «Карнавала ужасов». Вас поджидают предзнаменования страха, шутки и... леденящий ужас.",
"2400160": "Вооружись скоростью печати. Glyphica: Typing Survival — это одиночная рогалайт-игра на выживание против полчищ врагов, где ты уничтожаешь толпы противников на минималистичной арене с помощью ловкости пальцев, выбранного арсенала и чистой решимости.",
"1436700": "Серия Trine возвращается с новым эпическим приключением! В пятом походе героям Тройки придется сразиться с подлыми и двуличными злодеями, готовыми на все, чтобы захватить власть в королевстве. Успеют ли герои спасти мир Trine?",
"1637730": "Crystal Project — нелинейная JRPG, в которой вы сами создаете собственное приключение. Исследуйте мир, находите кристаллы, изучайте способности и разработайте стратегию победы над самыми крутыми боссами. Ну или просто исследуйте мир.",
"1457080": "Разработанная Digital Sun, создателями Moonlighter, игра The Mageseeker – это ролевой боевик, действие которого разворачивается во вселенной League of Legends. Играйте за мага Сайласа, который вырвался на свободу после долгих лет заточения. одолеть охотников на магов и спасти страну от тирании.",
"574720": "Управляйте рабочими, станками и прочим оборудованием, создавайте потрясающие товары и смотрите, как самая большая из маленьких мастерских превращается в завод мечты!",
"1386900": "Детективный хоррор от первого лица в киберпанковом мире будущего, утопающем в свете неоновых ламп. Играя за наблюдателя, вторгайтесь в людские сознания и продирайтесь сквозь тернистые воспоминания в поисках улик, которые ведут к загадочному убийце и тайне вашего собственного прошлого.",
"691260": "Королевская битва в VR, где можно залезть на что угодно и спрыгнуть с крыши, расправив крылья.",
"40720": "Samorost 2 — это милая сюрреалистическая история о космическом путешествии Гнома, чью собаку похитили злобные инопланетяне. Посетите удивительные места, познакомьтесь с их странными обитателями и спасите песика — все под изумительную музыку Томаша Дворжака (Floex).",
"1491670": "В Venba вам предстоит готовить блюда южноиндийской кухни и путешествовать вместе с семьей эмигрантов!",
"1849900": "Оптимальная версия социальной игры на выживание в виртуальной реальности! Выживут ли члены экипажа, или же предатели победят? Роли, срочные собрания, обман, саботаж, задачи: ваш любимый хаос из оригинальной Among Us в VR.",
"1643310": "Абсолютное Зло и верная *кхм* ему темная эльфийка Талия возвращаются в Dungeons 4 после легендарных событий предыдущей части. Они готовы вновь одержать победу над силами добра.",
"1708010": "Испытайте захватывающую вселенную The Expanse, как никогда раньше, в последнем приключении Telltale The Expanse: A Telltale Series. Возьмите на себя роль барабанщика Камины и исследуйте опасные и неизведанные края Пояса на борту «Артемиды».",
"2195410": "Возглавьте армии, восстановите павшие королевства и достигните величия! Отправьтесь в эпическое стратегическое путешествие по визуально потрясающему миру. Ведите напряжённые сражения и раскройте увлекательную историю.",
"1336980": "Завоюйте и объедините Японию периода Сэнгоку под одним флагом",
"617480": "Новый вид РПГ. В этой игре странствия по подземельям с увлекательным сюжетом сочетаются с невероятно захватывающими битвами в реальном времени (также можете поставить битву на паузу или замедлить время). Тактическое мышление выходит на первое место. Войдите в загадочную Башню и обретите новый опыт.",
"1540210": "Пора поприветствовать старого приятеля — Фреда. Arizona Sunshine® 2 — современное продолжение полюбившегося фанатам ВР-апокалипсиса, в котором еще больше шикарного зомби-экшена! Что может быть лучше, чем пережить ср*ный конец ср*ного света? Выживайте со своим новым лучшим другом — Дружком.",
"1345890": "Deliver Us Mars — атмосферное приключение в жанре научной фантастики. Ставки высоки как никогда. Группировка Outward угнала ковчеги колонизаторов, и вы отправляетесь за ними на красную планету.",
"1357210": "Управляй цивилизацией, освоившей сверхсветовые путешествия в Galactic Civilizations IV - новинке серии космических стратегий 4X. Исследуй галактику, колонизируй планеты, формируй культуры, заключай союзы, веди войны и открывай технологии.",
"1191330": "Классическая бесплатная MMORPG с открытым миром, гриндом, PvP и рискованной системой улучшений до +10. Уровни 1–100 без сброса. 33 карты. Crossplay для PC & мобильных устройств (Android бета).",
"1730700": "Второй проект серии Katamari Damacy вернулся — в новой улучшенной версии! Вас ждут улучшенная графика и оптимизированный геймплей. А в Royal Reverie вы сможете сыграть за Короля Всего Космоса в детстве!",
"1262060": "Боевой баран - эксперимент ученых разработанный в тайной секретной лаборатории, могущественное существо против роботов, кто победит?",
"587430": "Шпионские головоломки: зловещий доктор Зор очень хочет, чтобы ты погиб.",
"430210": "Станьте воплощением непобедимой межпространственной силы в супергеройской игре от первого лица и спасите Землю от инопланетного вторжения. Будьте осторожны: ваша мощь позволяет уничтожать целые небоскребы (на случай, если вы случайно промахнетесь, атакуя врага).",
"1289810": "Siralim Ultimate - это ролевая игра в жанре \"ловля монстров\" и \"прохождение подземелий\" с невероятной глубиной. Призывайте более 1200 различных существ и путешествуйте по случайно генерируемым подземельям, чтобы добыть ресурсы, новых существ и добычу.",
"1769170": "Shattered Pixel Dungeon это традиционный рогалик про подземелье, в который легко втянуться, но освоить — сложно! Каждый забег уникальный: шесть разных героев, случайные уровни и враги, и сотни предметов, которые можно найти и использовать.",
"1029890": "Психологический хоррор с видом от первого лица, действие которого разворачивается на борту таинственного океанского лайнера. В роли актера, приглашенного эксцентричным режиссером, вам предстоит столкнуться со зловещими тенями прошлого и узнать истинную цену идеального перформанса.",
"1581770": "Исследуйте и контролируйте земли Эо на пути к обретению магического силы в мире этой динамичной стратегической ролевой игры. Выступайте с армией и героями в тактических боях, выполняйте сотни миссий и соберите заклинания и артефакты, чтобы стать величайшим магом.",
"1677350": "Уникальная площадка для проведения чемпионатов серии Мейджор — EA SPORTS™ PGA TOUR™ — представляет игру «Чистый удар» на базе ShotLink®, а также исключительный доступ к самым лучшим в мире полям для гольфа.",
"1879330": "Потрясающая игра WARRIORS OROCHI 3 уже доступна в Steam! В WARRIORS OROCHI 3 вас ждут новые персонажи и эпизоды, которые делают сюжет глубже, новые режимы и новый загружаемый контент, выпущенный для других платформ. Насладитесь миром Орочи (Orochi)!",
"262830": "Тысячи пришельцев, гигантских пауков, мутировавших ящериц и других чудищ — готовы ли вы отразить этот натиск? Crimsonland — это шутер с видом сверху и элементами ролевой игры. Разблокируйте более 30 видов оружия и 50 вспомогательных и жестоких перков.",
"1202200": "Добро пожаловать в игру Paleo Pines, на очаровательный остров с таинственным прошлым, населённый добрыми динозаврами и чудаковатыми людьми. Вместе со спутницей Лаки откройте тайны острова и попросите динозавров помочь обустроить уютное ранчо!",
"385380": "Погрузитесь в эпическое приключение – в одиночку или с друзьями! Исследуйте скрытые подземелья, захватывайте и приручайте свирепых монстров, стройте и защищайте свою деревню. Создавайте мощное оружие, овладевайте магическими заклинаниями и превращайте планету в колыбель новой цивилизации!",
"271260": "Вы капитан первого межзвездного корабля Земли. Поздравляем! Есть лишь одна проблемка. Ничего особенного, просто скрайвы, могучая раса инопланетян, хочет уничтожить человечество. Поэтому ваша задача — найти союзников, улучшить корабль и спасти нас!",
"1785650": "Теннисный симулятор нового уровня TopSpin 2K25 возвращается со сверхреалистичными возможностями и сложным игровым процессом. Играйте в одиночную или многопользовательскую игру, локально или онлайн. Создайте игрока MyPLAYER или играйте за Федерера и Уильямс с графикой, отражающей их настоящий стиль.",
"1286990": "Первая мировая война. Одинокий французский солдат вынужден пробираться по извилистым траншеям, добывать припасы и решать сложные головоломки, борясь за выживание в разгар жесточайшего военного конфликта в истории человечества. CONSCRIPT — это новая интерпретация классического хоррора на выживание.",
"433100": "12 марта 1938 года, привычный, для 16-ти летней Рени, мир внезапно перестал существовать и виной тому было лишь ее незнание своего места в этом самом мире.",
"1347970": "Patch Quest — это своеобразное сочетание «рогалика», метроидвании и игры про приручение монстров. Обманчиво сложная на вид, она бросает вызов всем канонам жанра и заставляет вновь и вновь возвращаться, чтобы пополнить свою коллекцию монстров. Хватит ли вам сил пробраться через хитроумный лабиринт?",
"1316230": "Force of Nature 2: Ghost Keeper - это невероятное приключение, полное тайн, опасностей, исследований и магии. Игра сочетает в себе жанры Survival, Sandbox, Action, Adventure, RPG, Strategy и Management",
"1309950": "В этом тактическом шутере-головоломке вам предстоит отправиться в смертельное странствие во тьму, найти путь для единственной пули и свирепо отомстить зловещему культу, который разрушил вашу жизнь.",
"436320": "Киберпанк-экшен в VR с кооперативом на двоих.",
"1858630": "Представляем вторую часть серии, приуроченную к 10-летию SWORD ART ONLINE! В сражении за пределами памяти участвует 21 персонаж. Сражайтесь в одиночку или с друзьями. Отправьтесь за пределы памяти!",
"736850": "В роли судьи Революционного трибунала вы ведёте сложные дела простых граждан, опасных преступников и врагов революции в Париже времён террора. Выносите приговоры, плетите политические интриги и постарайтесь сохранить голову на плечах!",
"1190150": "Быстрый онлайн-шутер с реактивными рюкзаками, дельтапланами, быстрыми возрождениями, раундами в 6 минут и мгновенными матчами.",
"1370050": "Молодой самурай Хироки поклялся умирающему мастеру, что защитит свой город и дорогих людей от любых угроз. Столкнувшись с трагедией, юноша должен исполнить долг и в одиночку отправиться в путешествие за гранью жизни и смерти, чтобы преодолеть себя и определить свою судьбу.",
"543260": "Прекрасные нарисованные от руки анимации и обновленный звук — культовая классика приключений вернулась!",
"1000410": "Взрывайте, рубите и шинкуйте врагов в этом жестком шутере от первого лица, источником вдохновения для которого послужили культовые игры девяностых на легендарном движке Quake 1. Очутившись в умирающем мире, возьмите в руки оружие, чтобы открыть древние тайны и отыскать Стражей Старого мира.",
"9310": "Дополнение вводит в существующий игровой процесс Dawn of War совершенно новых бойцов и новые стратегии. Имперская Гвардия получает новое снаряжение, в том числе тяжелые доспехи, новые боевые подразделения, а также разнообразные тактические приемы нападения и защиты. Новые способности делают эту армию поистине смертоносной.",
"1096570": "Song of Horror — это приключенческая история о выживании, действие в которой происходит от третьего лица. Ваш самый страшный враг — Присутствие, таинственное существо, с которым невозможно бороться. Вам остается лишь прятаться, быть предельно осторожными и дышать как можно тише...",
"640590": "Играйте полюбившимися ниндзя, чтобы защитить Ниндзяго от злого Лорда Гармадона. Освойте искусство Ниндзя-проворства, бегая по стенам, прыгая и сражаясь с врагами, чтобы расти в ранге и улучшать боевые навыки ниндзя.",
"2095340": "Приквел к Road 96 и история о дружбе людей из совершенно разных миров. Зои и Кайто. История о том, с чего все началось. А вы готовы пересматривать свои взгляды?",
"529780": "Примерьте на себя роль фермера, пытающегося вдохнуть жизнь в увядающую ферму. Надежды нет, всё в ваших руках.",
"1538970": "Соберите героев и отправляйтесь в путешествие за пределы подземелий замка Хаммервотч, исследовать пиксельный мир. Помогите сопротивлению короля Роланда, а между делом — и жителям деревни. В этой великой оде классическим ролевым боевикам нужно сражаться со зверями, ордами нежити и силами зла.",
"361550": "«Cradle» — научно-фантастический квест с видом от первого лица, ориентированный на исследование окружающего мира. В основе сюжета — отношения главного героя и механической девушки, волей загадочных обстоятельств очутившихся посреди пустоши. Задача игрока — отремонтировать механическое тело своей спутницы и вместе с ней раскрыть тайну заброшенного парка развлечений, находящегося неподалёку от юрты.",
"914260": "Проходи через смертоносные комнаты многоэтажного комплекса. Объединяйся с другими игроками, и пробирайся через ловушки в дружной компании (Кооператив). Или же возьми в руки оружие и сразись с ними в PvP режиме игры!",
"2086430": "NIMRODS — тот самый рогалик в жанре bullet heaven про сборку оружия: выберите оружие, поставьте экспериментальные модули, выкашивайте рои пришельцев на одной огромной карте и играйте бесконечно. В следующем забеге назначьте любую сборку дрону-напарнику. Вы можете не выжить, но ваше оружие выживет!",
"13580": "Играйте за легендарного тайного агента Сэма Фишера в напряженном стелс-экшене, продолжающем историю игры года 2005, и разрушьте жестокую террористическую организацию изнутри.",
"1554790": "Четвёртая игра франшизы Coloring Game (закраска по номерам). Для поклонников серии представлен обновлённый функционал игры и множество новых картинок.",
"726840": "Вы, основатель собственной компании по разработке видеоигр. Стартовая точка принадлежит вам: начните в гараже или мыслите масштабно и сразу приобретите первый офис. В конечном счёте, именно ваши решения сделают студию успешной и оставят след в истории видеоигр.",
"936780": "Хватайте штурвал и летите на поля сражений Второй мировой войны в этой захватывающей игре. В кампаниях за США, Великобританию, СССР, Германию и Японию вы возьмёте на себя роль пилота и командира эскадрильи элитного подразделения ВВС.",
"2609610": "CONVRGENCE - это VR-шутер на выживание. Исследуйте Чернокаменскую зону отчуждения: ищите хабар, сражайтесь с бандитами и охотьтесь за таинственными артефактами. Но поспешите вернуться на базу до заката. Ведь ночью охотник превращается в жертву.",
"1454970": "Решите судьбы ученого-альтруистки Ану, ее амбициозного, «уличного» брата Октавио и свирепой, бросающейся фрогуртом Фрэн. Всеми правдами и неправдами прорвитесь через пять захватывающих глав!",
"410380": "HEX: Shards of Fate - новая разновидность цифровой карточной игры, сочетающая в себе классическую ККИ и элементы онлайн РПГ. Создавайте могущественные колоды из более чем 1000 карт и испытывайте свои навыки в битвах с другими игроками.",
"741510": "Проложите путь по улицам Гонконга в динамичном боевике с видом сверху. The Hong Kong Massacre, вдохновленная классическими боевиками, позволит вам оказаться в центре лихой истории о мести, наполненной жестокими кинематографическими перестрелками и яркими образами преступного мира.",
"1405500": "Невероятно странная красота. Стреляй, уворачивайся и уничтожай! Шутер, в котором апокалиптический мир пробуждается к первобытным желаниям!",
"2061440": "Это бесплатная версия Oxygen, которая включает первые 50 игровых дней. Постройте свой город вокруг Кислородного Центра и обеспечьте выживание своего народа в постапокалиптическом будущем, которому угрожают взрывы трещин, смертоносные ветры, засухи и морозы.",
"542050": "Приглашаем вас полное чудес анимационное царство, в котором самые обычные предметы обретают собственную жизнь. Найдите дорогу домой, разгадав тайны забывчиков и покорив магические силы.",
"782670": "Вы готовы воевать? Скачайте эту невероятно захватывающую игру про танки прямо сейчас! Выбирайте танк и сражайтесь с друзьями в динамичных боях в реальном времени.Встречай легендарный танковый шутер Battle Tanks! Покажи всему миру - кто здесь главный!",
"400940": "Budget Cuts — это VR-игра, в которой вы ловко пробираетесь, прокрадываетесь или с боем и брызгами машинного масла пробиваетесь через враждебный офис!",
"868020": "Свежий взгляд на ваши руки в высококачественной виртуальной реальности.",
"1084640": "Дикий рассказ о любви, смерти, пернатых рыцарях и спасении! «Пернатые копы» — это приключение друзей-копов в стиле черно-белого кино, с глубоко продуманным игровым миром, непростым сюжетом и морем юмора абсурда.",
"808290": "Начните свою героическую сагу в мире, полном магии и увлекательных событий, прямо сегодня: Выберите свою расу, постройте свой дом и исследуйте фантастический мир Табореи в классической free-to-play MMO!",
"460060": "Varenje это красочный квест для всех ценителей игр как искусства.",
"2522520": "Only Up: With Friends — это многопользовательская паркур-игра, где скорость имеет решающее значение. Соревнуйтесь с друзьями, преодолевая динамичные препятствия на пути к вершине. Один неверный шаг — и вы снова на старте...",
"757300": "Необычный отпуск в 60-х годах в параллельной вселенной! Научно-фантастическая приключенческая игра с созданными вручную декорациями.",
"1157220": "Создавайте и настраивайте города в Nebuchadnezzar — классической изометрической игре о строительстве городов, где тщательное планирование определяет ваш путь к власти в древней Месопотамии.",
"345330": "Приготовьтесь к абсолютно новому, напол-ненным множеством событий, открытому миру. Исследуйте его для сбора материалов и снаря-жения. Используйте все силы, чтобы защитить базы и победить орды враждебных монстров. Играйте один или до 8 игроков онлайн!",
"1502190": "From Space — это одиночный или совместный шутер для отрядов до четырех игроков. Освободите Землю от инопланетных захватчиков, используя сверхсовременное оружие. Постапокалипсис еще никогда не был таким веселым и красивым — только взгляните на эту графику!",
"2556990": "Отправляйтесь в потрясающее приключение: вас ждет игра с 60 FPS в разрешении до 4K, с улучшенной графикой и звуком, а также с новым режимом скоростного прохождения, обновленными достижениями и эксклюзивной галереей 20-й годовщины.",
"216890": "В этом жестоком спорте представлены 23 игровые расы, каждая со своим стилем, жестокими приёмами, рейтингами и многим другим!",
"2304990": "Начните в своей спальне в 2010 году. Создайте установки для добычи Bitcoin, Ethereum и других криптомонет. Торгуйте на рынке, чтобы приумножить свое богатство. Расширяйте свой бизнес, открывая новые офисы. Нанимайте квалифицированных сотрудников и распределяйте задания.",
"1144030": "Pesterquest – это эпическое приключение с эпической целью в сеттинге комиксов Homestuck/Hiveswap от американского художника Эндрю Хасси (Andrew Hussie).",
"465100": "LUNA The Shadow Dust — это полностью вручную анимированный квест с загадками. История рассказывается без единого слова — с помощью красивейших заставок и захватывающей музыки. Эта игра — опыт, который вы вряд ли забудете.",
"885000": "Танцуй с неоновыми сферами под синтвейв. Отличное кардио.",
"493540": "Figment — игра в жанре приключенческий боевик, где вам предстоит исследовать уникальную вселенную, полную музыки, юмора и сюжетных линий. Дасти и его неунывающая подружка Пайпер вместе пускаются в путешествие по разуму, разыскивая потерянную храбрость. Присоединяйтесь к ним в этом невероятном приключении.",
"747350": "VR-издание признанной критиками и отмеченной премией BAFTA игры Hellblade: Senua's Sacrifice. Новая игра от создателей Heavenly Sword, Enslaved: Odyssey to the West и DmC: Devil May Cry о путешествии в глубины легенд и безумия.",
"2401230": "Рубите роботов на кусочки в VR и наслаждайтесь тем, как ваш меч расщепляет их металлические тела. Сражайтесь и умирайте в Crashloop, roguelike-турнире не на жизнь, а на смерть. Скрестите мечи или метайте сюрикэны из рукава, ведь это CLONE DRONE... в HYPERDOME!",
"966680": "Научно-фантастический квест на заброшенной базе на спутнике Сатурна.",
"722230": "В игре L.A. Noire: The VR Case Files вам предстоит примерить на себя роль детектива Коула Фелпса и взяться за расследование жестоких преступлений, интриг и заговоров, навеянных реальными событиями 1947 года – одного из самых кровавых периодов в истории Лос-Анджелеса.",
"1599560": "Созданная с нуля специально для VR игра Wanderer сочетает в себе головоломки в стиле квест-комнат, тактильное взаимодействие и элементы экшн-аркады, чтобы по-настоящему погрузить вас в атмосферу путешествий во времени. Готовы пойти по стопам своих предшественников?",
"2100160": "Выкрутите ручку газа, обойдите соперников и пересеките финишную черту: станьте чемпионом в новой игре MotoGP™23 — еще более захватывающей чем раньше!",
"673450": "VR-головоломка с элементами sci-fi и escape room: управляйте временем, решайте задачи, отражайте атаки врагов и исследуйте мир в разных временных линиях.",
"328590": "Don't Knock Twice (Не стучи дважды) — игра-хоррор от первого лица, основанная на городской легенде, от которой стынет кровь и цепенеет сознание. Чтобы спасти свою покинутую дочь, терзаемая чувством вины мать должна раскрыть чудовищную правду городской легенды о мстительной демонической ведьме. Стукнешь раз - и пробудишь ее ото сна, стукнешь дважды - из мертвых восстанет она.",
"1341490": "Hellsweeper VR — это динамичный боевик от первого лица. Проложите себе путь по подземному царству, овладейте оружием и магией стихий или падите под неумолимым натиском оскверненных адом душ. Возьмите волю в кулак и спуститесь в преисподнюю.",
"1636030": "Неистовый военно-аркадный VR-шутер для одиночного или совместного прохождения. Попадайте в различные боевые ситуации, воюйте в закрытых помещениях и на открытых пространствах — вас ждут 63 задания, 39 видов оружия и 17 типов врагов. Возглавьте элитный отряд и погружайтесь в кипящий вокруг бой.",
"810500": "PowerBeatsVR — это интенсивная VR-игра для фитнеса, где вы бьёте, уклоняетесь и делаете приседания под энергичную музыку. Выберите официальные треки с таблицами лидеров или тренируйтесь под свою музыку с помощью генератора.",
"2456960": "Игра The 7th Guest VR — это отличное приключение в мире загадок с лучшими VR-технологиями, сложными головоломками, захватывающим игровым процессом.",
"343740": "Уменьшитесь до микроскопических размеров и отправляйтесь в короткое бесплатное аркадное путешествие по мозгу. Двигайтесь по заданному маршруту среди сияющих нейронов, наводите взгляд на цели и улучшайте свой результат. Играйте в VR или на обычном экране.",
"749960": "Постройте средневековую деревню в полностью интерактивном, смоделированном мире!",
"1133320": "Westworld Awakening - это рассказ от лица Кейт - хоста, достигнувшего самосознания. Чтобы выжить в опасном подземном мире, где никто и ничто не является тем, чем кажется, вы должны погрузиться в тайное прошлое вселенной Westworld и преодолеть все, что предназначалось для вашего уничтожения и порабощения.",
"1546500": "Погрузитесь в незабываемые воздушные бои Warplanes: WW1 Fighters времён Первой мировой в ВР! С гибкой системой параметров каждый сможет настроить реализм игры под себя."
};
